window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["26598457"]={"book":{"id":26598457,"title":"复盘+:把经验转化为能力","author":"邱昭良","translator":"","publisher":"机械工业出版社","pubdate":"2015-8-7","isbn":"9787111507628","tags":["学习方法","方法论","自我管理","管理","复盘","思维","经管","成长"],"memCount":14},"np":1,"pb":[33],"idx":[{"i":20096,"t":"主题2：复盘四步法，帮你把经验真正转化为能力。","l":"TF2-1","c":"李珍琪","g":1,"p":1},{"i":17662,"t":"晋级","l":"TF1-1","c":"霞姐","g":1,"p":1},{"i":16471,"t":"复盘，把经验转化为能力","l":"TF3-1","c":"[email]","g":1,"p":1},{"i":16090,"t":"复盘+把经验转化为能力","l":"TF2-2","c":"是燕子吖","g":1,"p":1},{"i":15861,"t":"复盘，把经验转化为能力","l":"TF3-1","c":"[email]","g":1,"p":1},{"i":14680,"t":"不懂复盘，再努力也只是无效的重复。","l":"TF3-2","c":"Dido","g":1,"p":1},{"i":13346,"t":"掌握复盘四步法，让你加速成长","l":"TF3-1","c":"陈俊忠","g":1,"p":1},{"i":13295,"t":"如何复盘","l":"TF3-3","c":"堤娜","g":1,"p":1},{"i":12789,"t":"用复盘思维提升自己—四步搞定复盘","l":"TF3-1","c":"清风缘林","g":1,"p":1},{"i":12712,"t":"用复盘思维提升自己—四步搞定复盘","l":"TF2-4","c":"清风缘林","g":1,"p":1},{"i":11244,"t":"如何利用过往经验学习并提升能力？","l":"TF3-3","c":"阳小齐","g":1,"p":1},{"i":10750,"t":"如何利用过往经验学习并提升能力？","l":"TF3-3","c":"阳小齐","g":1,"p":1},{"i":10396,"t":"如何复盘","l":"TF1-1","c":"Eala(瑶瑶)","g":1,"p":1},{"i":9980,"t":"如何使用五个为什么寻找问题的根本原因","l":"TF2-1","c":"elikong","g":1,"p":1},{"i":8996,"t":"怎样养成复盘的习惯","l":"TF1-1","c":"张宝建","g":1,"p":1},{"i":8117,"t":"学习复盘，每天都成长一点","l":"TF3-1","c":"郭明珠－太阳雨","g":1,"p":1},{"i":7744,"t":"如何高效复盘","l":"TF2-4","c":"陈松波","g":1,"p":1},{"i":7707,"t":"总结常常写，复盘时时念。 - 但你真的懂什么是复盘吗？","l":"TF3-1","c":"佳山","g":1,"p":1},{"i":7700,"t":"如何从过去经验中提升自己的见识和能力","l":"TF3-1","c":"张喆","g":1,"p":1},{"i":7473,"t":"快速进行个人简易复盘","l":"TF3-2","c":"石思思","g":1,"p":1},{"i":7139,"t":"如何掌握个人复盘的方法","l":"TF3-2","c":"丹丁先生","g":1,"p":1},{"i":6757,"t":"总结常常写，复盘时时念。 --  但你真的懂什么是复盘吗？","l":"TF3-1","c":"佳山","g":1,"p":1},{"i":6746,"t":"如何养成复盘的习惯","l":"TF2-2","c":"韩晓东","g":1,"p":1},{"i":6417,"t":"复盘+把经验转化为能力","l":"TF1-2","c":"周凯","g":0,"p":1},{"i":6188,"t":"关于复盘的那些事儿","l":"TF3-3","c":"华思语","g":1,"p":1},{"i":4858,"t":"学习还原事实，锻炼批判性思考的的能力。","l":"TF2-1","c":"佳山","g":1,"p":1},{"i":4490,"t":"知识的融合，能力的迭代","l":"TF1-2","c":"佳山","g":0,"p":1},{"i":4425,"t":"了解什么是复盘","l":"TF1-1","c":"佳山","g":1,"p":1},{"i":4275,"t":"《复盘：把经验转化成能力》邱昭良","l":"TF2-2","c":"齐艳","g":1,"p":1},{"i":3946,"t":"如何从过去的事中获得提升自己的能力","l":"TF3-1","c":"李佳","g":1,"p":1},{"i":3906,"t":"使用五个“为什么”找到解决问题的方案","l":"TF1-2","c":"英爱","g":1,"p":1},{"i":3435,"t":"五个“为什么”问题解决法","l":"TF1-2","c":"英爱","g":1,"p":1},{"i":2904,"t":"后悔药的正确服用方法","l":"TF1-1","c":"金宇龙","g":1,"p":1}],"ms":[{"id":20096,"topic":"主题2：复盘四步法，帮你把经验真正转化为能力。","learn_goal":"","remark":"主题2：复盘四步法，帮你把经验真正转化为能力。\n✅ 掌握“回顾评估、分析反思、萃取提炼、转化应用”四步完整流程，让复盘有章可循。\n✅ 学会用“实际结果对比预期目标”精准识别亮点与不足，避免主观归因。\n✅ 懂得将复盘结论直接落到“开始/停止/继续”的具体行动，让改变当场落地。\n","level":"TF2-1","duration":26,"status":10,"type":0,"chaishujia":{"username":"李珍琪","city":"深圳市"},"club":{"name":"深圳桃李分舵","city":"深圳"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>各位小伙伴们好，我叫李珍琪，我用三个标签做一下自我介绍。第一个标签是“培训”，我的职业是从事培训相关工作。第二个标签“早起”，在工作日我坚持5:30 起床，利用早起的这段时间学习。第三个标签是“拼豆”，这是我最近迷上的一项手工。\u003c/p>\u003cp>\u003cstrong>【书籍介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>F（特征）：\u003c/strong>今天拆解的片段出自书籍《复盘+：把经验转化为能力》，由管理学博士邱昭良撰写。本书从“道、法、术”三个层次，系统阐述了个人复盘、团队复盘、项目复盘与战略复盘的方法，囊括十余种常用工具与模板，并整理出复盘常见的25个“坑”及对策。\u003c/p>\u003cp>\u003cstrong>A（优势）：\u003c/strong>市面上复盘类书籍，如陈中《复盘》偏向个人复盘，而本书是少有的覆盖个人、团队、项目到战略全场景的系统性著作，是兼顾理论深度与落地实操的专业指南。\u003c/p>\u003cp>\u003cstrong>B1（这本书的收益）：\u003c/strong>读完这本书，你将掌握一套结构化复盘方法，把每一段经历都转化为可迁移的能力，对失败复盘避免再犯错，对成功复盘学会复制成功。\u003c/p>\u003cp>\u003cstrong>B2（本次拆解片段的收益）：\u003c/strong>今天我将带大家拆解书中核心片段“复盘四步法”，帮大家掌握可立即上手的复盘方法，之后就能用在工作与生活中。\u003c/p>","ratings_count":1,"texts":[{"id":24545,"quote":"\u003cp>基于上述分析,在我看来,要想真正从复盘中学习、就必须遵循特定的程序、逻辑或步骤。\u003c/p>\u003cp>\u003cstrong>回顾、评估\u003c/strong>\u003c/p>\u003cp>不仅要梳理事件的过程与结果，也要回顾预期的目标、策略打法与计划。因为事先进行系统的分析、设定科学合理的目标与周密可行的计划，是能力的具体表现；同时，没有目标和计划，就没有一个做比较的参考基准。之后，要将实际结果与预期目标进行对比、评估，找出一些有学习价值或意义的差异（亮点或不足）。\u003c/p>\u003cp>\u003cstrong>分析、反思\u003c/strong>\u003c/p>\u003cp>经过对比，发现了一些差异（亮点或不足），对此，要进行深入的分析、反思，找出根本原因，以便“知其然，知其所以然”。事实上，只有真正搞清楚了为什么会形成这些亮点或产生这些不足，找到关键因素，才能进一步提炼、形成经验或教训。在大卫·库伯提出的“经验学习循环”中，他将其称为“反思性观察”，指的是对具体经历进行回顾、反思。\u003c/p>\u003cp>\u003cstrong>萃取、提炼\u003c/strong>\u003c/p>\u003cp>在找出了根本原因之后，要“退出画面看画”，思考一下，从这个事件中，我们能从中学到什么？也就是说，什么是这类事件的一般规律？哪些做法是奏效的，值得继承或推广？哪些做法是无效的？这是一个萃取、结晶、提炼的过程。库伯将这一步骤称为“抽象概念化”，也就是总结出新想法或修正现有的抽象概念。但根据我的经验和理解，应“适度抽象”，既不能完全“就事论事”，没有提炼，也不应“过度拔高”，将实践经验概括为高度凝练或普适性的“道理”或原则。\u003c/p>\u003cp>\u003cstrong>转化、应用\u003c/strong>\u003c/p>\u003cp>因为学习的目的是更快、更好地行动，所以，要将总结、提炼出来的经验与教训转化到自己的后续行动中，看看需要开始做什么、停止做什么，以及继续做什么？或者，要做哪些改进？无论是个人，还是自己所在的团队与组织都要这样。库伯将这一过程称为“主动实验”，也就是将你复盘所学付诸实践，以观成效。这也是完成学习不可或缺的一个环节。\u003c/p>\u003cp>以上就是复盘的学习机理，是我们做复盘时要坚持的基本步骤或逻辑。我将其称为“复盘之道”。\u003c/p>","explains":"\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>我们来看下这个片段主要讲了什么，这个片段讲的是复盘的底层逻辑和操作程序。那什么是复盘呢？复盘，简单说就是把做过的事重新推演一遍，从中萃取可迁移的经验，再转化为下一步行动，让偶然的成功变为必然。复盘不是简单的“做完事想一想”，而是要遵循一套严谨的流程：从回顾事实到分析原因，从提炼规律到付诸行动，形成一个完整的经验学习闭环。缺了任何一步，复盘效果都会大打折扣。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&lt;一般人的做法&gt;\u003c/strong>\u003c/p>\u003cp>现在很多团队和个人其实已经知道复盘的重要性了，也愿意花时间去复盘。月度复盘会、项目复盘会、年度总结会。但实际做的时候，往往是这样的场景：\u003c/p>\u003cp>领导主持复盘会，让大家轮流发言，每人说几点做得好的和需要改进的，记录下来，形成一份会议纪要，复盘就算做完了；也有不少人确实会在项目结束后认真想一想，但缺少严谨的步骤指引，想到哪算哪，脑子里过一遍就算复盘了。\u003c/p>\u003cp>表面上看，大家都在“做复盘”，但有流程不等于有深度，有记录不等于有学习。\u003c/p>\u003cp>\u003cstrong>&lt;一般做法的坏处&gt;\u003c/strong>\u003c/p>\u003cp>不这么做有什么影响呢？我归纳了两点。\u003c/p>\u003cp>第一，归因表面化，找不到真正的成败根因。常见的情况是，复盘时大家把失败归因于时间不够、预算不足、部门不配合等外部因素，没有挖出根本原因，下次换一批人、换一个项目，同样的问题照样重现。更可惜的是，对成功经验的复盘同样浅尝辄止，真正促成成功的打法、节奏、关键决策没有提炼出来，成功是偶然性的。\u003c/p>\u003cp>第二，没有落地的行动计划。没有明确开始做什么、停止做什么、继续做什么，更没有指定谁来做、做到什么程度。复盘成果停留在纸面上，没有落实到具体行动里。无法验证，就无法修正，复盘成了一次性任务而非持续改进的起点。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong> \u003c/p>\u003cp>那复盘到底怎么做呢？有四个步骤。\u003c/p>\u003cp>第一步：回顾目标，评估结果\u003c/p>\u003cp>首先回看当初设定的目标是什么、期望的结果是什么；再看实际情况，包括哪些达成了、哪些没达成、差距具体是多少。\u003c/p>\u003cp>第二步：分析差异，反思根因\u003c/p>\u003cp>对照原来设定的目标找出过程中的亮点和不足；同时针对每个关键亮点或不足，找到关键影响因素。\u003c/p>\u003cp>第三步：萃取经验，提炼规律\u003c/p>\u003cp>跳出具体的事件，思考“这类事情的一般规律是什么”，识别出哪些做法奏效，值得继承推广；哪些做法无效，以后要避开。\u003c/p>\u003cp>第四步：转化成果，应用行动\u003c/p>\u003cp>明确开始做什么、停止做什么、继续做什么，并且制定行动计划，包括谁来做、什么时候做、做到什么程度。\u003c/p>\u003cp>\u003cstrong>&lt;反面案例&gt;\u003c/strong>\u003c/p>\u003cp>我们团队每个培训项目结束后都会做复盘，这是我们的工作习惯，也有固定的复盘流程。但我们发现了一个怪圈：A项目复盘时提的问题，B项目复盘时又出现了，C项目复盘时发现还是踩了同样的坑。同样的问题反复出现，每次复盘都发现了，每次都没解决。\u003c/p>\u003cp>问题出在哪里呢？\u003c/p>\u003cp>因为我们把复盘做成了一个闭环，发现、记录、归档，然后结束了。我们把“发现问题”当成了终点，而不是起点。没有转化成具体的行动并固化下来，下次启动新项目时，所有人还是按惯性走老路。\u003c/p>\u003cp>\u003cstrong>&lt;正面案例&gt;\u003c/strong>\u003c/p>\u003cp>A项目复盘时，前三步我们是做了的：回顾了目标与结果，分析了根因，也提炼出了经验。\u003c/p>\u003cp>但问题出在：经验提炼完就结束了。我们没有制定行动计划，没有明确停止做什么、开始做什么、继续做什么。所以B项目启动时，大家还是按老习惯走，同样的问题又出现了：设备调试依然出现了问题，上课时线上会议折腾了二十分钟没声音；学员出勤依然没有明确的规则，还是有人不打招呼直接缺席。\u003c/p>\u003cp>如果当时把第四步做全了，会怎样？\u003c/p>\u003cp>针对设备问题，我们会这样定行动：\u003c/p>\u003cp>停止做：停止“上课前15分钟才对接设备”的操作方式\u003c/p>\u003cp>开始做：和技术部同事、讲师约定训前30分钟测试设备。\u003c/p>\u003cp>继续做：训前1天找技术部同事测试设备。\u003c/p>\u003cp>针对学员出勤问题，我们会这样定行动：\u003c/p>\u003cp>停止做：停止“默认学员会按时参加”的放任心态\u003c/p>\u003cp>开始做：明确请假规则；训前3天再次提醒学员参训，并统计每位学员回复情况。\u003c/p>\u003cp>继续做：训前一周发出正式培训通知；统计培训出勤数据。\u003c/p>\u003cp>同时，将以上动作编制成行动计划表，明确责任人、时间节点、完成标准。这样一来，就不需要任何人刻意记住“这次要注意那个问题”，因为计划会自动牵引大家把事情做到位。结果是：B项目启动时，那个问题已经被前置解决了，后续项目里它再也没有反复出现过。\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>\u003c/p>\u003cp>关于复盘的适用边界，有两点想和大家分享。\u003c/p>\u003cp>第一，复盘四步法适用于绝大多数需要从经历中学习的场景，包括个人复盘、团队复盘、项目复盘。\u003c/p>\u003cp>第二，复盘的对象只能是你亲身经历过的事情。你可以看别人的案例写心得，但那叫案例学习，不叫复盘。复盘之所以有效，前提是你身处其中。\u003c/p>","interaction":"\u003cp>\u003cstrong>&lt;显像提问&gt;\u003c/strong>\u003c/p>\u003cp>请大家回想一下，你过往做项目复盘经历，复盘的时候，该走的流程都走了，该记录的也都记录了，但同样的问题在下一次类似项目中又再次出现了。\u003c/p>\u003cp>可能你根本没有回顾最初的目标，只是凭感觉说“项目效果还行”；也可能你发现了问题，但只归因于“供应商不行”“业务部门不配合”，没有追问到根因；又或者你提炼出了经验，但没有把它转化成具体的行动固化下来。\u003c/p>\u003cp>当时你是怎么做的复盘？是哪个环节没有做到位，导致复盘没有真正起作用？请各位先回忆、思考，稍后我们请伙伴分享一下具体的背景和情况。\u003c/p>\u003cp>\u003cstrong>&lt;学习者案例记录&gt;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享者彭利新：\u003c/strong>现在我们家在家自学备考高考，我是陪着他来学习的，然后我们约定每天晚上我们是要做一个复盘。其实我说是复盘，但是后来我对照了一下咱们这个流程，我发现我们做的是总结。对，就像昨天晚上我们一来的时候就说，来我们今天来回顾，我们来总结一下，然后就立刻就进入了哪里做的不好，哪里做的好。那就发现说这个其实根据你这个流程一看，发现每天晚上做出来的这个复盘的，或者其实我们都不能说复盘，就是我们总结的那个效果就不是很好。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>好的，还有其他的吗？好，谢谢彭老师的分享。也可以思考一下，如果按照现在的复盘思路法来，后续可以怎么做，也就是从明天开始可以怎么做好。由于时间关系，我们就不邀请其他伙伴来分享了。其他伙伴如果有想交流的，我们可以过后再去做交流。\u003c/p>\u003cp>\u003cstrong>&lt;A1+&gt;\u003c/strong>\u003c/p>\u003cp>好，刚才大家都分享了自己复盘做了但没做透、问题反复出现的经历。现在请大家再思考下，如果再碰到需要复盘的场景，你会怎么做？\u003c/p>\u003cp>请先思考，稍后我们邀请小伙伴分享，你会如何用复盘四步法来做好下一次复盘，具体每一步你准备怎么做？\u003c/p>\u003cp>\u003cstrong>&lt;学习者案例记录&gt;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享者月巧：\u003c/strong>我说一下，分享一下。就像我们做过案件，就是每个案件做完了，实际上我跟同事，我们都是要求要复盘，但我发现有时候复盘还是不到位，就是没有这么针对这四个方面，感觉也是变成总结了，就变成案件小结了。这个案件哪些地方做的好，哪些地方做的不好，下次应该怎么做？就是仅仅停留了一下，没有去把一些做的好的固化，然后用来应用到下一次同类案件中。然后目标也没有去细细的对比，我觉得反思的根因也没有去追问的不够深入。我觉得以后就可以把这事做成表格。对，就是能说到做成表格，然后去逐一比对，然后去复盘的更加全面一点。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>好的，谢谢月巧的分享。刚刚看到胜男也在留言说也是做一个总结表就没有了。这本书里面也提到了一个复盘画布，就是相当于把这四步它呈现在了一张表格上。大家课后有兴趣的可以找我要，或者是去这本书里面找。后续可以参考那个画布的格式去做一次复盘。非常感谢我们以上小伙伴的一个分享，我的分享到这里就差不多要结束了。\u003c/p>\u003cp>最后快速回顾一下今天的内容。\u003c/p>\u003cp>我们拆解了四步复盘法，分别是回顾目标、评估结果，分析差异、反思根因，萃取经验、提炼规律，转化成果、应用行动。\u003c/p>\u003cp>我们需要对失败复盘，避免重复犯错，更需要对成功复盘，才能不断复制成功。\u003c/p>\u003cp>我的分享完毕，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1788424055000,"updated_at":1788424078000,"ria":true},{"id":17662,"topic":"晋级","learn_goal":"","remark":"无","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"霞姐","city":"乌鲁木齐市"},"club":{"name":"乌鲁木齐筹备分舵","city":"乌鲁木齐"},"prologue":"\u003cp>师父好，教练好，拆书伙伴们，我是李宏霞，我的三个标签是:松鼠AI自习室负责人、学习力导师、新疆乌鲁木齐筹备分舵对接人。\u003c/p>\u003cp>●新疆新市区松鼠AI自习室创办人，松鼠AI甘肃省平台合伙人，让更多的孩子因遇到松鼠AI而变得更好。\u003c/p>\u003cp>●参加过赵周老师的学习力导师班两次，在这里有幸结识了丹丁大神/商拆专家月宫老师，收获颇多。\u003c/p>\u003cp>●现在正和一群有使命爱读书的伙伴筹办乌鲁木齐筹备分舵，期待在今年转正。\u003c/p>\u003cp>感谢栗子姐、丹丁、登伟、力珩师父对我们新疆伙伴的引领，感恩您们无私的付出与教导。新疆乌鲁木齐筹备分舵以后也是咱们师父和所有全国拆书伙伴们新疆的家。\u003c/p>\u003cp>拆书帮与拆书法\u003c/p>\u003cp>●【拆书帮】\u003c/p>\u003cp>拆书帮是一群以拆书爱好者聚集在一起的社群，全国各地都有拆书帮分舵也叫拆书俱乐部，拆书帮分舵是非营利性青年自组织。拆书帮的使命是让更多拆书爱好者成为拆书家。\u003c/p>\u003cp>●【拆书法】\u003c/p>\u003cp>拆书法是以解决问题、提升能力为目的的成人学习法。它强调以学习者为中心而不是以知识为中心，它强烈要求将知识关联学习者经验并规划具体运用。\u003c/p>\u003cp>拆书法分为个人学习拆书法和组织学习拆书法两种：\u003c/p>\u003cp>①个人学习法的应用于RIA便签法，通过读一本书就能达到同主题培训的效果。\u003c/p>\u003cp>②组织学习法的应用是一名拆书家通过一本书就能加工出一场现场活动，同时引导和促进一群人将知识拆为己用。\u003c/p>\u003cp>拆书法可以将书拆为己用，也可以搭建自己的知识体系，希望能通过乌鲁木齐分舵（转正后），帮助和陪伴更多新疆人成为拆书家，拆为己用。为边疆发展做出贡献。\u003c/p>","ratings_count":1,"texts":[{"id":21867,"quote":"\u003cp>复盘，是联想企业文化重要的内容之一，指的是工作完成之后，重新回顾一遍，目的是检验和校正。\u003c/p>\u003cp>联想的复盘共包括四个步骤：回顾目标——评估结果——分析原因——总结经验。\u003c/p>\u003cp>第一回顾目标\u003c/p>\u003cp>回顾目标，其实就是回述一下，自己当时做这件事的目的和初衷，或者说，你所希望的结果到底是什么？也就是用结果导向轮或目标法则进行分析。\u003c/p>\u003cp>第二评估结果\u003c/p>\u003cp>对照最初设定的目标，看看现在完成的情况是否一致，一定要事实求事。\u003c/p>\u003cp>第三是分析原因\u003c/p>\u003cp>要仔细分析事情成功或者失败的原因，每一个重要的节点都要分析清楚。\u003c/p>\u003cp>第四是总结规律\u003c/p>\u003cp>整件事的得失体会，其中蕴含的规律，都值得我们去参考，还有包括下一步的行动计划。总结经验和规律的时候，千万不要轻易下结论，否则容易就出现不客观或自己骗自己的情况。\u003c/p>\u003cp>一次两次的复盘，未必能够摸索出真正的客观规律，只有通过若干次的复盘，才能逐渐总结出更为准确的规律。如果错误地把不是规律的法则，当成规律去指挥企业作战，结果回避不知道规律更可怕。\u003c/p>","explains":"\u003cp>【I】原文阐释（三张便签5-10分钟）\u003c/p>\u003cp>我看到大部分的小伙伴都阅读完毕了，那么接下来的时间我则使用便签读书法来讲解一下我的理解、经验及规划应用。\u003c/p>\u003cp>【what】片段讲了什么\u003c/p>\u003cp>刚刚大家阅读的这个片段主要讲了何为复盘及复盘的四个步骤。\u003c/p>\u003cp>【why】为什么这个很重要（一般做法是什么及后果+这么做的好处）\u003c/p>\u003cp>然而很多伙伴也会好奇了？复盘是指什么呢？其实，复盘是一个围棋中的术语，是指我们做完一件事后，对整个过程进行回顾。如果我们做完一件事后不及时复盘呢？那么不但不能清楚地知道自己哪些环节做得好哪些环节做得不足，更重要是无法总结经验，那么下次做事时依旧会继续沿用旧的模式。\u003c/p>\u003cp>如果我们做到事结后及时复盘，那有什么好处呢？可以通过结果和目标的比对、原因分析找出做事过程中的成功或失败的因素，同时更科学地总结经验和教训，并把经验和教训固化应用于未来的工作中。\u003c/p>\u003cp>【how】具体清晰的步骤（3-5步）\u003c/p>\u003cp>既然复盘那么重要，那么复盘有哪些步骤呢？复盘分为四个步骤，\u003c/p>\u003cp>第一、回顾目标，主要是重述一下做这件事的初衷和目的；\u003c/p>\u003cp>第二、第二、评估结果，评估一下达成的结果跟当初预设目标的差距；\u003c/p>\u003cp>第三、第三分析原因，针对结果和原定目标的差距找出做事过程中存在的问题和原因；\u003c/p>\u003cp>第四、第四总结经验，归纳总结这次事件中自己的收获，收获可以是好的经验或者一些未来需要注意的教训，并将收获点固化下来。\u003c/p>\u003cp>而复盘的工具特别适用于我们做完一件事或一个项目后使用，但是我们需要注意到复盘总结的经验并非一次就可以成功的，也需要不断把总结的经验应用到下次项目并不断地检验经验的可行性。 \u003c/p>\u003cp>why\u003c/p>\u003cp>2. 如果按照这篇文章的核心观点进行复盘，有以下好处：\u003c/p>\u003cp>- 提高工作的质量和效率，确保目标的实现。\u003c/p>\u003cp>- 通过分析原因和总结经验，可以不断改进和提升自己的能力和技巧。\u003c/p>\u003cp>- 避免重复犯错，减少经济损失和负面影响。\u003c/p>\u003cp>如果不进行复盘，可能会导致以下严重后果：\u003c/p>\u003cp>- 工作结果与目标不符，浪费了时间和资源。\u003c/p>\u003cp>- 无法及时发现和解决问题，导致问题的积累和恶化。\u003c/p>\u003cp>- 无法吸取经验教训，重复犯错，影响个人和团队的发展。\u003c/p>\u003cp>生活中常见的反面案例：- \u003c/p>\u003cp>我与爱人之间，常常因为没有进行复盘，导致沟通不畅，关系紧张，影响了家庭和谐。\u003c/p>\u003cp>达到核心观点的四个主要步骤是：\u003c/p>\u003cp>- 回顾目标：明确当时做事的目的和初衷，回忆自己希望达到的结果。\u003c/p>\u003cp>- 评估结果：对照最初设定的目标，客观地评估现在完成的情况，看是否一致。\u003c/p>\u003cp>- 分析原因：仔细分析事情成功或失败的原因，找出关键节点，找出问题所在。\u003c/p>\u003cp>- 总结经验和规律：得出经验教训，总结出规律，制定下一步的行动计划。\u003c/p>\u003cp>正面案例：（把反面案例变成正面案例）\u003c/p>\u003cp>- 某人在与家人沟通后，回顾目标是和睦相处，评估结果发现沟通不畅，分析原因发现是双方都没有倾听对方的观点，于是下一次改变了沟通方式，关系得到改善。\u003c/p>","interaction":"\u003cp>A1反面案例：今年初，我开了一家AI自习室，但在经营过程中出现了很多问题。在没有按照复盘的步骤进行分析和总结的情况下，导致了严重后果。\u003c/p>\u003cp>时间：今年初\u003c/p>\u003cp>地点：AI自习室\u003c/p>\u003cp>人物：我、员工、学生、兼职督学老师\u003c/p>\u003cp>发生了什么：在经营过程中，我没有及时留住员工，导致人员流动频繁，影响了教学质量和学生的学习体验。我也没有关注到部分孩子的心理动态，没有及时发现和解决他们的问题，导致他们的学习情绪和兴趣受到了影响。与兼职督学老师之间的交流也不够，导致教学内容和进度不够顺利。此外，我自己也没有跟进关键步骤，导致一些重要事务的处理不及时。\u003c/p>\u003cp>导致的严重后果：经济损失，因为员工流动频繁和教学质量下降，导致学生的满意度和口碑下降，学生的流失增加，进而影响了收入。同时，学生的学习体验感很差，他们的学习成果没有达到预期。我也因此感到沮丧和失去信心，对自己的能力产生怀疑。\u003c/p>\u003cp>反思：根据梳理的达到核心观点的四个主要步骤，主要问题出在以下几个方面：\u003c/p>\u003cp>- 没有评估结果：我没有对照最初设定的目标，客观地评估自己的经营情况，没有及时发现和解决问题。\u003c/p>\u003cp>- 没有分析原因：我没有仔细分析事情成功或失败的原因，没有找出关键节点和问题所在，导致问题得不到解决。\u003c/p>\u003cp>【A2】催化应用（目标+行动）\u003c/p>\u003cp>目标：在未来一个月内，招收10-20个孩子来学习，并提供优质的学习体验。\u003c/p>\u003cp>行动计划：\u003c/p>\u003cp>1. 回顾目标：明确每个月的招生目标和细分计划，确保目标具体可行。\u003c/p>\u003cp> - 制定每个月的招生目标和计划，并将其具体细分到每周。\u003c/p>\u003cp> - 设定每周的招生任务和具体行动计划，如推广活动和宣传策略。\u003c/p>\u003cp>2. 评估结果：定期对照目标和实际招生情况，评估是否达到预期结果。\u003c/p>\u003cp> - 每周进行招生情况的统计和分析，对比目标和实际招生人数。\u003c/p>\u003cp> - 根据评估结果，及时调整招生策略和行动计划，以提高招生效果。\u003c/p>\u003cp>3. 分析原因：仔细分析成功和失败的原因，找出关键节点和问题所在。\u003c/p>\u003cp> - 定期回顾招生过程中的关键节点，如推广渠道、宣传效果等，并分析其影响因素。\u003c/p>\u003cp> - 找出招生过程中存在的问题，如招聘人员培训、学生关注度等，并寻找解决方案。\u003c/p>\u003cp>4. 总结经验和规律：总结招生经验教训，总结出规律，并制定下一步的行动计划。\u003c/p>\u003cp> - 每月末总结招生经验和教训，归纳出有效的招生规律和经验。\u003c/p>\u003cp> - 根据总结的经验和规律，制定下一个月的行动计划，包括招生策略、培训计划等。\u003c/p>\u003cp>以上就是我今天分享的内容，下面我再次来回复一下复盘的四个步骤，一、回顾目标，二、评估结果，三、分析原因、四、总结经验，希望通过今天的学习分享，大家都能领悟到复盘的精髓并对自己未来的工作和生活不断精进。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1716826036000,"updated_at":1725240831000,"ria":true},{"id":16471,"topic":"复盘，把经验转化为能力","learn_goal":"","remark":"通过在企业中使用复盘技术，避免出现屡教不改的问题，帮助企业提升绩效，提高组织整体能力。","level":"TF3-1","duration":60,"status":30,"type":0,"chaishujia":{"username":"[email]","city":"银川"},"club":{"name":"银川拉拉缨分舵","city":"银川"},"prologue":"\u003cp>\u003cstrong>一、 开场\u003c/strong>\u003cbr>\u003cstrong>1. 【主题介绍】\u003c/strong>\u003cbr>欢迎大家参加我 TF3-1 拆书晋级活动。今天我拆书的主题是——复盘，如何把经验转化为能力。\u003cbr>\u003cbr>\u003cstrong>2. 【自我介绍】\u003c/strong>\u003cbr>首先介绍一下我自己，我是来自银川筹备分舵的李永忠，木子李，永远的永，忠诚的忠，永远忠于内心就是我。\u003cbr>我也有三个标签：\u003cbr>第一个标签是[网络安全]，主业\u003cbr>第二个标签是[生涯规划师]，副业。\u003cbr>第三个标签是[终身学习的二级拆书家]。\u003cbr>【分组，根据参与人员数量具体确定】今天我们就自成一个大组，直接分享和讨论。\u003cbr>\u003cbr>\u003cstrong>3. 【学习目标】\u003c/strong>\u003cbr>在跟随我完成本次 RIA 现场学习后，学习者在现场就能够使用（行为）复盘的四步法（界定），对一件事复盘（澄清），萃取有价值的做法和经验，应用到以后的工作生活中。\u003cbr>\u003cbr>\u003cstrong>4. 【图书介绍】\u003c/strong>\u003cbr>今天我要拆解的书是邱昭良写的《复盘+：把经验转化为能力》。\u003cbr>[事件] 前两天，公司技术部的项目经理小王，被领导批评：小张那个项目刚刚犯的错，你这个项目又来了，怎么就屡教不改呢？小王一脸委屈的嘟囔：我也不知道这种事情以前发生过？\u003cbr>[提问]大家有没有过类似的经历，你们是怎么解决这种屡教不改的情况呢？解决的效果怎么样呢？\u003cbr>[影响]犯同样的错误，不仅浪费资源，而且个人能力也会被严重怀疑。工作效率不高，工作成果不好，影响个人成长，甚至有的错误直接影响到公司的生死存亡。\u003cbr>[解决]不管是组织或个人，都可以避免犯同样的错误。这本书介绍的复盘方法，借助结构化思考工具，找到事物内在规律，萃取经验转化成能力，避免重蹈覆辙。\u003c/p>","ratings_count":1,"texts":[{"id":20595,"quote":"\u003cp>\u003cstrong>二、【R 原文片段】\u003c/strong> \u003c/p>\u003cp>【 这是原文的片段，我已经放在了屏幕上，片段来自《复盘+：把经验转化为能力》的 P25，请大家读一下。】 \u003c/p>\u003cp>“复盘”原是围棋术语，本意是对弈者下完一盘棋之后，重新在棋盘上把对弈过程摆一遍，看看哪些地方下得好，哪些下得不好，哪些地方可以有不同甚至是更好的下法等。 \u003c/p>\u003cp>这个把对弈过程还原并且进行研讨、分析的过程、就是复盘。通过复盘，棋手们可以看到全局以及整个对弈过程，了解棋局的演变，总结出适合自己和不同对手的套路，或找到更好的下法，从而实现自己棋力的提升。\u003c/p>\u003cp>用到企业管理中，复盘指的是从过去的经验、实际工作中进行学习，帮助管理者有效地总结经验、提升能力、实现绩效的改善。\u003c/p>","explains":"\u003cp>\u003cstrong>三、【I 拆书家讲解引导】\u003c/strong> \u003c/p>\u003cp>1.\u003cstrong>【WHAT&amp;WHY】\u003c/strong> \u003c/p>\u003cp>这个拆页讲的是复盘，就是把对弈过程重摆一遍，找出好的和不好的下法，并探索不同甚至更好的下法。把复盘用到企业中，就是从过去的工作中总结经验，实现能力提升和绩效改善。 \u003c/p>\u003cp>为什么要做复盘呢？因为复盘能让我们不犯过去曾经犯过的错误，可以避免“重复交学费“，可以快速分享经验教训，可以提升组织整体智商。 \u003c/p>\u003cp>2.\u003cstrong>【概念辨析】\u003c/strong> \u003c/p>\u003cp>通过如下几个例子，我们来判断以下是行为是否和复盘有关： \u003c/p>\u003cp>举例1.小明在周五对本周工作进行了汇总，总结出上周完成了5项工作。请问这和复盘有关吗？ \u003c/p>\u003cp>[可能的回答]：无关。 \u003c/p>\u003cp>[回应与反馈]不属于复盘。只是完成了汇总，对于原目标和5个工作没有阐述，同时也没有得出没完成的差距和完成的经验分析。 \u003c/p>\u003cp>举例 2: 朋友高分通过考试，想邀请你和他一起分析一下这次考试高分通过的原因。请问这和复盘有关吗？ \u003c/p>\u003cp>[可能的回答]：有关。 \u003c/p>\u003cp>[回应与反馈]这是复盘的一部分。高分通过考试，是结果远远超出预期，这个差距非常有价值。分析超出预期的差距产生的原因是获得经验的途径。成功的经验有助于我们更上一层楼，失败的经验可以避免重蹈覆辙。 \u003c/p>\u003cp>举例 3: 你和朋友把他高分通过考试的事情提炼成 1 个原则和 3 个方法。请问这和复盘有关吗？ \u003c/p>\u003cp>[可能的回答]有关。 \u003c/p>\u003cp>[回应与反馈]这是复盘的一部分。把经验萃取提炼成方法、流程和原则，就具备了做好一件事的能力。 \u003c/p>\u003cp>举例 4:朋友对你说，如果以后有类似的考试就应用好这些方法和原则。请问这和复盘有关吗？ \u003c/p>\u003cp>[可能的回答]有关。 \u003c/p>\u003cp>[回应与反馈]这是复盘的一部分。把萃取提炼到的方法、流程和原则应用的后续的工作生活中，获得更好的成果。 \u003c/p>\u003cp>3.\u003cstrong>【HOW】\u003c/strong> \u003c/p>\u003cp>一个完整的复盘到底应该是什么样的呢？具体来说复盘有四步，我把这四步总结为“寻找黄金圈”（即找价值、Why、What、How）：\u003c/p>\u003cp>第一、回顾评估（找价值）：将实际结果与预期目标回顾评估，找出值得分析的、有价值的差距。\u003c/p>\u003cp>第二、分析反思（找原因 Why）：对差距分析和反思，找到成功或失败的根本原因、关键因素；\u003c/p>\u003cp>第三、萃取提炼（找原则 What）：举一反三，提炼和萃取出方法、流程和指导原则等；\u003c/p>\u003cp>第 四、转化应用（有方法 How）：将提炼到的方法、流程和指导原则，应用于后续工作生活中，获得更好的成果。 \u003c/p>\u003cp>【案例】 \u003c/p>\u003cp>下面我给大家说一下我复盘的故事。今年 4 月份，我通过学习和考试获得了一个很重要的中级证书，关键是有比较难的一部分还获得了高分。我觉得有必要对获得“高分”的意外情况复盘：\u003c/p>\u003cp>\u003cstrong>第一步：回顾评估（找差异）\u003c/strong>。我原本的目标就是顺利通过考试获得中级证书，意外的是其中比较难的一部分还高分通过。“高分通过”就是现状和目标之间的差距，值得进一步分析。\u003c/p>\u003cp>\u003cstrong>第二步：分析反思（找原因 Why）\u003c/strong>。之所以有超出预期的结果，经过分析发现，主要原因还是在于得到了很多老师指导，自己也投入了大量的时间和精力，还用到了多中学习方法。\u003c/p>\u003cp>\u003cstrong>第三步：萃取提炼（找原则 What）\u003c/strong>。通过对“高分通过”的原因分析后，提炼出了一个“三多”的方法，即：“多听、多看、多练”，这是超出预期的重要方法。\u003c/p>\u003cp>\u003cstrong>第四步：转化应用（有方法 How）\u003c/strong>。后续类似的考试，要继续发扬和保持“三多”的方法，争取每次考试都能顺利通过。 \u003c/p>\u003cp>4.\u003cstrong>【WHERE】\u003c/strong> \u003c/p>\u003cp>[适合]：亲自参与实践过的事情：有价值、重要的、未达/超出预期的事情。 \u003c/p>\u003cp>[不适合]： \u003c/p>\u003cp>1）他人之事。因为你没有亲身实践，不清楚有些事实，无法完整的执行整个复盘的逻辑； \u003c/p>\u003cp>2）尚未发生的事情。只能预想，不能复盘； \u003c/p>\u003cp>3）简单的事情。简单的事情脉络清晰，持续时间短，调用资源少，复盘没有意义。 \u003c/p>\u003cp>5.\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>有的小伙伴可能会说，复盘不一定就能总结出好的经验，提升能力吧？\u003c/p>\u003cp>确实不一定。第一得看这件事本身是否重要、是否有价值；第二还得看复盘主持人的能力（个人复盘的话，得看个人复盘经验；团队复盘的话，得看复盘主持人的能力以及其他人的配合程度）。不过，只要按复盘四步法复盘了，一定会有所收获。建议从个人复盘做起，经验越丰富，复盘的效果就越好。\u003c/p>","interaction":"\u003cp>\u003cstrong>四、【A 学习者拆为己用】\u003c/strong> \u003c/p>\u003cp>1.\u003cstrong>【A2 编剧本】\u003c/strong> \u003c/p>\u003cp>请大家想一想，有什么事情告一段落或者结束了。比如一个项目、一次学习考试、一个训练营等等，不管成功还是失败。在未来一周或一月内，你想对这个事情进行复盘，萃取经验。请大家编写一个复盘的剧本，在屏幕的右边我给出了一个剧本的案例。不用讨论，完成之后小伙伴分享一下。 请大家想想类似的事情，用 5 分钟自己把这件事编写成一个小剧本，几百字即可。要求如下： 1）剧本要求有人物、情节（事情的起因、经过、结果）和当时双方的对话、动作等。 \u003c/p>\u003cp>2）剧本内容可以是你和朋友一起针对某件事进行复盘，也可以是你自己和内心的对话； \u003c/p>\u003cp>3）剧本中要用到复盘的四步法：回顾评估（找差异）、分析反思（找原因）、萃取提炼（找原则）、转化应用（有方法）。 \u003c/p>\u003cp>【下发指令，1 分钟。深入讲解剧本要求及答疑 3 分钟，编写小剧本 3 分钟，分享 3-5 分钟。】 \u003c/p>\u003cp>下面我们请一位小伙伴分享一下自己的剧本：\u003c/p>\u003cp>我对3-3的过级做个复盘，时间就是接下来的两天，地点在书房。\u003c/p>\u003cp>首先我会问自己，3-3通过之后有什么想法？找差距的话，我的目标是达成的。我想说不足之处是，以前没有做过线下过级，当时听到后没有及时调整，还是使用了tx视频会议，当然音频也是有的，只是效果有点差。另外就是PPT忘了翻。\u003c/p>\u003cp>原因就在于没有经验，从来没有线下过级的经验，之前也没有练过没有模拟过。之前线上模拟过3-3，但没有模拟过线下应该怎么操作。应该要提前准备，并且模拟练习，查漏补缺。下一步在进行这样的活动的时候，还是需要事先的模拟或者推演，尽可能把可能发生的状况都预料到，预备好解决的方法或者替代方案，不会出现严重的疏漏。\u003c/p>\u003cp>转化应用就是提前预演。希望以后不管是线上还是线下，拆书课什么的，做的更从容、效果更好。\u003c/p>\u003cp>【反馈和回应】谢谢芷旭老师的分享，这个分享不仅对以后的拆书课有提升，对我自己过3-3也有借鉴作用。这个故事有人物、有情节，而且用到了复盘的四步法。我相信通过这次简单的复盘，你已经掌握了复盘的基本方法。非常感谢芷旭老师的分享，由于时间关系，就不请其他小伙伴来分享了。 \u003c/p>\u003cp>2.\u003cstrong>【总结】（1 分钟）\u003c/strong> \u003c/p>\u003cp>好的，下面由我来总结一下，复盘四步就是第一回顾评估（找差距），经验来源于差；第二分析反思（找原因），一定要深入分析找到本质原因；第三萃取提炼（找原则），要举一反三，发现可行的方法、流程和指导原则；第四转化应用（有方法），要把提炼出来的方法、流畅和原则应用到未来类似的事情当中。\u003c/p>\u003cp>我今天的分享就到这里，感谢各位小伙伴的聆听和陪伴，希望大家今后都可以使用复盘的方法，把经验转化为能力，让自己持续精进\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1692860328000,"updated_at":1692879334000,"ria":true},{"id":16090,"topic":"复盘+把经验转化为能力","learn_goal":"","remark":"纸上得来终觉浅，绝知此事要躬行。\n没有成功经验可以借鉴，只能靠自己摸索，具体该如何操作？\n不犯曾经犯过的错误，不被同一块石头绊倒，谈何容易？\nVUCA时代，复盘让你“温故而知新”，助你将过去的经验转化为能力，并激发创新！我们需要对失败复盘，避免重复犯错，更需要对成功复盘，才能不断复制成功。 ","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"是燕子吖","city":"长沙市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>大家好，我是燕子，我是一个爱学习、爱养生、爱旅游的业余吃货；\u003c/p>\u003cp>由于本身从事传媒行业相关工作，我每天都会看电影、看电视剧、看综艺、读书来学习行业技能和热点，希望有追电影、追剧爱好的一起分享嘞；\u003c/p>\u003cp>我还爱养生，每天坚持早睡早起，保持良好精神面貌，虽然还算年轻但始终坚持“保温杯里泡枸杞”的优良作风，还老爱分享老年养生公众号；\u003c/p>\u003cp>我还爱旅游，每一年我都会安排自己1-2次旅游。\u003c/p>\u003cp>希望可以在拆书帮交到志同道合的朋友、锻炼自己的演讲表达能力，然后成为三级拆书家，与大家一起知识赋能。\u003c/p>\u003cp>【学习目标】本次拆书页主要讲的是通过回顾评估、分析反思、萃取提炼、转化应用的方式，来复盘自己所经历的事件、项目、活动，通过这种复盘的方法从而将自己的经验转化为能力进而逐步成为人生赢家。\u003c/p>\u003cp>\u003cstrong>【图书介绍】（预计时间：1分钟）\u003c/strong>\u003c/p>\u003cp>【Feature特征】：\u003c/p>\u003cp>《复盘+》是一本关于工作方法的书，作者叫陈中。这本书是陈中所著，由联想董事长柳传志唯一审读并指导修改书籍，联想复盘术是中国做得最好得，这本书讲的是复盘的内容、价值、方法、步骤和检验原则，非常有阅读价值。\u003c/p>\u003cp>【Advantage优势】：\u003c/p>\u003cp>这本书的一大亮点就是它从自我复盘、团队复盘、项目复盘三个层面做了不同程度的介绍，并且每一个复盘类型都会列举1-2个国内+国外复盘案例来解说，从理论到案例，再从案例到理论来解说。\u003c/p>\u003cp>【Benefit利益、好处】：B1\u003c/p>\u003cp>复盘是一种“温故而知新”的能力，帮助你将过去的经验转化为能力，并激发创新！在学习和工作的过程中，我们经常就某些方面反复掉进同一个坑里，本书将告诉我们通过复盘可以在经历中总结经验，把经验转化为做事的能力，避免再犯同样的错误，为以后做事节省时间和精力。 \u003c/p>\u003cp>【Benefit利益、好处】：B2\u003c/p>\u003cp>同时，通过书籍的学习，你可以总结经验发挥自己的优势、避免自己的劣势并将自己的总结经验应用到接下来的生活和工作中。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>后面因为要请小伙伴来分享，所以现在我进行一下分组，分组具体如下：依据人数情况，大概2~3人一组。\u003c/p>","ratings_count":2,"texts":[{"id":20175,"quote":"\u003ch2>\u003cstrong>l\u003c/strong> \u003cstrong>R：阅读原书拆页（预计时间：2分钟）\u003c/strong>\u003c/h2>\u003cp>【主 题】： 自我复盘、赋能\u003c/p>\u003cp>【片段来源】： 复盘+把经验转化为能力\u003c/p>","explains":"\u003cp>好，我看到大家都已经看完拆页了，那么接下来我就来分享下我对这个拆页的理解和体会。\u003c/p>\u003cp>【What】：\u003c/p>\u003cp>这个片段主要讲的是复盘的步骤，我们可以根据事件本身的大小、重要程度及复杂程度进行不同方式的回顾、反思、推演、总结，改进，从经验中获得提升，这就是复盘对个人学习和成长的意义。个人复盘适用于个人对其亲生经历的活动/事件以及项目进行结构化总结，促进个人成长。\u003c/p>\u003cp>【Why】：\u003c/p>\u003cp>【人们常规的做法】每个人都会经历成功与失败，正是每一个经历成就现在的你，复盘过才能将经验沉淀下来转变成属于自己的能力，坚定淡然地走向未来。生活中，你是否经常发现自己有些任务总是完不成？或者有些任务总能快速完成？又或者刚完成一个项目就急急忙忙的进入另一个项目？\u003c/p>\u003cp>【不这么做的坏处】 那么，如果你总是一个任务接着一个任务的执行、一个项目接着一个项目去完成，但结果总是不尽人意。那么很可能总是稀里糊涂的成功、亦或者是接二连三的失败。所以，我们需要复盘。需要把经验转化为自己的能力，为自己赋能！否则你很可能在同一个地方摔跤…却不知道摔倒的原因。只有及时复盘、复盘后再出发我们才能在人生的道路上披荆斩棘、无所不惧。\u003c/p>\u003cp>【How】：\u003c/p>\u003cp>【拆页行动建议】\u003c/p>\u003cp> \u003cstrong>1.回顾与评估\u003c/strong>\u003c/p>\u003cp> 复盘的第一步是回顾预期的目标，要将实际结果与预期目标进行对比，找出差异或差额。\u003c/p>\u003cp> \u003cstrong>2.分析与反思\u003c/strong>\u003c/p>\u003cp> 经过对比，找出亮点或不足\u003c/p>\u003cp> \u003cstrong>3.萃取与提炼\u003c/strong>\u003c/p>\u003cp> 在亮点和不足中寻找新的启发，提炼经验，学到了什么。\u003c/p>\u003cp>\u003cstrong>4.\u003c/strong> \u003cstrong>转化与应用\u003c/strong>\u003c/p>\u003cp>将上述提炼萃取的经验，放入到接下来的生活中，进行下一步的行动，即现在开始需要做什么？停止做什么？继续做什么？\u003c/p>\u003cp>【Where】\u003c/p>\u003cp>当然也许你认为什么事情都不值复盘，因为人算不如天算，一切都是命。也许你对某项活动只是消遣，比如我看一些解压的书籍，不就是放松吗？干嘛费劲去复盘。但是复盘适用于人生的每个转折、阶段性规划，如：5年规划、10年规划、离职后/入职前、分手后/恋爱前、离婚后/再婚前…或者是某个项目的结束，也适用于阶段性反省。不适用于间隔时间太短、案例不够具完整性的事件。\u003c/p>\u003cp>【例子】\u003c/p>\u003cp>接下来我给大家分享一个我的案例。\u003c/p>\u003cp>今年上半年，我的体重飙升了十多斤，于是3月份时候就找了个瑜伽班打算启动减肥计划，但是经过3个月的时间，体重是一点没减下来。接下来，我用四步法来分析下以上的案例。\u003c/p>\u003cp>\u003cstrong>1、回顾与评估\u003c/strong>\u003c/p>\u003cp>回顾目标：3月开始练习瑜伽减肥，既没有具体完成任务时间，也没有具体减肥指标数字。\u003c/p>\u003cp>具体什么时间内完成多少公斤的减肥计划不具体，注定任务失败。\u003c/p>\u003cp>\u003cstrong>2、分析与反思\u003c/strong>\u003c/p>\u003cp>亮点：有计划就行动；\u003c/p>\u003cp>不足：目标不具体，计划和行动也不具体；\u003c/p>\u003cp>\u003cstrong>3、提取与淬炼\u003c/strong>\u003c/p>\u003cp>经验提取：1是制定目标时候要具体，明确具体的目标、执行计划、行动计划以及相应的奖励；2是有想法要付诸行动；\u003c/p>\u003cp>\u003cstrong>4、转化与应用\u003c/strong>\u003c/p>\u003cp>接下来要做的：指定目标要结合主客观、分解目标要有准确清晰的计划和行动；\u003c/p>\u003cp>要停止做的：不可拍脑袋定目标或者无目标的行动；\u003c/p>\u003cp>要继续做的：将想法付诸行动而不是停留在想法；\u003c/p>","interaction":"\u003ch2>\u003cstrong>l\u003c/strong> \u003cstrong>A2：分步骤催化（小组内分享且有1人发言，预计时间：4分钟）\u003c/strong>\u003c/h2>\u003cp>设想下，下周，你和你的同事就前段时间做的一个工作进行回顾，时间真快，2023年余额不足半年了，是不是应该对最近发生的事件，或者学习内容做一个复盘呢？你最想复盘的内容是什么呢，同时回想下，你想要确定的复盘内容是什么？初始目标是什么？请大家先在小组内分享，时间为2分钟。好了，时间到，下面我请一位小伙伴来分享一下他的应用的场景。\u003c/p>\u003cp>【组内分享】\u003c/p>\u003cp>学习者A：给湖大学生做关于大客户销售技能的培训，2个目标：1是让学员掌握大客户销售技能；2是让学员轻松愉快高效的掌握而不是学了记不住；\u003c/p>\u003ch2>\u003cstrong>l\u003c/strong> \u003cstrong>A2：催化应用（预计时间：4分钟）\u003c/strong>\u003c/h2>\u003cp>【反思加工指令，强调加工未来的场景】刚才大家分享了自己要完成的任务以及该任务的初始目标，那么请你们按我发给你们的复盘4步骤提问清单和已确定的复盘内容， 22分组进行分享，即一个人按清单提问，一个按自己确定的复盘内容客观的回答。时间是5分。\u003c/p>\u003cp>我看大家分享的很热烈，现在请一个小伙伴分享下自己用复盘四步骤来复盘自己确定的内容。\u003c/p>\u003cp>【组内分享】\u003c/p>\u003cp>学习者 A：给湖大学生做关于大客户销售技能的培训：\u003c/p>\u003cp>\u003cstrong>1、回顾与评估\u003c/strong>\u003c/p>\u003cp>回顾目标：2个目标：1是让学员掌握大客户销售技能；2是让学员轻松愉快高效的掌握而不是学了记不住；\u003c/p>\u003cp>\u003cstrong>2、分析与反思\u003c/strong>\u003c/p>\u003cp>亮点：课程轻松幽默；\u003c/p>\u003cp>不足：内容太多，时间不够用；\u003c/p>\u003cp>\u003cstrong>3、提取与淬炼\u003c/strong>\u003c/p>\u003cp>经验提取：课程设计要考虑可实操性\u003c/p>\u003cp>\u003cstrong>4、转化与应用\u003c/strong>\u003c/p>\u003cp>接下来要做的：把要放入学习的内容按照逻辑列出更加准确明了；\u003c/p>\u003cp>要停止做的：删除价值含量低的；\u003c/p>\u003cp>要继续做的：业务含量高的话术和方法要继续； \u003c/p>\u003cp>【结束语】感谢A小伙伴的分享，给到的一个小建议是：在做目标回顾和结果分析时候，最好能够量化，量化的目标更容易分析出有效的成果。每个人都有自己与生俱来的特殊气质，我们可以阶段性的分析自己的核心优劣势、不断调整不断进步。希望从今天开始，刻意对自己在意的事情复盘，用复盘方式提升自己，让经验产生价值。希望今天的拆页有帮助到大家，我的分享到这里，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1687313247000,"updated_at":1687661436000,"ria":true},{"id":15861,"topic":"复盘，把经验转化为能力","learn_goal":"","remark":"通过结构化的方法对事情进行复盘，总结经验，提升能力，改善绩效。","level":"TF3-1","duration":30,"status":29,"type":0,"chaishujia":{"username":"[email]","city":"银川"},"club":{"name":"银川拉拉缨分舵","city":"银川"},"prologue":"\u003cp>\u003cstrong>一、 开场\u003c/strong>\u003c/p>\u003ch2>1. 【主题介绍】\u003c/h2>\u003cp>欢迎大家参加我TF3-1拆书晋级活动。今天我拆书的主题是——复盘，如何把经验转化为能力。\u003c/p>\u003ch2>2. 【自我介绍】\u003c/h2>\u003cp>首先介绍一下我自己，我是来自银川筹备分舵的李永忠，木子李，永远的永，忠诚的忠，永远忠于内心就是我。\u003c/p>\u003cp>我也有三个标签：\u003c/p>\u003cp>第一个标签是[网络安全]，这个是我的主业。\u003c/p>\u003cp>第二个标签是[二级拆书家]。\u003c/p>\u003cp>第三个标签是[终身学习的践行者]。\u003c/p>\u003cp>【分组】今天我们就自成一个大组，直接分享和讨论。\u003c/p>\u003ch2>3. 【学习目标】\u003c/h2>\u003cp>在跟随我完成本次RIA现场学习后，学习者在现场就能够使用（行为）复盘的四步法（界定），对一件事复盘（澄清），实现总结经验、提炼方法，应用到以后的工作生活中。\u003c/p>\u003ch2>4. 【图书介绍】\u003c/h2>\u003cp>今天我要拆解的书是邱昭良写的《复盘+：把经验转化为能力》。\u003c/p>\u003cp>[事件]公司技术部实施的项目，不管项目经理能力如何，每个项目都没那么顺利。以前项目发生过的老问题还时常在新项目中出现。总是解决不了，一问起来，他们还觉得自己挺委屈的：我也不知道这种事情以前发生过？\u003c/p>\u003cp>[提问]大家有没有遇到过类似的经历，你们是怎么解决这种屡教不改的情况呢？解决的效果怎么样呢？\u003c/p>\u003cp>[影响]犯同样的错误，不仅浪费资源，而且个人能力也会被严重怀疑。工作效率不高，工作成果不好，影响个人成长，甚至有的错误直接影响到公司的生死存亡。\u003c/p>\u003cp>[解决]不贰过，非常难。谁没有犯过同样的错误呢？这本书通过介绍复盘的方法，借助结构化的思考工具，找到事物的内在规律，把经验转化成能力，在一定程度上就可以避免重蹈覆辙。\u003c/p>","ratings_count":1,"texts":[{"id":19939,"quote":"\u003cp>\u003cstrong>二、 【R 原文片段】\u003c/strong>\u003c/p>\u003cp>这是原文的片段，我已经放在了屏幕上，片段来自《复盘+：把经验转化为能力》的P25，请大家读一下。我们请以为小伙伴给大家朗读一下，可以吗？有哪位小伙伴给大家读一下呢？子宽：我来吧。好的，谢谢子宽，那就有你来读一下。\u003c/p>\u003cp>“复盘”原是围棋术语，本意是对弈者下完一盘棋之后，重新在棋盘上把对弈过程摆一遍，看看哪些地方下得好，哪些下得不好，哪些地方可以有不同甚至是更好的下法等。\u003c/p>\u003cp>这个把对弈过程还原并且进行研讨、分析的过程、就是复盘。通过复盘，棋手们可以看到全局以及整个对弈过程，了解棋局的演变，总结出适合自己和不同对手的套路，或找到更好的下法，从而实现自己棋力的提升。\u003c/p>\u003cp>用到企业管理中，复盘指的是从过去的经验、实际工作中进行学习，帮助管理者有效地总结经验、提升能力、实现绩效的改善。\u003c/p>","explains":"\u003cp>\u003cstrong>三、 【I拆书家讲解引导】\u003c/strong>\u003c/p>\u003ch2>1. 【WHAT】\u003c/h2>\u003cp>这个拆页讲的是复盘，就是把经验转化为能力的一种方法。个人可以通过复盘不断成长，企业可以通过团队复盘提升能力改善绩效。\u003c/p>\u003ch2>2. 【WHY】\u003c/h2>\u003cp>为什么要做复盘呢？就是从过去的事情中获得经验，提升能力，应用在以后的工作生活中获得更好的成果。\u003c/p>\u003ch2>1. 【概念与案例相互参照】\u003c/h2>\u003cp>复盘就是从已经发生的事情中获取经验，并把这些经验转化为能力，应用到后续的工作生活中，获得更好的成果。\u003c/p>\u003cp>复盘注重把经验转化为能力，促进个人和组织不断成长。因此可以看出，复盘有三个关键要素：经验、能力（方法）和应用。\u003c/p>\u003cp>下面我举个例子：\u003c/p>\u003cp> 举例1:快下班的时候，朋友对你说：晚上我想邀请你和我一起对下周的考试做个复盘。请问这属于复盘吗？\u003c/p>\u003cp>[可能的回答]：不属于。\u003c/p>\u003cp>[回应与反馈]不属于复盘。根据今天拆页的内容，复盘针对过去发生的事情，对于还没有发生的事情不能复盘。\u003c/p>\u003cp> 举例2: 朋友高分通过高考，想邀请你和他一起分析一下这次考试高分通过的原因。请问这属于复盘吗？\u003c/p>\u003cp>[可能的回答]：属于复盘。\u003c/p>\u003cp>[回应与反馈]这是复盘的一部分。高分通过考试，是结果远远超出预期，这个差距非常有价值。分析超出预期的差距产生的原因是获得经验的途径。这和复盘三个关键要素中的经验有关。成功的经验有助于我们更上一层楼，失败的经验可以避免重蹈覆辙。\u003c/p>\u003cp>举例3: 你和朋友把他高分通过考试的事情提炼成了1个原则和3个方法。请问这属于复盘吗？\u003c/p>\u003cp>[可能的回答]属于复盘的一部分。\u003c/p>\u003cp>[回应与反馈]这是复盘的一部分。把经验萃取提炼成方法、流程和原则，就具备了做好一件事的能力。这和复盘三个关键要素中的能力（方法）有关。\u003c/p>\u003cp>举例4:朋友对你说，如果以后有类似的考试就应用好这些方法和原则。请问这属于复盘吗？\u003c/p>\u003cp>[可能的回答]属于复盘的一部分。\u003c/p>\u003cp>[回应与反馈]这是复盘的一部分。把萃取提炼到的方法、流程和原则应用的后续的工作生活中，获得更好的成果。这和复盘三个关键要素的应用有关。\u003c/p>\u003cp>只有同时具备这三个关键要素，才能称为复盘。\u003c/p>\u003ch2>4. 【HOW】\u003c/h2>\u003cp>复盘怎么做呢？具体来说有四步，我把这四步总结为“寻找黄金圈”（即找差距、Why、What、How）：\u003c/p>\u003cp>第1、 回顾评估（找差距）：将实际结果与预期目标回顾评估，找出值得分析的、有价值的差距。\u003c/p>\u003cp>第2、 分析反思（找原因Why）：对差距分析和反思，找到成功或失败的根本原因、关键因素；\u003c/p>\u003cp>第3、 萃取提炼（找原则What）：举一反三，提炼和萃取出方法、流程和指导原则等；\u003c/p>\u003cp>第4、 转化应用（有方法How）：将提炼到的方法、流程和指导原则，应用于后续工作生活中，获得更好的成果。\u003c/p>\u003cp>【案例】\u003c/p>\u003cp>下面我给大家说一下我复盘的故事。今年4月份，我通过学习和考试获得了一个很重要的中级证书，关键是有比较难的一部分还获得了高分。我觉得有必要对获得“高分”的意外情况做个复盘：\u003c/p>\u003cp>第一步：回顾评估（找差异）。我原本的目标就是顺利通过考试获得中级证书，意外的是其中比较难的一部分还高分通过。“高分通过”就是现状和目标之间的差距，值得进一步分析。\u003c/p>\u003cp>第二步：分析反思（找原因Why）。之所以有超出预期的结果，经过分析发现，主要原因还是在于得到了很多老师指导，自己也投入了大量的时间和精力。\u003c/p>\u003cp>第三步：萃取提炼（找原则What）。通过对“高分通过”的原因分析后，提炼出了一个“三多”的方法，即：“多听、多看、多练”，这是超出预期的重要方法。\u003c/p>\u003cp>第四步：转化应用（有方法How）。后续类似的考试，要继续发扬和保持“三多”的方法，争取每次考试都能顺利通过。\u003c/p>\u003ch2>5. 【WHERE】\u003c/h2>\u003cp>[适合]：亲自参与实践过的事情：有价值、重要的、未达/超出预期的事情。\u003c/p>\u003cp>[不适合]：\u003c/p>\u003cp>1）他人之事。因为你没有亲身实践，不清楚有些事实，无法完整的执行整个复盘的逻辑；\u003c/p>\u003cp>2）尚未发生的事情。只能预想，不能复盘；\u003c/p>\u003cp>3）简单的事情。简单的事情脉络清晰，持续时间短，调用资源少，复盘没有意义。\u003c/p>\u003ch2>6. 【预防异议】\u003c/h2>\u003cp>有的小伙伴可能会说，复盘不一定就能总结出好的经验，提升能力吧？\u003c/p>\u003cp>确实不一定。第一得看这件事本身是否重要、是否有价值；第二还得看复盘主持人的能力（个人复盘的话，得看个人复盘经验；团队复盘的话，得看复盘主持人的能力以及其他人的配合程度）。不过，只要按复盘四步法复盘了，一定会有所收获。建议从个人复盘做起，有经验了再做团队复盘。\u003c/p>","interaction":"\u003cp>\u003cstrong>四【A学习者拆为己用】\u003c/strong>\u003c/p>\u003ch2>1. 【A2编剧本】\u003c/h2>\u003cp>请大家想一想，在未来的一周或者一月内，有什么事情告一段落或者结束了。比如你的一个项目、一次学习考试、一个训练营等等。不管成功还是失败。你想对这个事情进行复盘，总结经验。需要大家编写一个剧本，在屏幕的右边我给出了一个剧本的案例。不用讨论，完成之后小伙伴分享一下。\u003c/p>\u003cp>请大家想想类似的事情，用5分钟自己把这件事编写成一个小剧本，几百字即可。要求如下：\u003c/p>\u003cp>1）剧本要求有人物、情节（事情的起因、经过、结果）和当时双方的对话、动作等。\u003c/p>\u003cp>2）剧本内容可以是你和朋友一起针对某件事进行复盘，也可以是你自己和内心的对话；\u003c/p>\u003cp>3）剧本中要用到复盘的四步法：回顾评估（找差异）、分析反思（找原因）、萃取提炼（找原则）、转化应用（有方法）。\u003c/p>\u003cp>【下发指令，1分钟。深入讲解剧本要求及答疑3分钟，编写小剧本3分钟，分享3-5分钟。】\u003c/p>\u003cp>【我的剧本，把剧本简单介绍一下】\u003c/p>\u003cp>下面我们请一位小伙伴分享一下自己的剧本：\u003c/p>\u003cp>分享一（丽静）：我准备下周对我考中级设工的考试做一个复盘。人物就是我自己。\u003c/p>\u003cp>事情的起因是考试有一门综合专业没有过，这确实也是我的一个难点。今年拿不到证书，没有达到目标。一共三科，其他两科过了。\u003c/p>\u003cp>我会问我自己：这次考试感觉怎么样？\u003c/p>\u003cp>回答：我已经很努力了，我也看了书了，视频也听了，可是还是失败了。\u003c/p>\u003cp>这是评估回顾找差距。差距就是综合这科我没有过。导致今年没有拿到证。\u003c/p>\u003cp>第二步分析反思找原因：\u003c/p>\u003cp>我会问：综合这一科为什么没有通过考试？\u003c/p>\u003cp>回答：就是难点、理论的东西太复杂，没有掌握好。考试的时候反反复复的修改，又改错了几个。其他原因可能还是重视程度不够。\u003c/p>\u003cp>接下来就是萃取提炼找原则。\u003c/p>\u003cp>我会问：那用什么方法解决这些问题呢？\u003c/p>\u003cp>回答：首先就是重点难点部分，心里有畏惧，看的时候还是又点儿抵触。需要多练习、多投入时间，或者多听几个老师来讲，把它弄透。现场改答案的问题，要相信第一感觉，不要反复修改。\u003c/p>\u003cp>第四步转化应用有方法，\u003c/p>\u003cp>我会问：如何准备下次考试？\u003c/p>\u003cp>回答：就是结合刚才说的几个点，投入精力时间把知识点搞懂。\u003c/p>\u003cp>结果就是，相信下一次一定能通过考试。\u003c/p>\u003cp>【反馈和回应】谢谢丽静的分享，这个故事有人物、有情节，而且用到了复盘的四步法。我相信通过这次简单的复盘，你就知道怎么准备考试了。由于时间也不是很多，就不请其他小伙伴来分享了。如果想要分享的话，等我总结完后，大家可以继续分享。\u003c/p>\u003ch2>2. 【总结】（1分钟）\u003c/h2>\u003cp>好的，下面由我来总结一下，复盘四步就是第一回顾评估（找差距），经验来源于差；第二分析反思（找原因），一定要深入分析找到本质原因；第三萃取提炼（找原则），要举一反三，发现可行的方法、流程和指导原则；第四转化应用（有方法），要把提炼出来的方法、流畅和原则应用到未来类似的事情当中。\u003c/p>\u003cp>我今天的分享就到这里，感谢各位小伙伴的聆听和陪伴，希望大家今后都可以使用复盘的方法，把经验转化为能力，让自己持续精进。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1684717116000,"updated_at":1685744049000,"ria":true},{"id":14680,"topic":"不懂复盘，再努力也只是无效的重复。","learn_goal":"","remark":"通过复盘不仅可以让你避免低水平的重复，不再犯同样的错误，还能让成功变得可复制，而非稀里糊涂，全凭运气。","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"Dido","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>大家晚上好，我是张丹丹，微信名Dido。三个标签介绍一下自己，第一个标签，精益生产推行者；第二个标签，控糖饱瘦践行者，第三个标签，二级拆书家。\u003c/p>\u003cp>为了方便后面的讨论，我们先进行一下分组，从我左手边开始，依次两两一组。\u003c/p>\u003cp>对齐一下我们的学习目标。在跟随我完成本次RIA现场学习后，学习者能够运用\u003cstrong>[行为]\u003c/strong>“复盘四步法”\u003cstrong>[澄清]\u003c/strong>，从自己经历的事件中\u003cstrong>[界定]\u003c/strong>，发现实际与目标的差异，找出原因，制定改进方案。\u003cstrong>[行为]\u003c/strong>\u003c/p>\u003cp>首先，和大家分享一个自己的小故事：\u003c/p>\u003cp>上周六天气晴朗，闲来无事，于是约了三五好友，在网红打卡地-隐山茶馆，一起喝茶闲聊。过程中我兴致盎然地分享了-赵玉平老师讲的“ 三顾茅庐背后的沟通启示“。故事分享后，不禁感慨这位老师太厉害了，讲得太精彩了，他竟能从中分析出营销自己的四大套路。这时对面的小李问我：”赵玉平是谁”？我随口反问道：”赵玉平，你都不知道吗？小李听后，停顿了一下，半开玩笑半提醒道，恭喜你，丹丹，又一次，两句话不到，成功把天给聊死了。我连忙用手轻拍嘴巴，懊悔地说道：“瞧我这张嘴”。\u003c/p>\u003cp>你是否也遇到过类似的事件呢？是否在同一件事情上前后犯过几乎一模一样的错误？ \u003c/p>\u003cp>看来不懂复盘，不仅事后让我们内心常常充满了懊悔和自责，还容易得罪人，从而导致人际关系的不和谐。\u003c/p>\u003cp>当我们遇到类似错误重复发生，应该如何做，才能吃一堑长一智，不重复交学费，作者邱邵良在《复盘+》这本书中提出的“复盘四步法”，能够帮助我们解决此类问题。\u003c/p>\u003cp>听完了前面的介绍，你可能想了解自己在实践复盘方面的现状。那接下来，请你做一个简单的测试。请仔细阅读表格中的每句话，并勾出在每一项中你做的如何（1分表示完全做不到，5分表示总是能做到）。\u003c/p>\u003cp>好的，看到大家都完成了自测，我们一起对其结果进行一个解读。总分在20分以上的，请举手示意。非常好！总分在20分以上，说明你的个人复盘不但完整，还能够践行。总分在15-20分之间的，请举手示意。很好！说明你能做一些简易的复盘，但还有提高的空间。总分在1-15分之间的，请举手示意。1-15分说明你今天来对了，对复盘方法的系统学习，非常有必要，相信接下来的分享一定可以帮到你。\u003c/p>","ratings_count":3,"texts":[{"id":18700,"quote":"\u003cp>给大家1分钟时间阅读拆页，OK后，请向我点头示意。好，阅读开始。\u003c/p>\u003cp>\u003cstrong>摘自原文片段P25 -“认识复盘”，出自《复盘》\u003c/strong>\u003c/p>\u003cp>\u003cstrong>什么是复盘\u003c/strong>\u003c/p>\u003cp> “复盘”原是围棋术语，本意是对弈者下完一盘棋之后，重新在棋盘上把对弈过程“摆”一遍，看看哪些地方下得好，哪些下得不好，哪些地方可以有不同甚至是更好的下法，等等。\u003c/p>\u003cp> 这个把对弈过程还原并且进行研讨、分析的过程，就是复盘。通过复盘，棋手们可以看到全局以及整个对弈过程，了解棋局的演变，总结出适合自己和不同对手的套路，或找到更好的下法，从而实现自己棋力的提升。唐代诗人杜牧在《重送绝句》一诗中曾形象生动地描述了他与一位围棋高手对弈之后复盘的场景：“绝艺如君天下少，闲人似我世间无。别后竹窗风雪夜，一灯明暗覆吴图。”\u003c/p>\u003cp> 用到企业管理中，复盘指的是从过去的经验、实际工作中进行学习，帮助管理者有效地总结经验、提升能力、实现绩效的改善。正如联想集团创始人柳传志先生所说：所谓复盘，就是一件事情做完了以后，做成功了，或者没做成功，尤其是没做成功的，坐下来把当时的这个事情，我们预先怎么定的、中间出了什么问题、为什么做不到，把这个要理一遍，理一遍以后，下次再做的时候，自然这次的经验教训就吸收了。\u003c/p>","explains":"\u003cp>好1分钟时间到。没有读完的也没事，接下来跟我一起来看下这个拆页。\u003c/p>\u003cp>【提问1】这一段的“标题”是什么？\u003c/p>\u003cp>【现场1】什么是复盘\u003c/p>\u003cp>【提问2】复盘的本意是指对弈者在下完一盘棋之后，重新在棋盘上把对弈过程“摆”一遍，看看哪些地方下得好，哪些下得不好，哪些地方可以有不同甚至是更好的下法。对吗？\u003c/p>\u003cp>【现场2】对\u003c/p>\u003cp>【提问3】如果用到企业管理中，复盘指的是从过去的经验和实际工作中学习，对吗？\u003c/p>\u003cp>【现场3】对\u003c/p>\u003cp>这个拆页片段，作者分别从围棋术语及在企业管理中的应用，全面讲述了复盘的含义。\u003c/p>\u003cp>那为什么要复盘，因为通过复盘，可以及时发现错误，并采取纠正措施，让我们能从失败或错误中汲取经验和教训，避免低水平的重复或不再犯同样的错误。同时，通过复盘，还可以让我们能知其所以然，事情干成了或失败了，能从中搞清楚“为什么”，而非稀里糊涂，全凭运气。\u003c/p>\u003cp>那复盘对我们的个人价值这么大，如何做复盘呢，主要包含以下四个基本步骤：\u003c/p>\u003cp>1. \u003cstrong>回顾目标\u003c/strong>。在回顾目标时，要罗列出预期的初衷或目标或关键成果。\u003c/p>\u003cp>2. \u003cstrong>评估结果。\u003c/strong>在评估结果时，要以目标为基准，罗列出“亮点-做得好的地方”和“不足-做得不好的地方”。 \u003c/p>\u003cp>3. \u003cstrong>分析原因。\u003c/strong>对成功或失败进行原因分析。多问几次为什么，找到成功的关键因素和失败的根本原因。\u003c/p>\u003cp>4. \u003cstrong>总结经验。\u003c/strong>将罗列出的关键发现，转化为可执行的行动计划，包括具体的行动措施、完成时间和责任人。\u003c/p>\u003cp>针对开头我不超两句就能跟人把天给聊死，事后悔恨事件。运用以上复盘四步法，我会这样做：\u003c/p>\u003cp>1. \u003cstrong>回顾目标\u003c/strong>。在此次的沟通聊天中，我的目标是不说任何贬损他人的话语。\u003c/p>\u003cp>2. \u003cstrong>评估结果。\u003c/strong>结果是未达到目标要求，这属于我的不足。实际场景中，当小李问我谁是赵玉平时，我说了“这你都不知道“-贬损他人的话。\u003c/p>\u003cp>3. \u003cstrong>分析原因。\u003c/strong>失败的根本原因是在跟小李的聊天中，我把关注点全放在自己身上，去炫耀自己很厉害，很博学，却忽略了高清商的聊天要把关注点放在对方的身上。\u003c/p>\u003cp>\u003cstrong>4.\u003c/strong> \u003cstrong>总结经验。\u003c/strong>通过以上的分析，一个关键发现 - 在聊天中，把关注点多放在对方身上。接下来转化为可执行的行动计划 - 在周六的朋友聚会聊天中，当小李向我提问谁是赵玉平时，我要专注于响应对方的需求。我会这样说：”你是想了解一下赵玉平老师的资历背景吗？“\u003c/p>\u003cp> 在进行第三个步骤-分析原因时，你可能习惯于对失败进行根本原因分析。但对成功的关键原因也要进行分析时，会觉得有点不太理解，心里会想，我既然都做成功了，还分析它干嘛，多浪费时间。但其实不然，因为有可能你获得的成功，凭的是运气，自己也不清楚为什么这事就干成了。这时候，就特别需要去分析成功的关键因素或内在机理，让成功不再是偶然，让成功可复制。\u003c/p>\u003cp>对任何事件，无论是个人、团队或组织，只要你觉得有必要，均可进行复盘，但必须自己亲身经历的事件，所以不适用于对他人事件进行复盘。\u003c/p>","interaction":"\u003cp>听完了以上复盘四步法的介绍，接下来我将给出一个案例场景，请大家先在小组内进行讨论和演练，5分钟后，我将邀请其中一组进行角色扮演和分享。\u003c/p>\u003cp>场景描述：小李是你的弟弟，他想考个驾照，可一连考了两次，科目三都挂了科，于是他灰头土脸找你倾诉，希望你能帮他分析分析。而你觉得最了解整个事件经过，只有他自己，于是你准备将刚学习到的复盘四步法教授给他，指导他从中发现问题，找到原因，获得经验教训。\u003c/p>\u003cp>接下来，小组内一人扮演哥哥，一人扮演弟弟，组内演练开始…..\u003c/p>\u003cp>好5分钟时间到，请张老师和驰驰老师分享：\u003c/p>\u003cp>张老师（哥哥）：诶哟，怎么垂头丧气的？\u003c/p>\u003cp>驰驰老师（弟弟）：别提了，科目3挂二次了。\u003c/p>\u003cp>张老师（哥哥）：你最近在搞科目3，考了两次都没过。\u003c/p>\u003cp>驰驰老师（弟弟）：是的。\u003c/p>\u003cp>张老师（哥哥）：跟我说说，科目3都考哪些项目？\u003c/p>\u003cp>驰驰老师（弟弟）：上车准备、起步、直线行驶、变更车道、通过路口、靠边停车\u003c/p>\u003cp>张老师（哥哥）：你是哪个环节没过\u003c/p>\u003cp>驰驰老师（弟弟）：靠边停车\u003c/p>\u003cp>张老师（哥哥）：那你是犯了哪个错误，导致你没过 \u003c/p>\u003cp>驰驰老师（弟弟）：错误就是，不知道是谁，在我准备停车的时候，他突然闯了过来，系统提示有障碍物，你没有远离，就判不过了。\u003c/p>\u003cp>张老师（哥哥）：那你想想，如果以后再遇到这样的情况，你怎么办呢\u003c/p>\u003cp>驰驰老师（弟弟）：下次再遇到这样的情况，后面跟小伙伴商量好，相互之间帮忙看着，大家可以一起先吃个饭，以后遇到这样情况，我们稍微等一下。\u003c/p>\u003cp>张老师（哥哥）：所以说这种意外场景都会发生，但是如何应对，你回去之后可以好好想想，相信下次可以十拿九稳了。\u003c/p>\u003cp>驰驰老师（弟弟）：是的。\u003c/p>\u003cp>非常感谢张老师和驰驰老师的精彩分享。让我们将掌声送给他们。张老师作为哥哥先是带着弟弟回顾了目标，就是要过科目三，接下来又分为几个关键节点。接着评估结果，发现不足，靠边停车未过，然后分析了根本原因-针对突发情况，怎样有一个应急措施，最后找到了关键发现，并制定下一步的行动计划。非常棒。\u003c/p>\u003cp>为了大家更好的应用，我来给大家布置一个回去之后要完成的具体任务。在接下来的一周或一个月内，大家如果遇到类似的场景会怎么做呢？\u003c/p>\u003cp>可以是生活中，如想坚持6点钟早起，写日记、晨跑或是每天睡前不带手机上床，也可以是工作中刚做了一个培训、或是完成了一个项目，可结果未达到预期，又或是做得特别好。请试着运用今天在折页中学习的复盘四步法，1、回顾目标，2、评估结果，3、分析原因，4、总结经验。在2周内完成，并拍照发送到我们的会员群里，也非常期待大家的作业！\u003c/p>\u003cp> 来自微信“鱼戏莲叶间”的作业分享：\u003c/p>\u003cp>场景：在完成组合零件测绘后的总结。\u003c/p>\u003cp>\u003cstrong>第一步：回顾目标：\u003c/strong>在7天内完成一个全新的组合零件A。\u003c/p>\u003cp>\u003cstrong>第二步：评估结果：\u003c/strong>整体零件及时完成，但是出现几个问题：①轴承件1的零件图修改2次②零件2的测绘时间有点长③零件3发外热处理时间占用了三天，导致后面工序时间紧张\u003c/p>\u003cp>\u003cstrong>第三步：分析原因：\u003c/strong>\u003c/p>\u003cp>1 轴承件1比较复杂，如需要清楚零件需要多个视图配合，理清每个视图的作用。\u003c/p>\u003cp>2 零件2刚开始测绘时，并未发现它与之前零件是有细微区别的，导致后来装配推导数据时发现不对，再返回找原因，从而耽误了时间。\u003c/p>\u003cp>3 忘记提前把零件3发外热处理。\u003c/p>\u003cp>\u003cstrong>第四步：总结经验\u003c/strong>\u003c/p>\u003cp>经验一：做配套产品组合件时，整体思路，分—总—分，先单个零件，再装配，再细化每个零件的细节。\u003c/p>\u003cp>经验二：对于复杂零件的表达，要注意其他视图的辅助。\u003c/p>\u003cp>经验三：注意每个零件的材质及工序，需要发外热处理的，提前交申请单。\u003c/p>\u003cp>经验四：测绘零件，每个细节不能大意。 \u003c/p>\u003cp>最后让我们一起回顾一下今天的学习目标，能够运用“复盘四步法”，从自己经历的事件中，发现实际与目标的差异，分析差异原因，获得经验教训。其中关键的四个步骤是：1、回顾目标，2、评估结果，3、分析原因，4、总结经验。在此，也希望大家将复盘四步法应用到日常生活和工作中，让错误不再重复，让成功可以复制。好了，今天的3-2拆书到此结束！谢谢大家的参与和陪伴！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1669604001000,"updated_at":1670303971000,"ria":true},{"id":13346,"topic":"掌握复盘四步法，让你加速成长","learn_goal":"","remark":"没有成功经验，只能自己摸索，怎么办？曾经犯过的错，被同一块石头绊倒两次？VUCA时代，复盘让你“温故而知新”，助你将过去的经验转化为能力，激发创新！对失败复盘，就能避免重复犯错！对成功复盘，才能不断复制成功！","level":"TF3-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"陈俊忠","city":"深圳"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"\u003cp>各位线上的小伙伴大家晚上好，我是今晚的第一位拆书家，我叫陈俊忠。首先简单地再自我介绍一下，我的本职工作是一名HR，目前在一家上市公司从事人才发展的岗位，主要负责学习平台运营、大学生培养以及专业人才培养的工作。然后呢，在拆书帮我目前是一级拆书家，今年的目标是在自己6月份生日前能够成为一名三级拆书家。最后，自己平时比较喜欢运动，例如羽毛球、徒步等等。很高兴今晚能和大家一起交流学习。\u003c/p>\u003cp>今天我的部分拆书将会给大家带来主题为《掌握复盘四步法，让你加速成长》的拆书，时间为25-30min。\u003c/p>\u003cp>\u003cstrong>图书介绍【事件-提问-影响-解决】2min\u003c/strong>\u003c/p>\u003cp>【事件】在日常生活中，我们是否曾经遇到过重复犯某一个错误的经历？例如：在工作中负责某个项目时，曾经因为漏掉了某个环节导致项目进度延期而被领导批评，但后面还是三番两次漏掉某个环节。又例如，你带领的销售团队总是一而再再而三的在销售术语中出现错误。想必我们多少都会有这样的经历。我自己就发生过很多次这样的事情，明明一件事以前犯过错误了，但总是不吸取教训，导致后面又出现一样的错误。\u003c/p>\u003cp>【提问】有句话说得好：吃一堑，长一智。但为什么我们总是会犯了错误还是会再犯呢？我们应该怎么去避免这种重复犯错的情况呢？\u003c/p>\u003cp>【影响】想必很多人都希望能够找到一个比较好的解决办法。因为我们心里清楚，重复犯错不仅会让我们受到批评，让自己的职业发展受到影响，也会极大打击自己的自信心，怀疑自己的能力。\u003c/p>\u003cp>【解决】所以，今天给大家带来的这本书就能够帮助大家去改善这个问题。我将会在今天的拆书中给大家介绍复盘的四个步骤，让大家能够运用这个工具避免重复犯错，把自己的过往经验快速转变成自己的能力沉淀。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>此次拆书的学习目标是：在跟随我完成本次RIA现场学习后，学习者能够陈述复盘的四个步骤，能够运用复盘的四个步骤进行剧本设计，并进行演绎。\u003c/p>","ratings_count":2,"texts":[{"id":17356,"quote":"\u003cp>\u003cstrong>什么是复盘\u003c/strong>\u003c/p>\u003cp>“复盘”原是围棋术语，本意是对弈者下完一盘棋之后，重新在棋盘上把对弈过程摆一遍，看看哪些地方下得好，哪些下得不好，哪些地方可以有不同甚至是更好的下法等。\u003c/p>\u003cp>这个把对弈过程还原并且进行研讨、分析的过程、就是复盘。通过复盘，棋手们可以看到全局以及整个对弈过程，了解棋局的演变，总结出适合自己和不同对手的套路，或找到更好的下法，从而实现自己棋力的提升。\u003c/p>\u003cp>用到企业管理中，复盘是指从过去的经验、实际工作中进行学习，帮助管理者有效地总结经验，提升能力，实现绩效的改善。正如联想集团创始人柳传志先生所说：\u003cstrong>所谓复盘，就是一件事情做完了以后，做成功了，或者没做成功，尤其是没做成功的，坐下来把当时的这个事情，我们预先怎么定的、中间出了什么问题、为什么做不到，把这个过程要理一遍，理一遍之后，下次再做的时候，自然这次的经验教训就吸收了\u003c/strong>。\u003c/p>","explains":"\u003cp>【what、why】这个拆页跟我们讲了什么是复盘以及如何做复盘。从拆页中我们可以了解到，复盘概括来说就是当一件事情结束后，重新把这件事的整个过程进行梳理，包括你当时定的目标是什么，在这个过程中你做了哪些事，哪些是做得好的、哪些是做得不好的，为什么会产生这样的结果，把这些统统梳理一下，从中找到规律或者经验，从而让你下次再遇到类似的问题时能够运用。\u003c/p>\u003cp>那为什么要这样做呢？\u003c/p>\u003cp>华为的任正非曾经说过：华为最大的浪费来自于经验的浪费。因为我们在日常的工作中会产生大量的经验，例如你完成了一个项目、和客户达成了一项合作、攻克了一个难题等等。但是我们很少会在事后花时间来好好回顾一下整个事件的过程，从而沉淀下来宝贵的经验。所以，学会复盘，能够让我们快速积累经验，加速成长。\u003c/p>\u003cp>【概念对比强化讲解】听到这里可能大家会有疑惑，这不就是总结吗？我平时也经常做总结啊。平时我们也会总结一下自己最近经历，反思一下哪些做的不好的，然后下次不犯这样的错误。对不对？\u003c/p>\u003cp>为了方便大家区分两者之间的差别，我来给大家详细讲解一下（按图片讲解复盘和总结的区别）：\u003c/p>\u003cp>其实总结和复盘有着很强的共性，但是复盘会比总结做得更全面。总的来说，复盘和总结的区别在于：复盘更关注未来如何应用，更具结构化，更强调经验的沉淀。这样给大家区分后，我们是不是对总结和复盘的区别更清晰了。\u003c/p>\u003cp>【举例辨析引出步骤】下面给大家举两个例子，来判断下是复盘还是总结：\u003c/p>\u003cp>案例1：小王经过不懈努力，和腾讯达成了电商合作项目，他写了一份工作报告，里面重点阐述了本项目的成果，同时也罗列一些不足的地方。请问这是总结还是复盘？\u003c/p>\u003cp>案例2：小王经过不懈努力，和腾讯达成了电商合作项目，他写了一份工作报告，写报告前，他重新梳理了这次项目过程的所有细节，回顾了开展活动的目的，想要达成的目标，是否按照阶段目标推进项目进展。他重点分析了项目的目的，是否达成了预定期望目标，详细分析了其中的亮点和不足，更是分析了不足产生的原因，并提出了后续的改进措施。请问这是总结还是复盘？\u003c/p>\u003cp>【hw引出细化步骤】详细通过前面的讲解，大家已经对复盘有了深刻的理解了。那复盘具体该如何操作呢？\u003c/p>\u003cp>第1步，回顾目标。回想一下当初做这件事的目的是什么？想要达成的目标是什么？阶段性或里程碑事件有哪些？\u003c/p>\u003cp>第2步，评估结果。结果与预期目标相比，本次过程中的亮点有哪些？本次活动（事件）提升的地方有那些？\u003c/p>\u003cp>第3步，分析原因。找出导致成功或者失败的根本原因。要找出来是哪些因素造成的失败；成功的关键因素又是什么。\u003c/p>\u003cp>第4步，总结规律。在复盘中，我们学到了什么？是否总结出一些经验和规律。如果以后遇到类似的情况，可以如何进行？\u003c/p>\u003cp>【举例子】我是19年加入拆书帮的，在这期间曾经两次立下flag说要通关三级，但却迟迟没有行动，导致3年过去了自己还没有成为三级拆书家。所以我在今年年初的时候给自己做了个复盘。\u003c/p>\u003cp>第一步，回顾目标：我当时想成为三级拆书家是想提升自己的表达能力和知识整合输出能力，通过每一个级别的拆书通关能让我看到自己这方面能力的提升。所以我给自己定的目标是一年内要成为三级拆书家；；\u003c/p>\u003cp>第二步，评估结果：但是三年过去了我还是没有成为三家拆书家，拆完1级后就没有继续拆了，中间有过两次感到压力断断续续拆了一两次又没有继续拆下去了\u003c/p>\u003cp>第三步，分析原因：我回顾了整个拆书过程中我做的一系列举动和心路历程，中间放弃的原因以及又断断续续拆了几次但没有继续拆下去的原因，罗列了一系列因素，最终发现造成我没有坚持下去的根本原因是我害怕失败，我会把拆书过级的失败当然是对我能力的否定，所以即使我有欲望提升自己，但是因为这种害怕太过强烈，导致我一直没能坚持下去，内心也充满了痛苦。\u003c/p>\u003cp>第四步，总结规律。今年是我工作第四年了，工作和生活中发生的一些事让我意识到我必须要全力以赴地提升自己。所以年初的时候我又把拆书提起了议程。为了避免拆了几次又放弃的情况出现，我当时给自己制定了几条措施：1）观念修正：过级失败不是对我能力的否定，而是帮助我了解自己当前还有哪些可以改进的地方，为了让自己后面更好做准备。如果不拆书，我永远无法检验自己的成果，发现自己的问题，从而进步；2）细化目标：我给自己定的目标是在自己6月生日前要成为三级拆书家，然后根据自己的目标进行阶段细化，3月份要拆完2-1到2-3,4月份要通关3-1和3-2,最终要在6月中旬前完成通关；3）强化行动：每次抢拆书名额的时候都先去争取名额，然后写稿子给师傅审核，在每一次的拆书时也不断强调自己的目标，加强自己的信念。\u003c/p>\u003cp>所以，到目前为止，我基本按自己的节奏完成了拆书，3月份即使疫情转战线上也坚持拆书，顺利通过了2-1到2-3。\u003c/p>\u003cp>【where】复盘的用途广泛，不仅可以用在个人工作的复盘，还可以用于团队复盘、项目复盘，日常生活中我们也可以用复盘这个工具来帮助自己提升。但是因为一整个复盘流程下来需要花比较多时间，所以对于日常生活一些很简单的事情，我们只需要简单总结一下即可。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>有些小伙伴可能会问，复盘是一定要对失败的事情进行复盘吗？例如有些人习惯当自己遇到挫折或者失败的事情时才做复盘，但成功的事情可能就一扫而过了。但是对成功的事情做复盘也是很有必要的，它能够帮助你总结成功的经验，从而在以后进行运用。\u003c/p>","interaction":"\u003cp>好的，通过我的讲解，想必大家对复盘的认识和操作步骤都了解了，为了帮助大家更好地运用，接下来将让大家自己动手实操一下。\u003c/p>\u003cp>你可以想一下，接下来的一周内你想复盘的一件事，最好是复盘后就可以用到的：如：本周定的目标没有完成、负责的一个项目出现了失误、减肥计划失败等等。\u003c/p>\u003cp>我在这里给了大家一个模板，大家利用这个模板设计一个剧本，这个剧本的内容可以是你和朋友一起针对某件事进行复盘，又或者是你自己和内心的自己对话，运用今天所学的复盘四步法来帮助自己梳理，沉淀经验。\u003c/p>\u003cp>【学习者分享】以下尤玲老师分享\u003c/p>\u003cp>背景：本周我们做了业务大讲堂的第一次线上直播，这几天我想对这个事情做复盘。\u003c/p>\u003cp>时间：下周一约个朋友去咖啡厅做个复盘\u003c/p>\u003cp>主题：线上大讲堂直播经验复盘\u003c/p>\u003cp>对话内容：\u003c/p>\u003cp>（其实我这个复盘的是一个成功的经验，然后复盘的过程中也对一些可以优化的细节进行复盘沉淀下来）\u003c/p>\u003cp>第一步：回顾目标\u003c/p>\u003cp>朋友：你针对这个业务大讲堂，整体想要达成什么目标？\u003c/p>\u003cp>我：我们业务把业务线的系列课程准确地赋能给业务线的同事\u003c/p>\u003cp>第二步：评估结果\u003c/p>\u003cp>朋友：那你认为第一次做这个线上直播有效地达成了传递的结果吗？\u003c/p>\u003cp>我：整体还不错，过程很顺畅，该邀请的人，参训人都邀请到了，参训率很高，结果很满意。\u003c/p>\u003cp>第三步：分析原因\u003c/p>\u003cp>朋友：针对线上直播，你觉得做得好的原因是？你觉得还有哪些可以完善的地方？\u003c/p>\u003cp>我：整个过程我对人员的分工，节奏把控都比较好。可能有些不足的是我们是否真正挖掘到了业务需求，精准赋能业务，达到帮助他们的目的。\u003c/p>\u003cp>第四步：总结经验\u003c/p>\u003cp>朋友：那你觉得后续该怎么做？\u003c/p>\u003cp>我：做得好的继续保持。另外可以完善的点：要更贴合业务，事后可以进行系列回访，了解通过这种形式的培训是否能够给业务同事带来他们想要的东西，所以，业务需求了解是一定要做的。做得好的呢，要沉淀下一条条经验，后续持续去用。讲师邀请和准备方便要继续加强。\u003c/p>\u003cp>剧本模板\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1651569717000,"updated_at":1654443516000,"ria":true},{"id":13295,"topic":"如何复盘","learn_goal":"","remark":"你是否遇到这样的情况？\n\n想要学习，没有效率？\n\n汇报工作，说不到重点？\n\n制定目标，总也完不成？\n\n如果你有这样的困惑，来听拆书家堤娜与您分享复盘的意义.","level":"TF3-3","duration":80,"status":30,"type":0,"chaishujia":{"username":"堤娜","city":"北京市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"\u003cp>设定学习目标：【技能点】学习目标包含了学习者可被观察到／被测量到的行为或动作。\u003c/p>\u003cp>\u003cstrong>【学习目的】两个拆页为递进关系。\u003c/strong>\u003c/p>\u003cp>【学习总目标】在跟随我完成本次RIA现场学习后，大家能够区分有目的的练习和天真练习，并运用有目的练习方法进行复盘（行为），最终养成复盘的习惯。（界定）两个片段是递进关系，掌握正确的练习方法，用复盘的行为来拔高层次。\u003c/p>\u003cp>【自我介绍】大家好！我是拆书家堤娜，我的三个标签：（1）营销编辑（2）5点早起（3）未来的三级拆书家：是我今年的目标。\u003c/p>\u003cp>【分组】拆书之前，我们先进行分组，方便一会儿的讨论。\u003c/p>\u003cp>A组：雷总，李小易，栾洋，刘永\u003c/p>\u003cp>B组：cherry，九虎，刘琴，小伙伴1，小伙伴2\u003c/p>\u003cp>【场景介绍法介绍图书】【事件场景】\u003c/p>\u003cp>前两天我在网上蹭网课，学了半个月，发现自己什么也没有记住，后来听到某一集的时候，up主说，我也不是这个专业的老师，我就是把我自己学习过程中搜集整理复习资料的方法分享给了大家。弹幕里考过的同学都来感谢老师。我就突然很绝望，感觉人生就是一场降维打击\u003c/p>\u003cp>【提问】不知道大家有没有这样的经历？同样都是学习，你付出了比别人更多的努力，还没有别人的成绩好，同样都是学习一个技能，你就是比别人慢。\u003c/p>\u003cp>【影响】甚至产生怀疑自己的念头，我真的这么笨吗？我真的没有天赋吗？要不就这样算了等待这样的负面情绪\u003c/p>\u003cp>【解决】所针对以上这些问题，有什么办法可以解决呢？方法就在《刻意练习》《复盘》这两本书里。刻意练习，可以让我们在节省时间的同时顺利渡过新手期，达成我们的目标，而复盘是刻意练习的核心，让我们认清问题的本质，总结过去的经验教训，得出规律，让我们随时随地随事都可以成长。\u003c/p>","ratings_count":2,"texts":[{"id":17296,"quote":"\u003cp>R原文片段：\u003c/p>\u003cp>接下来，我把拆页发给大家，请大家用1分钟，请大家阅读一下，看完的小伙伴点头示意一下。\u003c/p>\u003cp>有目的的练习VS天真的练习\u003c/p>\u003cp>如果对这种自动化的表现并不满意，你要做什么？如果你是一位工作了10年之久的老师，你想做一些事情，让学生对你上的课更感兴趣，并让你在课堂上更加高效，你该做什么？你基本上每个周末都打高尔夫球，想再提高一些，该怎么办？你在一家广告公司担任打字员，想让别人对你的打字速度感到惊叹，又该怎么办？\u003c/p>\u003cp>这便是史蒂夫•法隆在经过几次练习之后发现他自己所处的情形。在那一刻，他对自己能够听到一串数字、把它们记下来、再念给我听，感到很满意，而且，由于大家知道，短时记忆存在局限，所以，他的表现也和人们期望的差不多，中规中矩。\u003cstrong>他原本可以不停地这样记下去，在经过一次又一次的练习之后，最多能记住8个或是9个数字\u003c/strong>。但他并没有这样做。他参加了我设计的这个实验，而我设计这个实验的初衷，就是使他持续不断地接受挑战，以便每次都能比上次多记住一位数字，同时，也因为他是那种天生就喜欢挑战的人，所以，他在逼自己变得更优秀。\u003c/p>\u003cp>他采用的这种方法，我们称之为“有目的的练习”，事实证明，这种方法对他来说是不可思议的成功。正如我们接下来将看到的那样，这种方法并非总是如此成功，但它比通常的方法更有效一些，而且，这是通向刻意练习的第一步，而我们的最终目标便是刻意练习。\u003c/p>\u003cp>有目的的练习有几个特征，使得它与我们所说的“天真的练习”区分开来。所谓“天真的练习”，基本上只是反复地做某件事情，并指望只靠那种反复，就能提高表现和水平。\u003c/p>\u003cp>【目标1】通过现场学习，可以分清有目的的练习和天真练习，并且通过有目的练习的对比，掌握有目的练习的4个步骤。\u003c/p>","explains":"\u003cp>I拆书家讲解引导：\u003c/p>\u003cp>\u003cstrong>【互动提问】\u003c/strong>看大家都读完了这个片段，那么在开始讲解之前，想先问大家几个问题，带大家回顾一下片段，加深一下记忆。\u003c/p>\u003cp>\u003cstrong>拆书家提问：\u003c/strong>这个片段里作者介绍了两种练习方法，它们分别是什么？\u003c/p>\u003cp>\u003cstrong>学习者回答：\u003c/strong>有目的的练习、天真练习\u003c/p>\u003cp>\u003cstrong>拆书家提问：\u003c/strong>那么这两种方法，片段里推崇哪一种方法呢？\u003c/p>\u003cp>\u003cstrong>学习者回头：\u003c/strong>有目的的练习。\u003c/p>\u003cp>【what】是的，在我们的拆页中讲了两个概念“天真练习”“有目的的练习”，并且作者更加的推崇“有目的的练习”它的特点是目标 明确、专注练习、获得反馈\u003c/p>\u003cp>【why】有目的的练习可以让我们在短时间内快速的获取知识。\u003c/p>\u003cp>\u003cstrong>【概念解析】\u003c/strong>接下来我们来看几个案例，大家来看看这些例子是不是有目的的练习。\u003c/p>\u003cp>例子1：小红想学写作，每天在朋友圈里发一些自己的生活日常，大家觉得这是有目的的练习吗？\u003c/p>\u003cp>学习者反馈：不是\u003c/p>\u003cp>拆书家回应：对，不是。这是没有目的的“天真练习”。练习的时候没有明确目标，你都不知道航行的方向在哪里，就去执行，不就是浪费时间吗？所以，有目的的练习的第一个步骤就是需要明确可执行的目标，是上稿百万公众号的标准，还是只要糊弄就行。\u003c/p>\u003cp>例子2：小红明确了目标，上稿百万公众号，在练习的过程当中，一会儿接个电话，一会刷刷抖音，看看微信，半个小时过去了，大家觉得这叫做“有目的的练习”吗？\u003c/p>\u003cp>学习者反馈：不是\u003c/p>\u003cp>拆书家回应：不是。这是“天真的练习”。因为我们练习的时候不够专注。所以，有目的的练习的第二个步骤是专注。\u003c/p>\u003cp>例子3：她有了明确的目标，有了专注的练习，写作了一个月，终于写出一篇自己满意的文章，她就去投稿了，结果编辑说，你的文章不符合我们平台的调性啊！大家觉得这叫“有目的的练习”吗？\u003c/p>\u003cp>学习者反馈：不是\u003c/p>\u003cp>拆书家回应：对，也不是。这是“摸着石头过河瞎练”没有指导和反馈，又浪费了许多时间，也没有得到满意的结果。所以，有目的的练习的第三个步骤是及时反馈指导调整方向。\u003c/p>\u003cp>【强化讲解有目的练习的概念】\u003c/p>\u003cp>通过以上三个例子比对，我们得知有目的练习指的是，有明确的目标、专注练习和反馈,不具备这三个特点的练习只是简单重复的练习，就是天真练习。像我要学习写作，如果是有目的的练习，就应该有目标——上稿百万公众号，专注——每天固定时间心无旁骛的练习，有反馈——找老师或者自我复盘找到问题所在\u003c/p>\u003cp>【How】从上面的案例中，我们总结出“有目的练习”的3个步骤\u003c/p>\u003cp>1、明确目标：能力范围内，能执行可达到的程度。\u003c/p>\u003cp>2、专注练习：练习的时候屏蔽一切外来打扰因素。\u003c/p>\u003cp>3、获得反馈：找领域内的专家或者老师帮忙监督指导，社群。\u003c/p>\u003cp>【举个例子】前面说最近我一直在蹭网课，效率低下，学了这个有目的的练习以后，我做了一个调整\u003c/p>\u003cp>1、明确目标：听懂这节课为目标，而不是求量\u003c/p>\u003cp>2、专注练习：每天晚上8-10点，用专用的手机听课\u003c/p>\u003cp>3、获得反馈：去做题和回忆\u003c/p>\u003cp>【where适用边界】“有目的的练习”适用于生活当中的各种技能，尤其是换新领域，想要短时间获得结果的技能。比如写作，乐器，考证，摄影。\u003c/p>\u003cp>【预防异议】值得注意的是第三点，反馈的标准是不好衡量的，我们可以采取量化的思维去衡量或者根据导师的反馈来达成。\u003c/p>","interaction":"\u003cp>A学习者拆为己用：学习者拆为己用：\u003c/p>\u003cp>【A2】催化学习者应用【显像提问】【教学习者编剧本】\u003c/p>\u003cp>接下来请大家想想未来的一段时间内，有没有一件事，你已经做了一遍但是仍旧没有成功准备再做一遍？可以是去年一直想要学却没有学会的摄影剪辑，也可以是想要开展副业变现要继续深耕的写作请大家想一想，减肥，也可以是最近要开展的项目等等在我们的便签纸上写下来，运用有目的的三个步骤来编写一个小剧本，故事中要体现出主题、人物、情节变化（包括：起因、经过、结果）和双方的对话、动作等，其中角色的部分对话要用到刚才“有目的三步骤”，来对应前面学到的技能内容。\u003c/p>\u003cp>比如：小红最近在学习摄影，学了半个月仍旧没有什么进步，她为此特别苦恼，向小明倾诉自己的难题，小明用”复盘三步法帮助小红排忧解难，由此展开了对话\u003c/p>\u003cp>小红：小明你看我学习手机摄影半个月 也没什么进步，你有没有什么更好的方法呀\u003c/p>\u003cp>小明：当然有，你有明确的目标吗？学人物摄影还是风景摄影？\u003c/p>\u003cp>请大家把故事摘要写到一张纸上。时间3分钟。3分钟后我们请一组伙伴代表来讲讲你们组内编写的故事。\u003c/p>\u003cp> 【学习者分享】\u003c/p>\u003cp>背景：李小易是一个高校老师，为了学生们学习方便，准备运用互联网技术录制线上课程，帮助更多的学生学习\u003c/p>\u003cp>李小易：栾老师，我最近计划想要录一个学习课程，但是我很苦恼怎么开始\u003c/p>\u003cp>栾洋：首先我们要明确我们的目的，我们不妨从这几个方面来思考，这个课程的专业度如何，为什么要做这个课程？这个课要录制几节？心里有预期的内容选定吗？\u003c/p>\u003cp>李小易：目前打算做一些初级的普及课程，相对简单，我计划做30节，范围就是我们初级的的基础知识。\u003c/p>\u003cp>栾洋既然我们已经确定了目标是录制30节课程，那你有整块的时间做这个事吗？\u003c/p>\u003cp>李小易：我每天晚上9-12点这个时间段都可以专注的做这个事情，平时碎片化时间我可以搜集资料。\u003c/p>\u003cp>栾洋：OK，在这里我们要注意一点，反馈。你录这个课，有老师朋友监督吗？\u003c/p>\u003cp>李小易：目前暂时没有，我之前是录完以后看一遍，自己给自己找缺点，会发现自己说错了话，口齿不清，只能再来一遍\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":17297,"quote":"\u003cp>【过渡语】感谢我们两位小伙伴的精彩分享，小易老师分享了初步制作课程的计划，运用了我们有目的练习的3个步骤”，有目的的。专注的练习，最关键的是获得有效反馈。\u003c/p>\u003cp>请问小伙伴们获得反馈除了社群朋友老师监督以外，大家觉得还有什么方法能帮助我们获得反馈。\u003c/p>\u003cp>学习者李小易：自己看自己，比如录视频，听语音\u003c/p>\u003cp>学习者刘永：复盘\u003c/p>\u003cp>拆书家总结：对的，感谢我们两位小伙伴的分享，小易分享的自己看自己，是不是可以把它归类在刘永提出的复盘里呢？\u003c/p>\u003cp>请主持人帮我发一下第二个拆页，请大家花一分钟的时间做一下我们的自测题\u003c/p>\u003cp>【A1量表自测】：\u003c/p>\u003cp>本次测试的目的是为了让大家了解在学习之前，我们具备复盘意识吗？1分是完全不符合，5分是非常符合。请大家凭第一直觉打分就可以，第一直觉往往是最我们最直接的反应，最后算下总分。做完的伙伴示意我下。\u003c/p>\u003cp>1.每次成功，我都会回顾过往的经历，总结成功的经验。\u003c/p>\u003cp>2.面对失败，我会及时调整自己的情绪，寻找失败的原因。\u003c/p>\u003cp>3.当遇到不会的事情，我不会轻易放弃，我会探求问题的本质。\u003c/p>\u003cp>4.做一件事，我会精益求精，想方设法做到最好。\u003c/p>\u003cp>5.每做一件事我都会总结过去的经验探索规律，分类归档。\u003c/p>\u003cp>序号\u003c/p>\u003cp>题目\u003c/p>\u003cp>分数\u003c/p>\u003cp>1、每次成功，我都会回顾过往的经历，总结成功的经验。\u003c/p>\u003cp>1 2 3 4 5\u003c/p>\u003cp>2、面对失败，我会及时调整自己的情绪，寻找失败的原因。\u003c/p>\u003cp>1 2 3 4 5\u003c/p>\u003cp>3、当遇到不会的事情，我不会轻易放弃，我会探求问题的本质。\u003c/p>\u003cp>1 2 3 4 5\u003c/p>\u003cp>4、做一件事，我会精益求精，想方设法做到最好。\u003c/p>\u003cp>1 2 3 4 5\u003c/p>\u003cp>5、每做一件事我都会总结过去的经验探索规律，分类归档。\u003c/p>\u003cp>1 2 3 4 5\u003c/p>\u003cp>【I解释自测题】做完测试的请大家加一下总分，对照一下自己的分数，如果总分在15分以上，这说明你在本次学习之前已经具备一定的复盘意识，这对我们今天的学习非常有帮助，如果分数在15分以下，也不必着急，你会在我们今天的现场学习中收获复盘思维，所以我们要打起精神，认真学习今天的知识。\u003c/p>\u003cp>接下来请大家把学习资料翻过来看到片段二，这是今天学习的第二个内容——什么是复盘，\u003c/p>\u003cp>【过渡语】请大家用一到两分钟的时间阅读一下，看完的伙伴举手向我示意我一下。\u003c/p>\u003cp>R原文片段： 《复盘》\u003c/p>\u003cp>“复盘”原是围棋术语，本意是对弈者下完一盘棋之后，重新在棋盘上把对弈过程摆一遍，看看哪些地方下得好，哪些下得不好，哪些地方可以有不同甚至是更好的下法等。\u003c/p>\u003cp>这个把对弈过程还原并且进行研讨、分析的过程、就是复盘。\u003cstrong>通过复盘，棋手们可以看到全局以及整个对弈过程，了解棋局的演变，总结出适合自己和不同对手的套路，或找到更好的下法，从而实现自己棋力的提升\u003c/strong>。\u003c/p>\u003cp>用到企业管理中，复盘是指从过去的经验、实际工作中进行学习，帮助管理者有效地总结经验，提升能力，实现绩效的改善。正如联想集团创始人柳传志先生所说：\u003cstrong>所谓复盘，就是一件事情做完了以后，做成功了，或者没做成功，尤其是没做成功的，坐下来把当时的这个事情，我们预先怎么定的、中间出了什么问题、为什么做不到，把这个过程要理一遍，理一遍之后，下次再做的时候，自然这次的经验教训就吸收了。\u003c/strong>\u003c/p>\u003cp>【学习目标2】：通过今天的现场学习以后，学习者能够通过回顾目标，反思原因，探究规律提升能力，三个步骤学会复盘。\u003c/p>\u003cp> 看到大部分小伙伴已经看完啦！没看完也没有关系，我们一起来学习一下。\u003c/p>","explains":"\u003cp> I拆书家讲解引导：\u003c/p>\u003cp> \u003cstrong>【what】\u003c/strong>这个片段讲解了有目的练习的最关键步骤，无老师指导的情况下，我们可以通过复盘来俯瞰自己的学习目标和过程，从而达到提升能力的效果。它有3个特点回顾目标、反思原因、探究可行性。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>复盘可以让我们看到自己的缺陷，认清问题的本质，重新构建自己的思维，让我们学会从工作中总结经验教训，提升能力，改善问题。\u003c/p>\u003cp>【How-行动步骤】在片段中我们可以看到复盘的3个步骤：\u003c/p>\u003cp>第一步：回顾过标。一件事完成以后，坐下来，以结果为导向理一遍，目标是什么？结果如何？做了什么？\u003c/p>\u003cp>第二步：反思原因。没有做到的原因是什么\u003c/p>\u003cp>第三步：探究可行性。\u003cstrong>下次再做的时候，吸收这次的经验教训。\u003c/strong>\u003c/p>\u003cp>【举例】\u003c/p>\u003cp>这个月月初的时候，我给自己设置了一个目标，3个月能联系到500个博主，平均每天6个，要是周末休息的话，平均每天得联系8，一个月过去了，还没有实现100个目标，学习了复盘的这个方法以后我就按照复盘的3个步骤做了一个简单的复盘。\u003c/p>\u003cp>第一步：回顾过程。我的目标就是三个月联系500个达人，实现升职加薪。\u003c/p>\u003cp>第二步：反思原因。在找达人的时候，很容易被达人的内容吸引，因此就会去看更多的内容，导致效率低下\u003c/p>\u003cp>第三步：探究可行性。借鉴上个月的经历可以适当的降低标准，刷达人的内容不超过3条，争取4月能过80人。\u003c/p>\u003cp>【适用范围】可以用于事件复盘，问题复盘，情绪复盘，对标复盘，分类复盘。但是不适于团队复盘，团队复盘会更加复杂，今天在我们的现场不做讨论，如果大家感兴趣可以去【复盘】这本书里做进一步学习。\u003c/p>\u003cp>【预防异议】可能大家会有这样的疑问，复盘和总结有什么区别，复盘是总结更高级别的体现，是以结果为导向，看过去定未来，而总结只有回顾过去。\u003c/p>","interaction":"\u003cp> A学习者拆为己用：【A3】促动参与:【一、明确问题】【学习微行动】\u003c/p>\u003cp>刚才在我们有目的练习的步骤里，李小易同学分享了想要录一个线上课，如果我们现在要用复盘3步法来做一个复盘的话，回顾过程和目标，反思原因，探究可行性，那个步骤最难。根据刚才的分组，\u003c/p>\u003cp>A组：雷总，李小易，栾洋，刘永\u003c/p>\u003cp>B组：cherry，九虎，刘琴，小伙伴1，小伙伴2\u003c/p>\u003cp>请大家在我们的小组没讨论一下，稍后请两个小组进行一下分享。\u003c/p>\u003cp>我看讨论的差不多啦，下面请每个小组有一个代表来分享一下讨论结果\u003c/p>\u003cp>第一步：选择一个最普遍的值得讨论的步骤(最难）明确问题\u003c/p>\u003cp>【小组反馈】\u003c/p>\u003cp>A组：反思原因\u003c/p>\u003cp>B组：反思原因和回顾过程目标\u003c/p>\u003cp>拆书家引导：最终投票表决，确定反思原因作为下一步讨论的环节\u003c/p>\u003cp>第二步：引导分组讨论问题的本质\u003c/p>\u003cp>（针对讨论出的问题进行深入探讨）\u003c/p>\u003cp>下面请大家继续思考一个问题，为什么你们认为反思原因这一步很难？难的原因是什么，可以是一条，也可以是好几条，最后每个小组总结两到三条内容。大家可以先不找解决方案，先挖一挖为什么。\u003c/p>\u003cp>看到大家都讨论得差不多了，我们邀请A组先分享\u003c/p>\u003cp>A组：目标不清晰、缺乏行动\u003c/p>\u003cp>B组：环节太多、认知有限、不够专业、目标不清晰\u003c/p>\u003cp>第三步：\u003cstrong>（明确问题本质）\u003c/strong>\u003c/p>\u003cp>拆书家：经过大家的头脑风暴，最终选出5个原因，最后经过举手表决，选定反思原因最难的一步是目标不够清晰。请大家顺着这个点继续深挖？大家先不用想解决，请大家继续讨论。\u003c/p>\u003cp>我看大家聊的差不多了，我们一起来聊一下大家觉得最关键的因素或者问题的本质是什么？不一定重复上面五个点的某一个点，而是更进一步的推演。\u003c/p>\u003cp>B组：不够了解自己、大环境导致的\u003c/p>\u003cp>拆书家总结\u003c/p>\u003cp>拆书家：你们组觉得那个最重要\u003c/p>\u003cp>学习者：不够了解自己\u003c/p>\u003cp>A组：不知道自己发现的方向，未来的愿景、圈子很重要\u003c/p>\u003cp>拆书家：你们组觉得这两个最重要的是那个\u003c/p>\u003cp>学习者：从本质上看，还是不够了解自己\u003c/p>\u003cp>第四步：引导分组讨论解决方案\u003c/p>\u003cp>那么我们就到了最后一步，怎么解决这个问题。请大家继续分组讨论这个点。如何才能更加了解自己\u003c/p>\u003cp>\u003cstrong>（讲解讨论成果）\u003c/strong>我看大家讨论的差不多了，还是请每组派一个小伙伴来为我们分享。\u003c/p>\u003cp>A组：\u003c/p>\u003cp>刘永：\u003c/p>\u003cp>1.给自己高频反馈\u003c/p>\u003cp>2.复盘日记\u003c/p>\u003cp>3.向书本学习\u003c/p>\u003cp>4.向行业标杆学习\u003c/p>\u003cp>5.向前辈学习\u003c/p>\u003cp>李小易补充：\u003c/p>\u003cp>1.性格测试\u003c/p>\u003cp>2.八卦算命\u003c/p>\u003cp>3.职业探索\u003c/p>\u003cp>4.技能学习\u003c/p>\u003cp>栾洋补充\u003c/p>\u003cp>1.镜子：看自己\u003c/p>\u003cp>2.尺子：认知的纬度\u003c/p>\u003cp>B组：\u003c/p>\u003cp>刘琴\u003c/p>\u003cp>1.整理\u003c/p>\u003cp>2.测试\u003c/p>\u003cp>3.复盘\u003c/p>\u003cp>小伙伴补充\u003c/p>\u003cp>1.试错\u003c/p>\u003cp>拆书家：非常感谢大家，经过这么长的讨论之后贡献的智慧。我们刚刚进行了一场微行动学习。\u003c/p>\u003cp>首先提出问题。关于三个步骤回顾过程目标、反思原因、探究可行性哪个最难，大家一致认为是反思原因最难，从而推倒出问题本质是目标不清晰，目标不清晰主要是因为不够了解自己，从而讨论出了解自己的方法有15步，就不一一给大家赘述了，我来给大家总结三个纬度，第一：借助工具；第二：找他人反馈；第三：反求诸己。\u003c/p>\u003cp>【布置任务】通过我们微行动的学习和探讨，给大家布置一个作业，请大家回去以后，运用我们今天学习的复盘的练习3步法，对我们近期想要做的事情和想做未成功的事，做一个规划，可以是今年考试，也可以是写作能力提升训练，大家可以私信发给我，或者发在我们的群里，我们一起来监督\u003c/p>\u003cp>九虎的复盘作业\u003c/p>\u003cp> 复盘作业：\u003c/p>\u003cp>2021年10月份，由于道路建设，涉及北京市xxx家属院围墙还建工程。我公司同意：出资修建。但是，2022年3月17日，施工单位正式通知我公司，不再承担此项工程任务。\u003c/p>\u003cp>1、回顾\u003c/p>\u003cp>（1）目标：北京市xxx家属院围墙还建工程；原则是我公司仅仅出资，不参与工程建设、验收、监理、协调等工作。\u003c/p>\u003cp>（2）结果：目标未完成；\u003c/p>\u003cp>2、反思\u003c/p>\u003cp>没有做到的原因：第一，对方提供的资质，有造假的嫌疑，否则，不会犯了这么多的低级错误；第二，审计公司提要求，应该列出清单，并提前告知对方；第三，组织现场核查，应提早安排。第四：预算价格未达成一致\u003c/p>\u003cp>3方面因素，造成如此局面：对方申报预算水平，审计公司要求提出滞后，现场核查应放在申报预算之前进行。\u003c/p>\u003cp>3、探究可行性：\u003c/p>\u003cp>（1）对方技术水平要求，不仅仅看其提供的资质，更要看对方的实际能力；\u003c/p>\u003cp>（2）提前组织现场核量，并要求审计公司，提出明确的要求，告知对方，减少障碍和沟通环节。\u003c/p>\u003cp>【强有力的结束语】：以上就是我今天的分享，今天我们学习了两个片段，第一个片段有目的练习的3个步骤：明确目标，专注练习，反馈指导，进一步探究了复盘的三个步骤：回顾目标，反思原因，探究可行性，让我们学会反求诸己，向自己学习向生活学习。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1650416748000,"updated_at":1651142196000,"ria":true},{"id":12789,"topic":"用复盘思维提升自己—四步搞定复盘","learn_goal":"","remark":"用复盘思维提升自己——四步搞定复盘，掌握高效复盘的四个步骤，实现持续精进、改善工作能力。","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"清风缘林","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>各位老师，大家晚上好。非常开心再次与大家相聚在这里，感谢在我拆书升级打怪的路上一路相伴，一路相随。我是今天的拆书家林荣增。给大家介绍三个关于我的标签。第一个标签，PPT爱好者。第二个标签，我是一名企业内部培训讲师。第三个标签，中级茶艺师，尤其喜欢武夷岩茶（金骏眉、正山小种、肉桂）。\u003c/p>\u003cp>为了更好的开展我们今天的拆书活动，接下来我们来分个小组，两个人一个小组，大家都知道自己属于哪个小组了吗？\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>在跟随我完成本次RIA现场学习后，学习者能够陈述高效复盘的四个步骤（澄清），并且使用复盘结构化四步法对工作、生活中的一个事情开展一场复盘活动（行为），总结经验，提升能力，避免未来犯同样错误（界定）。\u003c/p>\u003cp>\u003cstrong>【事件场景】\u003c/strong>在的日常工作生活中，我们经常会看到这些状况：某同事从事一项常规工作，尽管每个月都要做，理应来说应该做的很好了，但是每个月都会出现同样的低水平重复错误。销售部小王在客户那里吃了“闭门羹”之后，拍着自己的脑袋，懊悔地说：“以前，我曾经犯过这样的错误，今天，为什么又犯了同样的错误”。你自己或你带的团队，总是有人一而再再而三的犯同样的错误。等等这类类似的事情，总是屡见不鲜。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>为什么“低水平”的重复错误总是一直出现？为什么已经做了很多次的事情，就不能改进，还是有错误纰漏呢？ \u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong> 非常可怕的是：“吃一堑，不长一智”。一个人不能从失败或错误中学习、吸取教训，实现个人成长。低水平的重复错误，极大影响了我们个人目标的实现，我们个人能力的成长，导致我们能够取得的成就非常的有限。。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>《复盘+，把经验转化为能力》这本书中给出了复盘操作的四个详细的步骤，复盘这个方法能够帮助我们避免同样的错误再犯，实现传承经验和提升能力。今天跟大家分享的是“用复盘思维提升自己—四步搞定复盘”，这个拆页告诉我们如何用四步搞定复盘，实现个人能力提升。\u003c/p>\u003cp>接下来我们花一分钟的时间来看一下片段。\u003c/p>","ratings_count":1,"texts":[{"id":16734,"quote":"\u003cp>\u003cstrong>原文拆页片段1：什么是复盘\u003c/strong>\u003c/p>\u003cp>“复盘”原是围棋术语，本意是对弈者下完一盘棋之后，重新在棋盘上把对弈过程摆一遍，看看哪些地方下得好，哪些下得不好，哪些地方可以有不同甚至是更好的下法等。\u003c/p>\u003cp>这个把对弈过程还原并且进行研讨、分析的过程、就是复盘。通过复盘，棋手们可以看到全局以及整个对弈过程，了解棋局的演变，总结出适合自己和不同对手的套路，或找到更好的下法，从而实现自己棋力的提升。\u003c/p>\u003cp>用到企业管理中，复盘是指从过去的经验、实际工作中进行学习，帮助管理者有效地总结经验，提升能力，实现绩效的改善。正如联想集团创始人柳传志先生所说：\u003cstrong>所谓复盘，就是一件事情做完了以后，做成功了，或者没做成功，尤其是没做成功的，坐下来把当时的这个事情，我们预先怎么定的、中间出了什么问题、为什么做不到，把这个过程要理一遍，理一遍之后，下次再做的时候，自然这次的经验教训就吸收了。\u003c/strong>\u003c/p>","explains":"\u003cp>\u003cstrong>【what】\u003c/strong>这个片段讲解了复盘的由来，界定了复盘的定义。把事情发生的过程还原并且进行研讨、分析的过程就是复盘。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>复盘是一种行之有效的从经验中学习的方法，无论对于个人学习与成长，还是对于团队与组织能力提升、绩效改善，都有重要的意义和价值。成人的学习途径主要从工作中总结经验教训。在职场中，成人学习的最大部分来自“岗位实践”（约在70%）；其次，是通过与他人交流（约占20%）；最后，是培训教育（约占10%）。从工作中学习最好的办法就是复盘，让他们在实践过程中总结经验，然后快速提升自己的能力。\u003c/p>\u003cp>\u003cstrong>【概念对比强化讲解】\u003c/strong>\u003c/p>\u003cp>很多时候我们在第一眼认识复盘的时候都会觉得这不就是总结吗?\u003c/p>\u003cp>试着回顾你最近的一次总结吧:我在过去的一年中做了什么，哪些地方我做的不错，哪些地方存在不足，我下一步打算怎么做怎么改进。\u003c/p>\u003cp>是不是感觉被套路了?\u003c/p>\u003cp>事实上总结只是复盘的一部分，复盘比总结具有更为全面和丰富的内涵。\u003c/p>\u003cp>那么到底“复盘”和“总结”有什么区别？\u003c/p>\u003cp>下面我们通过几个例子来看一下什么是复盘，什么是总结。\u003c/p>\u003cp>案例1：一个企业文化活动结束了，小王写了一份工作报告，里面重点阐述了本次活动取得业绩成果，同时也罗列一些不足的地方。请问这是总结还是复盘？\u003c/p>\u003cp>学习者唐老师：总结\u003c/p>\u003cp>是的，这个总结。报告更多是过去的回顾。没有太多的反思和改善建议。\u003c/p>\u003cp>案例2：一个企业文化活动结束了，小王写了一份工作报告，写报告前，他重新梳理了这次活动发生的所有细节，反思了开展活动的目的，想要达成的目标，是否按照阶段目标推进活动。里面重点阐述了本次活动取得业绩，分析是否达成了预定期望目标，对指出其中的亮点和不足，更是分析了不足产生的原因，并重构了改善的措施。请问这是总结还是复盘？\u003c/p>\u003cp>学习者李老师：是复盘\u003c/p>\u003cp>是的，这个复盘。报告中有回顾目标，反思原因，重构措施。\u003c/p>\u003cp>\u003cstrong>【how，细化步骤】\u003c/strong>\u003c/p>\u003cp>复盘是一种行之有效的从经验中学习的方法，那么，如何操作复盘呢？\u003c/p>\u003cp>第1步，回顾目标。回想一下当初做这件事的目的是什么？想要达成的目标是什么？阶段性或里程碑事件有哪些？ \u003c/p>\u003cp>第2步，评估结果。结果与预期目标相比，本次过程中的亮点有哪些？本次活动（事件）提升的地方有那些？\u003c/p>\u003cp>第3步，分析原因。找出导致成功或者失败的根本原因。要找出来是哪些因素造成的失败；成功的关键因素又是什么。第4步，总结规律。在复盘中，我们学到了什么？是否总结出一些经验和规律。如果以后遇到类似的情况，可以如何进行？\u003c/p>\u003cp>\u003cstrong>【举例说明】\u003c/strong>\u003c/p>\u003cp>在2020年12月份，申请加入龙城分舵。原本计划着花9个月时间，通过所有拆书升级，成为一名三级拆书家。现在已经12月了，我现在还在过TF3-1。针对我自己拆书过级这个事情，我的朋友老李，近期帮我做了个复盘。\u003c/p>\u003cp>\u003cstrong>第一步：回顾目标\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>老李：\u003c/em>\u003c/strong>林老师，听说年初你现在的拆书过级进度未达到你自己既定的目标。你年初定的拆书目标是什么？有没有设置多长时间必须过一级呢？\u003c/p>\u003cp>\u003cstrong>\u003cem>林荣增：\u003c/em>\u003c/strong>在年初的时候，我给自己定了要花9个月时间来过级，成为一名三级拆书家。计划化着每个月过一级。\u003c/p>\u003cp>\u003cstrong>\u003cem>老李：\u003c/em>\u003c/strong>你当初是基于什么目的要来参加拆书帮呢？\u003c/p>\u003cp>\u003cstrong>\u003cem>林荣增：\u003c/em>\u003c/strong>我就是想学习一下这个拆书技术，然后用在公司储备干部培养项目中。\u003c/p>\u003cp>\u003cstrong>第二步：评估结果\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>老李：\u003c/em>\u003c/strong>你现在的拆书过级到什么级别了？\u003c/p>\u003cp>\u003cstrong>\u003cem>林荣增：\u003c/em>\u003c/strong>现在过到3-1了，没有达到预期目标。\u003c/p>\u003cp>\u003cstrong>\u003cem>老李：\u003c/em>\u003c/strong>那么在这之前的拆书过级中有没有哪些地方做的自己还是比较满意的，哪些地方是不满意的？\u003c/p>\u003cp>\u003cstrong>\u003cem>林荣增：\u003c/em>\u003c/strong>说实在只能说之前的过级表现很一般，没有特别突出的地方。自己不满意的地方就是过级速度太慢了。\u003c/p>\u003cp>\u003cstrong>第三步：分析原因\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>老李：\u003c/em>\u003c/strong>那你有么有想过是什么原因导致你过级的速度慢呢？\u003c/p>\u003cp>\u003cstrong>\u003cem>林荣增：\u003c/em>\u003c/strong>第一，有点眼高手低了，感觉这个过级不难，但实际在写逐字稿的时候还是很费时间的。平常下班之后，有点懈怠，没有坚持去看书。就想着下个月多过一级，这样子进度就能赶上。实际上要想很好掌握每个级别的要点，是需要花时间去认真研究。第二，对于观察家和师傅提出点评建议，要认真琢磨，不理解时，要及时与他们进行沟通。\u003c/p>\u003cp>\u003cstrong>第四步：总结经验\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>老李：\u003c/em>\u003c/strong>经过刚才我们的分析，你有没有一些启发和收获？\u003c/p>\u003cp>\u003cstrong>\u003cem>林荣增：\u003c/em>\u003c/strong>第一，经过前面的反思，要想顺利通过三级，要摆正心态，需要投入大量的时间和精力；第二，认真研究过级要点，严格按照既定过级计划去执行。\u003c/p>\u003cp>\u003cstrong>\u003cem>老李：\u003c/em>\u003c/strong>那么后续拆书过级你将会怎么做？\u003c/p>\u003cp>\u003cstrong>\u003cem>林荣增：\u003c/em>\u003c/strong>首先，积极投入时间和精力，自己认真研究技能点要求。其次，保持与观察家和师傅实时沟通。\u003c/p>\u003cp>\u003cstrong>【where适用边界】\u003c/strong>复盘的底层逻辑非常简单，按照复盘涉及的主题范围、主题内容，我们将复盘分为四类（个人复盘、团队复盘、项目复盘、经营/战略复盘）。今天学习的复盘主要用于个人复盘，可以对工作、生活中的关键事件、有价值的、重要的事情，通过复盘能实现能力迭代的一些事情，去做复盘。其他一些对自身意义不大的事件就简单反思即可。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>可能有人就会问一定是失败的事情才需要复盘吗？很显然，不仅要复盘失败的事情，成功的事情也需要复盘。对成功的事情通过复盘提炼、复制成功做法；对失败的事情，通过复盘，提炼经验，改善做法，避免同样错误再犯。\u003c/p>","interaction":"\u003cp>通过以上的讲解分享，想必大家已经初步掌握了复盘的四个步骤，为了加强运用，我们今天尝试编一个故事场景。在未来一周，我们想一想，有哪些事特别想要复盘的，你将如何运用复盘的四个步骤开展复盘呢？（比如你刚完成一个较大工作项目,领导要求做个复盘又或是工作中与同事碰到了冲突，要复盘一下沟通技巧，以便提升自己沟通水平，也有可能是你制定的个人学习目标没有完成，内心特别焦虑，想做个自我反思复盘等等），想想你将如何开展复盘？通过对话的形式将其表达出来。编写的故事要有时间、地点、人物、场景、起因、事件内容、对话，结果等等。时间5分钟。\u003c/p>\u003cp>大家一定要把复盘四个步骤体现在内容中，就是回顾目标、评估结果、分析原因、总结经验。\u003c/p>\u003cp>写完后，可以在小组内先交流一下，编写的故事是否符合前面的要求。然后我们请1位伙伴分享一下自己写的故事。\u003c/p>\u003cp>\u003cstrong>【学习者案例】\u003c/strong>李老师分享：\u003c/p>\u003cp>1、 时间：12月18日\u003c/p>\u003cp>2、 地点：公司\u003c/p>\u003cp>3、 场景：新产品生产结束复盘\u003c/p>\u003cp>4、 人物：李老师\u003c/p>\u003cp>5、 时间背景：本周刚结束了为期半个月的新产品生产，整个过程还算比较少顺利，只是出现了几个小问题。然后我自己做了个复盘\u003c/p>\u003cp>6、 复盘过程：\u003c/p>\u003cp>第一步：回顾目标 把新产品保质保量的顺利生产出来\u003c/p>\u003cp>第二步：评估结果 整个新产品的生产过程比较顺利，产品的质量也都符合要求 \u003c/p>\u003cp>第三步：分析原因 1、生产前对操作员工进行了培训；2、生产准备工作也比较到位；3、生产过程中，盯着也比较细，发现问题，及时处理。\u003c/p>\u003cp>第四步：总结经验 后续在生产新产品时候，必须做好前面三点（员工培训，生产准备、紧盯过程），相信新产品的生产不会出现什么问题。 \u003c/p>\u003cp>7、结果：通过复盘，能够对新产品的生产起到很好的分析，确保后续能顺利生产。\u003c/p>\u003cp>好的，非常感谢李老师精彩的分享。李老师对成功的案例进行了复盘，总结出成功的关键要素。大家用热烈的掌声送给李老师。\u003c/p>\u003cp>\u003cstrong>【结束语】：\u003c/strong>经过刚才分享交流，我们对复盘的四个步骤的认识又进一步加深了。希望大家回去之后能将这个方法真正的用于实际生活之中。我今天的分享就到此结束了，感谢各位学友的陪伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1639368349000,"updated_at":1640508076000,"ria":true},{"id":12712,"topic":"用复盘思维提升自己—四步搞定复盘","learn_goal":"","remark":"用复盘思维提升自己——四步搞定复盘，掌握高效复盘的四个步骤，实现持续精进、改善工作能力。","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"清风缘林","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>各位老师，大家晚上好。非常开心再次与大家相聚在这里，感谢在我拆书升级打怪的路上一路相伴，一路相随。我是今天的拆书家林荣增。目前我就职一家制造业，是一名人力资源从业者，现阶段主要负责培训和企业文化工作。给大家介绍三个关于我的标签。第一个标签，PPT爱好者。第二个标签，我是一名企业内部培训讲师。第三个标签，中级茶艺师，尤其喜欢武夷岩茶（金骏眉、正山小种、肉桂）。\u003c/p>\u003cp>为了更好的开展我们今天的拆书活动，接下来我们来分个小组，两个人一个小组，大家都知道自己属于哪个小组了吗？\u003c/p>\u003cp>\u003cstrong>图书介绍\u003c/strong>\u003c/p>\u003cp>\u003cstrong>F\u003c/strong>今天拆解的片段选自这本《复盘＋把经验转化成能力》，本书作者是邱昭良，实战派专家。书中主要阐述了复盘实操的步骤、复盘的内功心法、复盘方法的推广及在构建学习型组织场景中复盘的应用方法。\u003c/p>\u003cp>\u003cstrong>A\u003c/strong>这本书深度解析了联想、万达、美军、英国石油公司的实践经验，总结了复盘的“内功心法”，并提出引导复盘的工作指引与常用工具，还提供了经过实践检验的复盘模板。相比较其他同类型的书籍，本书不仅强调理论和体系，而且强调实战、实用，强调干货。\u003c/p>\u003cp>\u003cstrong>B1\u003c/strong>复盘作为一种从经验中学习的结构化方法，它能够强化目标，避免同样的错误再犯，传承经验和提升能力，总结规律和固化流程，打破思维框架和转变思维范式，能够实现个人、团队、组织能力快速提升。\u003c/p>\u003cp>\u003cstrong>B2 \u003c/strong>拆页片段详细阐述了复盘的四个步骤，并列出了各个阶段的核心问题，给出对策和建议，使得操作复盘的人更容易掌握复盘的方法。\u003c/p>\u003cp>\u003cstrong>拆页片段1学习目标：\u003c/strong>在跟随我完成本次RIA现场学习后，学习者能够掌握高效复盘的四个步骤，并且能够开展一场复盘活动。请大家花1分钟的时间阅读手中的拆页，阅读完的老师请举手示意一下。\u003c/p>","ratings_count":1,"texts":[{"id":16645,"quote":"\u003cp>\u003cstrong>拆页片段1 复盘步骤解析\u003c/strong>\u003c/p>\u003cp>基于复盘的机理和长期的实践，联想集团于2011年提出了复盘的操作步骤，包括四个阶段：回顾目标、评估结果、分析原因、总结经验，如图3-2所示。这与美军的行动后反思(AAR)和英国石油公司的“事后回顾”的做法基本一致。我将其称为在企业中进行复盘的“底层逻辑”。\u003c/p>\u003cp> 图3-2复盘步骤\u003c/p>","explains":"\u003cp>\u003cstrong>【what】\u003c/strong>这个片段解析复盘的四个步骤。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>复盘是一种行之有效的从经验中学习的方法，无论对于个人学习与成长，还是对于团队与组织能力提升、绩效改善，都有重要的意义和价值。成人的学习途径主要从工作中总结经验教训。在职场中，成人学习的最大部分来自“岗位实践”（约在70%）；其次，是通过与他人交流（约占20%）；最后，是培训教育（约占10%）。从工作中学习最好的办法就是复盘，让他们在实践过程中总结经验，然后快速提升自己的能力。\u003c/p>\u003cp>\u003cstrong>【不这么做的坏处】\u003c/strong>如果不复盘，做事的人就不能够从中学到经验教训，碰到类似的事情，就会再犯同样的错误。不复盘，无法实现经验传承，无法让个人智慧变成组织智慧，团队能力得不到提升。\u003c/p>\u003cp>\u003cstrong>【how，细化步骤】\u003c/strong>\u003c/p>\u003cp>复盘是一种行之有效的从经验中学习的方法，那么，如何操作复盘呢？\u003c/p>\u003cp>\u003cstrong>第1步，回顾目标。\u003c/strong>回想一下当初做这件事的目的是什么？想要达成的目标是什么？阶段性或里程碑事件有哪些？ \u003c/p>\u003cp>\u003cstrong>第2步，评估结果\u003c/strong>。结果与预期目标相比，本次过程中的亮点有哪些？本次活动（事件）提升的地方有那些？\u003c/p>\u003cp>\u003cstrong>第3步，分析原因\u003c/strong>。找出导致成功或者失败的根本原因。要找出来是哪些因素造成的失败；成功的关键因素又是什么。\u003c/p>\u003cp>\u003cstrong>第4步，总结经验\u003c/strong>。在复盘中，我们学到了什么？是否总结出一些经验和规律。如果以后遇到类似的情况，可以如何进行？\u003c/p>\u003cp>\u003cstrong>【举例说明】\u003c/strong>\u003c/p>\u003cp>在2020年12月份，申请加入龙城分舵。原本计划着花9个月时间，通过所有拆书升级，成为一名三级拆书家。现在已经11月了，我现在还在过TF2-4。针对我自己拆书过级这个事情，我近期做了个复盘。\u003c/p>\u003cp>第一步，回顾目标。我的目标是花9个月时间，一个月过一级，通过所有拆书升级，成为一名三级拆书家。参加拆书帮的目的就是想学习一下这种拆书方法。\u003c/p>\u003cp>第二步，评估结果。截止现在，我才过了TF2-3。与原计划相比，我的目标没有完成。在这过程中，谈不上有做的比较好的地方。需要提升的地方就是过级速度太慢。\u003c/p>\u003cp>第三步，分析原因。分析了一下，未能按计划进展的原因。有点眼高手低了，感觉这个过级不难，但实际在写逐字稿的时候还是很费时间的。平常下班之后，有点懈怠，没有坚持去看书。就想着下个月多过一级，这样子进度就能赶上。实际上要想很好掌握每个级别的要点，是需要花时间去认真研究。\u003c/p>\u003cp>第四步，总结经验。经过前面的反思，要想顺利通过三级，需要投入大量的时间和精力，认真研究过级要点，严格按照既定过级计划去执行。后续过级就要按照这个思路去认真准备。\u003c/p>\u003cp>\u003cstrong>【where适用边界】\u003c/strong>复盘的底层逻辑非常简单，按照复盘涉及的主题范围、主题内容，我们将复盘分为四类（个人复盘、团队复盘、项目复盘、经营/战略复盘）。今天学习的复盘主要用于个人复盘，可以对工作、生活中的关键事件、有价值的、重要的事情，通过复盘能实现能力迭代的一些事情，去做复盘。其他一些对自身意义不大的事件就简单反思即可。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>可能有人就会想“复盘”和“总结”不都差不多吗？何必搞得这么复杂。其实，复盘和总结的底层逻辑是有本质区别。总结偏向于对过去事件的回顾，吸取教训。复盘是在回顾的基础上，提出改进措施，偏向于行动改善。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】激活经验\u003c/strong>\u003c/p>\u003cp>听完了复盘的四个步骤后，现在请大家回想一下，在过去一个月里，你的工作、学习、生活中有没有什么事情值得你去总结反思的（比如你刚完成一个较大工作项目,领导要求做个总结反思又或是工作中与同事碰到了冲突，要总结一下沟通技巧，以便提升自己沟通水平，也有可能是你制定的个人学习目标没有完成，内心特别焦虑，想做个自我反思的等等），当时你是怎么做的？给大家2分钟时间，大家可以在小组内讨论一下，然后写在你们面前的便签纸上。邀请一位老师进行一个分享。\u003c/p>\u003cp>\u003cstrong>【A1+】反思加工\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家设计提问：\u003c/strong>好，我看大家都写的差不多了，现在我们邀请一位老师进行一个分享当时的总结反思场景。\u003c/p>\u003cp>\u003cstrong>【学习者案例实录】：\u003c/strong>\u003c/p>\u003cp>张老师：在家临摹毛笔字，目标是计划一周临摹一遍，平均每天就是150个字。临摹10遍之后测算是每天只临摹了128个字，没有达成预期目标。\u003c/p>\u003cp>非常感谢张老师的分享，现在请大家设想一下，假如你现在坐上时光穿梭机回到那个时间点，你会怎么运用刚才学到的复盘四步法？给大家2分钟的时间，大家可以在便签上写下应用的过程。\u003c/p>\u003cp> 好的，2分钟时间已经到了，那么我们有请一位老师来给我们分享一下，讲述一下他需要复盘的事件以及如何应用复盘的四步法。\u003c/p>\u003cp>\u003cstrong>【学习者案例实录】：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>背景：\u003c/strong>张老师在家临摹毛笔字，目标是计划一周临摹一遍，平均每天就是150个字。临摹10遍之后测算是每天只临摹了128个字，没有达成预期目标。做如下复盘：\u003c/p>\u003cp>第一步：回顾目标。原计划目标是每天临摹150个字，每周临摹一篇。\u003c/p>\u003cp>第二步：评估结果。实际每天临摹128个字，没有达成目标。\u003c/p>\u003cp>第三步：分析原因。没有强制性要求自己每天必须临摹150个字，状态好的时候，就多临摹。今天事情多了，就少临摹了。没有完全按计划去做。\u003c/p>\u003cp>第四步：总结经验。本身这个事情就是一个比较随心的事情，要想完成这个事情，就必须按照既定计划去实施。另外一个经验就是选择教材的时候，要特别注意一下。\u003c/p>\u003cp>\u003cstrong>【回应或反馈】：\u003c/strong>好的，张老师用了复盘的四个步骤，对临摹字帖进行了一个复盘。非常感谢张老师精彩的分享。大家用热烈的掌声送给张老师。\u003c/p>\u003cp>\u003cstrong>【结束语】：\u003c/strong>经过刚才分享交流，我们对复盘的四个步骤的认识又进一步加深了。希望大家回去之后能将这个方法真正的用于实际生活之中。\u003c/p>\u003cp>\u003cstrong>【过度语】\u003c/strong>\u003c/p>\u003cp>实践证明，复盘实一个非常实用的工具，其逻辑关系非常好理解。要想真正开展深入且有效的复盘并非易事，需要熟知每个步骤的操作要点，接下来我们选取复盘的四个步骤中，最关键的一个步骤“分析原因”展开讲解，要如何进行深度的原因分析？\u003c/p>\u003cp>\u003cstrong>拆页片段2学习目标：\u003c/strong>在跟随我完成拆页片段学习后，学习者能够掌握5why分析法，并且对工作、生活中的一个事情进行深度原因分析。请大家花3分钟时间阅读手中的拆页，阅读完的伙伴请举手示意一下。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":16646,"quote":"\u003cp>\u003cstrong>拆页片段2原文\u003c/strong>\u003c/p>\u003cp>“分析差异原因”是复盘最为重要的阶段之一，只有找到真正的原因，才能实现高质量的学习。对此，“五个为什么”是一种简单实用的方法。\u003c/p>\u003cp>\u003cstrong>如何使用“五个为什么”\u003c/strong>\u003c/p>\u003cp>这一方法的使用非常简单，以至于只需要以下三个步骤。\u003c/p>\u003cp>\u003cstrong>第一步，提问第一个为什么\u003c/strong>\u003c/p>\u003cp>挑选出一个问题症状作为开端，然后问小组成员第一个为什么：“为什么这件事情正在发生?\u003c/p>\u003cp>可能对这个问题有三四个答案。把这些答案全部粘贴在墙上，在这些答案周围留有足够的空间。\u003c/p>\u003cp>\u003cstrong>第二步,依次追问“为什么\u003c/strong>\u003c/p>\u003cp>重复墙上每个答案，依次追问“为什么”。把每个答案和答案的答案”粘贴到它的“母问题”附近。\u003c/p>\u003cp>\u003cstrong>第三步,对问题进行整合\u003c/strong>\u003c/p>\u003cp>当所有的问题回答完毕后，一些问题可能开始整合，并追溯到十几个不同的症状，发掘两三个系统性的根源。\u003c/p>\u003cp>例如，里克·罗斯在《第五项修炼·实践篇》中提到了一个有趣的案例\u003c/p>\u003cp>一位车间主任看到车间地板上有一摊油。他马上习惯性地抓住离他最近的一个工人，让他把油擦掉。\u003c/p>\u003cp>此时，一个善于使用“五个为什么”的顾问提出了第一个为什么”：“为什么地板上会有一摊油?\u003c/p>\u003cp>旁边的工人回答道：“噢，噶本机漏油了。”\u003c/p>\u003cp>那你还不赶紧去把噶本机修好?”车间主任吼道。可那个顾问却继续追问：“为什么噶本机会漏油?\u003c/p>\u003cp>因为塞子有毛病。”工人答道。\u003c/p>\u003cp>为什么塞子有毛病?”那个顾问继续追问，提出了第三个“为什么”。\u003c/p>\u003cp>我也不清楚，反正这一批塞子都不经用，很差。”工人无奈地说。\u003c/p>\u003cp>“那么，你需要搞清楚，为什么你们会买这么差的塞子。”顾问对车间主任说。\u003c/p>\u003cp>通过不停地追问“为什么”，可以找到导致问题出现的深层次原因，避免就事论事，只是消除了问题的“症状”，而未从根本上解决问题。\u003c/p>","explains":"\u003cp>好的，大部分伙伴已经阅读完了，没有读完也没有关系，接下来我来进一步讲解一下。\u003c/p>\u003cp>\u003cstrong>【what】\u003c/strong>这个片段讲的是在复盘中如何应用5WHY分析原因，最终找到真正的原因,在源头就把问题解决掉，从而达成目标。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>对大部分人来说，如果工作生活中碰到困难或目标反复难以实现时，通常采取的措施是针对症状 “头痛医头，脚痛医脚”，但这样做“治标不治本”，它还会反复发作，折磨着我们。为什么会这样呢？那是因为问题，它就像冰山一样，不是一天积累而成的，是过去很多事件一个个累积而成，最后爆发呈现出来的表象只是最后一层，我们唯有深入下去，才能把问题根源找到，把它移除或摘取，要不然即便这刻处理完后，下一刻它又露出来。5WHY分析方法就是教我们如何深刻剖析问题，寻找最根本的原因的一种方式。5why分析方法能帮助我们透过现象，发现问题背后的根本原因，彻底杜绝问题再次发生。\u003c/p>\u003cp>\u003cstrong>【how，细化步骤】那么，具体应该怎么样运用5WHY原因分析法呢？它包括三个步骤：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一，识别表象问题。\u003c/strong>提问第一个为什么，识别表面问题，问现状、问差距。针对出现的问题，提问问题发生的现象。\u003c/p>\u003cp>\u003cstrong>第二，探寻直接原因。\u003c/strong>依次追问前面时间发生的原因是什么。提问why寻找前一个事实的原因，直到找到根源问题。\u003c/p>\u003cp>\u003cstrong>第三，挖掘根本原因。\u003c/strong>对问题进行整合，寻找问题本质。在不断提问中，问题的根因逐渐浮出水面，达到寻找问题的根本原因。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>可能这个时候有小伙伴也会疑惑是不是五why分析法一定要问五个问题？答案是5Why提问法并非只能是五个问题，而是宽泛地表示多个，如果你可以使用3个提问就找到本质，也可以，当然需要问到10次，只要有必要也是可以的。\u003c/p>\u003cp>\u003cstrong>【意译案例】\u003c/strong>\u003c/p>\u003cp>2021年10月14日，我首次过TF2-4练级，结果未能通过。针对这个事情，一个不善于使用“五个为什么”的朋友就会说：“下次再来一次”。但是，一个善于使用“五个为什么”的朋友提出了第一个为什么。\u003c/p>\u003cp>1\u003cstrong>why:\u003c/strong>为什么没通过TF2-4练级？\u003c/p>\u003cp>我回答道：因为涉及TF2-4技能点未达到要求 。一个不善于使用“五个为什么”的朋友就会说：“那你再回去修改逐句稿，再来一次”。而一个善于使用“五个为什么”的朋友提出第二个为什么。\u003c/p>\u003cp>\u003cstrong>2why:\u003c/strong>为什么没有达到技能点要求？\u003c/p>\u003cp>我回答道：因为觉得这个技能点不是很难，对具体技能点未能深入理解其中的要求。一个善于使用“五个为什么”的朋友继续追问，提出了第三个“为什么”。\u003c/p>\u003cp>\u003cstrong>3why:\u003c/strong>为什么不重视技能点具体要求，深入去理解一下？\u003c/p>\u003cp>我回答道：因为对自己比较自信，大意了，只从自己角度出发理解技能点，未与观察家或师傅进行技能点要求沟通。过级的要求就是考核技能点。\u003c/p>\u003cp>\u003cstrong>4why\u003c/strong>：为什么会过于自信和大意，不提前沟通技能点？\u003c/p>\u003cp>我回答：自己在准备过程中，准备时间不充分，使得拆书稿在审核反馈过程中，稿子刚准备好，就已经需要上场拆书了。\u003c/p>\u003cp>\u003cstrong>5why\u003c/strong>：为什么不提前准备，让准备时间更充分？\u003c/p>\u003cp>我回答：主要还是意识上不重视，所以以后先提前半个月准备好拆书稿，然后对技能点逐个熟悉并根据反馈调整完善。\u003c/p>\u003cp>\u003cstrong>通过不停地追问“为什么”，探究未能过级的根本原因。得出解决问题的最终方法是：摆正态度，提前准备，充分与观察家或师傅沟通一下技能点具体要求。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【where 适用边界】\u003c/strong>\u003c/p>\u003cp>1、5Why分析法起初是用来解决生产现场出现问题，找解决问题的根源，当我们在工作生活学习中，当计划或目标执行出现问题，或方案及策略无效时，也可以使用5Why提问法连续追问，发现根本原因进而去解决。2、5why提问法适合对事不对人，连续提问的时候有咄咄逼人的感觉，连续追问会给人造成压迫感，引起反感。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3应用】\u003c/strong>通过以上的讲解，我们各位老师都对5why分析法有一定了解，那么接下来我们进行一个实操演练，以便我们更好掌握这个方法。\u003c/p>\u003cp>\u003cstrong>【场景设计】\u003c/strong>现在让我们置身于这样一个场景中，老王向他的好朋友老李倾诉最近他在读书过程中碰到的困惑。老王是一名读书爱好者，在年初的时候给自己定了个小目标，每个月要阅读一本书，并做好读书笔记，本年度至少要完成12本书籍阅读。截止今年10月底，他才读了8本书，做了7个PPT读书笔记，距离他当初设定的目标有很大的差距。作为老王的好朋友老李，你用刚才我们所学的5why帮他剖析一下未能完成预期目标的原因。\u003c/p>\u003cp>\u003cstrong>【角色扮演】\u003c/strong>我们预计花5分钟时间，我们两个人一个小组，大家先在小组内容讨论、交流、演练一下。最后，我们邀请两位老师进行一个角色扮演，一个扮演老王，一个老李，给我们现场演练分享一下。\u003c/p>\u003cp>好的时间到，邀请两位老师进行一个角色扮演。\u003c/p>\u003cp>\u003cstrong>【学习者案例实录】\u003c/strong>\u003c/p>\u003cp>李老师扮演老李，夏老师扮演老王\u003c/p>\u003cp>老李：\u003cstrong>1why\u003c/strong> 老王啊，你为什么没有完成既定读书计划呢，才读了八本书？\u003c/p>\u003cp>老王：客观上没有时间啊\u003c/p>\u003cp>老李：\u003cstrong>2why \u003c/strong>为什么没有时间呢？\u003c/p>\u003cp>老王：就是工作太忙了\u003c/p>\u003cp>老李：\u003cstrong>3why \u003c/strong> 老王啊，按照每个月一本书，平均下来每天也就10页，为什么你一天10页书都看不完呢？\u003c/p>\u003cp>老王：老李，你不知道啊。累的时候，根本就不想翻动那个书。\u003c/p>\u003cp>老李：\u003cstrong>4why\u003c/strong> 为什么你每天那么累啊？\u003c/p>\u003cp>老王：因为我工作太忙，导致我很累，没有精力，所以我自读了8本书。\u003c/p>\u003cp>老李：\u003cstrong>5why\u003c/strong> 鉴于你的工作情况，为什么你当初要定这个12本/年的读书目标。\u003c/p>\u003cp>老王：对自己的认知不够，读书目标定高了。\u003c/p>\u003cp>\u003cstrong>【拆书家回应或反馈】\u003c/strong>非常感谢两位老师精彩的演绎，两位老师用5WHY分析法层层剖析了未能完成年度读书目标的时间，探究出根本原因是老王高估了自己，把读书目标定高了。让我们用热烈的掌声送给两位老师。\u003c/p>\u003cp>\u003cstrong>【A2 分步催化1】\u003c/strong>那现在请你设想一下，在你未来的半个月里，在生活和工作过程中会有哪些场景可以用到5why来剖析失败原因（比如你组织了一场活动，中间突发了一些状况，领导很生气，活动结束，领导要求你分析一下原因，避免类似的情况发生，你就可以用5WHY来分析一下突发状况的原因；又比如说月初时候自己设定一个小目标，结果临近月底了，小目标只完成50%，你很焦虑，这时候就可以用5WHY来分析一下什么原因导致了目标未实现呢？等等类似的场景）？强调一下，只需想像一下可能会发生的场景就行，不需要涉及如何分析原因，我们将在下一环节思考如何分析原因。\u003c/p>\u003cp>给大家两分钟时间，2分钟后我会邀请一位老师分享一下。两分钟时间到，那么请一位老师给大家分享一下他的场景。\u003c/p>\u003cp>\u003cstrong>【学习者案例】\u003c/strong>\u003c/p>\u003cp>王驰驰：给武图做读书分享，未提前把读书稿和大纲罗列好，到最后急急忙忙去做，最后效果呈现就会很差。\u003c/p>\u003cp>好，谢谢王老师给我们的分享。我们大家把热烈的掌声送给他。\u003c/p>\u003cp>\u003cstrong>【A2 分步催化2】\u003c/strong>拆书家设计提问：\u003c/p>\u003cp>现在，请每个小组针对刚才讨论的情景，运用今天所学的5WHY分析法对这个事件进行一次原因分析。现在请你拿出便签，花5分钟时间写下你原因分析的过程，并在小组内分享一下。然后，5分钟后，我们会请一位老师，给我们分享一下他的应用。\u003c/p>\u003cp> 时间到，这次请一位老师给我们分享一下。\u003c/p>\u003cp>\u003cstrong>【学习者案例】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>案例1\u003c/strong>王驰驰老师分享背景：给武图做读书分享，未提前把读书稿和大纲罗列好，到最后急急忙忙去做，最后效果呈现就会很差。\u003c/p>\u003cp>1why:为什么给武图的读书分享不及时，呈现效果不好呢？\u003c/p>\u003cp>原因：原本是每个月两个老师分享，有时候另外一个老师都没有空，我都要补上，一个月要讲两次，一次要准备两本书在那里讲，导致准备不够充分。\u003c/p>\u003cp>2why:为什么准备不充分？\u003c/p>\u003cp>原因：在时间规划上没有安排好\u003c/p>\u003cp>3why:为什么没有规划好呢？\u003c/p>\u003cp>原因：在生活上，工作上没有把这个事情列为重点\u003c/p>\u003cp>4why:为什么没有列为重点呢？\u003c/p>\u003cp>原因：这个读书分享没有多少钱，激励性不强。\u003c/p>\u003cp>好，我们再邀请一位老师进行一个分享，有请郑老师\u003c/p>\u003cp>\u003cstrong>案例2\u003c/strong>郑玲老师分享背景：拟计划12月初开展一场3小时的亲子正面财商沙龙，截止今天，海报没有做、场地也没有定，招募也没有开始，这个事情99%是要黄了。\u003c/p>\u003cp>1why:为什么亲子正面财商沙龙无法按照既定时间开展？\u003c/p>\u003cp>原因：没有指定计划，这个事情今天拖明天，明天拖后天，一天拖一天，眼看时间要到了\u003c/p>\u003cp>2why:为什么没有提前做好准备呢？\u003c/p>\u003cp>原因：因为有疫情，不好出门，然后最近事情有特别多，要准备这个，又要准备那个，没有时间。\u003c/p>\u003cp>3why:为什么会没有时间？\u003c/p>\u003cp>原因：其实是不想去做\u003c/p>\u003cp>4why:为什么会不想做呢？\u003c/p>\u003cp>原因：一个字“懒”，怕麻烦，内心有种恐惧感。\u003c/p>\u003cp>5why:为什么内心会有恐惧感？\u003c/p>\u003cp>原因：因为在公众面前开这个沙龙，害怕万一失败了，太丢面子。不自信，自己不相信自己，害怕自己做不好。\u003c/p>\u003cp>\u003cstrong>【对学习者回应或反馈】\u003c/strong>\u003c/p>\u003cp>非常感谢两位老师的精彩演练分享。两位老师针对自己的事情，分别用5WHY分析法深度剖析了问题，探究出根本原因。5WHY分析法是一种非常实用的工具，大家可以在以后工作、生活中尝试多应用，让问题得到彻底解决。\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp>今天我们将近花了一个小时的时间，给大家分享了复盘的四个步骤和5WHY分析法。一个完整的复盘包含回顾目标、评估结果、分析原因、总结经验，这四个步骤。我们重点学习了5WHY分析法，如何探究问题根源。熟练掌握复盘的方法，去应用、去实践，可以将过去的成与败转化为能力，不断持续精进工作、改善生活。那么，我今天的分享就到此结束了，感谢各位老师的陪伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1637935421000,"updated_at":1638247331000,"ria":true},{"id":11244,"topic":"如何利用过往经验学习并提升能力？","learn_goal":"","remark":"许多人都或多或少有这样的想法：我就是做不好菜、我没有计算天赋、我演讲水平怎么也没法提高……是什么阻碍了我们的进步？天赋吗？还是资源？不，是学习方法。高手之所以学习效率很高，其中一个很重要的原因就是他懂得如何“复盘”，复盘是学习的最高效方式，懂得如何利用复盘来学习，你也有机会成为某领域高手。","level":"TF3-3","duration":60,"status":30,"type":0,"chaishujia":{"username":"阳小齐","city":"南宁"},"club":{"name":"南宁清澄分舵","city":"南宁"},"prologue":"\u003cp>学习目标：第一部分我们主要探讨什么是复盘，如何做个人复盘。通过学习，学习者了解什么是复盘，并能够用复盘结构化系统化的四步法，即个人复盘模板（澄清），协助自己在过往经历中发现和提炼新的认知，列出有针对性的行动计划（行为），帮助自己在未来遇到同样或类似的事情时，能继承过往好的经验，并避免犯相同的错误（界定）。第二部分我们要探讨个人复盘的优势和局限性，并懂得利用“验证复盘结论三原则”（澄清）来检验复盘结论是否正确（行为）。现场将通过微行动学习讨论学习者对本次学习感到困惑的其它难点，并加工出解决方案。\u003c/p>\u003cp>开场：（自我介绍）大家好，很高兴大家今天能来参加我们清澄分舵的拆书活动，我是来自广西图书馆的小齐，因为书，我和拆书帮结缘，和小伙伴一起学习是我的荣幸，今天将进行我三级拆书家之旅的最后一关3-3的学习，（分组）在学习之前我想给大家分一下组，待会儿会有两种分组的形式，一种是两两为一组，今天来的小伙伴比较少，我们就分为两组，第二个片段我们将合在一起讨论，一个组即可。\u003c/p>\u003cp>介绍图书：今天我们要拆的这本书叫《复盘+》（事件场景）先给大家讲一个故事，平时大家有没有遇到这样一类人，他很喜欢烹饪，看了很多烹饪的书，也请教了很多烹饪达人，结果他的烹饪技术还是不咋地，最后人家对他的烹饪技术的评价就两字：能吃。我们办公室就有这样的一个小伙伴，他看了很多烹饪的书，图书馆嘛，很多这类的资源，但是他的技术很难提高，或者提高得很缓慢。（提问）所以我就想问一下，为什么他的烹饪技术总是提高得这么慢呢，原因在哪里呢？（影响）我们可以把事物发展的原因分为内因、外因；主观原因、客观原因。我们常常会把失败归结为各种客观原因，外因，比如“我天赋不够”“看的书有问题”“食材有问题”“工具不好”，也有分析可能是我自己的原因，内因，如“学习方法不对”，可是怎样的学习方法才对呢？又不知道了，于是我们就在这种屡败屡试，屡试屡败的过程中反复，进步很慢。（解决）直到我看了这本《复盘+》，我才发现，正如有句老话讲得好“前事不忘后事之师”，很多时候我们学到的知识都来自过去的经验总结，如果我们能找到一个种科学的总结经验的方式方法，我们将会比别人学得更快更好，这本《复盘+》就给到了我们很多这方面的启示，什么是复盘？简单来说就是一种特殊的总结，具体概念待会儿我再讲。 这本书的作者邱昭良博士，他曾经是柳传志的业务助理，万达学院的副院长，经历过大大小小无数次的复盘，于是他就总结并写成了这本书，这本书是第三版了，通过这本书的学习，我们可以学到各种复盘的知识，包括个人复盘，组织复盘等。\u003c/p>\u003cp>我们来看一下今天学习地图，即学习内容：\u003c/p>\u003cp>第一部分：什么是复盘，如何做个人复盘。\u003c/p>\u003cp>第二部分：复盘的优势和局限性。\u003c/p>\u003cp>（量表测试）在进入第一部分学习之前，我想先请大家做一个量表测试，请看学习资料的第一页，以下6道题目，请按照1到6分的标准给自己打分，1代表题目表述完全不符合你内心的想法，6代表完全符合，数字越大，符合度越高。请仔细阅读表格中的每句话，根据自己的实际情况为自己打分。总分： \u003c/p>\u003cp> 做完测试的请大家加一下总分，本次测试目的是为了让大家了解在学习之前，大家是不是具备复盘的原始意识，对照一下自己的分数，如果总分在15分以上，这说明你在本次学习之前已经具备一定的复盘意识，这对接下来的学习非常有帮助，如果分数在15分以下，也不必着急，这说明你在本次学习中会更加有收获，所以我们要打起精神，认真学习今天的知识。\u003c/p>\u003cp> 接下来请大家把学习资料翻过来看到第二页，这是今天学习的第一个内容——什么是复盘，请大家用一到两分钟的时间阅读一下，并拿笔划出关键词，你觉得什么是复盘，他有什么特点，自己试着总结一下。\u003c/p>","ratings_count":1,"texts":[{"id":15159,"quote":"\u003cp>什么是复盘？\u003c/p>\u003cp> “复盘”原是围棋术语，本意是对弈者下完一盘棋之后，重新在棋盘上把对弈过程“摆”一遍，看看哪些地方下得好，哪些下得不好，哪些地方可以有不同甚至更好的下法，等等。\u003c/p>\u003cp> 这个把对弈过程还原并且进行探讨、分析的过程，就是复盘。通过复盘，棋手们可以看到全局以及整个对弈过程，了解棋局的演变，总结出适合自己和不同对手的套路，或找到更好的下法，从而实现自己棋力的提升。唐代诗人杜牧在《重送绝句》一诗中曾形象生动地描述了他与一位围棋高手对弈后复盘的场景：“绝艺如君天下少，闲人似我世间无。别后竹窗风雪夜，一灯明暗覆吴图。”\u003c/p>\u003cp> 用到企业管理中，复盘指的是从过去的经验、实际工作中进行学习，帮助管理者有效地总结经验、提升能力、实现绩效的改善。正如联想集团创始人柳传志先生所说：所谓复盘，就是一件事情做完以后，做成功了，或者没做成功，尤其是没做成功的，坐下来把当时的这个事情，我们预先怎么定的、中间出了什么问题、为什么做不到，把这个要理一遍，理一遍以后，下次再做的时候，自然这次的经验教训就吸收了。\u003c/p>\u003cp>《复盘+》第三版P25\u003c/p>","explains":"\u003cp> 好了，通过上面这段文字我们知道，复盘来自围棋的术语，下完一盘棋，我们通常会回去研究每一手棋的走法，哪些下得好，哪里下得不好，帮助下次做得更好。用到企业和个人里，复盘就有更丰富的外延了，（互动）我想请问各位，你觉得关于复盘的定义，有哪些关键词呢？\u003c/p>\u003cp> 学习者回答：过去的总结；还原、探讨、分析；好和不好的；对未来的规划\u003c/p>\u003cp> 好的，大家的总结都很不错，接下来我想请大家来看一下我的总结：复盘是一个结构化系统化的，目标指向学习，并针对自身过往经历的一个特殊的总结。（对比混淆概念）我们用语文拆解句子的方法，我们发现这句话就是“复盘就是总结”。这就是很多人学复盘时的一个疑惑，总结经常做，那我干嘛还要学复盘，平时不都在做吗？但大家注意复盘的定义里还有一段长长的定语，这就说明它和一般的总结还是有区别的，他们之间的概念是不能混淆的。\u003c/p>\u003cp> 那我们就从这些定语里的关键词解析一下什么是复盘，\u003c/p>\u003cp> 第一个关键词：结构性系统性。\u003c/p>\u003cp> 刚才有小伙伴说复盘要总结好和不好的地方，那我们一般的总结会只总结做得差的地方，我的儿子的老师最近叫孩子们写考试的反思，他们就都是写“我这次被扣几分，我下次争取不被扣这么多分”，但是复盘除了总结不好的部分，我们还需要总结做得好的部分，请大家看到学习资料的第三页：个人复盘模板，这里给到大家一个做复盘结构化系统化的四个步骤。\u003c/p>\u003cp>（how）：\u003c/p>\u003cp>个人复盘模板\u003c/p>\u003cp>（举例）接下来我就给大家看我儿子数学考试的复盘案例：\u003c/p>\u003cp> 这就是复盘结构化系统化的体现。这样大家就能看见和一般总结的区别就很大了，一般的总结都是总结不足和失败，没有更全面系统化的过程。\u003c/p>\u003cp> 第二个关键词：指向学习。\u003c/p>\u003cp> 复盘的目的是指向学习，但很多总结不是，比如很多会议，开着开着就变成批斗大会，或者表彰大会，总结的目标不一定是为了学习，而是变成表达情绪了。\u003c/p>\u003cp> 第三个关键词：针对自身过往的经历。\u003c/p>\u003cp> 很多总结是帮着别人做的，比如帮领导，帮孩子做，但我们这里指的复盘一定是针对自身的过往经历。\u003c/p>\u003cp> （强化讲解概念1） 所以我们这里给复盘与总结画了一张关系图：复盘只是总结的一个子集，而我们平时做的很多总结不是复盘，只能算一般总结。\u003cbr>\u003c/p>\u003cp> （where 预防异议·适用边界）当然，我这里需要再次强调一下，我们今天讲的是个人复盘，而组织复盘会比个人复盘更复杂，大家如果对组织复盘感兴趣，可以去自行查看《复盘+》里的内容。我们今天讲到的知识点：复盘模板的四个步骤，如果把这四个步骤用于组织复盘，那就过于简单了，所得结论就不一定正确。\u003c/p>\u003cp> （强化讲解概念2，学习者做完A2后拆书家再次回顾复盘的定义）所以再次说一遍：复盘是一个特殊的总结，是总结的一个类型，但是复盘特殊的地方在于它是一个结构化系统化的，目标指向学习，不是发泄情绪的，并针对自身过往经历的一个特殊的总结。\u003c/p>","interaction":"\u003cp> A2（分步催化） 给大家一个小任务：根据刚才的两两分组，请大家在未来一个月内和你的小组搭档一起完成三次复盘任务。这个复盘怎么做呢，接下来的时间我就带着大家一起来演练其中的一次复盘，大家回去后就按照这个演练的过程完成自己的复盘任务。请大家听我的指令。\u003c/p>\u003cp> 第一步：大家请想一下，过往的一年半载里有没有什么事情是你觉得值得你再“过一次”的？如果现在摆着一台时光机在你的面前，你如果把这件事写下来扔进时光机，它就能带着你回到那时，让你重新再来一次，重新经历一次，你会往里面投一件什么事情呢？请你把想到的事情写在个人复盘模板的“事件”这一栏里。这件事可能是你感到后悔的，如和家人、同事等做错了，或做好了，让你印象深刻的事，你觉得这事做得太好或者有缺憾，想重新再做一次的，再体验一次的。\u003c/p>\u003cp> 第二步：填好你想回顾的事件后，请大家用几分钟的时间填写一下个人复盘模板的四个部分内容：回顾目标、评估结果、分析原因、总结经验。\u003c/p>\u003cp> 第三步：填好后，假设今天晚上或者明后几天，你和你的分组伙伴通话聊一聊你的复盘，现在就来模拟一下这个聊天的过程：一个小伙伴问，一个小伙伴回答，然后交换。\u003c/p>\u003cp> 第四步：请一组小伙伴上台表演示范聊天的过程（小剧本）。\u003c/p>\u003cp> 蓝夏问：你要复盘的这个主题是什么呢？\u003c/p>\u003cp> 婉娴答：我一月份参加一个线上训练营的情况。\u003c/p>\u003cp> 蓝夏问：具体的事件大概说一下。\u003c/p>\u003cp> 婉娴答：我一月份的时候报名了一个销售类的线上训练营，但我当时没有坚持学完。就想对这个事情进行一次复盘\u003c/p>\u003cp> 蓝夏问：你当初的初衷是什么？\u003c/p>\u003cp> 婉娴答：想通过这个训练营学习销售，也看看自己到底适不适合做销售。\u003c/p>\u003cp> 蓝夏问：结果呢？\u003c/p>\u003cp> 婉娴答：没有学完课程。浪费了。\u003c/p>\u003cp> 蓝夏问：那你觉得这次学习的亮点是什么？\u003c/p>\u003cp> 婉娴答：就是我发现我需要提升，然后我还主动报名了训练营，有提升的想法还行动了，在训练营里我还链接了几个同学，这些\u003cbr> 同学还给了我很多新点子，打通了许多卡点。\u003c/p>\u003cp> 蓝夏问：那不足呢？\u003c/p>\u003cp> 婉娴答：没完成课程，没有完成作业和打卡。\u003c/p>\u003cp> 蓝夏问：那你觉得成功的因素是什么？\u003c/p>\u003cp> 婉娴答：是因为我是比较喜欢结交朋友的。而且我有这方面的积累，能快速获得他人信任，做好了给予他人帮助的准备。\u003c/p>\u003cp> 蓝夏问：失败的原因是什么？\u003c/p>\u003cp> 婉娴答：因为这个销售训练营和拆书帮的RIA训练营冲突了，我在时间上没有安排好。有拖延症。\u003c/p>\u003cp> 蓝夏问：你觉得你有什么关键的发现？\u003c/p>\u003cp> 婉娴答：我发现虽然在家里宅了几年（带娃），但是我还是有一定与人交往的能力的，有这方面的优势的。也发现我在时间安排\u003cbr> 能力上有待提高。我还有完美主义的倾向，我作业如果不能完成得很好，我就不想去打卡。\u003c/p>\u003cp> 蓝夏问：那你有什么行动计划？\u003c/p>\u003cp> 婉娴答：我觉得我需要去学习时间管理，参加拆书帮有关时间管理的课程。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":15169,"quote":"\u003cp> \u003cstrong> 复盘的优势和局限性\u003c/strong>\u003c/p>\u003cp> 复盘的优势是它基于每个人具体、生动的实践（“躬行”），如果能够深入地反思，可以实现“绝知此事”，也就是说，通过个体的身体力行，我们可以获得大量一手信息，深入分析、举一反三，可以把握事物的一般规律，从而更好地将其应用于未来类似的场景或工作任务与挑战中。当然，要做到这一点，前提是把复盘做到位，而不是走形式。\u003c/p>\u003cp> 与此同时，复盘这种学习方法也有局限性：一是它基于个人实践，每个人的反思、分析、提炼的深度都有差异，你以为发现了事物的规律，实际上可能并非如此；二是个人实践终归是有限的，就像职业围棋棋手终其一生，高质量的对弈也只有数千盘；如果只是依赖复盘，即使个人悟性很高，也可能存在一定的偶然性。\u003c/p>\u003cp>《复盘+》P29 \u003c/p>","explains":"\u003cp> 不知道大家对刚刚蓝夏和婉娴的分享有没有疑问呢？如果有的话，我们可以带着这个疑问阅读一下资料的最后一页，也就是今天我们学习的第二个片段：复盘的优势和局限性。\u003c/p>\u003cp> 这个片段告诉我们两点，首先是复盘的优势，刚刚我们已经讲过一些了，有研究表明，人类的70%的知识是来自过往的经验，如果你懂得科学的复盘，那么你将学得比很多人更快、更扎实，效率更高。这些都是复盘的优势，我在这里就不复述了。但我们明白复盘的优势还不够，我们还需要懂得如何把复盘坚持下来，所以这里我也给到大家一些建议（how），帮助大家养成复盘的习惯。1先僵化后优化：刚刚给了大家一个学习模板，为什么我们要给大家这个模板，并要求大家把每一个空格都填好呢？这就是一个僵化的过程。我们一开始对复盘并不熟练，完了之后，我们可以优化这个过程，有些环节可以省略就省略，快速过就快速过；2做重要事情的复盘，哪些比如忘记带伞这样的小事就没必要复盘了，但是如果是上班迟到这样的比较严重的错误，我们就可以去复盘一下；3建立一个复盘的学习小组，相互鼓励和督促，养成复盘的习惯。也可以把复盘的内容放入小组群里，让自己更有成就感，这样可以帮助大家坚持下来。\u003c/p>\u003cp> 但复盘也有它的局限性，因为我们个人的原因：履历，事业，对事情的认知是有限的，所以我们复盘出来的结论不一定完整，不一定正确。比如上次我们在现场讲复盘，分享的小伙伴就复盘了她找老公的过程，其实这可能跟她自我认知有限有关，她的复盘结果不一定对。为了避免复盘的局限性对我们造成负面的影响，我在这里也给到大家检测复盘的三原则：\u003c/p>\u003cp>1、复盘的结论的落脚点是否在偶发性的因素上？（我举个栗子）：拿破仑曾经称霸欧洲，但是还是滑铁卢——失败了，很多人就说那是因为拿破仑有痔疮。他们认为拿破仑一直受到痔疮的困扰，导致他没法指挥战斗，最后失败。这种就是典型的把原因归结为痔疮这种偶发性因素上了，但其实在备战之前，肯定会有预案，比如将领出现意外不能指挥战斗了，有没有副将顶替，做权力交割等，这才可能是原因。\u003c/p>\u003cp>2、复盘的结论是指向事而非人的。（例子）比如我上班迟到了，我会埋怨是今天开车的司机开车技术太差，导致我迟到了。这就是落脚点放在了人的身上，容易变成阴谋论。而指向事的复盘就应该把思路放到事件本身，比如有没有预留遇到突发情况的时间，有没有遇到突发情况的应对措施等等。\u003c/p>\u003cp>3、结论是否经得起交叉验证。比如你丈夫回来晚了，你就说他出轨了——证据之一是他回家晚了。但即便是法官判案，孤证是很难算数的。所以你还得找别的证据，比如他的聊天记录是否有问题，平时他对你是不是冷淡了，以及他的经济往来情况，甚至雇人跟踪（开个玩笑），意思就是你得找到多个证据指向你的同一个结论，你才能去下这个判断，孤证是不能得到正确结论的。\u003c/p>","interaction":"\u003cp>A3微行动学习\u003c/p>\u003cp> （发散·提出问题）：经过两个片段的学习：一个是什么是复盘，如何进行复盘；一个是复盘的优势与局限性，接下来的时间我将给到大家。那么在刚才的学习过程中，大家还有什么疑惑的地方吗？比如比较难操作的步骤，或难以执行的点，我们可以利用今天余下的时间一起来讨论，一起集众人智慧解决这个难点。\u003c/p>\u003cp> 学习者提出三个问题：1、如果把复盘的方法用到孩子的学习当中，怎么简便一些，大孩子容易理解，但一二年级的孩子就需要父母去协助，爸爸妈妈怎么去做（帮助低年级的孩子理解并应用复盘）？\u003c/p>\u003cp> 2、个人认知的局限性，不知道关键点在什么地方，也不知道找谁帮助自己点出局限性是什么，怎么办？\u003c/p>\u003cp> 3、不知如何去写复盘模板里的“亮点”和“成功的因素“，疑惑：感觉亮点和成功因素是同一件事。（拆书家答疑：亮点是成功的点是什么，是好的结果，成功因素是成功的原因是什么，是什么原因造成了这个好的结果。）\u003c/p>\u003cp> （收敛·明确问题）拆书家总结大家的讨论并给出反馈，经过投票决定讨论第二个问题。拆书家向提问者确认，明确问题：当复盘者不清楚自身局限性在哪里，如何帮助自己挖掘自身局限性，避免掉入“坑”里，导致得出错误的复盘结果。\u003c/p>\u003cp> （发散·明确问题本质）建议大家利用“丰田五问法”深挖一下这个问题的本质。（拆书家向学习者简单介绍丰田五问法：修车时有些部件坏了，比如方向盘转不动了，这可能只是表象，车里边可能发生了一系列问题，于是车企就发明了此法来追问问题的本源，举个例子：我今天上班迟到了，我问自己为什么迟到？答：因为起来晚了；为什么起来晚了？答：睡得晚了；为什么睡得晚？答：昨晚和朋友去喝酒了或者加班太晚了；为什么加班太晚？答：上班的时候没有抓紧时间，看腾讯视频刷抖音去了，自制力不够；为什么会这样？答：原因是个人时间管理能力比较差。）此处讨论实录略。\u003c/p>\u003cp> （收敛·学习者讨论结果）问题的本质是：因为我们害怕失去安全感、懒惰而不愿意走出舒适区；没有自我觉察；经验少等三方面的原因导致个人认知的局限，也不知自己有局限。\u003c/p>\u003cp> （发散·学习者就三个方面原因进行讨论）此处讨论实录略。\u003c/p>\u003cp> （收敛·拆书家引导学习者总结解决方案）1，关于如何走出舒适区和抵御懒惰的解决办法：从小事做起；把后果写出来；列每日清单让自己有做事的成就感；番茄钟；2，关于如何自我察觉的解决办法：挖掘自我需求；做呼吸练习以及冥想；多问自己what、why、how;借助如《非暴力沟通》等书籍里的方法去挖掘自己的感受和需求；。3，关于如何拓宽自己的经验的解决办法：多学习，学习包括线上和线下互动学习，最好是能线下学习，多与人连接进行头脑风暴；要刻意练习，多行动多实践；把所感所闻所想以书面形式写出来，加深印象。\u003c/p>\u003cp> 拆书家补充：大家也可以通过我们第二个片段的检测复盘三原则——即结论是否落脚于偶发性因素上、结论是否指向事而非人、结论是否经得起交叉论证——来减少个人复盘时的局限性带来的负面影响。\u003c/p>\u003cp>A2 留给大家第二个作业：请大家就自己今天讨论出来的解决方案，回去后列出属于自己的行动计划，以帮助自己走出舒适区，进行自我觉察，拓宽经验，从而发现个人认知的局限，并避免这些局限性给你的复盘带来错误的结论。\u003c/p>\u003cp>学习者A的行动计划如下（课后一周后提供）：\u003c/p>\u003cp>1、继续在拆书帮里升级打怪，每月都参加一到两次线下活动，这样我就可以多看书，多与人交流，从而拓宽自己的经验和认知。\u003c/p>\u003cp>2、买一本计划本，在上面写下每日每周每月计划，做完后在后面打勾，完成月计划就给自己买一件衣服作为奖励。\u003c/p>\u003cp>3、去淘宝下单《非暴力沟通》，争取半年内读完这本书，并用上面的片段来拆书过级，教是最好的学。\u003c/p>\u003cp>4、把个人复盘模板复印20份，每个星期填写至少一份，写完以后用监测复盘三原则来检验我的复盘的正确性。\u003c/p>\u003cp>拆书家总结本次学习（现场用板书配合总结）：今天我们学习了什么是复盘，复盘是一个结构化系统化的，目标指向学习，并针对自身过往经历的一个特殊的总结。怎么做复盘，我们给出四个步骤：回顾目标，不仅要评估做得不好的地方，还要评估做得好的地方，亮点在哪，给出做得好和不好的原因，最后一定要给出出行动计划，这才是结构化系统化的完整的复盘。接下来我们还讨论了复盘的优势和局限性，如何避免复盘局限性给我们带来的影响。最后，我们通过头脑风暴给出了拓宽自我认知，觉察自我局限性和避免局限性的方法和行动方案。这就是我们今天全部学习的内容，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1616754670000,"updated_at":1618199302000,"ria":true},{"id":10750,"topic":"如何利用过往经验学习并提升能力？","learn_goal":"","remark":"许多人都或多或少有这样的想法：我就是做不好菜、我没有计算天赋、我演讲水平怎么也没法提高……是什么阻碍了我们的进步？天赋吗？还是资源？不，是学习方法。高手之所以学习效率很高，其中一个很重要的原因就是他懂得如何“复盘”，复盘是学习的最高效方式，懂得如何利用复盘来学习，你也有机会成为某领域高手。","level":"TF3-3","duration":60,"status":29,"type":0,"chaishujia":{"username":"阳小齐","city":"南宁"},"club":{"name":"南宁清澄分舵","city":"南宁"},"prologue":"\u003cp>自我介绍：大家好，我是来自广西图书馆的小齐，欢迎大家参加我们今天3-3这个级别的拆书，分组（刚才咕咚猫分了组，我们待会儿就以咕咚猫的分组来进行讨论。）\u003c/p>\u003cp>介绍图书：\u003cstrong>（事件场景）\u003c/strong>首先我想给大家讲一个笑话，我们部门有一个人，她特别喜欢看书，尤其是烹饪类的书，大家也喜欢看吗？哪些图片特别养眼好看，看完了之后就回去实践，但每次实践之后的成品用四个字来形容——就是“黑暗料理”！\u003cstrong>（提问）\u003c/strong>如果你那个个人，你对自己的烹饪技术下一个什么评价？（学习者回答：不适合，不擅长）。\u003cstrong>（影响）\u003c/strong>对，你会觉得自己不是那块料对吗！\u003cstrong>为什么说这是一个笑话呢？因为这个人，就在这里——就是我！我曾经一度认为我就不是这块料，没有天赋\u003c/strong>。\u003cstrong>（解决）\u003c/strong>直到我发现了这本《复盘+》，我才发现可能我在学习的过程中我少了一个步骤，才导致我不会做这件事情，那就是这本书的名字——复盘。复盘，原来是围棋里的术语，就是两个人下完一盘棋后，就返回去，对每一步，每一手棋是怎么下的做一个复盘，复盘可以延伸到各行各业，怎么去学习，做完一件事后回头看一下，这件事情我是怎么处理的，当时我做得好的地方，不好的地方，总结一下，这是复盘。有研究表明，人的学习有70%左右来自过往的经历，所以如果我们能把复盘技术学到手，我们其实能比其别人学到更多的东西，成为更优秀的人。 这本书的作者邱昭良博士是柳传志的业务助理，万达学院的副院长，大大小小的复盘他经历过很多次，他非常有理论和实践的经验，于是他把对复盘的所知集结成了这本书，通过对这本书的学习，我们可以学到个人复盘和组织复盘的技术和方法。\u003c/p>\u003cp>\u003cstrong>学习思路及学习目标\u003c/strong>\u003c/p>\u003cp>今天我就带领大家阅读来自这本书里的两个片段，一起学习如何进行个人复盘。\u003c/p>\u003cp>第一部分我们来探讨\u003cstrong>什么是真正的复盘，如何复盘\u003c/strong>。（目标在现场没有说出来，但每个学习者的资料里都印有）学习者能够\u003cu>通过复盘的四步法（澄清）来协助我们从过往经验中发现和提炼新的认知（行为），从而在未来的行为里继续继承优点，同时避免再次犯相同的错误（界定）\u003c/u>；\u003c/p>\u003cp>第二部分的我们来探讨\u003cstrong>在复盘的过程中我们需要注意一些什么问题\u003c/strong>，\u003cu>大家在“复盘的几点建议”中选出最难执行的一个建议（行为）通过微行动学习（澄清），讨论并发现问题的本质，总结执行这一建议的行动步骤（界定）。【\u003cem>注：最后大家讨论结果为：通过朋友圈、抖音、微博等渠道的及时分享；给自己小奖励；制定周、月、季、年计划；要事优先处理等方法，来缩短复盘的效果周期，以及安排好用于复盘的时间，从而帮助我们持续复盘并定期回顾做过的复盘。】\u003c/em>\u003c/u>\u003c/p>","ratings_count":1,"texts":[{"id":14627,"quote":"\u003cp> \u003cstrong>片段一：柳总是怎样炼成的？\u003c/strong>\u003c/p>\u003cp>\u003cbr> 柳传志先生（我们很多人亲切地称呼他“柳总”） 是我最为敬重的人之一。从和他的接触中，我们能感受到他的人格魅力和领导力。那么，柳总是否生而如此？他的领导力和人格魅力是如何获得或形成的呢？\u003cbr> 在我看来，柳总应该具有极高的天赋，又有远大的目标、不断提高自己的追求，再加上极强的学习力，使其“修炼”成为伟大的企业家。在学习力方面，复盘是柳总总结发现的，也是其最主要的学习方式。\u003cbr> 这样的例子有很多。其中一个例子是，在早期创业时，在他的小办公室里，一个上午接连有四五个人去找他说事情，经常是前面一个人还没把话讲完，就被后面的人打断了，看上去很忙。\u003cbr> 可他晚上回去把整件事情重新想了一遍，认为自己这样的工作方法事倍功半，需要改进。同时，他还发现，大家和他讲的那些事与赚钱活命的事情都毫无关系。最后，他得出结论：不能让下面的同事拽着走，自己首先要想明白到底要干什么，然后把事情分出轻重缓急。这个想的过程就是复盘，虽然那时候没有一个特定的名称，但它可以成为个人快速学习、提升能力的一种有效方法。\u003cbr> 同时，柳总从这次复盘中也产生了设立一个协助总裁进行战略策划、推进和监督的机构的想法，为此，他设立了“企划办”，对于公司的规范化运作与管理也起到了积极作用。\u003cbr> 事实上，柳总一直保持着复盘的习惯，他在接受记者采访时表示：“我平常习惯每隔一个月左右，静下心来花5天左右的时间，把近来做的事情捋一遍，写写东西。”\u003cbr> 此外，柳总在联想内部大力倡导复盘，并使其成为企业的文化。这也是联想之所以有很强的组织学习力，可以应对一个又一个挑战的重要原因。\u003c/p>\u003cp> 《复盘+》P60-61\u003cbr> \u003c/p>","explains":"\u003cp>\u003cstrong>（讲解）\u003c/strong>看完片段不知道大家有什么收获?我们可以发现包括柳传志在内的很多成功人士其实都有复盘的习惯，不是说我们都要成为那么成功的人士，但是至少我们可以精进自己，成就更好的自己。\u003cstrong>（预防异议·对比混淆概念）\u003c/strong>可能有些小伙伴就会有疑问了：“复盘”平时我也有做啊，比如平时我们做完一件事情也会去想我是怎么做的啊，怎么做更好了，怎么改进啊等等，那么平时我们做的这种叫复盘吗？这里大家可以告诉大家，平时我们做的这种可能只能叫一般的总结。我们搞混了复盘和总结之间的区别。我在这里画了一个图给大家（见下），一个数学概念里的集合，如果总结是里面的总集，那么复盘其实是里面的一个子集，也就是说复盘只是总结的一种类型，我们很多时候做的总结其实是这个集合里的白色区域——一般的总结。\u003c/p>\u003cp> 下面我举两个例子大家给大家对比一下，比如说我们单位开了个礼仪培训，讲了三个小时，太长了，很多人中途就走了，后来等礼仪培训结束后，领导把门一关就说了：“来我们总结一下，这个礼仪培训，结果一帮人就这么走了，这个基本的礼仪都没有，今天在场的就算出勤了，不在场的就缺勤。”后面巴拉巴拉又说了一大堆；那么我们看一下拆页里柳传志先生他做的总结和我们领导这个有什么区别。柳传志是怎么做的？拆页里的第四段，起先他定的目标是赚钱；结果是被很多事情耽误了；他就分析原因是被杂事不相干的事消耗了时间；最后形成一个关键的发现：我不能被下属拽着走，我应该树立自己的目标，应该做什么事情；然后做了一个规划：设定目标，朝着目标走，另外设立一个部门来辅助处理庶务。\u003c/p>\u003cp> \u003cstrong>（互动）\u003c/strong>大家发现没有，我单位礼仪培训的总结和刘总的复盘，他们的区别在哪里？（学习者回答：刘总是发现问题解决问题；刘总有改进措施，发现问题，解决问题，提出具体做法，单位领导这种就是说说就完了；刘总把事情分轻重缓急）\u003c/p>\u003cp> \u003cstrong>（回应大家的回答并总结）\u003c/strong>好，刚才几位小伙伴总结得都很到位，我来总结一下它们的区别。一个最重要的区别就是复盘有明确的目标，而一般的总结不一定有，一般的总结可能就是一个情绪的发泄，包括一些表彰性的总结也是这样，上台拍照等等，具体要达到什么目标并不明确，包括我们的领导，他上台发泄情绪，他也没有达到他想要的目标；第二个区别，一般的总结根据个人的行为习惯，想到哪里就是哪里，流程是非常随意非常个性化的，比较没有章法，但是复盘是有程序化，模块化，流程严密的过程的，必须按照流程走，那才是复盘。这就是一般的总结和复盘的区别。所以我们可以再次定义一下复盘的概念：\u003c/p>\u003cp>\u003cstrong>（强化讲解概念）复盘是一个程序化模块化的，有特定目标的，并针对自身过往经历的一个特殊的总结。\u003c/strong>\u003c/p>\u003cp> \u003cstrong> （how）\u003c/strong>那么我们接下来就来看看怎么去复盘。大家请看“个人复盘模版”，下面的1,2,3,4点就是我们要做复盘的四个步骤。\u003cstrong>回顾目标\u003c/strong>，一开始初中是什么，最终结果是什么，它们之间有没有差距；\u003cstrong>评估结果\u003c/strong>，亮点是什么，做得好的地方是什么，不足又在哪里，需要改进的地方在哪里；\u003cstrong>分析原因\u003c/strong>，亮点，成功的因素是什么，失败了，失败的原因是什么，我们做一件事情不可能完全失败或完全成功，总有亮点和不足，就可以分开来讨论形成原因；最后我们还要\u003cstrong>总结经验\u003c/strong>，我在这件事情上有什么关键发现，可以帮助我今后的实践，另外更重要的是制定将来的行动计划。这就是整个复盘的模板。\u003c/p>\u003cp>个人复盘模版:\u003c/p>\u003cp>\u003cstrong>（举例）\u003c/strong>比如这个礼拜一，我参加了一个全区的业务竞赛，我分析：\u003c/p>\u003cp>\u003cstrong>（预防异议·说明适用边界）\u003c/strong>可能有小伙伴会说，我们可不可以把这个复盘模板用在某次集体活动里？不好，因为我们今天学的是针对个人的复盘，这个模板也是属于个人复盘模板，适合你自己，并不适合集体和组织的复盘，如果大家对组织的复盘感兴趣，不妨找这本书来看，里面有相当一部分的内容是介绍组织复盘的。\u003c/p>","interaction":"\u003cp>\u003cstrong>A2\u003c/strong> \u003c/p>\u003cp> 好，\u003cstrong>我们今天第一部分的学习目标是认识什么是真正的复盘，以及怎么复盘，\u003c/strong>现在就把时间交给大家，来计划一下未来的一个复盘。大家听我的指令，按照我的指令来一步一步做这个未来的规划。\u003c/p>\u003cp>\u003cstrong>（分布催化）\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 第一步：\u003c/strong>假设我们面前有一台时光机，你往里面投一件事情，它就可以帮你回到过去，从新再经历一次这件事，这事可以是你遗憾想重来一次的事，也可以是很开心的想再体验一次的事，大家想一想，你会往里面投一件什么事情呢？请你把这件事填入个人复盘模版中“事件”那一栏里(现场给了大家几分钟时间去思考和填写)。\u003c/p>\u003cp>\u003cstrong>第二步：\u003c/strong>填好之后，请大家根据复盘模版的四个步骤，把这件事复盘一下，填写一下相关的内容(现场给了大家几分钟时间去思考和填写)。\u003c/p>\u003cp>\u003cstrong>第三步：\u003c/strong>假设今天晚上或者明天，你找你的朋友，或你和你自己就这件事聊一聊，用这个复盘的方式聊一下，然后我们在小组里演绎一下这个对话，比如你和你内心的另一个自己对话，聊一下这件事，用复盘的四个步骤，一问一答，把整个复盘的过程演绎一遍，大家先把对话内容以剧本的形式写出来（写关键词即可），然后在小组里演绎，待会儿我们请其中两个小伙伴上台来演绎一下他们复盘的整个过程。\u003c/p>\u003cp>\u003cstrong>小剧场（案例）：\u003c/strong>\u003c/p>\u003cp>要复盘的事情：对的伴侣\u003c/p>\u003cp>对话：\u003c/p>\u003cp>A：亲爱的，我们现在来复盘一下一件事可以吗，请问是什么事情呢？\u003c/p>\u003cp>B：对的伴侣。\u003c/p>\u003cp>A：时间？\u003c/p>\u003cp>B：十年前。\u003c/p>\u003cp>A：地点？\u003c/p>\u003cp>B：南宁。\u003c/p>\u003cp>A：人物？\u003c/p>\u003cp>B：我自己。\u003c/p>\u003cp>A：是什么样的一次事件呢？我们来回顾一下当时你的目标吧，当时你的初衷是什么？\u003c/p>\u003cp>B：找到对的伴侣。\u003c/p>\u003cp>A：结果呢？\u003c/p>\u003cp>B：半对！\u003c/p>\u003cp>A：整件事的亮点是什么？\u003c/p>\u003cp>B：自我修炼的功力越来越强了。沉淀了许多东西。\u003c/p>\u003cp>A：那你觉得你还有什么遗憾和不足呢？\u003c/p>\u003cp>B：差距。\u003c/p>\u003cp>A：差距？哪方面？\u003c/p>\u003cp>B：思想方面的差距，目标的差距，价值的差距等。\u003c/p>\u003cp>A：那么我们分析一下，当初你选择他，你觉得你成功的地方是什么呢？\u003c/p>\u003cp>B：经营，我花了九年的时间去经营，才得到了半对的结果。\u003c/p>\u003cp>A：那你觉得这段感情需要检讨的地方是什么？\u003c/p>\u003cp>B：人的认知不同，我当时完全忽略掉了，另外原生家庭的影响也很重要，我都忽略掉了。当然，我也不认为是失败，我现在调整了。\u003c/p>\u003cp>A：那整个过程的关键发现是什么呢？\u003c/p>\u003cp>B：父辈靠经验，没有一套理论帮助到我，都得在自己付出了代价才能有这样的认知。所以我现在要让孩子从小就去思考如何去找正确的伴侣这个问题。\u003c/p>\u003cp>A：事情已经发生了，那么将来你打算做什么规划呢？\u003c/p>\u003cp>B：影响孩子，再通过孩子影响爸爸，9年以后，是我儿子去改变他，而不是让我去改变他。我们要接受和接纳他，但不可能放弃他，在这个过程中慢慢影响他，我需要继续修炼。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":14628,"quote":"\u003cp>\u003cstrong>（第二部分过渡）\u003c/strong>好感谢小伙伴的演绎，看来大家已经对复盘以及复盘的底层逻辑有了一定的认识，并且也计划去实践了，那么认识了什么是复盘，以及如何复盘以后，我们可以进入第二阶段的学习，首先我们先做一道测试题。\u003c/p>\u003cp>\u003cstrong>（量表测试）\u003c/strong>以下6道题目，请按照1到6分的标准给自己打分，1代表题目表述完全不符合你内心的想法，6代表完全符合，数字越大，符合度越高。请仔细阅读表格中的每句话，根据自己的实际情况为自己打分。总分： \u003cu> \u003c/u>\u003c/p>\u003cp>\u003cstrong>解释\u003c/strong>：这个测试题是为了检验大家过去的一些处理事务的习惯，如果你的得分在15分以上，说明你已经具备了初步的复盘基因了，你过去的经历和意识能够很好地帮助你很好的掌握复盘，15分以下的小伙伴也不用着急，本次活动对你来讲有很重要的意义，你可以学到比别人更多的东西，今天我们的学习对你来说会比别人更有意义。\u003c/p>\u003cp> 接下来我们就来看看我们在执行个人复盘的时候，需要注意一些什么问题。\u003c/p>\u003cp> \u003cstrong>片段二： 对个人复盘的四个建议\u003c/strong>\u003c/p>\u003cp>\u003cbr> 对于个人复盘，我的建议包括以下几点：\u003cbr> （1）把握重点\u003cbr> 我们每天会遇到许多事，大多数情况可能比较正常，按照惯例、规定或经验处理即可，有些事情则需要当机立断，因此，不是所有事情都要花专门的时间、按照标准流程进行复盘。但是，对于一些重要问题、例外情况，或者按照规范、惯例处置不太奏效的事情，要特别留意，认真复盘。\u003cbr> （2）“先僵化，后优化”\u003cbr> 如果你还没有养成复盘的习惯，或者没有一套能自圆其说的逻辑，不妨先参照复盘的四个步骤，按部就班地进行（甚至一开始可能需要写出来）；直到你已经对复盘的逻辑和问题非常熟悉，则可以根据自己的实际情况，有选择地进行适当取舍。\u003cbr> （3）记录要点并定期回顾、提醒自己\u003cbr> 俗话说：好记性不如烂笔头。如果对复盘不做记录，可能因为事务繁忙导致冲淡记忆，从而影响复盘的效果。但是，如果只是记下来，而不定期回顾、提醒自己，那复盘的效果也有限。\u003cbr> 所以，不仅应该把复盘记录下来，还要定期回顾、梳理，把相同或相关联的事件系起来看，发现共性的问题以及深层次的问题，以便让自己获得更大的成长。\u003cbr> （4）习惯成自然\u003cbr> 虽然偶尔进行自我反思和复盘也是有益的，但先贤教育我们要“吾日三省吾身”，如果能够持续地进行个人复盘，形成习惯，无疑会学习得更多、成长得更快。事实上，联想集团创始人柳传志先生在选拔干部时，标准之一就是看这个干部有没有很强的总结反思能力。\u003cbr>\u003c/p>\u003cp> 《复盘+》P63 \u003cbr> \u003cbr> \u003c/p>","explains":"\u003cp>\u003cstrong>I\u003c/strong> \u003cstrong>（讲解）\u003c/strong>拆页里作者给到大家复盘的四个建议，第一个建议是把握重点，不可能什么事都复盘，（举例）比如你在街上踩到一块香蕉皮摔倒了，你不需要复盘，你大概会跟自己说，下次小心点，走路不玩手机就好，不需要来一次系统的复盘，什么事情值得我们复盘呢，重要的，复杂的事情，你需要认真复盘。\u003c/p>\u003cp>第二先僵化后优化，复盘我们给了一个模板给大家，回去后我们就按照这个模板网上填，这就叫先僵化，当我们已经把流程和模块烂熟于心了，我们再慢慢优化过程，有些点就可以跳过去，这个就叫先僵化后优化。对于新手来说我们必须完成这个过程，不能眼高手低。\u003c/p>\u003cp>第三，定期回顾的自己的复盘。做了复盘就放着了，我们人的记忆是有限的，可能过一段时间就忘了，我们需要定期拿出来看一下\u003cstrong>（举例）\u003c/strong>比如我们考试，做了复盘，过了一两个星期拿出来复习一下，对学习效果就更好了。\u003c/p>\u003cp>第四，养成复盘的习惯，大家都知道复盘很重要，但是要养成复盘的习惯就不那么容易。\u003c/p>\u003cp> \u003cstrong>（微行动学习）\u003c/strong>\u003c/p>\u003cp> 我现在就这四个建议，请小伙伴来给它们画一下难度系数，用一颗星为标准，如果第一个建议，你做到的难度系数是一颗星，那么第二个建议的难度系数是几个星，或者半颗星？我们现在用画星星的方式来比较一下这四个建议的完成难度，你们觉得哪个建议比较难实现？\u003c/p>\u003cp>\u003cstrong>（明确问题）\u003c/strong>\u003c/p>\u003cp> 和学习者就四个建议的完成难度进行讨论，让他们给出完成难度的系数，现场投票，大部分学习者选择“定期回顾自己的复盘”比较难完成。既然大家大部分小伙伴觉得第三个建议最难完成，我们现场不妨来一次行动学习，我们来讨论一下为什么“定期回顾自己的复盘”比较难以实现呢，眼前阻止你实现这个建议的障碍是什么？我们一起来找到原因，并想出解决问题的办法好吗？（小组讨论，便签纸写原因，并请每组一个代表分享小组讨论结果）\u003c/p>\u003cp> 便签记录的原因：1.坚持不了；2.做过了就不管了；3.分不清轻重缓急，知道事情重要但不去做；4.不知道用什么方法去定期做复盘；5.不知道要做定期回顾；6.时间管理不好，知道要做但没有时间做；7.缺少正向反馈，没有乐趣和意思；8.拖延症；9.没动力；10.惰性大，懒；11.目标不符合自身的情况；12.时间有限，每天事情太多没空做定期复盘回顾；13.不爱回顾，做了就做了。\u003c/p>\u003cp>\u003cstrong>（明确问题本质）\u003c/strong>\u003c/p>\u003cp>我们刚刚大家都给了原因，我发现大家给的原因里可以大概总结为两类问题：\u003c/p>\u003cp>第一类属于\u003cstrong>“反射弧太长”\u003c/strong>（这类便签包括：坚持不了；不知道要做定期回顾；缺乏正向反馈，没有意思和做的乐趣；没动力；惰性大，懒；目标不符合自身情况；不爱回顾；做了就不管了），就是定期复盘给我们带来的好处要很长一段时间才能体现，它不像打游戏——一会儿就升一级，一会儿就拿到很多金币，反射弧很短，很有成就感——我们不能及时看到它的意义和重要性，做了半天不知道做这件事的好处在哪里，没有动力没有反馈，执行力就不强了。\u003c/p>\u003cp>第二类属于\u003cstrong>“不懂时间管理”\u003c/strong>（这类便签包括：不分轻重缓急，知道要做但不去做；时间管理不好，知道要做，但没有时间做；拖延症；时间有限，每天事情太多没空做）\u003c/p>\u003cp>所以问题的本质大概可以总结为两个：\u003cstrong>一，如何缩短复盘的“反射弧”，提升做定期回顾复盘的动力；二，如何管理好自己的时间，及时复盘及时定期回顾。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（步骤呈现）\u003c/strong>让小组组长用便签纸记录小组的解决办法，一张便签纸写一个解决办法，回收便签纸，并对便签纸上的解决办法进行归类总结。\u003c/p>\u003cp>第一个问题的解决办法：1.分享，我们自己记，没意思，我们可以分享到社群里，朋友圈里，就有人回复，这就可以获得及时反馈了；2.给自己小奖励；3.从小事情上复盘比较容易做到；4.分周计划，月计划，季度计划，年计划\u003c/p>\u003cp>第二个问题的解决办法：1.认识到重要不紧急的事情是最重要最应该做的事情，要事优先；2.把目标拆分成若干个小目标；3.只在重要的事情上做复盘，抓重点；4.分周计划，月计划，季度计划，年计划\u003c/p>\u003cp>\u003cstrong>（讲解提炼和强有力的总结）好，感谢大家的分享，我来总结一下大家给出的解决方案，针对反射弧的问题，大家认为我们可以通过分享出去的办法获得及时的反馈，即可缩短反射弧，另外也可以从小事情开始，做好计划分周计划，月计划等，让任务获得更快更好的反馈；针对时间管理方面，我们总结了要事优先法，拆分目标法，抓重点法去把复盘坚持做下去，并定期做好回顾。\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 好了，非常感谢大家今天的参与，是不是觉得时间过得也不是很漫长啊，最后我再次总结一下今天的知识点：第一拆页，我们探讨了什么是真正的复盘，如何复盘（在现场文案上指出四点复盘的步骤）。第二部分我们来探讨在复盘的过程中我们需要注意一些什么问题，大家在“复盘的几点建议”中选出执行难度系数比较高的一个建议：记录要点并定期回顾。通过微行动学习，我们讨论发现问题的本质（反馈不及时，时间管理），并总结执行这一建议的一系列方式和方法（界定）。\u003c/strong>\u003c/p>","interaction":"\u003cp>A2 最后给大家一个作业，请大家回去以后做一个复盘的计划，以后怎么做自己的复盘，让自己能够坚持下来。把你的计划po到群里，分享给其他的小伙伴。\u003c/p>\u003cp>学习者小a提供的A2案例：\u003c/p>\u003cp> 1.打印今天拆书活动中拆书家给我们设计的个人复盘模板，打印一叠摆在办公桌上。\u003c/p>\u003cp> 2.每周周末前把本周最重要的一件事填在个人复盘模板上。\u003c/p>\u003cp> 3.填好以后拍照发朋友圈，给朋友，特别是今天来学习复盘的同学看一看，收获他们的赞和评论。\u003c/p>\u003cp> 4.每个月我会抽空整理书桌，整理的时候就顺便把这些复盘模板拿来读一读，看一看，回顾一下，提醒自己。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1607503095000,"updated_at":1608862388000,"ria":true},{"id":10396,"topic":"如何复盘","learn_goal":"","remark":"本书的作者是邱昭良博士，管理学博士，它是唯一经过联想董事长柳传志审读并指导修改的图书，卡拉卡有限公司创始人孙陶然以自己亲身经历为证，倾情作序的。本书是 “复盘”实务的操作指南，从复盘日常的工作指导和常用方法，到工具和模型都能直接帮助我们快速实操复盘掌握复盘这个方法这个工具,从而掌握提升自己能力的制胜法","level":"TF1-1","duration":13,"status":29,"type":0,"chaishujia":{"username":"Eala(瑶瑶)","city":"广州市"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>\u003cstrong>自我介绍:\u003c/strong>大家好！我是瑶瑶，很高兴加入拆书帮这个学习群体，我有三个标签：儿童产品设计师 阅读爱好者，头马会员，我的座右铭是从没有长大，从没有停止过成长。也就是说时刻保持好奇心看世界，去探索成长。希望在未来拆书打怪路上，大家能一起陪伴成长。谢谢！\u003c/p>\u003cp>\u003cstrong> 介绍拆书帮:\u003c/strong>“折书”是一种转化和内化,强调把图书的知识拆页转化为学习者能力的学习方法。拆书法分为应用为个人学习的便签读书法，和应用于组织学习的拆书帮现场学习法--RIA拆书法。R指的是原书拆页。I:对原文知识拆页的讲解和学习者的指导。A:拆为己用（有三种方法，A1,回顾过王经验。A2 催化应用。A3促进学习演练。\u003c/p>\u003cp>“拆书帮”是基于拆书法的学习爱好者社群,各地的拆书帮分舵(也叫拆书帮俱乐部)。拆书帮分舵是公益性青年自组织,其使命是帮助更多学习爱好者成长为拆书家\u003c/p>","ratings_count":1,"texts":[{"id":14247,"quote":"\u003cp>《R:阅读全文》\u003c/p>\u003cp>回顾、反思、探究、提升一个都不能少\u003c/p>\u003cp>抽象围棋中复盘的做法,我们可以提炼出一个一般性的复盘概念\u003c/p>\u003cp>所谓复盘,就是在头脑中对过去所做的事情重新“过”一遍。它通过对过去的思维和行为进行回顾、反思和探究,找出原因,找到规律,从而指导我们解决间题,帮助我们提升能力。\u003c/p>\u003cp>对于复盘来说,回顾、反思、探究、提升,一个都不能少。\u003c/p>\u003cp>回顾就是回顾过程;\u003c/p>\u003cp>反思就是反思原因;\u003c/p>\u003cp>探究就是探究规律\u003c/p>\u003cp>提升就是提升能力\u003c/p>\u003cp>回顾、反思、探究,是复盘的动作；提升,是复盘的结果。我们用一次销售活动的复盘来举例\u003c/p>\u003cp>假定销售的产品是网络培训产品销售时间三个月,计划销售额是100万元,实际销售额是10万元,去过学校办过讲演,做过论坛。\u003c/p>\u003cp>回顾,就是对这三个月的工作进行描述\u003c/p>\u003cp>①目标是什么?\u003c/p>\u003cp>100万元。\u003c/p>\u003cp>②2结果如何?\u003c/p>\u003cp>10万元。\u003c/p>\u003cp>3做了什么?\u003c/p>\u003cp>跑了十几所学校,做了一些广告页,举办了一些讲座,在学校的网站上\u003c/p>\u003cp>做了一些宦传。\u003c/p>\u003cp>④与计划有什么出入?\u003c/p>\u003cp>媒体宣传减少了,讲座增加了,网络宣传增加了。与校学生会和系学生会搭上关系的目标没有实现。\u003c/p>\u003cp>⑤产生了什么意外结果?\u003c/p>\u003cp>渠道比原来熟悉了,在学校发展了批做兼职的学牛,如果下次有合适的产品,可以继续使用,等。\u003c/p>\u003cp>反思,就是找出原因\u003c/p>\u003cp>①为什么实际销售额与计划差别那么大?\u003c/p>\u003cp>自己对市场的认知不对,远程教育虽然看起来很热,自己代理的产品也是名牌,但是,真正愿意掏钱购买的人不多。市场上卖得好的产品,都是跟收入挂钩的,比如职称类的,学习了、考试\u003c/p>\u003cp>了,可以得到加薪。其他的纯粹学习类。产品,市场购买欲望还比较低。\u003c/p>\u003cp>②为什么实际做的事情与计划要做的事情不完全一致?\u003c/p>\u003cp>主要是现在的平面媒体不能辐射校园,而大学生上网是极其普遍的,可谓是“长”在网上。因此,增加了网络营销的投入,减少了平面媒体的宣传。\u003c/p>\u003cp>③时间上太仓促,错过了与主要消费者大面积接触的机会,只在学校推广了两个月就到了暑假,很多学生都离校了。\u003c/p>\u003cp>探究,就是发现规律,找到原因背后的原因,发现问题背后的问题：\u003c/p>\u003cp>①对市场认知不对,是因为没有深入市场做调研。现在看来,消费者还是喜欢能够尽快得到实惠的产品,强调的是短线收益,而不关注长期的效果,这是消费心理。\u003c/p>\u003cp>②做决策太草率。看到远程培训宣传得火,代理的也是名牌,就仓促决定\u003c/p>\u003cp>上马,归根结底是自己做决策之前只看见利益没看见风险。以后应该形成一个决策机制,在决策之前,不能光听厂家怎么忽悠,而是要看看做过的人是怎么说的。\u003c/p>\u003cp>③这次损失巨大,是因为不能退，,都是先付款拿的货,亏的都砸在自己手里,这相当于没有给自己任何保护。以后凡是这样的产品,都不做,不管厂家多么大牌。\u003c/p>\u003cp>④4在做之前,厂家说有各种支持,但是交钱后,很多支持都没有兑现。下次找合作对象,要看接触的厂家的人,不能听他们说的,要看他们做的。那种说起来滔滔不绝、天花乱坠的厂家,不可信。\u003c/p>\u003cp>经过这个复盘的过程,我们发现,如果重新来一次,则:第一,不会代理。\u003c/p>\u003cp>这种远程产品,代理的将是对消费者更加有即时效果的产品;第二,不会因为厂家说得好听就掏钱,保证了自己资金的安全,也节约了时间成本;第三,决策更加慎重。\u003c/p>","explains":"\u003cp>\u003cstrong>【I】:\u003c/strong>\u003c/p>\u003cp>\u003cstrong>［What］\u003c/strong>\u003c/p>\u003cp>运用回顾目标；分析原因；总结经验，提升能力这四个步骤进行复盘，每个参与者都能有价值的收获。\u003c/p>\u003cp>\u003cstrong>［Why］\u003c/strong>\u003c/p>\u003cp>如果运用这四步骤进行复盘，我们可以回顾事件，总结收获，得出经验，把知识，经验运用下次的事件当中。如果没用有这些步骤，复盘就会没序，没目的，发挥了复盘的价值。\u003c/p>\u003cp>\u003cstrong>［How］\u003c/strong>\u003c/p>\u003cp>第一：回顾目标。完成事件后，回看做事情的目的。\u003c/p>\u003cp>第二：分析原因。分析过程中做得好和做得差的原因。\u003c/p>\u003cp>第三：总结经验。总结过程的操作规律，经验。\u003c/p>\u003cp>第四：提升能力。经过分析，发现哪些可以做得更好的地方。\u003c/p>\u003cp>\u003cstrong>［Were］\u003c/strong>\u003c/p>\u003cp>适用于生活，工作中的工作汇报，总结。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>［背景介绍］\u003c/strong>\u003c/p>\u003cp>想在生活中每上一节课，参加活动，都有深刻收获，把经验运用下次的事件当中，迭代式成长，从今天期我运用这四步骤进行复盘。\u003c/p>\u003cp>\u003cstrong>［目标］\u003c/strong>\u003c/p>\u003cp>把四个步骤运用到月复盘当中\u003c/p>\u003cp>\u003cstrong>［时间］\u003c/strong>2020年9月30日\u003c/p>\u003cp>\u003cstrong>［地点］\u003c/strong>办公室\u003c/p>\u003cp>\u003cstrong>［人物］\u003c/strong>我，同事们，老板\u003c/p>\u003cp>\u003cstrong>［怎么做］\u003c/strong>\u003c/p>\u003cp>第一：回顾目标。回看月前定下的目标。\u003c/p>\u003cp>1达成3家集团园的订制；\u003c/p>\u003cp>2完成两季度的新产品开发。\u003c/p>\u003cp>第二：分析原因。根据前后结果对比找原因。\u003c/p>\u003cp>1．目前达成长期合作2家，原因有价格贵，生产质量影响，设计图没体现到位。\u003c/p>\u003cp>2．产品文化细节体现没到位。\u003c/p>\u003cp>第三：总结经验。分析自己哪方面做得最得心应手的，记录下来。\u003c/p>\u003cp>1了解客户需求，有目的开发。\u003c/p>\u003cp>2把模型分类整理，可以提高效率，降低成本。\u003c/p>\u003cp>第四：提升能力。把目标计划细分到每个人身上，OKR目标管理。\u003c/p>\u003cp>\u003cstrong>【如何衡量]\u003c/strong>\u003c/p>\u003cp>2020年9月30日月度复盘中，有用上以上四步骤的话，我给自己买一套新衣服。 \u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1599655229000,"updated_at":1604109938000,"ria":true},{"id":9980,"topic":"如何使用五个为什么寻找问题的根本原因","learn_goal":"","remark":"有没有因为头tong医头脚痛医脚，总觉得自己无法从全局思考问题，而是什么地方有问题就在什么地方解决，临时应付。学会五个为什么帮你寻找问题的根本原因，实现全局的思考。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"elikong","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>大家好，我是今天的拆书家孔利。\u003c/p>\u003cp>F特征（核心是书）：今天我给大家带拆的图书是《复盘+：把经验转化为能力》，作者是邱昭良博士，上市以来受到市场广泛欢迎，多次重印；当前已经是第三版了。同时，也有大量企业邀请作者进行培训或辅导。在《培训》杂志2017年12月刊推出的年终回顾专刊中，“复盘”被列为当年热门关键词。（书）\u003c/p>\u003cp>A优势（重点是比较）：这本书把中国围棋复盘的理念运用到个人、团队和企业中，可以把在工作中积累和学习到的经验，进行有效的总结和提升，最终提高目标的成功率。本书与《高效能人士的七个习惯》相比，在自我提升方面提出了新的方法—复盘，来实现自我提升。（比较）\u003c/p>\u003cp>B利益（强调学习者）：\u003c/p>\u003cp>B1：这本书对大家有什么帮助呢？你有没有因为头痛医头脚痛医脚，总觉得自己无法从根本上解决问题，而是什么地方有问题就在什么地方解决问题，总是临时应付。如果是这样的话，那么这本书就非常适合你。\u003c/p>\u003cp>B2：那我们接下来要学习的《复盘+》的片段就是可以帮助你寻找问题的根本原因，看清事件的本质，从而不断的提升全局思考的能力。（学习者）\u003c/p>","ratings_count":1,"texts":[{"id":13812,"quote":"\u003cp>\u003cstrong>五个为什么\u003c/strong>\u003c/p>\u003cp>“分析差异根因”是复盘最为重要的阶段之一，只有找到真正的原因，才能实现高质量的学习。对此，“五个为什么”是一种简单实用的方法。\u003c/p>\u003cp>这一方法的使用非常简单，以至于只需要以下三个步骤。\u003c/p>\u003cp>1. 提问第一个为什么\u003c/p>\u003cp>挑选出一个问题症状作为开端，同时列出你希望用以解开症结的线索，然后问小组成员第一个为什么：“为什么这件事情正在发生？”\u003c/p>\u003cp>可能针对这个问题有三四个答案。把这些答案全部粘贴在墙上，在这些答案周围留有足够的空间，也可以只保留经确认无误的关键要素或直接原因。\u003c/p>\u003cp>2. 依次追问“为什么”\u003c/p>\u003cp>重复墙上每个答案，依次追问“为什么”。把每个答案和“答案的答案”粘贴到它的“母问题”附近。在每一层中，都要把握重点，找到关键或本质。\u003c/p>\u003cp>3. 对问题进行整合\u003c/p>\u003cp>当所有的问题回答完毕后，一些问题可能开始整合，并追溯到十几个不同的原因，并发觉两三个系统性的根源。\u003c/p>","explains":"\u003cp>\u003cstrong>&lt;what&gt;\u003c/strong>\u003c/p>\u003cp>这个片段讲的在复盘中如何运用5WHY分析法进行分析，从而找到真正的原因。\u003c/p>\u003cp>&lt;how&gt;\u003c/p>\u003cp>我们具体应该怎么样运用5WHY原因分析法呢？\u003c/p>\u003cp>第一步 提问第一个为什么；就是针对这个问题，问为什么这个问题会发生\u003c/p>\u003cp>第二步 依次追问为什么；对上次回答的结果，继续问为什么\u003c/p>\u003cp>第三步 对问题进行整合；对问题进行归纳整理，寻找问题的根本原因。\u003c/p>\u003cp>&lt;适用边界&gt;\u003c/p>\u003cp>特别注意的是5why分析法主要适合以下3个适用场景\u003c/p>\u003cp>工作上问题的分析\u003c/p>\u003cp>生活中查询问题的思路\u003c/p>\u003cp>教育上对孩子的学习辅导中多问为什么。\u003c/p>\u003cp>不适用场景\u003c/p>\u003cp>根本原因在外部而无法控制时，就不要继续why了\u003c/p>\u003cp>根据目的，已经达到目的时不要再继续问为什么了\u003c/p>\u003cp>\u003cstrong>&lt;why&gt;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【技能点：不这么样的坏处】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&lt;一般人的做法&gt;\u003c/strong>\u003c/p>\u003cp>人们常常习惯于快速解决一个问题，遇到什么问题就解决什么问题，但是很少深入探究问题的根本原因\u003c/p>\u003cp>\u003cstrong>&lt;一般做法的坏处&gt;\u003c/strong>\u003c/p>\u003cp>这样做的结果就是看起来快速的解决了这个问题，但是由于没有解决根本问题，导致类似的问题还会发生。\u003c/p>\u003cp>\u003cstrong>&lt;反面案例&gt;\u003c/strong>\u003c/p>\u003cp>我给大家分享一个我失败的案例。我这周一的时候解决了一个bug，主要是汉字的乱码问题，一开始我检查了文件的字符集确实是utf8，然后检查发现是数据库使用的字符集是gbk，两个字符集不一致，所以我把数据库的字符集也修改为utf8，当时这个问题解决了，但是第二天问题又出现了。\u003c/p>\u003cp>\u003cstrong>&lt;变成正例&gt;\u003c/strong>\u003c/p>\u003cp>经过学习5why分析法之后，我发现正确做法应该是继续深入探究汉字乱码的根本原因。我们可以这样提问：\u003c/p>\u003cp>问题一：为什么汉字出现乱码？\u003c/p>\u003cp>答案一：因为数据库的字符集设置不对\u003c/p>\u003cp>问题二：为什么设置了数据库字符集还是出现乱码\u003c/p>\u003cp>答案二：因为数据库重启后，字符集恢复了原样\u003c/p>\u003cp>问题三：为什么恢复了原样\u003c/p>\u003cp>答案三：因为数据库只有修改配置文件，下次启动才能不变\u003c/p>\u003cp>通过三个问题的追问，才能够找到根本原因，彻底解决这个乱码问题。\u003c/p>\u003cp>讲到这里，你可能会问：\u003c/p>\u003cp>1、5个为什么是不是一定要问5个问题呢？不是的，简单问题可能一两个就问明白了，复杂的问题不止要问5个。要有打破砂锅问到底的精神。另外一个为什么不一定是只有一个原因与之对应，而实际上一个问题之所以发生往往是多个原因的共同结果，若问题有一个以上的原因，则应该找到每个原因的根源。\u003c/p>\u003cp>2、什么时候问问题算结束呢？当你找到的原因解决后，开始遇到的问题不会发生了，就是解决了。但是如果解决了原因，问题还会发生，我们就应该继续问下去。\u003c/p>\u003cp>3、我们要用客观事实来描述问题/分析问题，而不是主观推测\u003c/p>\u003cp>比如美国为什么不普及移动支付? \u003c/p>\u003cp>因为手机信号不好很多地方没有网络;\u003c/p>\u003cp>这里的错误就是主观推测，问题和答案不存在因果关系，美国为什么不普及移动支付的原因不是因为手机信号不好，而是因为信用卡非常发达，另外信号不好，移动支付也是可以使用的，比如微信就可以在无网络下支付。\u003c/p>","interaction":"\u003cp>接下来请大家回忆一下，在你过去一个月里，有没有在工作中遇到问题需要深入分析，比如为什么老板不给我加薪，产品经理为什么又增加了需求；在生活中反复出现的问题，比如为什么这个月又没钱了，为什么又单身了，为什么又胖了，你是否有这样的经历呢？ \u003c/p>\u003cp>我们按开始的分组，请小伙伴们在小组内分享一下你自已的失败经历。\u003c/p>\u003cp>相信各位学习者都在小组中分享了自己的经历，现在我请一位小伙伴上来分享一下自己的经历。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>我最近发现自己每天很忙，但是很多工作都没有做，连续好多天都是这样。\u003c/p>\u003cp>谢谢这位同学的分享，接下来我们可以使用这个办法继续分析。\u003c/p>\u003cp>\u003cstrong>&lt;A1+&gt;\u003c/strong>\u003c/p>\u003cp>好，经过我们之前的学习，我们应该学会了用5个为什么来发现问题的根源。大家也都分享了自己原来的失败案例。请大家再次讨论一下，假如你下次再遇到这个情况，你会如何通过5个为什么来找到问题的根本原因呢？请大家再次讨论一下，说出你反思后的你会怎么提问？然后我再请一位伙伴分享一下。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>我最近发现自己每天很忙，但是很多工作都没有做，连续好多天都是这样。\u003c/p>\u003cp>为什么出现明明很忙，但是很多事情没有做完的情况，\u003c/p>\u003cp>我最开始没有制定工作计划\u003c/p>\u003cp>为什么没有制定工作计划\u003c/p>\u003cp>是因为我在家上班，每天起来的很晚\u003c/p>\u003cp>为什么起来的很晚\u003c/p>\u003cp>是因为头一天晚上睡的很晚\u003c/p>\u003cp>为什么睡的很晚\u003c/p>\u003cp>是因为熬夜玩狼人杀\u003c/p>\u003cp>为什么要熬夜玩狼人杀\u003c/p>\u003cp>是因为这个对我来讲是个放松的方式\u003c/p>\u003cp>我觉得是否可以通过其他方式来替代需要熬夜来缓解疲劳的方法，这样就解决我的问题了\u003c/p>\u003cp>谢谢这位小伙伴的分享，相信大家也都学会了如何使用5why分析法来解决问题。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1592568821000,"updated_at":1593329557000,"ria":true},{"id":8996,"topic":"怎样养成复盘的习惯","learn_goal":"在跟随我完成本次RIA现场学习后，学习者能够基本建立如何进行","remark":"过去，你有没有在一个地方掉过两次坑？\r\n或者因为没有及时吸取经验举一反三，导致连续因为同一个原因犯过两次错？\r\n你有没有想过吸收每次的经验教训以期如何更有效的应对发生的事件？\r\n今天，我们一起来学习如何建立复盘规划，让你轻松应对各种挑战！","level":"TF1-1","duration":10,"status":30,"type":0,"chaishujia":{"username":"张宝建","city":"襄樊"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>自我介绍\u003c/p>\u003cp>预计时间：1 分钟\u003c/p>\u003cp>大家好！我是张宝建，弓长张，百家姓里的大户，宝建的寓意是：在我出生时，军人的父亲希望我在长大后，保卫家乡，建设祖国，改变国家落后挨打的局面。我来自一家国企，我曾带领我的团队在技术岗位上辛勤耕耘28年，它培养了我创新、勤劳、不放弃的品质，我心怀感恩；目前是阳光智心教育咨询的一名家庭教育指导师、沉迷行为干预心理咨询师。我的兴趣爱好有看书、还有户外游泳、骑车等体育运动项目。我参加拆书帮的目的是通过有组织的系统学习，让拆书这项技能快捷有效的应用，与一群志同道合的朋友们一起持续为生活、工作赋能。（50‘’）\u003c/p>\u003cp>拆书帮介绍\u003c/p>\u003cp>预计时间：2 分钟\u003c/p>\u003cp>接下来，由我来为大家先介绍一下什么是拆书和拆书帮是干什么的？。拆书法和拆书帮，是由资深培训师赵周先生创始。拆书呢，它其实是一种学习方法论，主要强调把书中知识转化为学习者自己的能力，它不是物理性质的拆散，而是转化和内化。目的是为了帮助学习者提升能力、解决问题，而且是以学习者本身为中心的。拆书分为两种形式：个人学习和组织学习。个人学习的应用就是通过阅读原文拆页片段，解释说明并用自己的语言讲解描述原文。这样可以激活过去经验，回顾过去发生的某一件具体的事情，通过书中的方法之后学会怎么做，有具体的行动方案。组织学习则是一位拆书家用一本书加工出一次现场学习，引导和促进一群人把知识拆为己用。 &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;拆书帮，是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵。拆书帮是公益性组织，其使命就是帮助更多的学习爱好者成长为拆书家。（1‘43’‘）\u003c/p>","ratings_count":2,"texts":[{"id":12736,"quote":"\u003cp>阅读原书拆页\u003c/p>\u003cp>预计时间：2.5分钟\u003c/p>\u003cp>来源：《复盘+》第二版P205主题：怎样养成复盘的习惯\u003c/p>\u003cp>【R阅读原文】如何养成复盘的习惯按照这个理论，我认为养成复盘的习惯是完全可行的。主要可参考的做法包括以下几点。\u003c/p>\u003cp>通过一些做法，创造出一些“暗示”比如，在你的日历或工作安排中事先列上“复盘”的时间；通过手机或邮件订阅有关复盘的动态；在公司例会上，经常进行或提示复盘等。\u003c/p>\u003cp>强化对复盘的“奖赏”比如，上级领导和组织的认可；在公司网站、知识管理系统里建立复盘专栏，定期刊登各单位的复盘成果，并对优秀复盘给予奖励等。在这里特别想指出的是，要强化“奖赏”，就要“玩真的”，让复盘真正起作用，而且轻松、简单、好玩，千万不要搞得很复杂或成为负担，或者只是“走走形式”“自己骗自己”，更不要让大家觉得会受到批评，会让自己很难堪。如果是这样的话，从复盘中获得的，就不是“奖赏”，而是痛苦了。那样的话，复盘就很难成为人们的习惯。\u003c/p>\u003cp>将奖赏与内心渴求联系起来长期来看，要将从复盘中获得的“奖赏”与每个人内心深处隐藏着的对学习与成长的“渴求”联系起来，让大家看到:复盘有助于个人学习与成长；复盘可以帮助个人和团队更好地完成工作；复盘简单而有效。尽管人们本能地害怕或倾向于回避错误，但一方面，无论在东方还是西方文化中，都存在“从失败中学习”的信念，让大家接受并树立这样的观念，有助于消除对失败或错误的“恐惧”；另一方面，用学习与成长产生的“正能量”来抵消这些本能上的“不适”。\u003c/p>\u003cp>4.充分利用团队的力量如上所述，复盘从本质上是一个团队学习的过程，不仅在复盘过程中要鼓励团队的参与，在组织层面上，也要成立复盘实践小组，定期组织复盘学习、复盘分享会以及交流使用复盘的经验和心得。此外，公司还可以对各级干部和骨干进行复盘方法论和复盘引导技术的培训，为大家创造共同的理解、共同的经历和共同语言，有助于建立集体信念，让复盘更容易地变成习惯。\u003c/p>\u003cp>现在，给大家:2.5分钟时间进行拆页阅读。（25’‘）（留意控制时间）大家读完就示意我一下。好的，那我们这边大家的阅读环节就先告一段落。\u003c/p>","explains":"\u003cp>分享【I】便签\u003c/p>\u003cp>预计时间：2分钟\u003c/p>\u003cp>通过原文介绍，我们知道复盘习惯有助于团队学习与成长，还可以帮助团队更好地提升业绩、改进方法、完善制度等，并且简单有效，但如何持续有效的融入到工作中，形成团队特色，也就是把复盘内化成良好的行为习惯呢？\u003c/p>\u003cp>具体步骤如下：\u003c/p>\u003cp>1、利用工具提示复盘；&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2、增加复盘的趣味性等；\u003c/p>\u003cp>3、让复盘的趣味性与个人成长挂钩（奖评）；&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;4、建立复盘实践小组且定期活动。\u003c/p>","interaction":"\u003cp>分享【A1】便签\u003c/p>\u003cp>预计时间：2分钟\u003c/p>\u003cp>年初，在公司学习清单管理时，老师有讲到做“晨间复盘”的技法，我和王鑫坚持了两个月写晨间复盘，主要是记录每天的工作事项；总结前一天的事情，反思，改进；基本能做到日清日毕，纠正前一日的一些日常问题，效率也有了提升。但由于我没有跟小伙伴们结对，缺乏互相监督，没有激励，不知何时就没有在做了。\u003c/p>\u003cp>【反思】刚开始了解到“复盘习惯”的概念，还没有形成复盘的习惯，每日复盘的任务没有激励措施、缺乏监督，与学习小组的同修也没有互动和分享、缺乏学以致用的动力。\u003c/p>\u003cp>分享【A2】便签\u003c/p>\u003cp>预计时间：2分钟\u003c/p>\u003cp>目标：15日在广场经与工作室同事协商成立三人工作复盘实践小组，建立微信群，约定每周一下午14:00固定开展复盘一周工作。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>①设置微信时间提醒提示复盘活动；&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>②设立复盘评比通关流程，增加互动趣味等；\u003c/p>\u003cp>③评比通关成果分级逐步进行绿花、红花、礼品、红包等进行激励、对突出个人给与晋升机会；\u003c/p>\u003cp>④实践小组建立微信群，线下周一下午为固定复盘时间、每月一日为复盘明星展示日交流、分享，组织展示复盘成果。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1570176906000,"updated_at":1570177232000,"ria":true},{"id":8117,"topic":"学习复盘，每天都成长一点","learn_goal":"通过学习，学习者能够在计划进行经验反思总结时，有效复盘","remark":"生活中发生的有价值的事情，都可以进行复盘，个人复盘，引导他人对自己的事情复盘，都可以帮助我们每一天都进步一点点","level":"TF3-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"郭明珠－太阳雨","city":"西安"},"club":{"name":"西安古城分舵","city":"西安"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，在我们正式拆书之前，我先做一个简单的自我介绍。我是今天的晋级拆书家太阳雨－郭明珠。接下来，我用三个标签来介绍自己：二级拆书家、中医养生从业者、终身学习者，今天是我3-1升级打怪。\r\n在拆书之前，我先给大家分一下组。左手边两个小伙伴一组，右手边两个小伙伴一组。\r\n事件：聪明的人一般都不会让自己在同一个地方摔倒两次，可是很多人却一而再而三的在同一个地方摔倒，就是我们常说的，吃一堑，要长一智。\r\n提问：如果在工作中你也总是这样的摔倒，不长记性，不改进方法，领导敢不敢把重要的项目交给你做？重要的岗位会不会轮到你呢？面对职场，这意味着什么？\r\n影响： 那将意味着，十年你可能还只是一个普通职员，有多少人都是这样子的啊！\r\n解决：\r\n解决1怎样才能突破，让自己真正成长呢？今天，我将和大家一起学习这本《复盘：把经验转化为能力》这本书，这本书教我们如何把过去的经验进行复盘，系统化分析，优化方案，在应用中快速学习和成长，在多变复杂的商业环境中把错误降到最低。\r\n解决2:如果能在生活中，养成复盘的习惯，每天都能把当天的事情去回顾、复盘，那是不是天天都在进步，今天我们一起来学习一下复盘。\r\n学习目标：\r\n今天我们将学习书中的一个片断，了解什么是复盘，以及如何复盘。\r\n通过今天的学习，学习者能够在计划进行经验反思总结（where）时，使用复盘四步骤（澄清），总结（行为）过往经验中的亮点与不足（界定），避免不停试错。\r\n接下来，我们花一分钟的时间来阅读书原文拆页！\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":5,"texts":[{"id":11716,"quote":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>这个拆页选自本书P25页，大家先花1分钟时间阅读原文，如果阅读完毕，可以举手示意一下。\u003c/p>\u003cp>原文：《复盘－把经验转化为能力》拆书片段\u003c/p>\u003cp>&nbsp; &nbsp;\u003cstrong>什么是复盘\u003c/strong>\u003cstrong>\u003c/strong>\u003cstrong>\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; “复盘”原是围棋术语，本意是对弈者下完一盘棋之后， 重新在棋盘上把对弈过程摆一遍， 看看哪些地方下得好，哪些下得不好，哪些地方可以有不同甚至是更好的下法等。这个把对弈过程还原并且进行研讨、分析的过程，就是复盘。通过复盘，棋手们可以看到全局以及整个对弈过程，了解棋局的演变，总结出适合自己和不同对手的套路，或找到更好的下法，从而实现自己棋力的提升。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp; 用到企业管理中，复盘是指从过去的经验、实际工作中进行学习，帮助管理者有效地总结经验，提升能力，实现绩效的改善。正如联想集团创始人柳传志先生所说:所谓复盘，就是一件事情做完了以后，做成功了，或者没做成功，尤其是没做成功的，坐下来把当时的这个事情，我们预先怎么定的、中间出了什么问题、为什么做不到，把这个过程要理一遍，理一遍之后，下次再做的时候，自然这次的经验教训就吸收了。&nbsp;\u003c/p>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>拆书家讲解引导\u003c/p>\u003cp>强化讲解概念的能力\u003c/p>\u003cp>&nbsp;&nbsp; 复盘，不了解围棋的人，对这个词还是比较陌生的，什么是复盘呢？指的是下围棋的棋手，两人下完一盘棋之后，想要知道这盘棋到底是哪一步决定了最后的胜负，于是重新在棋盘上把对弈的过程摆一遍，回顾哪些地方下的好，哪些下得不好，哪些地方可以有不同甚至更好的下法等。重点是还原过程、思考分析、优化提升。\u003c/p>\u003cp>我们怎么理解生活中的事情复盘呢？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 就是过去发生的一件你认为比较重要事情，做的漂亮成功也好，做的失败也好，结果的差距在哪里，对过程进行事实回想，不是指责批评感叹，而是思考分析哪些地方是做的好的，以后可以沿用，哪些地方做的不好，需要改进提升，进一步优化下一次的方案。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>（复盘的意义）复盘是以学习为导向，通过复盘得到启发，提升自己的见解和能力，改进自己的下一次行动，有效提高自己的行为能力。\u003c/p>\u003cp>我们举2个例子，进一步理解一下复盘的概念。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; “昨天在买衬衣的时候，和老板砍价，他要260,我出180,他很快就答应了，我现在感觉，应该砍到150也能买下来。“这算不算不复盘，看起来有还原事情，但充其量算是一个不太具体的反思，复盘是需要对结果，比如，我想多少钱买到这件衬衣，中间是怎样砍价的，为什么离我的目标还差一点，如果当时，我出180,他马上答应了，为什么没有反思一下更低的价钱，是因为什么没有让价钱更低一些，下次应该注意的地方是什么。这个复盘只是简单反思后，臆想了结果可以更低一些，所以不算复盘。\u003c/p>\u003cp>&nbsp;&nbsp; “我总结了一下，昨天的会议我做的好的地方，是时间观念非常好，都能按时到位，唯一需要提升的是配合度和沟通，这里浪费了很多时间，降低了工作效率。“这是复盘吗？这也不是。复盘是不追究哪个人的功过得失、不批评、不表扬，只是忠实还原事实、分析差异。你总得说明事实经过中，守时为什么做的好，对事情的结果促进了什么作用，以后可以保持，什么地方什么时候是配合和沟通出了问题，如何影响到工作效率的，应该如何避免，做出的调整优化是什么，所以，这不是复盘。\u003c/p>\u003cp>\u0016\u003c/p>\u003cp>（总结复盘的关键点）\u003c/p>\u003cp>&nbsp; &nbsp;好，那我们看一下，复盘的关键点是什么呢？复盘一定要有目标结果的对比，计划与现实中的结果差距在哪里？复盘一定要还原事实，这样才能清晰知道哪一个环节需要优化改进，复盘一定要分析原因，找出解决的方案，这时候不是追究和评判；复盘一定要有问题总结和下次的计划提升改进方案，预防下次同一个问题反复出现。这才能把经验转化为能力。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>如何在很短的时间，就能让对方明白到关键的点呢？\u003c/p>\u003cp>（How）具体步骤\u003c/p>\u003cp>复盘的步骤就很关键。我总结了以下四个步骤，这样去复盘，就不会偏了方向。\u003c/p>\u003cp>1､ 评估结果。就是在做这件事的时候，你想要达成的结果是什么，实际达成的结果是什么。\u003c/p>\u003cp>2､ 还原事实。在执行的时候，发生了什么，也就是真实的过程。\u003c/p>\u003cp>3､ 分析原因。就是把做的好的地方和不足的地方分析出来。\u003c/p>\u003cp>4､ 总结经验。下次做的时候，你会保持哪些，会改进哪些。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>讲一个我给闺蜜复盘的案例\u003c/p>\u003cp>我的闺蜜上个月发誓要一个月瘦8斤，结果很尴尬，只瘦了1斤，昨天中午在北大街一起吃饭的时候，我帮她进行了复盘，就是用这个方法去get到他的点的。给大家演绎一下这个场景。\u003c/p>\u003cp>一个人两个角色，左边是闺蜜，右边是我。\u003c/p>\u003cp>&nbsp;&nbsp; 闺蜜说：真丢人，上个月逢人都讲，我要减肥8斤，结果只瘦了1斤，跟没减有什么区别？同事都笑话我，没救了。\u003c/p>\u003cp>&nbsp; 我：也就是说，你的目标是减8斤，结果只少了1斤，有7斤还在你身上？（回顾目标）\u003c/p>\u003cp>&nbsp;&nbsp; 闺蜜：那可不？\u003c/p>\u003cp>我：结果差距还是挺大的，我觉得你身材挺好的，你为什么要减肥呢？（回顾目标）\u003c/p>\u003cp>闺蜜：我就是觉得自己腿太粗了，肚子太松了，其实不是挺胖的。\u003c/p>\u003cp>我：你就是想让你瘦一点，肚子紧一点，最好有点腹肌、马甲线之类的吧？\u003c/p>\u003cp>闺蜜：对对对，就是，线条好一点，最好能看出来一点马甲线。\u003c/p>\u003cp>我：你之先的计划是怎么做的呢？（还原事实）\u003c/p>\u003cp>闺蜜：我其实做了很好的计划的，每一周的饮食食谱，我都列出来，贴在冰箱上，厨房，还设在手机上当屏保，每天都特意规划1个小时的运动。\u003c/p>\u003cp>我：计划做出来了，执行过程中发生了什么吗？\u003c/p>\u003cp>闺蜜：第一个星期，基本都坚持下来，当时都瘦了3斤，我还挺开心的，后来晚上老是有聚餐，饮食就没有遵守了，再加上一熬夜，早上就起不来了，不过早上有做十多分钟拉伸，第二周还又胖回了两斤，后面就没有严格执行。\u003c/p>\u003cp>我：所以，没有达到预期结果，你觉得最关键是什么原因？（引发复盘者反思）\u003c/p>\u003cp>闺蜜：我觉得还是我自己不够自律，被人叫去吃饭，也没忍住，运动也容易找借口偷工减料。\u003c/p>\u003cp>我：那你觉得你做的比较好的地方有哪些？\u003c/p>\u003cp>闺蜜：我的计划做的还是很好的，饮食结构、运动动作设计，都是能够达到我想要的结果的。\u003c/p>\u003cp>我：如果接下来你继续一个月的，根据上个月的经验，你会怎么改进你的方案和执行呢？（总结经验，）\u003c/p>\u003cp>闺蜜：我觉得可以计划不变，就是在执行的时候，如果有人叫我去吃饭，我要拒绝上饭桌，生活作息要规律，避免疲劳，影响运动时间和运动量，每周给自己设置个执行奖励，只要一周严格执行了，就犒劳一下自己，鼓励一下自己继续坚持。\u003c/p>\u003cp>我：非常好，相信你接下来一定能得到你想要的结果的。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>(Where)\u003c/p>\u003cp>这个方法，适用于个人复盘，只要自己认为对自己有价值的事情，都可以使用，把做的不好的复盘后优化，做的好的复盘后沿用。如果是月复盘，年复盘，或工作中有重要项目的复盘就不适用，这个就需要专门学习书中的详细复盘方法进行训练。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>新技能点：教学习者编剧本\u003c/p>\u003cp>这样读书就够了中有介绍一个重要的关于学习的研究结果：在大脑中过一遍，等于实际应用了一遍。接下来我们要应用今天所学习的复盘来解决一个生活中实际遇到问题，事件可以是未来一周你想复盘的事，最好是你将来可以用到的，如：约会失败、工作没按时完成、推销某个产品没有成功等等，几百字就可以，设计出人物、情节变化（包括事情的起因、经过、结果）和双方当时的对话动作等，内容一定要用到今天学习的复盘技术，我给一个模版给大家，大家可以把内容摘要写下来。\u003c/p>\u003cp>学员剧本记录\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>事件内容\u003c/p>\u003c/td>\u003ctd>\u003cp>背景：小岳拆书线下通过了，下周三跟姐姐约了一起吃晚饭，小岳向姐姐讲自己拆书的成功\u003c/p>\u003cp>时间：下周三晚7点\u003c/p>\u003cp>地点：某餐厅\u003c/p>\u003cp>人物：拆书家和姐姐，姐弟关系\u003c/p>\u003cp>拆书家打怪升级成功，心里很开心，通过复盘向姐姐传授经验\u003c/p>\u003c/td>\u003ctd>\u003cp>介绍背景、时间、地点、人物、关系、人物的内心想法和心情\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>人物角色\u003c/p>\u003c/td>\u003ctd>\u003cp>角色A拆书家岳春林\u003c/p>\u003cp>角色B姐姐\u003c/p>\u003c/td>\u003ctd>\u003cp>多个角色可自行扮演\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>对话\u003c/p>\u003c/td>\u003ctd>\u003cp>角色B：听说你这次拆书升级顺利过关了了，想知道你是怎么做到的？\u003c/p>\u003cp>（拆书家开始复盘分享）\u003c/p>\u003cp>角色A:那天升级过关，也在我预料之中，（回顾目标）\u003c/p>\u003cp>角色A:那你说说你当时是什么情况啊\u003c/p>\u003cp>角色Ｂ：当我选拆页的时候，像师父请教了很多，也看了很多的拆书家的拆页，\u003c/p>\u003cp>角色A：你真棒，你也有做很多准备吧？\u003c/p>\u003cp>角色B:确实，我总结了之前失败的经验，这次有了很多准备，拆完之后，让师父也过了好几遍，在家里也练习了几次，感觉顺畅熟悉了很多，所以在级的时候，也没有那么紧张，思维也清楚很多。\u003c/p>\u003cp>角色A：那你这次收获了什么呢？\u003c/p>\u003cp>角色B：我觉得选择拆页很重要，写逐字稿的时候，师父帮助审稿也是很重要的，写完后，要多加练习，只有不断的练习，才能更深一层对内容熟悉和理解。下次过级的时候，要好好把这几点做好。\u003c/p>\u003c/td>\u003ctd>\u003cp>内容步骤：\u003c/p>\u003cp>1､&nbsp;&nbsp; &nbsp; 回顾目标\u003c/p>\u003cp>2､&nbsp;&nbsp; &nbsp; 还原事实\u003c/p>\u003cp>3､&nbsp;&nbsp; &nbsp; 分析原因\u003c/p>\u003cp>4､&nbsp;&nbsp; &nbsp; 总结经验\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>拆书家反馈：（按现场分享的是否有四个步骤进行反馈）\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>非常感谢两位的分享，反馈一下你们的分享，因为两位都学习了复盘，其实被提问的人就是在用复盘的四步，向提问的人分享了自己拆书升级成功的经验，那对于提问的人，复盘的步骤还需再熟悉一下。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>结束语：\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp;&nbsp; 今天我们对复盘有了新认识和学习，但真正要在个人的工作和生活中能用好复盘技术，还需要有意识的去多用，养成一种习惯，这样才能把经验转化为自己的能力，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1560075552000,"updated_at":1563469466000,"ria":true},{"id":7744,"topic":"如何高效复盘","learn_goal":"如何高效复盘","remark":"","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"陈松波","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"\u003cp>\u003cstrong>自我介绍\u003c/strong>\u003cstrong>+\u003c/strong>\u003cstrong>FAB\u003c/strong>\u003cstrong>+\u003c/strong>\u003cstrong>目标\u003c/strong>\u003cstrong>（\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>分钟）\u003c/strong>\u003c/p>\u003cp>大家好！我是陈松波，我今天要拆的是TF2-4，片段选自\u003c/p>\u003cp>\u003cstrong>《复盘\u003c/strong>\u003cstrong>+\u003c/strong>\u003cstrong>》\u003c/strong>\u003cstrong>——\u003c/strong>\u003cstrong>把经验转化为能力\u003c/strong>\u003c/p>\u003cp>\u003cstrong>F\u003c/strong>\u003cstrong>特征（核心是书）\u003c/strong>：本书的作者是邱昭良博士，他也是一名高级经济师，他曾任联想控股董事长的业务助理，万达学院副院长，曾为中石化、中国航天、中粮集团、中国移动等数百家企业提供过咨询与培训服务，本书是他的第5部专著，也是他出版的第13本书，本书主要介绍了复盘的方法、复盘的底层逻辑、复盘的应用等等。（书）\u003c/p>\u003cp>\u003cstrong>A\u003c/strong>\u003cstrong>优势（重点是比较）\u003c/strong>：《复盘+》这本书与其它方法工具类书不同，本书深度解析了联想、万达、美军、英国石油公司的实践经验，提供了大量方法与常用工具。它不是教你怎么去做事，而是教你在做完成后，怎么对事情的过程进行一次推演，进而发现问题、找出方法，为后来的工作和生活提供指导。本书与其它工具类书相比更强调实战，注重方法和工具（比较） \u003c/p>\u003cp>\u003cstrong>B\u003c/strong>\u003cstrong>利益（强调学习者）\u003c/strong>：大家有这样的困惑吗？看了很多沟通类的书箱，却还是不知道如何更好的与人沟通；一直在减肥，可体重一直没有变化；一直嚷嚷着了脱单，可今年情人节还是一个人过？而又不知道这些问题到底出在什么地方？如果是这样的话，那我们接下来要学习的《复盘+》的片段就是可以帮助你看清事件的本质，让你把事情琢磨透做成功，从而不断的提升自己的解决问题的能力。（学习者）\u003c/p>\u003cp>\u003cstrong>学习目标\u003c/strong>\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>学习目标一：首先，我们将通过对片段一的学习，大家在遇到“重新预价”的事时，能运用复盘四步法，做一个包含的复盘四个步骤的复盘。\u003cbr>\u003c/p>\u003cp>要做一个有效的复盘，仅仅靠掌握复盘的四个步骤是远远不够的，例如复盘中的分析原因就是非常关键了的一步，而在平常的复盘中，我们往往不知道怎么做，所以为了让我们复盘更有效，我们要重点学习一下复盘中的第三步如何做原因分析。\u003c/p>\u003cp>学习目标二：我们将通过对片段二的学习，让大家掌握5WHY分析法，大家能运用5WHY分析法做复盘的原因分析，从而找到成功或失败的根本原因。\u003c/p>\u003cp>接下来请大家花1分钟的时间阅读片段一，大家在阅读的过程中可以带着这个问题去阅读。“复盘到底应该怎么做呢？”找找看片段中有没有什么提示信息\u003c/p>","ratings_count":1,"texts":[{"id":11248,"quote":"\u003cp>\u003cstrong>RIA\u003c/strong>\u003cstrong>片段一\u003c/strong>\u003c/p>\u003cp>\u003cstrong>R\u003c/strong>\u003cstrong>阅读原拆页（\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>分钟）\u003c/strong>\u003c/p>\u003cp>&nbsp;\u003cstrong>什么是复盘\u003c/strong>\u003c/p>\u003cp>“复盘”原是围棋术语，本意是对弈者下完一盘棋之后，重新在棋盘上把对弈过程摆一遍，看看哪些地方下得好，哪些下得不好，哪些地方可以有不同甚至是更好的下法等。\u003c/p>\u003cp>这个把对弈过程还原并且进行研讨、分析的过程，就是复盘。通过复盘，棋手们可以看到全局以及整个对弈过程，了解棋局的演变，总结出适合自己和不同对手的套路，或找到更好的下法，从而实现自己棋力的提升。\u003c/p>\u003cp>用到企业管理中，复盘是指从过去的经验、实际工作中进行学习，帮助管理者有效地总结经验，提升能力，实现绩效的改善。正如联想集团创始人柳传志先生所说：\u003c/p>\u003cp>所谓复盘，就是一件事情做完了以后，做成功了，或者没做成功，尤其是没做成功的，坐下来把当时的这个事情，我们预先怎么定的、中间出了什么问题、为什么做不到，把这个过程要理一遍，理一遍之后，下次再做的时候，自然这次的经验教训就吸收了。\u003c/p>","explains":"\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享\u003c/strong>\u003cstrong>I\u003c/strong>\u003cstrong>便签（\u003c/strong>\u003cstrong>3\u003c/strong>\u003cstrong>分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>WHAT:\u003c/strong> \u003c/p>\u003cp>这个片段告诉我们什么是复盘以及复盘的方法。\u003c/p>\u003cp>\u003cstrong>WHY\u003c/strong>\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>复盘对围棋对弈双方来说可以找出适合自己的、更好的下法，从而实现自己棋力的提升。对于企业管理者或个人来说可以总结经验、提升能力、改善绩效。\u003cstrong> \u003c/strong>\u003c/p>\u003cp>\u003cstrong>HOW\u003c/strong>\u003cstrong>：（细化行动步骤）\u003c/strong>\u003c/p>\u003cp>那复盘到底应该怎么做呢？我们一起来看看原文中柳传志怎么说的，大家看再次看到片段中的最后一段。\u003c/p>\u003cp>“所谓复盘，就是一件事情做完了以后，做成功了，或者没做成功，尤其是没做成功的，坐下来把当时的这个事情，我们预先怎么定的、中间出了什么问题、为什么做不到，把这个过程要理一遍，理一遍之后，下次再做的时候，自然这次的经验教训就吸收了。”\u003c/p>\u003cp>事情做完了——结果；预先怎么定的——目标；为什么做不到——原因；经验教训——经验。由此，我们可以把复盘分为以下四步：\u003c/p>\u003cp>\u003cstrong>第一步\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>回顾目标\u003c/strong>\u003cstrong> \u003c/strong>\u003c/p>\u003cp>当初制定的目标是什么？\u003c/p>\u003cp>\u003cstrong>第二步\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>评估结果\u003c/strong>\u003c/p>\u003cp>与目标相比有无差异？达成与否？\u003c/p>\u003cp>\u003cstrong>第三步\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>分析原因\u003c/strong>\u003c/p>\u003cp>如果有差异，就要分析下为什么会发生这些差异？什么原因导致我们没有达成目标？失败的根本原因是什么？如果没有，成功的关键因素是什么？\u003c/p>\u003cp>\u003cstrong>第四涉\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>总结经验\u003c/strong>\u003c/p>\u003cp>这是里我们可以从以下几个角度思考：我们从中学到了什么新东西？如有人要进行同样的行动，我会给他什么建议？自己再遇到类似的情况应该怎么做？\u003c/p>\u003cp>预防异议：\u003c/p>\u003cp>讲到这里，你可能会说:\u003c/p>\u003cp>1、刚刚你不是先说的结果吗？怎么步骤中第一步是回顾目标呢？\u003c/p>\u003cp>那是因为在评估结果时，我们要看我们有哪些做得好的？哪些做得不好？那么这个做得好与不好，得有一个判断标准，而这个标准就是我们当初定的目标，而没有目标就是谈不上有没有达成目标，也就无所谓做得好与坏。所以我们第一步是回顾目标。\u003c/p>\u003cp>2、我当初没有制定目标怎么办呢？\u003c/p>\u003cp>如果复盘时发现没有目标，我们就需要“亡羊补牢”重新确认、理清当初做这项目或事件的目标到底是什么。事实上，没有目标这件事本身也是一个重要的学习点，是下次改进的重要教训之一。\u003c/p>\u003cp>\u003cstrong>WHEN\u003c/strong>\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>那什么时候？什么事情要复盘呢？其实用四个字就是可以概括需要复盘的事情：\u003cstrong>“重新预价”\u003c/strong>。重是重要的事，新是新的、第一次做的事，预是没有达到预期的事，价是有学习价值的事。\u003c/p>\u003cp>\u003cstrong>案例：\u003c/strong>\u003c/p>\u003cp>我去年没有拿到全年的全勤奖——“预”没到达到我拿全勤奖预期的事\u003c/p>\u003cp>第一步，回顾目标——拿12个月的全勤奖\u003c/p>\u003cp>第二步，评估结果——拿到10月的，有2个月没有拿到\u003c/p>\u003cp>第三步，分析原因——两个月都有迟到\u003c/p>\u003cp>第四步，总结经验——要想拿12个月的全勤奖，至少不能迟到或要相办法避免迟到。\u003c/p>\u003cp>\u003cstrong>分组：\u003c/strong>\u003c/p>\u003cp>接下来我们会有分组学习和讨论，所以我们先来进行一个简单的分组。\u003c/p>\u003cp>\u003cstrong>A1\u003c/strong>\u003cstrong>激活经验（\u003c/strong>\u003cstrong>5\u003c/strong>\u003cstrong>分钟）\u003c/strong>\u003c/p>\u003cp>【显像提问】好了，我例子讲完了，请大家各自想想，在过去一周、一个月内你工作或生活中有没有发生过“重新预价”的事？ \u003c/p>\u003cp>这件事可以是你去年的一项重要的年度目标，新学习的一门课程，没有完成一个月度任务，非常有价值的一次社群活动，或其它你能想到的“重新预价”的事件。\u003c/p>\u003cp>想好后，请大家先花1分钟的时间把它写在便签上，然后在小组里分享一下，简单说下这是一件什么事就行。一会儿，我会请一个小伙伴来分享一下。\u003c/p>\u003cp>\u003cstrong>学习者分享\u003c/strong>：小鱼——参加了一个PPT训练营，目标就是要坚持21学习打卡，结果没有坚持下去，中途放弃了\u003c/p>\u003cp>【反馈】好，谢谢小鱼的分享，小鱼给我们分享的是参加PPT训练营，自己的目标是要坚持21天学习并打卡，结果没有坚持下来。这是符合我们这个复盘方法的适用范围，它就是一个没有达到预期目的的事情，好的谢谢小鱼的分享。\u003c/p>\u003cp>\u003cstrong>A1+\u003c/strong>\u003c/p>\u003cp>好的，现在请大家各自想一下，如果当初你就掌握了复盘的四步法，你会怎样按照复盘四步法去做一个复盘？请在小组里谈论。待会，我会请一个小伙伴来给大家分享下。\u003c/p>\u003cp>\u003cstrong>学习者分享\u003c/strong>：佳音——\u003c/p>\u003cp>第一步回顾目标 我给自己设定了每天早上5：30起床的目标。\u003c/p>\u003cp>第二步评估结果 经常早上起不来\u003c/p>\u003cp>第三步分析原因 闹钟放在身边，闹钟响了随手关了，又睡过去了；闹钟在我深度睡觉的时候把自己闹醒，自己还想睡；晚上睡得太晚了\u003c/p>\u003cp>第四步总结经验 把闹钟放远点，根据睡眠周期调整晚上的上床休息的时间，晚上早点入睡。\u003c/p>\u003cp>【反馈】好，让我们掌声感谢佳音的分享，通过佳音的分享我们可以看，她基本上已经掌握了复盘的四步法了，刚刚的分享中她对自己未能早起的这个未达预期目的的事进行了一个复盘，非常棒！\u003c/p>\u003cp>以上就是关于什么是复盘以及复盘四步法介绍，大家有没有什么疑问？ \u003c/p>\u003cp>【学习者提问】璐琳：我有个问题，你刚刚说总结经验可以从三个角度去思考。前面两个我记住了，第三个是什么呢？\u003c/p>\u003cp>【回应】总结经验可以从很多角度入手，刚刚给大家说的是如果你不知道从哪里入手，可以从这三个角度去思考：一、我们从中学到了什么新东西？二、如有人要进行同样的行动，我会给他什么建议？三、自己再遇到类似的情况应该怎么做？ \u003c/p>\u003cp>\u003cstrong>强有力的结语：\u003c/strong>\u003c/p>\u003cp>通过这个片段的学习我希望大家记住的是四个词：目标，结果，原因，经验！\u003c/p>\u003cp>\u003cstrong>过渡语：\u003c/strong>\u003c/p>\u003cp>好，通过上面的学习大家掌握了复盘的四步法，那么复盘中非常关键的一步就是原因分析，如果原因分析没有做好，那我们的复盘效果就会大打折扣。好，接下来我们重点学习一下如何做好复盘中的第三步--分析原因。\u003c/p>\u003cp>\u003cstrong>RIA\u003c/strong>\u003cstrong>片段二\u003c/strong>\u003cstrong>（有\u003c/strong>\u003cstrong>HOW\u003c/strong>\u003cstrong>的片段\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>R\u003c/strong>\u003cstrong>阅读原拆页（\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>五个为什么\u003c/strong>\u003c/p>\u003cp>“分析差异原因”是复盘最为重要的阶段之一，只有找到真正的原因，才能实现高质量的学习。对此，“五个为什么”是一种简单实用的方法。\u003c/p>\u003cp>\u003cstrong>如何使用“五个为什么”\u003c/strong>\u003c/p>\u003cp>这一方法的使用非常简单，以至于只需要以下三个步骤。\u003c/p>\u003cp>\u003cstrong>第一步，提问第一个为什么\u003c/strong>\u003c/p>\u003cp>挑选出一个问题症状作为开端，然后问小组成员第一个为什么：“为什么这件事情正在发生？”\u003c/p>\u003cp>可能对这个问题有三四个答案。把这些答案全部粘贴在墙上，在这些答案周围留有足够的空间。\u003c/p>\u003cp>\u003cstrong>第二步，依次追问“为什么”\u003c/strong>\u003c/p>\u003cp>重复墙上每个答案，依次追问“为什么”。把每个答案和“答案的答案”粘贴到它的“母问题”附近。\u003c/p>\u003cp>\u003cstrong>第三步，对问题进行整合\u003c/strong>\u003c/p>\u003cp>当所有的问题回答完毕后，一些问题可能开始整合，并追溯到十几个不同的症状，发掘两三个系统性的根源。\u003c/p>\u003cp>例如，里克·罗斯在《第五项修炼·实践篇》中提到了一个有趣的案例。\u003c/p>\u003cp>一位车间主任看到车间地板上有一摊油。他马上习惯性地抓住离他最近的一个工人，让他把油擦掉。\u003c/p>\u003cp>此时，一个善于使用“五个为什么”的顾问提出了第一个“为什么”：“为什么地板上会有一摊油？”\u003c/p>\u003cp>旁边的工人回答道：“噢，噶本机漏油了。”\u003c/p>\u003cp>“那你还不赶紧去把噶本机修好？”车间主任吼道。可那个顾问却继续追问：“为什么噶本机会漏油？”\u003c/p>\u003cp>“因为塞子有毛病。”工人答道。\u003c/p>\u003cp>“为什么塞子有毛病？”那个顾问继续追问，提出了第三个“为什么”。\u003c/p>\u003cp>“我也不清楚，反正这一批塞子都不经用，很差。”工人无奈地说。\u003c/p>\u003cp>“那么，你需要搞清楚，为什么你们会买这么差的塞子。”顾问对车间主任说。\u003c/p>\u003cp>……\u003c/p>\u003cp>通过不停地追问“为什么”，可以找到导致问题出现的深层次原因，避免就事论事，只是消除了问题的“症状”，而未从根本上解决问题。\u003c/p>\u003cp>\u003cstrong>分享\u003c/strong>\u003cstrong>I\u003c/strong>\u003cstrong>便签（\u003c/strong>\u003cstrong>4\u003c/strong>\u003cstrong>分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>WHAT:\u003c/strong> \u003c/p>\u003cp>这个片段讲的在复盘中如何运用5WHY分析法进行分析，从而找到真正的原因。\u003c/p>\u003cp>\u003cstrong>WHY\u003c/strong>\u003cstrong>：\u003c/strong>强调不那么做的坏处\u003c/p>\u003cp>人们在工作和生活中，【一般做灶】常常是出现什么问题就是直接解决什么问题，很少深入的去分析问题。【这样做的坏处】这样做的结果，很可能只是暂是解决了问题，可这个问题还是会不断的出现。长此以往，会对自己丧失信心，甚至开始怀疑人生。【举个反例】拿我一个朋友小李来说吧，他经常晚睡，睡晚了他又很自责，常常对我们说以后一定要早点睡。可以第二天晚上他依旧一两步才睡，然后又自责，这样的进入一个恶性循环的怪圈。长此以往不仅影响他们身体健康，甚至还会让他们长期陷入自我否定中。\u003c/p>\u003cp>【变成正例】要是，他们都掌握了这个5WHY分析法，首先问自己为什么晚睡呢？然后根据回答继续追问，就可以找到晚睡的根源，从而找到相应的处理方法，就很有可能解决好这个问题，打破这个怪圈，取得不一样的效果。\u003c/p>\u003cp>\u003cstrong>HOW\u003c/strong>\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>我们具体应该怎么样运用5WHY原因分析法呢？\u003c/p>\u003cp>第一步 提问第一个为什么；就是问“问题”为什么发生\u003c/p>\u003cp>第二步 依次追问为什么；对上次回答的结果，问为什么\u003c/p>\u003cp>第三步 对问题进行整合；对问题进行分类，排序整理，寻找应对方法。\u003c/p>\u003cp>\u003cstrong>WHEN\u003c/strong>\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>当我们想解决问题，避开主观或自负的假设和逻辑陷阱时，就是可以用5WHY分析法，从结果着手，沿着因果关系链条，顺藤摸瓜，直至找出原有问题的根本原因。\u003c/p>\u003cp>更贴近实际的案例\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>好，我们再来看一个更贴近我们实际生活的例子，就是我的同事小王迟到了。\u003c/p>\u003cp>面对员工迟到，人事专员一般都是习惯性地罚没奖金。\u003c/p>\u003cp>而一个善于使用“五个为什么”的人事经理就会提出了第一个“为什么”：“为什么今天上班会迟到呢？”\u003c/p>\u003cp>小王说：“今天起床比平时晚了15分钟。”\u003c/p>\u003cp>经理继续追问：“为什么起床会晚呢？”\u003c/p>\u003cp>“没有被闹钟闹醒”小王答道。\u003c/p>\u003cp>“为什么闹钟闹不醒你？”经理继续追问，提出了第三个“为什么”。\u003c/p>\u003cp>“睡太熟了、没听到”小王无奈地说。\u003c/p>\u003cp>“为什么睡太熟呢？”经理继续问\u003c/p>\u003cp>“昨晚12点才睡着”我说\u003c/p>\u003cp>“为什么昨天失眠呢？”经理又问道\u003c/p>\u003cp>“昨天下午喝了咖啡”\u003c/p>\u003cp>……\u003c/p>\u003cp>第三步，对问题进行整合\u003c/p>\u003cp>对所有的原因进行按重要程度进归类，排序，从而找到根本原因\u003c/p>\u003cp>预防异议：\u003c/p>\u003cp>讲到这里，你可能会问\u003c/p>\u003cp>1、5WHY分析法是不是一定要问5个为什么呢？其实不是，5是一个虚数，有的问题简单问一两个为什么就是找到了根本原因，有的问题比较复杂也许得问十几个为什么\u003c/p>\u003cp>2、你可能会说这个方法也太简单了，只要问为什么就可以了，其实不是。比如：小王今天上班迟到了？问为什么今天上班会迟到？因为堵车；为什么会堵车？因为今天是工作日啊；类似这样的情况，在5Why分析中，经常发现。\u003c/p>\u003cp>所以，我们在利用5Why进行\u003ca href=\"https://www.baidu.com/s?wd=%E6%A0%B9%E6%9C%AC%E5%8E%9F%E5%9B%A0%E5%88%86%E6%9E%90&tn=SE_PcZhidaonwhc_ngpagmjz&rsv_dl=gh_pc_zhidao\">根本原因分析时，有几点问答规则要特别注意：\u003c/p>\u003cp>A、作为分析的主体要明确；比如在上一个例子中，本来我们分析的主体是小王，但在问为什么堵车的时候，主体就是变了，保护主体不变的问法应该是——为什么堵车你就是会迟到呢？\u003c/p>\u003cp>B、回答的理由是受控的；这个好理解就不用多说了\u003c/p>\u003cp>C、从回答的结果中，我们能够找到行动的方向。\u003c/p>","interaction":"\u003cp>\u003cstrong>A3\u003c/strong>\u003cstrong>促动参与（\u003c/strong>\u003cstrong>20\u003c/strong>\u003cstrong>分钟）\u003c/strong>\u003c/p>\u003cp>以上就是5WHY分析法的三个步骤，大家有没有什么疑问？（反馈和回应）\u003c/p>\u003cp>【学习者提问】涛涛，我怎么知道判断是不是找到了根本原因呢？\u003c/p>\u003cp>【回应】这个问题非常好啊，我们要判断找到的原因是不是根本原因，就可以思考下如果把这个原因解决后，之前的问题还会不会发生。如果之前的问题不会再发生了，那么说明我们就找到了问题的根源。如果把找到的原因解决后，之前的问题还会出现，那么我们可能就需要继续问下去。\u003c/p>\u003cp>好，没问题的话，我们就进入下一个环节——场景演练\u003c/p>\u003cp>\u003cstrong>场景：——（\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>分钟）\u003c/strong>\u003c/p>\u003cp>我们刚刚学习了5WHY分析法，现在我们来做一个演练。\u003c/p>\u003cp>唐僧师徒取经回来，开了一个公司，公司业绩越来越好，年底发年终奖，大家都拿到八万块钱的年终奖，而八戒却只拿到八百，八戒气呼呼的找到唐僧理论。唐僧说\u003c/p>\u003cp>不急，不急，我们来看看你的考勤，嗯……一月第一周请病假两天…嗯…二月第二周请病假一天……六月第三周请病假两天……”\u003c/p>\u003cp>八戒不耐烦听不下去唐僧的唠叨，说好好别说了，暗自离开……\u003c/p>\u003cp>回到家的八戒还是闷闷不乐，心想都是去了西天、见了佛主的人，怎么自己就这么容易生病呢？经常请假，让自己损失了79200元。\u003c/p>\u003cp>于是，他找到他的老婆，让老婆和他一起运用5WHY分析法，来分析一下自己为什么会经常生病，从而找到了自己经常生病的根本原因。\u003c/p>\u003cp>\u003cstrong>小组讨论\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>指令：\u003c/strong>\u003c/p>\u003cp>首先，请大家各自以八戒的身份各自运用WHY分析法，梳理一下自己经常生病的原因，时间是2分钟；\u003c/p>\u003cp>写好后，请大家按照之前的分组，俩人一组，一位扮演八戒，一位扮演八戒的老婆，一起运用5WHY分析法来帮助八戒分析经常生病的原因。在小组里讨论演练3分钟\u003c/p>\u003cp>\u003cstrong>现场演练\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>指令：\u003c/strong>\u003c/p>\u003cp>有哪一组的小伙伴愿意来给我们大家演练一下呢？\u003c/p>\u003cp>\u003cstrong>场景演练：\u003c/strong>\u003c/p>\u003cp>我们有请花花和小船来给我演练一下\u003c/p>\u003cp>花花：媳妇儿，我18年的年终奖有8万，但我只得到800……\u003c/p>\u003cp>小船：什么？！为什么只有800？8万变成800？为什么呢？\u003c/p>\u003cp>花花：8万变800的原因是我请了太多次的病假，就被扣掉了很多钱，最后就只剩下800\u003c/p>\u003cp>小船：那这个可能就需要分析一下，你为什么经常请病假了。你为什么经常生病？\u003c/p>\u003cp>花花：生病的原因是因为我本来身体不好，还有太胖了。\u003c/p>\u003cp>小船：那我们一个一个得来，我们先看看为什么你身体不好呢？\u003c/p>\u003cp>花花：运动得太少了\u003c/p>\u003cp>小船：为什么运动得太少了呢？\u003c/p>\u003cp>花花：因为没有时间，时间没有安排好\u003c/p>\u003cp>小船：嗯，那可以去向加一学习下时间管理。那我们再看你你身体为什么会这么胖呢？\u003c/p>\u003cp>花花：我的脾胃不好\u003c/p>\u003cp>小船：为什么脾胃不好呢？\u003c/p>\u003cp>花花：饮食结构不合理\u003c/p>\u003cp>小船：为饮食结构不合理呢？\u003c/p>\u003cp>花花：我不知道怎么去搭配自己的饮食结构\u003c/p>\u003cp>小船：那我们可以去请教一下艳琰姐。\u003c/p>\u003cp>花花：嗯，听你这么一分析，我觉得还真有道理。我请这么多的病假就是因自己没有管理好自己的时间导致自己没有时间锻炼身体不好。没有调整好的自己的饮食结构导致自己长胖，两个根本的因素加起来就导致了自己经常生病。看来我接下来要好好应对了。争取明年拿到8万的奖金。\u003c/p>\u003cp>【关联原文知识点的回应】好，让我们用掌声感谢花花和小船的演练，小船扮演的八戒老婆首先按原文说所说“挑选出一个问题症状作为开端，然后问小组成员第一个为什么：“为什么这件事情正在发生？”即“为什么8万变成了800?&quot;根据花花扮演的八戒的回答，接着八戒老婆继续按原文所说的\u003cstrong>“依次追问“为什么””\u003c/strong>进行了追问，这样层层追问下去，最终找到了八戒经常感冒的根本原因\u003c/p>\u003cp>他们刚刚的演练非常棒！让我们再次用热烈的掌握感谢他们给我们带来的精彩演绎。\u003cbr>\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>\u003cstrong>催化应用（\u003c/strong>\u003cstrong>8\u003c/strong>\u003cstrong>分钟）\u003c/strong>\u003c/p>\u003cp>请大家畅想一个，在未来一周或一个月内，你可能会运用到5WHY分析法进行原因分析的事件。\u003c/p>\u003cp>这件事可能是你将要进行了年度目标复盘、工作总结、一次培训学习效果的评估，或者其它你想到的需要进行原因分析的事。\u003c/p>\u003cp>请大家花1分钟的时间把它写在便签了。写好后请在小组里讨论下。待会儿，我会请一个小伙伴来分享一下他可能需要分析原事 \u003c/p>\u003cp>【学习者分享】小江：需要在下周日对公司网络营销方案取得成功的原因，进行5Why分析。\u003c/p>\u003cp>【回应】好的，谢谢小江的分享，非常棒。\u003c/p>\u003cp>好，接下来请各位小伙伴用5WHY分析法，为你刚刚写下的那件事儿，做一个简单的分析计划。写下时间、地点，操作步骤及预期结果。写好后，请在小组分享讨论。待会儿，我会请一个小伙伴来分享一下他的分析计划？（先做一个分析计划，在你计划的时间再去分析完善）\u003c/p>\u003cp>【学习者分享】Andy：\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>5WHY原因分析计划\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>将来可能会运用5WHY分析法分析的事\u003c/p>\u003c/td>\u003ctd>\u003cp>公司的课程转化率低\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>时间\u003c/p>\u003c/td>\u003ctd>\u003cp>下周日\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>地点\u003c/p>\u003c/td>\u003ctd>\u003cp>公司培训室\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>人物\u003c/p>\u003c/td>\u003ctd>\u003cp>自己\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>操作步骤\u003c/p>\u003c/td>\u003ctd>\u003cp>第一步 就问为什么这个课程的转化率低呢？这时候可能会得到原因A\u003c/p>\u003cp>第二步 接下就原因A问为什么，就会得到原因B，这样一至追问下去……，最后可能会得到根本的原因E\u003c/p>\u003cp>第三步，然后对所有的答案进行整合找到系统性的原因\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>预期结果\u003c/p>\u003c/td>\u003ctd>\u003cp>通过分析找到转率低的根本原因\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>【回应】好的，谢谢Andy的分享，看来Andy已经很好的掌握了5WHY分析法，非常棒。\u003c/p>\u003cp>\u003cstrong>强有力的结语：\u003c/strong>\u003c/p>\u003cp>今天我们通过两个片段，希望大家能掌握复盘的四步法，在遇到“重新预价”的事后，能及时运用复盘四步法做一个高效的复盘。\u003c/p>\u003cp>我们常说不经思考的人生不值得过，那么让我们学好复盘，用好复盘，让我们有一个更精彩，更值得的人生！\u003c/p>\u003cp>\u003cstrong>好，我的分享到此结束，谢谢大家！\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1556289582000,"updated_at":1557114951000,"ria":true},{"id":7707,"topic":"总结常常写，复盘时时念。 - 但你真的懂什么是复盘吗？","learn_goal":"学习者学习后，可以运用复盘的方式，进行总结","remark":"","level":"TF3-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"佳山","city":"厦门"},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"开场：\r\n 大家好！我是佳山。\r\n【事件】我们都听过这样一句话，“人，不应在同一个地方摔倒两次。”可我们却总忍不住在同一个地方要摔倒三次、四次。\r\n【提问】如果这个摔倒是在工作中发生的，那将意味着什么呢？\r\n【影响】那将意味着，同是工作十年，别人拥有了十年的经验，而你却是一个经验用了十年，没有成长。\r\n【解决】怎么解决这种情况，让自己能够真正成长呢？今天我讲和大家一起学习的这本《复盘+：把经验转化为能力》一书，就是教我们如何对过去的成败进行结构化总结，快速学习与成长，应对复杂多变的商业环境挑战。\r\n【学习目标】今天我们将学习书中的一个片段，来了解什么复盘，以及如何复盘。通过今天的学习，大家能够使用（行为）复盘技术解决工作和生活中遇到的需要改进（界定）的问题。","ratings_count":1,"texts":[{"id":11202,"quote":"\u003cp>\u003cstrong>什么是复盘\u003c/strong>\u003c/p>\u003cp>“复盘”原是围棋术语，本意是对弈者下完一盘棋之后， 重新在棋盘上把对弈过程摆一遍， 看看哪些地方下得好，哪些下得不好，哪些地方可以有不同甚至是更好的下法等。\u003c/p>\u003cp>这个把对弈过程还原并且进行研讨、分析的过程，就是复盘。通过复盘，棋手们可以看到全局以及整个对弈过程，了解棋局的演变，总结出适合自己和不同对手的套路，或找到更好的下法，从而实现自己棋力的提升。\u003c/p>\u003cp>用到企业管理中，复盘是指从过去的经验、实际工作中进行学习，帮助管理者有效地总结经验，提升能力，实现绩效的改善。正如联想集团创始人柳传志先生所说:所谓复盘，就是一件事情做完了以后，做成功了，或者没做成功，尤其是没做成功的，坐下来把当时的这个事情，我们预先怎么定的、中间出了什么问题、为什么做不到，把这个过程要理一遍，理一遍之后，下次再做的时候，自然这次的经验教训就吸收了。&nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","explains":"\u003cp>【强化讲解概念的能力】\u003c/p>\u003cp>我们这个时代是一个时不时会创造些新概念的时代，比如新零售、降维打击、场景、以及今天我们要学习的“复盘”。\u003c/p>\u003cp>那什么是复盘呢？所谓“名正则言顺，言顺则事成。”只有正本清源搞清楚什么是复盘，我们才能正确使用复盘。这个片段给出了复盘的来源——来自围棋，其本意是对弈者下完一盘棋之后， 重新在棋盘上把对弈过程摆一遍， 看看哪些地方下得好，哪些下得不好，哪些地方可以有不同甚至是更好的下法等。\u003c/p>\u003cp>我们通过几个例子来理解下复盘的概念。\u003c/p>\u003cp>“我昨天的表现太差了，下次我要改进表现好些。”这是复盘吗？这不是。因为复盘的定义中强调要“重新在棋盘上把对弈过程摆一遍”，这是一个回顾事实还原过去的过程，回顾当初我们的期望标准是什么，回顾过程中发生了什么。而这句话只是对过去的一个简单的评价——“表现太差”，没有还原原先的事实和过程。另外复盘的定义中还有“看看哪些地方下得好，哪些地方下得不好”的这么一个比较分析，而这个日常的总结里也没有我差在哪儿了？没有和标准对比，我差在哪儿了的这个分析差异的过程。所以他不是复盘。\u003c/p>\u003cp>那有了回顾事实和差异分析这两步以后呢？我们接着看。\u003c/p>\u003cp>玩过80分，或看别人玩80的人都知道，在一把结束之后，总有一个人会说他的对家，“刚才我出什么什么的时候，你应该出什么什么，这样他就大不过你了。。。。。”嗯，别人帮你还原了事实，比较了差异，还交给你怎么做。这下总该是复盘了吧！\u003c/p>\u003cp>还不是！因为这虽然是别人帮你回顾和分析，但缺少了你反思自我的过程。为什么在这个点我应该出那张牌？为什么在这个点我要大过他让自己一方抢先机？反思是为了探寻背后的规律，而把握规律才是你成长提升的阶梯。而且在这么短的时间内，我们谁又能get到那么多点呢？这是复盘的第三个步骤。\u003c/p>\u003cp>那什么是真正的复盘呢？我们再回到复盘的来源，下棋的例子中。\u003c/p>\u003cp>一盘棋局结束后，为了提升对弈者的棋力，他们将对弈的过程在棋盘上重新摆了一遍，这是回顾。二人在重新摆的过程中，对每一步进行了说明讲解，为什么你的白子放这里，我的黑子摆那边，这是分析。摆这里是为了在后面的落子中能封点挤拆逼？还是为了碰压接扳刺？这是反思。经过这样的过程，最终让自己在下一次的对弈中能够提升自己的棋力，取得胜利。这样才是一个完整的、闭环的复盘过程。熟悉拆书帮RIA阅读法的朋友也都知道，A2环节就是要将你的所学应用在今后的生活和工作中，真正实现学以致用。这也是我们复盘的意义之所在。\u003c/p>\u003cp>【HOW】\u003c/p>\u003cp>通过刚才对复盘概念的讲解，我们得出了复盘的四个步骤：\u003c/p>\u003cp>1、回顾\u003c/p>\u003cp>2、分析\u003c/p>\u003cp>3、反思\u003c/p>\u003cp>4、提升\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>同时也发现，复盘这个办法，是一套系统严谨的方法，他需要时间去研究、探讨、打磨。所以当我们遇到一些没有成功的、重大的、经常发生的事情，只要时间充裕，又十分必要时，那都可以尝试运用复盘来帮助自己进步、成长。而那些不经常发生的事，也无伤大雅的事，就没必要费那个精力了。\u003c/p>\u003cp>举一个我自己的例子，那是发生在去年，我的工作岗位刚发生变化的时候。\u003c/p>\u003cp>从人力资源岗位转到了市场营销的岗位，一时有些不适应。具体体现在哪儿呢？体现在指标意识上。因为指标意识的缺乏，导致我去年的工作很盲目、疲惫，不得章法，最后的指标也差强人意。\u003c/p>\u003cp>于是今年初，公司领导组织对去年四季度的营销活动进行复盘。\u003c/p>\u003cp>首先，回顾。当时我的指标跟的很辛苦，季度的总指标有，每天的销量有，然后要把每天的销量和之前的销量进行相加，然后再和目标值相减看缺口差多少。。。。。\u003c/p>\u003cp>其次，分析。这个跟踪指标的方式劳动量很大，每天都在做重复的事情，很浪费时间和经历。其他人的指标好像没有我跟的这么辛苦。\u003c/p>\u003cp>第三，反思。有没有更好的方法呢？有！把总目标分解成月目标、周目标、日目标。这样每天的销量和日目标相比，就知道能不能完成了！\u003c/p>\u003cp>第四，提升。在今年一季度的工作中，我将我负责的指标进行了分解，一直分解到最小的颗粒度，日目标。\u003c/p>\u003cp>结果我的工作果然神清气爽，让我每天只工作3小时。\u003c/p>","interaction":"\u003cp>下面，我们通过分组讨论的方式做个案例来实际演练下复盘的方法。以我左手边为一组，右手边为另一组。\u003c/p>\u003cp>每年我们都会经历几次盛大的购物狂欢节。去年的双十一不知道大家是否购物愉快愉快？你有没有什么糟心的经历来分享一下？\u003c/p>\u003cp>年年618、双十一，你是否总是在剁手这件事情上犯相同的错误？你是否对自己的购物行为后悔总结过？\u003c/p>\u003cp>请大家结合在今天所学的知识，按下面的表格要求，编写一个剧本，要设计出一个包含人物角色、有起因经过结果对话的故事，复盘你去年的双十一或最近的一次大规模的购物活动。\u003c/p>\u003cp>给大家5分钟的时间讨论，然后我们请一个小组来和大家分享。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>项目\u003c/p>\u003c/td>\u003ctd>\u003cp>内容\u003c/p>\u003c/td>\u003ctd>\u003cp>备注\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>事件内容\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>介绍背景、时间、地点、人物关系、人物的内心想法、点睛评语等\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>人物角色\u003c/p>\u003c/td>\u003ctd>\u003cp>角色A：\u003c/p>\u003cp>角色B：\u003c/p>\u003c/td>\u003ctd>\u003cp>多角色可自行补充\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>对白\u003c/p>\u003c/td>\u003ctd>\u003cp>角色A：\u003c/p>\u003cp>角色B：\u003c/p>\u003cp>角色A：\u003c/p>\u003cp>角色B：\u003c/p>\u003cp>角色A：\u003c/p>\u003cp>角色B：\u003c/p>\u003cp>角色A：&nbsp;\u003c/p>\u003cp>角色B：\u003c/p>\u003cp>角色A：\u003c/p>\u003cp>角色B：\u003c/p>\u003cp>角色A：\u003c/p>\u003cp>角色B：\u003c/p>\u003cp>角色A：&nbsp;\u003c/p>\u003cp>角色B：\u003c/p>\u003c/td>\u003ctd>\u003cp>对话内容要体现以下步骤：\u003c/p>\u003cp>1、回顾\u003c/p>\u003cp>2、分析\u003c/p>\u003cp>3、反思\u003c/p>\u003cp>4、提升\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>学员佳音的分享\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>项目\u003c/p>\u003c/td>\u003ctd>\u003cp>内容\u003c/p>\u003c/td>\u003ctd>\u003cp>备注\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>事件内容\u003c/p>\u003c/td>\u003ctd>\u003cp>买到了用不着的东西\u003c/p>\u003c/td>\u003ctd>\u003cp>介绍背景、时间、地点、人物关系、人物的内心想法、点睛评语等\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>人物角色\u003c/p>\u003c/td>\u003ctd>\u003cp>角色A：同事\u003c/p>\u003cp>角色B：佳音\u003c/p>\u003c/td>\u003ctd>\u003cp>多角色可自行补充\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>对白\u003c/p>\u003c/td>\u003ctd>\u003cp>角色A： 今年双十一又买了一堆用不到的东西。\u003c/p>\u003cp>角色B： 为什么呢？怎么会买用不到的东西呢？\u003c/p>\u003cp>角色A：【回顾】先前手里抢了一堆券，后面又是满减，又为了凑单。不知不觉买了很多用不到的东西。\u003c/p>\u003cp>角色B： 那你想买的东西买到了吗？\u003c/p>\u003cp>角色A： 有的买到了，有的没买到。\u003c/p>\u003cp>角色B： 没买到的是什么原因呢？\u003c/p>\u003cp>角色A：&nbsp;【分析】 还不是为了凑单，各种选，等再选其他的东西时候，有的已经没货了。\u003c/p>\u003cp>角色B：那是本来目标定的要买ABC，结果买了ADE，目标从买ABC变成了更便宜地买A？\u003c/p>\u003cp>角色A：是这样的。\u003c/p>\u003cp>角色B：那最后算下来A买便宜了吗？\u003c/p>\u003cp>角色A： 【反思】也没有啊！这样看买A也不划算，还搭了用不着的DE。\u003c/p>\u003cp>角色B：那有没有办法让自己的目标锁定呢？\u003c/p>\u003cp>角色A：【反思】其实想想吧，活动内容一开始已经公布了，我只要列好清单，盯住ABC，买回来。反正价格已经比平时便宜了，不能一味地追求更便宜，差不多就可以了。太贪心反而不划算。\u003c/p>\u003cp>角色B：嗯，那双十二你还淘吗？\u003c/p>\u003cp>角色A：淘啊！把没买的BC捞回来。\u003c/p>\u003cp>角色B：那你打算再怎么折腾？\u003c/p>\u003cp>角色A：【提升】先了解活动内容，看双十二是怎么个玩法。然后列好自己要买的东西，锁定目标，不为其他诱惑所困。最后在0点赶紧下手！\u003c/p>\u003c/td>\u003ctd>\u003cp>对话内容要体现以下步骤：\u003c/p>\u003cp>1、回顾\u003c/p>\u003cp>2、分析\u003c/p>\u003cp>3、反思\u003c/p>\u003cp>4、提升\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>非常感谢佳音的分享，刚才佳音结合同事的经历复盘了双十一的购物经历。帮同事回顾了当时购买的过程，准备的一堆券；分析了因为凑单，错失自己想买的东西；而后反思发现要锚定自己的购物目标，不能太贪，结果买了一堆没用的东西。最后在接下来的618中提升措施是列好购物清单，不为其他货品所动。非常感谢佳音。\u003c/p>\u003cp>【Ending结尾】\u003cbr>\u003c/p>\u003cp>古人说，知其然知其所以然。我们常常在念叨着复盘，但我们真的会复盘吗？今天我们重新认识了复盘，学习了复盘，希望对大家能够真正掌握复盘。\u003c/p>\u003cp>我是拆书家，我是崔俊峰。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1556007553000,"updated_at":1556007553000,"ria":true},{"id":7700,"topic":"如何从过去经验中提升自己的见识和能力","learn_goal":"用个人复盘的方法提升自己的见识和能力","remark":"《复盘：把经验转化成能力》这本书的作者是邱绍良，他是管理学博士，高级经济师，中国学习型组织网创始人。曾为数百家公司提供咨询与培训服务。书中介绍的复盘方法“U型学习法”更是集合了中国智慧，对于个人、团队、项目复盘都有针对型的实际操作指导。","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"张喆","city":"青岛"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"【开场】各位拆书帮的伙伴们，大家好，我是青岛拆书帮筹备分舵的拆书家张小喆，很高兴今天晚上大家相聚于此，参加拆书活动，今天是我现场tf3-1的拆书活动，拆书的主题是如何进行个人复盘。下面分一下组，今天到场的有胡老师和转圈圈老师，胡老师为一组，转圈圈老师为 一组\r\n【学习目标】在跟随我完成本次的RIA现场学习后，学习者能够从自己的过去的经验（界定）当中，用个人复盘的方法（澄清）进行（行为）结构化的自我反思，以提升自己的个人能力。\r\n【图书介绍】\r\n（事件场景）：现场的伙伴们不知道你们有没有这样类似的经历？又是月底了，工作上事情多而时间紧张，每逢月底这几天你都是神经紧张，早上给你了一摞资料，要求下班之前整理完，并提醒你认真不能出错，你满口答应，心里却很慌张，上次月底的资料出了错，最后整个部门都要改数据资料。仔细整理，认真检查，再三确认，第二天还是劈头盖脸的被老板骂了一顿，你很沮丧，在今日工作总结上又痛定思痛，保证下次不再分同样的错误。突然意识到月度、季度、年度的总结又是和今天的如此雷同。你陷入了沉思，更深一步的反思自己。\r\n（提问）：\r\n类似错误的重演，你是否怀疑自己的能力不如别人？\r\n日复一日的反思是否让你更加焦虑？\r\n你是否想过除了反思、总结还有没有其他的方法可以让你不重复交学费？\r\n（影响）：在同样的地方跌倒，本身不仅因为重复而浪费自己的时间和精力，而且会使你感到焦虑，更进一步就会质疑自己的能力，生活就像会墨菲定律一样，你担心的不好的事情总会发生，进入了一个循环，严重影响了你的生活工作的质量。\r\n（解决）：在《复盘：把经验转化成能力》这本书中，可以解决大家的遇到的问题。书中作者通过自己几十年的复盘行动，总结出复盘之道，借助结构化的工具，找到事物的内在规律，把经验转化成能力，避免重蹈覆辙，让伙伴们拥有更高效的人生。\r\n下面伙伴们阅读一下拆页原文，阅读完的伙伴示意我。","ratings_count":1,"texts":[{"id":11196,"quote":"\u003cp>【R】阅读原书拆页\u003c/p>\u003cp>什么是复盘\u003c/p>\u003cp>&nbsp; “复盘”原是围棋术语，本意是对弈者下完一盘棋之后，重新在棋盘上把对弈过程“摆”一遍，看看哪些地方下得好，哪些下得不好，哪些地方可以有不同甚至是更好的下法，等等。\u003c/p>\u003cp>&nbsp; 这个把对弈过程还原并且进行研讨、分析的过程，就是复盘。通过复盘，棋手们可以看到全局以及整个对弈过程，了解棋局的演变，总结出适合自己和不同对手的套路，或找到更好的下法，从而实现自己棋力的提升。唐代诗人杜牧在《重送绝句》一诗中曾形象生动地描述了他与一位围棋高手对弈之后复盘的场景：“绝艺如君天下少，闲人似我世间无。别后竹窗风雪夜，一灯明暗覆吴图。”《复盘+》是一本系统阐述复盘方法并教我们如何使用复盘的工具性书籍，通过复盘可以在经历中总结经验，把经验转化为做事的能力，避免没有进步的焦虑，为以后做事节省时间和精力。不是自己能力有问题，只是方法有问题。今天我们学习的主题就选自这本书，让我们看看什么是复盘，如何通过复盘让自己避免重复性且没有进步的行为的发生。\u003c/p>","explains":"\u003cp>【I】拆书家讲解引导（强化讲解概念）\u003c/p>\u003cp>（重述概念）\u003c/p>\u003cp>在这拆页当中，我们看到了“复盘”的由来和定义。我们现在来重新梳理一下这个定义，拆页中讲到的对弈者下完棋之后，这里指的是对奕者而旁观者，也就是说这是本人的亲身经历，并非旁人，“之后”一词是指事情结束后，也就是说，复盘必须是对过去发生的事情而言，重新摆一遍为了看那些地方下的好，下得不好，或者有什么改进，这个过程当中二人并不是互相指责，互相感叹早知如此何必当初出，也就是说复盘的目的是以学习为导向，为了获得启发、见解，提升自己的见识和能力，从而提高个人有效的行为能力。不仅要知其然，还要知其所以然。\u003c/p>\u003cp>（对比讲解）\u003c/p>\u003cp>从“咪蒙事件”编造故事，造成社会负面舆论，到其公众号注销，到咪蒙公司解散，我们可以从咪蒙事件中获得启发或借鉴是复盘吗？不是复盘，‘咪蒙事件’你并不是当事人，再详细的案例都无法真实还原事实，无法让人完整执行整个复盘逻辑，这也是为什么复盘强调的是亲身经历。\u003c/p>\u003cp>那么公司举行的庆功宴上代表发言的个人总结，这叫不叫个人复盘那？不是的，在庆功宴的特殊场合的总结，很多具体细节无法很好的真实还原，会存在报喜不报忧的情况，而且个人代表的发言是对于整个团队的总结，只不过个人的形式体现，如果不是在庆功宴的场合，不受外界因素的干扰，对项目中与自身有关的过程、结果进行回顾、描述，对差异的原因进行分析，得出经验与教训，而非简单回顾事件，这就是个人复盘了。\u003c/p>\u003cp>我觉得复盘太好用了，我要把复盘用到生活工作的每一件事情，大事小事都复盘，这样真的是会复盘了吗？比如在分析与解决问题时，在复盘的过程当中是会有找到问题和不足，并对其分析原因，但这部分并不是复盘的全部，如果将重点侧重在分析原因上，会削减反思和学习的成分，达不到复盘的效果。\u003c/p>\u003cp>（给出步骤）\u003c/p>\u003cp>通过上述适应边界的分析，伙伴们对复盘有了更进一步的认识，那么接下来，我将给出复盘的具体步骤\u003c/p>\u003cp>1-回顾目标。复盘的事情需目标清晰，且明确目标的实现情况。\u003c/p>\u003cp>2-梳理过程。梳理过程当中保持开放心态，坦诚对待，实事求是。\u003c/p>\u003cp>3-对比分析。找到事情的亮点和不足，并分析原因，找到关键因素。\u003c/p>\u003cp>4-总结规律。反思遇到的问题的本质，对于同类事情的行为指导。\u003c/p>\u003cp>5-付诸实践。将经验、教训转化到后续的行动当中。\u003c/p>\u003cp>一个例子（举例验证）\u003c/p>\u003cp>这是过年小长假之后的复盘。\u003c/p>\u003cp>过年的小长假，原本计划读的书最终只读了三本。每次我要看书的时候妈妈总是过来找我说话，一些至少看起来对我无关紧要的事情，妈妈总来问我，比如手机上怎么清内存，怎么设置朋友圈，她看的文章的内容是不是真的，我就放下书给她解答，然后就聊聊天。\u003c/p>\u003cp>回顾目标：过年期间看完7本书，并完成19年全年目标梳理。\u003c/p>\u003cp>梳理过程：每天阅读的时间，在下午和晚上。这个时间，我想学习，而妈妈刚好也有空，每天的看书总是被打断，但和妈妈聊天的时候我很开心，事后要对没有按时读完书很懊恼，中间跟妈妈说过我要学习的事情，妈妈只记住了一天，后来就忘了，我也没有再说，最终没有完成自己定的目标。\u003c/p>\u003cp>对比分析：\u003c/p>\u003cp>1-亮点：在这过程当中和父母相处很愉快，找到了和父母的相处模式；对目标来说，努力完成，除了和父母聊天，没有懈怠过。\u003c/p>\u003cp>原因：在我心里，和家人相处比自己学习更重要，其实我已经做了选择，只是我一直碍于给自己的目标，对目标是自己尽力完成的，有时候聊天的时候也在看书。\u003c/p>\u003cp>2-不足：在制定目标时，没有充分考虑到回家之后的实际情况，过年走亲戚的情况有考虑到，但忘记了过年回家，父母都一整年没有好好交流过。在过程当中，对于自己的学习时间和习惯没有及时调整，一直是下午和晚上。\u003c/p>\u003cp>原因：阅读习惯无法及时调整，上午看书效率较低。回家的时候忘记了女儿的身份，在父母眼里，不忙的时候回家，回家是没有工作的，其实我的潜意识里也是这么认为的，不然我就会拒绝父母和我的聊天。\u003c/p>\u003cp>总结规律：回家就好好陪父母，做个好女儿，学习可以在私人空间。\u003c/p>\u003cp>付诸行动：目标还是要完成的，寒假结束去蓬莱小闭关5天。\u003c/p>\u003cp>（点破燃点）：\u003c/p>\u003cp>1-在这个过程中，哪个步骤是最容忽略的？复盘的内功心法，梳理过程中的坦诚的心态和在对比分析中的反求诸己，如果我的心态不过坦诚，我就不会发现何父母相处的愉悦感，没有反求诸己，在下一步分析的时候，我会抱怨父母老是打扰我学习。找不到真正的原因，虽然最终我还是回去小闭关几天，但心态会很不一样。\u003c/p>","interaction":"\u003cp>【A2】催化应用\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>刚刚我们一起学习了如何进行复盘，下面大家用复盘的知识解决一个生活中实际遇到的问题。接下来请大家独立编写一个剧本，这个剧本的场景最好是可以在将来可能遇到的，包括标题、人物、背景、情节变化（起因、经过、结果）、动作、对话，也可包括内心独白等，其中对话过程中能够使用“复盘”概念和复盘的步骤，摘要写在纸上，五分钟后我们请人讲讲他的剧本。\u003c/p>\u003cp>学习者案例：\u003c/p>\u003cp>标题：下周线下拆书课的个人复盘\u003c/p>\u003cp>人物：胡老师及拆书帮伙伴\u003c/p>\u003cp>背景：拆书课结束后复盘线下拆书课\u003c/p>\u003cp>对话：\u003c/p>\u003cp>拆书帮伙伴：胡老师你对这次线下拆书课的目标是什么？是否如期完成那？\u003c/p>\u003cp>胡老师：这次的活动的目标是通过线下拆书课，让学习者了解拆书帮，学习拆书法。这次活动圆满顺利达成目标，学习者在学习过程中都有很大的收获，愿意以后多参加拆书帮的活动。\u003c/p>\u003cp>伙伴：这次拆书课的亮点和不足是什么那？\u003c/p>\u003cp>胡老师：就个人而言，亮点是第一，准备相对充分；第二，现场气氛活跃，第三，互动充分。不足就是第一，拆书的技能点运用的不够娴熟，但是学习者虽然不了解这个情况，但自己是了解的；第二，宣传不是很充分，比预计的报名人数少10人，第三，作业留得不是很好，导致后续跟进会有难度。\u003c/p>\u003cp>伙伴：胡老师就这次拆书课有什么规律可以总结？后期会有什么样的行动？\u003c/p>\u003cp>胡老师：总结那，第一，拆书课的宣传至少要提前15天，第二，提前30天做内容的准备工作。\u003c/p>\u003cp>后续的行动就是每月开展线下拆书课，这是知行合一分舵的常规性的工作。\u003c/p>\u003cp>谢谢胡老师的分享，胡老师在分享的过程中灵活运用到了我们今天学习复盘的5个步骤。很精彩。伙伴们对于今天复盘方法学习得很到位，复盘就一件持续做下去的事情，希望伙伴们可以持续复盘让复盘成为一种习惯。\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>最后，我用孔子的一句话结束今天的拆书，“吾日三省吾身：为人谋而不忠乎？与朋友交而不信乎？传不习乎？”\u003c/p>\u003cp>谢谢伙伴们的参与，今天我tf3-1的线下拆书活动到此结束，下周二见。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1555992560000,"updated_at":1555992560000,"ria":true},{"id":7473,"topic":"快速进行个人简易复盘","learn_goal":"能够使用复盘的四步法，进行个人简易复盘","remark":"","level":"TF3-2","duration":25,"status":29,"type":0,"chaishujia":{"username":"石思思","city":"重庆市"},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"\u003cp>【自我介绍+分组】\u003c/p>\u003cp>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;各位亲爱的小伙伴们，大家上午好！我是今天的拆书家石思思。用三个标签简单介绍一下自己，谜一样的天蝎座，不规律的运动者，在路上的旅行人。正式开始前，我们先分组，我们分成二个组来完成今天的学习。&nbsp;\u003c/p>\u003cp>【事件场景】\r\n &nbsp; &nbsp; &nbsp; &nbsp;常言道：吃一堑长一智。那么我们在工作生活中，吃一堑了，是否长一智了呢？比如说策划一场活动结果效果不理想，比如说做了好几个减肥计划却因为一些原因没能执行下去，比如进行了几次拆书分享却都没有成功。&nbsp;\u003c/p>\u003cp>【提问】\r\n &nbsp; &nbsp; &nbsp; &nbsp;你有没有出现过类似有过经历经验，明明之前也经历过，再经历时依旧以不满意、不成功为结果呢？你有没有重蹈覆辙过呢？你有没有被同一个石头绊倒过呢？&nbsp;\u003c/p>\u003cp>【影响】\r\n &nbsp; &nbsp; &nbsp; &nbsp;对过去的经历经验，很多人持有无所谓的态度。不过大家可能听过这样一句话“过去的你成就了现在的你”，所以说如果过去的经历只是经历，那么十年后的你还是像现在一样。&nbsp;\u003c/p>\u003cp>【解决】\r\n &nbsp; &nbsp; &nbsp; &nbsp;今天要拆的这本《复盘+》，作者是邱昭良，第三版于2018年出版，是一本指导个人和团队进行复盘的工具书。书中指出，通过一系列的方法，对过去的经历经验进行复盘，能从而把过去或成功或失败的经验转换成为能力。&nbsp;\u003c/p>\u003cp>【学习目标】\r\n &nbsp; &nbsp; &nbsp; &nbsp;通过今天的学习，在之后的经历经验后，能够及时使用复盘的四步法，进行简易复盘。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>【评测表】\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 我们先来做个小测试，给到大家1分钟时间。\u003c/p>\u003cp>【I解释自测题】\u003c/p>\u003cp>这个量表的目的，是测试一下大家对复盘的了解和使用情况。总分为30分，分数越高，说明你对复盘的了解和使用情况越好。分数高也没关系，通过今天的学习，你可以知道接下来应该如何去进行。\u003c/p>\u003cp>那么现在我们来看看，15分及以下的请举手。这说明你对复盘了解甚少。\u003c/p>\u003cp>15至25分的请举手。这说明大家对复盘有一定的了解，可能还不会使用，或者使用还不是很精练，但是稍加努力就可以熟练掌握。\u003c/p>\u003cp>25分以上的请举手。这说明你对复盘很熟悉了，甚至已经形成了复盘的习惯。\u003c/p>","ratings_count":1,"texts":[{"id":10941,"quote":"\u003cp>《复盘+：把经验转化成能力》P.25\u003c/p>\u003cp>“复盘”原是围棋术语，本意是对弈者下完一盘棋之后，重新在棋盘上把对弈过程“摆”一遍，看看哪些地方下得好，哪些下得不好，哪些地方可以有不同甚至是更好的下法，等等。\u003c/p>","explains":"\u003cp>【WHAT&amp;简短互动】\u003c/p>\u003cp>这个片段中，主要讲述了“复盘”来由。\u003c/p>\u003cp>拆书家：那么在这里请问大家，你阅读完这个片段之后，你认为的复盘是什么？\u003c/p>\u003cp>学习者：复盘就是让时间回到事情的起点，把事情如何做的再过一遍，其中做得好的，不好的，如何做得更好。\u003c/p>\u003cp>拆书家：小伙伴说的，复盘是回到复盘的起点，把做得好的、不好的进行回忆，从而更地为将来准备。那么小伙伴们是如何操作的呢？\u003c/p>\u003cp>学习者：通过参加会议，做的重点、难点。是一个回忆的过程。\u003c/p>\u003cp>拆书家：您是说复盘是回忆之前的过程，然后把重点提炼出来。\u003c/p>\u003cp>嗯嗯，不同的小伙伴对复盘的操作有一些不同，理解的也有些不同。那么在作者邱昭良在书中指出了他的方法供大家参考。\u003c/p>\u003cp>复盘，是把经历过的事情还原，并且进行研讨、分析，并总结出适合自己活不同对象的套路，找到更好的方法，从而实现能力的提升。\u003c/p>\u003cp>为了更加明确，我们举一个关于做海报的例子来说明。\u003c/p>\u003cp>1、我知道我们公司已经计划下个月要绘制一系列海报，所以现在我就要开始熟练PS，以免做海报的时候技术不行。请问大家，这是复盘吗？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;学习者：不是，因为事情还没有开始。这个是未来的计划。\u003c/p>\u003cp>2、我知道市场部的小明制作海报的技术不错，所以我觉得我们部门的小华应该跟他请教一下方法。请问大家，这是总结还是复盘？\u003c/p>\u003cp>学习者：这是给别人的建议，不是复盘。\u003c/p>\u003cp>3、上个月我们部门做的一批海报都不行，分析完后我发现，是因为配色不对，所以我决定在下个月做海报前，与客户沟通需求配色，做模板，然后再大批量制作。请问大家，这是复盘吗？\u003c/p>\u003cp>学习者：有复盘的行为。进行了分享、未来的方法步骤。\u003c/p>\u003cp>【WHY】\u003c/p>\u003cp>复盘，可以让自己更快更好成长。因为采用复盘，一次过往的事件可以萃取出多条经验，让自己得以快速迭代。如果没有复盘，每一次掉过的坑、受过的伤，都是资源白白地浪费。想要得到更好的结果，只能依赖运气。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>我们什么时候做复盘呢？某种角度上看，任何自己做过的事情，只要你感觉还有提升的余地，你都可以做复盘。复盘可以在企业管理中进行，也可以在个人在工作学习中进行。因此，通过复盘，提升个人工作学习能力，促进企业管理发展。\u003c/p>\u003cp>【how加工步骤】\u003c/p>\u003cp>那怎么做才，个人才可以快速进行简易复盘呢？四个步骤：\u003c/p>\u003cp>\u003cstrong>1、\u003c/strong>\u003cstrong>回顾\u003c/strong>\u003cstrong>评估\u003c/strong>\u003cstrong>。\u003c/strong>复盘的时候要先回顾一下我们当初想要达到的目标是什么；实际结果如何；结果如何发生的。最终呈现出亮点、不足。\u003c/p>\u003cp>\u003cstrong>2、\u003c/strong>\u003cstrong>分析\u003c/strong>\u003cstrong>结果。\u003c/strong>结果与预期目标相比，亮点达成的原因是什么？不足的主观原因是什么？最终呈现出成果的关键因素或失败的根本原因。\u003c/p>\u003cp>\u003cstrong>3、\u003c/strong>\u003cstrong>萃取提炼\u003c/strong>\u003cstrong>。\u003c/strong>有哪些方法可以坚持或推广？有哪些可以改进？最终呈现出推广方法或改进方法。\u003c/p>\u003cp>\u003cstrong>4、\u003c/strong>\u003cstrong>转化\u003c/strong>\u003cstrong>经验。\u003c/strong>如果有人要进行同样的行动，我会给他什么建议？哪些我们可以直接行动？哪些需要协助？最终呈现出行动计划或改善建议。\u003c/p>\u003cp>【这么做的好处】\u003c/p>\u003cp>这个方法，可以对我们经历过的事情，及时进行复盘，避免距离事件太久远而忘记影响因素；此外，可以深入地反思，可以通过身体力行获得大量的一手信息，深入分析、举一反三，把握事物的一般规律，从而更好地将其运用于未来类似的工作场景或工作任务与挑战中。\u003c/p>\u003cp>【不这么做的坏处】\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;不这么做，把过去的经验白白浪费了，并不能形成有效的方法来提升能力。\u003c/p>","interaction":"\u003cp>【A3拆书家提问设计】\u003c/p>\u003cp>刚才，是我对这个阅读片段的讲解，但我们的学习目标还是为了让大家掌握这个方法。\u003c/p>\u003cp>所以，现在请大家来做一个演练。作为一名在职员工的你，在上周五的时候，计划把本周的工作计划制定出来，并联系相关的负责人，告知他们你的工作计划内容或会议时间等。可是在上周五快到六点下班时间了，计划才写了一点点。这样的事情发生很多次了，我需要复盘一下来提升自己的执行力。\u003c/p>\u003cp>如果你是案例中主角的朋友，你可以怎样运用今天所学的知识，来帮助他复盘提升能力呢？\u003c/p>\u003cp>大家清楚练习的内容了吗？好那么请在小组内讨论，小组内运用复盘的方法，来解决这个问题，5分钟后我们请一组上来分享他们的方案。\u003c/p>\u003cp>学习者案例记录\u003c/p>\u003cp>瑞云（员工）：我又加班了，原本上周把本周计划做好，并联系相关负责人的，但是有没有弄好，还连累同事了，不好，每个星期都是这样咋办呀？\u003c/p>\u003cp>阿霞（朋友）：你做这个最初目标是什么？\u003c/p>\u003cp>瑞云：每周五要五点前做好计划、安排。\u003c/p>\u003cp>阿霞：那你其他工作安排是什么呀？\u003c/p>\u003cp>瑞云：接咨询、电话、临时邮件，反正杂事多。\u003c/p>\u003cp>阿霞：相对于杂事，计划是不是更重要些？\u003c/p>\u003cp>瑞云：每件事感觉都要做，没有排序，什么事来了就做什么。\u003c/p>\u003cp>阿霞：因为很重要，所以你是不是可以考虑吧这事作为重要紧急的事情，比如放到周五上午。\u003c/p>\u003cp>瑞云：那结合你刚刚提到的，这事挺重要，那么我把这安排在周五上午，先完成这事，才能做其他事情，成为一个流程。\u003c/p>\u003cp>【拆书家反馈】\u003c/p>\u003cp>谢谢两位小伙伴的分享。通过这个刚刚小伙伴的剧情演练，我们可以发现，通过复盘，把做计划失败的这个经历，转化成为了一个步骤流程，并形成自己的习惯，成为自己的能力。\u003c/p>\u003cp>【A2拆书家布置任务·特定任务】\u003c/p>\u003cp>好，大家听完了讲解，也做了一个小演练，但那都只是练习，最重要的还是要拆为己用，实践在工作生活中。给大家布置一个作业，今天回去大家思考一下，在过去的经历经验中，有没有值得复盘的内容，然后想想如何运用今天学到的技能，通过复盘四步法，快速进行简易复盘。并将这个方法在拆书群里跟大家分享。期待大家的收获哦！&nbsp;\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>瑞云：学习了这个方法后，我发现朋友小丽也不会复盘，特别是在一个全公司的项目中，做得一般，甚至称为失败。于是我在周三的吃午饭的时候，找到她，跟他说了这个方法。首先回顾评估事件的亮点与不足；然后分析反思了失败的根本原因。然后我们萃取提炼了失败的根本原因是在宣传的不足。于是，我们计划在未来的全公司大项目中，做好计划后，先让CEO同意，然后借他的力量进行宣传，然后再通过公司新媒体平台发布报名，这样的顺序，就更多人知道了，为成功铺路。\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>好的，非常感谢小伙伴们的分享。我们再回顾下复盘的步骤：1、回顾评估；2、分析结果；3、萃取提炼；4、转化经验。我们经常说，“不经过反思的人生不值得过！”，那么在这里我们提升一点“不经过复盘的人生不值得过”，希望大家在以后的工作和生活中经常性地复盘，把经验转换成能力！我的分享到此结束，谢谢大家的参与！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1553332995000,"updated_at":1553335591000,"ria":true},{"id":7139,"topic":"如何掌握个人复盘的方法","learn_goal":"掌握个人复盘的方法","remark":"掌握个人复盘的方法","level":"TF3-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"丹丁先生","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"大家好，我是丁丹，为了方便记忆可以叫丹丁先生——这还是一个影响历史的人物。三个标签：HR成本和风控顾问、WFA专家级促动师、思维导图管理师。今天很高兴给大家进行TF3-2的拆书分享。\r\n分组：为了让大家能够进行充分的沟通和智慧连接，根据现场情况我们两两分组。\r\n在跟随我完成本次RIA现场学习后，学习者能运用简单的四步法（行为），掌握个人复盘的技巧（澄清），使其成为个人快速学习，能力提升的一种有效方法。（界定）","ratings_count":3,"texts":[{"id":10541,"quote":"\u003cp>今天我拆析的书名是《复盘——把经验转化为能力》，作者邱昭良，管理学博士，是我国最早研究和实践学习型组织与知识管理的专业人士之一，曾任联想控股董事长助理、万达学院副院长等职位。\u003c/p>\u003cp>【事件场景】在VUCA时代，我们常常会遇到多变、不确定、复杂、模糊的任务。无论组织或个人都要更快更有效地进行学习，但很多领域并没有惯例或成熟的经验可以借鉴，我们需要总结行动中的经验或教训进行知识创新。比如，一个项目工作完成后立刻进行会议总结，丰富经验。或者每天工作结束后做个小结，每月做个总结，在实践工作中萃取经验。\u003c/p>\u003cp>【提问】那问问你，当你结束了一天繁忙的工作，你是如何提炼有价值的经验？如何确保今天犯的错误下次不会再犯？你是否每天也在写工作日志？这些对你后期工作有何指导意义？\u003c/p>\u003cp>【影响】人们常常在回顾问题时，往往没有按照正确的步骤进行，没有明晰问题和差距就开始了分析判断，结果不是过度的懊悔失败就是自以为是的成功，最终无法获得提升。\u003c/p>\u003cp>【解决】《复盘》这本书指导我们在工作和学习过程中，如何运用简单的四步法进行复盘，因为这个活动应用范围很广，而且看似容易，做起来难，所以我们今天就从复盘重要工作这个角度进行讲解。\u003c/p>\u003cp>在我们开始讲解之前，先做一个简单的测试题。请大家认真阅读，并在最符合自己情况的选项上打勾，给大家2分钟的时间。\u003c/p>\u003cp>自测题：仔细阅读下面表格中的每句话，根据自己的实际情况为自己打分（1表示很不符合，6表示很符合）\u003c/p>\u003cp>在我每天工作完成后……\u003c/p>\u003col>\u003cli>\u003cp>我在工作中总会对一些按照规范、惯例处置不太奏效的重要事件特别留意和关注。1 2 3 4 5 6\u003c/p>\u003c/li>\u003cli>\u003cp>我在回顾重要工作项目时，首先会考虑下当初做这个工作的目标。1 2 3 4 5 6\u003c/p>\u003c/li>\u003cli>\u003cp>我在反思重要工作时，总会对比最终结果与当初目标之间的差异。1 2 3 4 5 6\u003c/p>\u003c/li>\u003cli>\u003cp>在对比目标差异时，我总会分析过程中做得好的方面。1 2 3 4 5 6\u003c/p>\u003c/li>\u003cli>\u003cp>在对比目标差异时，我也会寻求过程中做得不足的地方。1 2 3 4 5 6\u003c/p>\u003c/li>\u003cli>\u003cp>我总会将反思过程中启发的经验及时记录下来，作为自己的努力方向。1 2 3 4 5 6\u003c/p>\u003c/li>\u003c/ol>\u003cp>【互动】我先来了解下，各位的得分情况如何？这组测试主要是考察大家平时进行重要工作复盘的方式。大家可以算一算自己的分数。有没有在30分以上的？哦，有伙伴30分以上，不错，那说明你的个人复盘做的还是不错的，有所章法。20分到30分的伙伴有么？也有，你还有提升努力的空间哦。低于20分的伙伴，不用说了今天你来对了，你可要认真注意下面环节了。苏格拉底曾经说过：“没有反思的人生不值得过”，而无效的反思不如没有反思。\u003c/p>\u003cp>好，接下来先用2分钟时间阅读我用荧光笔标注上下箭头的拆页部分，请完成的伙伴举手向我示意。\u003c/p>\u003cp>《复盘》P60-61\u003c/p>\u003cp>柳总是怎样炼成的?\u003c/p>\u003cp>柳传志先生(我们很多人亲切地称呼他&quot;柳总&quot;)是我最为敬重的人之一。从和他的接触中，我们能感受到他的人格魅力和领导力。那么，柳总是否生而如此?他的领导力和人格魅力是如何获得或形成的呢?\u003c/p>\u003cp>在我看来，柳总应该具有极高的天赋，又有远大的目标、不断提高自己的追求，再加上极强的学习力，使其&quot;修炼&quot;成为伟大的企业家。在学习力方面，复盘是柳总总结发现的，也是其最主要的学习方式。\u003c/p>\u003cp>这样的例子有很多。其中一个例子是，在早期创业时，在他的小办公室里，一个上午接连有四五个人去找他说事情，经常是前面一个人还没把话讲完，就被后面的人打断了，看上去很忙。\u003c/p>\u003cp>可他晚上回去把整件事情重新想了一遍，认为自己这样的工作方法事倍功半，需要改进。同时，他还发现，大家和他讲的那些事与赚钱活命的事情都毫无关系。最后，他得出结论不能让下面的同事拽着走，自己首先要想明白到底要干什么，然后把事情分出轻重缓急。这个想的过程就是复盘，虽然那时候没有一个特定的名称，但它可以成为个人快速学习、提升能力的一种有效方法。\u003c/p>\u003cp>同时，柳总从这次复盘中也产生了设立一个协助总裁进行战略策划、推进和监督的机构的想法，为此，他设立了“企划办”，对于公司的规范化运作与管理也起到了积极作用。\u003c/p>\u003cp>事实上，柳总一直保持着复盘的习惯，他在接受记者采访时表示：“我平常习惯每隔一个月左右，静下心来花5天左右的时间，把近来做的事情捋一遍，写写东西。”\u003c/p>\u003cp>此外，柳总在联想内部大力倡导复盘，并使其成为企业的文化。这也是联想之所以有很强的组织学习力，可以应对一个又一个挑战的重要原因。\u003c/p>","explains":"\u003cp>【互动】好，先问下各位读完刚才这段拆页，你获得的关键词或信息有哪些？\u003c/p>\u003cp>好，先问下各位读完刚才这段拆页，你获得的关键词或信息有哪些？\u003c/p>\u003cp>学习者：把事情分出轻重缓急。\u003c/p>\u003cp>学习者：提升能力、快速学习。\u003c/p>\u003cp>拆书家：什么是复盘呢？\u003c/p>\u003cp>学习者：经验总结，反思思考。\u003c/p>\u003cp>拆书家：复盘其实是指从过去的经验、实际工作中进行学习，帮助管理者有效地总结经验，提升能力，实现绩效的改善。\u003c/p>\u003cp>拆书家：那我问下大家，把一项完成的重要工作从头到尾做了什么想一遍是不是复盘？\u003c/p>\u003cp>学习者：不是。\u003c/p>\u003cp>拆书家：把重要工作从头到尾做了什么写下来，哪里好，哪里不好，如何改进，是不是复盘？\u003c/p>\u003cp>学习者：不是。\u003c/p>\u003cp>拆书家：把重要工作思考下当初期望做到什么程度，目前又做好了什么程度，之间差异时什么？哪里存在亮点或不足，导致的关键因素是什么，是不是复盘？\u003c/p>\u003cp>学习者：是。\u003c/p>\u003cp>拆书家：那么这里我们认为的是和不是复盘，关键差异是什么呢？对，只有进行对比目标、发现过程的优缺点、总结经验这些必要的步骤才算是复盘。\u003c/p>\u003cp>【WHAT】孔子曾将人区分为四类生而知之，学而知之，困而知之，困而不知。虽然我们不能排除成功人士或伟人生来就具有某些基因或特质的可能性，但不容怀疑的是，他们都经历了大量艰苦的磨炼，加上他们有很强的学习力，使得自己可以不断提升和自我超越。而对于这种学习力，最多、最主要的体现形式就是结构化的个人复盘。\u003c/p>\u003cp>【WHY】试想一下，如果我们能够把自己的每一个重要任务都变成学习机会，从中学习、促进自己能力提升，那会是怎样一种状况?事实上，按照学习发展领域公认的“70:20:10”人才培养法则,成人学习最重要的来源是在岗工作实践(约占70%)，其次是与他人的交流(约占20%)，正式的培训与教育只占很小的比例(10%)。而复盘作为一种从工作经验中学习的方法，无疑对于成人学习具有重要意义。\u003c/p>\u003cp>【HOW】那么重要工作的复盘要如何做呢？我们通过以下四个步骤来把握。\u003c/p>\u003col>\u003cli>\u003cp>回顾目标：复盘始于对预期目标的回顾，就像是一个原点。首先回顾做这项工作最初的目标，当时计划做到什么程度。\u003c/p>\u003c/li>\u003cli>\u003cp>评估结果：在目标明确的基础上，评价最终获得了什么结果，做到了什么样的程度。将实际过程和事实结果进行还原。以上两步是复盘的基础。\u003c/p>\u003c/li>\u003cli>\u003cp>分析原因：分析目标和结果存在差距的原因，寻找导致成功或失败的根本原因，并分析关键的因素。成功了，多想想客观因素；失败了，多找找主观原因。\u003c/p>\u003c/li>\u003cli>\u003cp>总结经验：将客观因素和主观原因进行经验萃取，总结经验教训，并将其付诸后续的改进行动，这是复盘的最重要的步骤。\u003c/p>\u003cp>【预防性异议及适用范围】好了，步骤讲完了，回顾目标、评价结果、分析原因和总结经验。有人会问这样做是不是太麻烦了，是否所有的问题都需要这么复盘呢？当然不是，首先不是所有的问题都需要复盘，所以我们今天也是讲的重要工作的复盘。其次不是每个复盘都必须按部就班，只要能最终萃取经验即可。例如，今天组织完一次月度总结会后，你可以复盘一下会议的过程和结果，以便下一次组织能更有成效。\u003c/p>\u003c/li>\u003c/ol>\u003cp>【举例子】我再举一个实际的例子帮助大家理解。我们单位处理完成每次劳动争议后，都会做一次复盘。最近是一次员工的工亡事件。首先回顾目标，我们当时目标是帮助客户梳理处理思路，劳资双方明确处理时限平稳局面，正常获得保险理赔。评价结果，通过部署和策略性沟通，局面获得控制，理赔材料获取，认定成功，基本实现当初目标。虽然过程周期较长，最终理赔顺利。分析原因：亮点，案发第一时间到达客户现场主导工作处理，组成临时工作小组加强沟通，快速反应与工伤认定、保险公司的衔接，材料要求明确，这些确保了该工作目标的顺利实现。不足，经办人保障意识不足；减少立场不确定的人员沟通。这些过程也导致了过程中产生了一些波折。总结经验：1.得到信息快速响应，现场沟通，明确时态状况；2.同时进行上下游资源互通；3.团队沟通，稳定沟通团队，每次与家属接触前提前做好团队准备。4.形成明确的工亡处理程序。\u003c/p>","interaction":"\u003cp>拆书家提问设计（逐字稿）：好，接下来我想让大家分组来做一个演练如何给重要工作做复盘。最近公司里组织了一次员工家属的亲子旅游活动，由行政部门进行主导，活动完成后行政部经理王经理主持与伙伴们一起复盘这次活动。王经理通过复盘的四个层问题向伙伴们提出问题，大家纷纷贡献智慧，总结经验。时间5分钟，然后我们请几个伙伴来扮演一下他们的具体场景，现在开始。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>王经理：上周末，我们组织了员工亲子旅游活动圆满结束了，我们来把这个活动来总结一下。我想问一下我们。当初我们搞这个活动设定的目标是什么？\u003c/p>\u003cp>组员A：增进员工间关系，相互了解各自家庭情况，链接与自己子女的关心和感情，至少确保有12组家庭出席。\u003c/p>\u003cp>王经理：那我们觉得这个目标达成了没有？\u003c/p>\u003cp>组员A：还不错。孩子热与参与，认识了很多同事的孩子。\u003c/p>\u003cp>王经理：我们当时计划了多少对家庭报名？\u003c/p>\u003cp>组员A：12对。\u003c/p>\u003cp>王经理：实际多少对参加了呢？\u003c/p>\u003cp>组员A：实际有16对家庭。\u003c/p>\u003cp>王经理：那已经远远超出了我们的目标。那在这个活动当中，我们有什么亮点吗？\u003c/p>\u003cp>组员A：准备充分：地点提前踩点，器材准备充分，包括食材帐篷；关心关怀：每个家庭人员的身体状况；破冰游戏：让大家融入氛围，大家感觉很好。另外活动中有礼物赠送，让同事和家庭更愿意参加这样的活动。\u003c/p>\u003cp>王经理：虽然这次活动办得很成功，但是我们哪些地方可以让下次办得更完美，有没有？\u003c/p>\u003cp>组员A：比如说统一的服装：能让大家看起来更加亲近，整体感觉也不同。更有创意的分组：除了小家庭外，下次我们还可以搞一些大家庭。在参与者的具体需求方面做出更加深入的调查和准备。\u003c/p>\u003cp>王经理：那我们邀请这个员工把这些内容做一个报告，记录下来，下次我们再举办类似的活动时就有经验可循了。\u003c/p>\u003cp>组员B：好的。我立马总结下来并作为活动经验总结。\u003c/p>\u003cp>【号召鼓掌】好，非常感谢大家，感谢自己。\u003c/p>\u003cp>【A2催化应用】好，今天我们学习了运用四步法进行个人复盘，使其成为个人快速学习，能力提升的有效方法。为了巩固所学的内容，最后布置一个作业，明天正好是周末，回顾下这周的工作和生活，与家人、同事或朋友进行一次简单的四步法复盘，请大家完成后将内容发送给我。\u003c/p>\u003cp>【结束语】好，今天我的分享就到此，最后总结一下复盘四步法，回顾目标、评价结果、分析原因和总结经验。希望大家能熟练掌握，提升自我能力。以上就是我的TF3-2的分享。感谢大家的参与。\u003c/p>\u003cp>学习者案例：\u003c/p>\u003cp>学习者A：儿童教育中心工作坊活动\u003c/p>\u003cp>回顾目标：1.帮助培训中心共识工作目标；2.普及促动技术和方法；3.培训方法和工具的练习。\u003c/p>\u003cp>评价结果：1.目标共识的程度存在一定差距；2充分让客户体会到了促动的活力；3.进一步对促动技术进行练习。\u003c/p>\u003cp>分析原因：亮点，根据客户要求及时找出目标点；迅速完成课件逻辑清晰；控场应变。不足：人员变动预估；会谈时间控制不足。\u003c/p>\u003cp>总结经验：时间控制需要更加精细化控制；开场时间需要提前至少1个小时到场。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1548429446000,"updated_at":1548429446000,"ria":true},{"id":6757,"topic":"总结常常写，复盘时时念。 --  但你真的懂什么是复盘吗？","learn_goal":"学习者学习后，可以运用复盘的方式，进行总结","remark":"","level":"TF3-1","duration":30,"status":29,"type":0,"chaishujia":{"username":"佳山","city":"厦门"},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好！我是佳山。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>\u003cp>【事件】我们都听过这样一句话，“人，不应在同一个地方摔倒两次。”可我们却总忍不住在同一个地方要摔倒三次、四次。\u003c/p>\u003cp>【提问】如果这个摔倒是在工作中发生的，那将意味着什么呢？\u003c/p>\u003cp>【影响】那将意味着，同是工作十年，别人拥有了十年的经验，而你却是一个经验用了十年，没有成长。\u003c/p>\u003cp>【解决】怎么解决这种情况，让自己能够真正成长呢？今天我讲和大家一起学习的这本《复盘+：把经验转化为能力》一书，就是教我们如何对过去的成败进行结构化总结，快速学习与成长，应对复杂多变的商业环境挑战。\u003c/p>\u003cp>【学习目标】今天我们将学习书中的一个片段，来了解什么复盘，以及如何复盘。通过今天的学习，大家能够使用（行为）复盘技术解决工作和生活中遇到的需要改进（界定）的问题。\u003c/p>\u003c/p>","ratings_count":1,"texts":[{"id":10107,"quote":"\u003cp>\u003cstrong>什么是复盘\u003c/strong>\u003c/p>\u003cp>“复盘”原是围棋术语，本意是对弈者下完一盘棋之后， 重新在棋盘上把对弈过程摆一遍， 看看哪些地方下得好，哪些下得不好，哪些地方可以有不同甚至是更好的下法等。\u003c/p>\u003cp>这个把对弈过程还原并且进行研讨、分析的过程，就是复盘。通过复盘，棋手们可以看到全局以及整个对弈过程，了解棋局的演变，总结出适合自己和不同对手的套路，或找到更好的下法，从而实现自己棋力的提升。\u003c/p>\u003cp>用到企业管理中，复盘是指从过去的经验、实际工作中进行学习，帮助管理者有效地总结经验，提升能力，实现绩效的改善。正如联想集团创始人柳传志先生所说:所谓复盘，就是一件事情做完了以后，做成功了，或者没做成功，尤其是没做成功的，坐下来把当时的这个事情，我们预先怎么定的、中间出了什么问题、为什么做不到，把这个过程要理一遍，理一遍之后，下次再做的时候，自然这次的经验教训就吸收了。&nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","explains":"\u003cp>【强化讲解概念的能力】\u003c/p>\u003cp>我们这个时代是一个时不时会创造些新概念的时代，比如新零售、降维打击、场景、以及今天我们要学习的“复盘”。\u003c/p>\u003cp>那什么是复盘呢？所谓“名正则言顺，言顺则事成。”只有正本清源搞清楚什么是复盘，我们才能正确使用复盘。这个片段给出了复盘的来源——来自围棋，其本意是对弈者下完一盘棋之后， 重新在棋盘上把对弈过程摆一遍， 看看哪些地方下得好，哪些下得不好，哪些地方可以有不同甚至是更好的下法等。\u003c/p>\u003cp>我们通过几个例子来理解下复盘的概念。\u003c/p>\u003cp>“我昨天的表现太差了，下次我要改进表现好些。”这是复盘吗？这不是。因为复盘的定义中强调要“重新在棋盘上把对弈过程摆一遍”，这是一个回顾事实还原过去的过程，回顾当初我们的期望标准是什么，回顾过程中发生了什么。而这句话只是对过去的一个简单的评价——“表现太差”，没有还原原先的事实和过程。另外复盘的定义中还有“看看哪些地方下得好，哪些地方下得不好”的这么一个比较分析，而这个日常的总结里也没有我差在哪儿了？没有和标准对比，我差在哪儿了的这个分析差异的过程。所以他不是复盘。\u003c/p>\u003cp>那有了回顾事实和差异分析这两步以后呢？我们接着看。\u003c/p>\u003cp>玩过80分，或看别人玩80的人都知道，在一把结束之后，总有一个人会说他的对家，“刚才我出什么什么的时候，你应该出什么什么，这样他就大不过你了。。。。。”嗯，别人帮你还原了事实，比较了差异，还交给你怎么做。这下总该是复盘了吧！\u003c/p>\u003cp>还不是！因为这虽然是别人帮你回顾和分析，但缺少了你反思自我的过程。为什么在这个点我应该出那张牌？为什么在这个点我要大过他让自己一方抢先机？反思是为了探寻背后的规律，而把握规律才是你成长提升的阶梯。而且在这么短的时间内，我们谁又能get到那么多点呢？这是复盘的第三个步骤。\u003c/p>\u003cp>那什么是真正的复盘呢？我们再回到复盘的来源，下棋的例子中。\u003c/p>\u003cp>一盘棋局结束后，为了提升对弈者的棋力，他们将对弈的过程在棋盘上重新摆了一遍，这是回顾。二人在重新摆的过程中，对每一步进行了说明讲解，为什么你的白子放这里，我的黑子摆那边，这是分析。摆这里是为了在后面的落子中能封点挤拆逼？还是为了碰压接扳刺？这是反思。经过这样的过程，最终让自己在下一次的对弈中能够提升自己的棋力，取得胜利。这样才是一个完整的、闭环的复盘过程。熟悉拆书帮RIA阅读法的朋友也都知道，A2环节就是要将你的所学应用在今后的生活和工作中，真正实现学以致用。这也是我们复盘的意义之所在。\u003c/p>\u003cp>【HOW】\u003c/p>\u003cp>通过刚才对复盘概念的讲解，我们得出了复盘的四个步骤：\u003c/p>\u003cp>1、回顾\u003c/p>\u003cp>2、分析\u003c/p>\u003cp>3、反思\u003c/p>\u003cp>4、提升\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>同时也发现，复盘这个办法，是一套系统严谨的方法，他需要时间去研究、探讨、打磨。所以当我们遇到一些没有成功的、重大的、经常发生的事情，只要时间充裕，又十分必要时，那都可以尝试运用复盘来帮助自己进步、成长。而那些不经常发生的事，也无伤大雅的事，就没必要费那个精力了。\u003c/p>\u003cp>举一个我自己的例子，那是发生在去年，我的工作岗位刚发生变化的时候。\u003c/p>\u003cp>从人力资源岗位转到了市场营销的岗位，一时有些不适应。具体体现在哪儿呢？体现在指标意识上。因为指标意识的缺乏，导致我去年的工作很盲目、疲惫，不得章法，最后的指标也差强人意。\u003c/p>\u003cp>于是今年初，公司领导组织对去年四季度的营销活动进行复盘。\u003c/p>\u003cp>首先，回顾。当时我的指标跟的很辛苦，季度的总指标有，每天的销量有，然后要把每天的销量和之前的销量进行相加，然后再和目标值相减看缺口差多少。。。。。\u003c/p>\u003cp>其次，分析。这个跟踪指标的方式劳动量很大，每天都在做重复的事情，很浪费时间和经历。其他人的指标好像没有我跟的这么辛苦。\u003c/p>\u003cp>第三，反思。有没有更好的方法呢？有！把总目标分解成月目标、周目标、日目标。这样每天的销量和日目标相比，就知道能不能完成了！\u003c/p>\u003cp>第四，提升。在今年一季度的工作中，我将我负责的指标进行了分解，一直分解到最小的颗粒度，日目标。\u003c/p>\u003cp>结果我的工作果然神清气爽，让我每天只工作3小时。\u003c/p>","interaction":"\u003cp>下面，我们通过分组讨论的方式做个案例来实际演练下复盘的方法。以我左手边为一组，右手边为另一组。\u003c/p>\u003cp>双十一刚过，双十二又接踵而至。不知道大家在今年的双十一剁手是否愉快？有没有什么糟心的经历？\u003c/p>\u003cp>年年双十一，你是否总是在剁手这件事情上犯相同的错误？你是否对自己的购物行为后悔总结过？\u003c/p>\u003cp>请大家结合在今天所学的知识，按下面的表格要求，编写一个剧本，要设计出一个包含人物角色、有起因经过结果对话的故事，复盘你的双十一。\u003c/p>\u003cp>给大家5分钟的时间讨论，然后我们请一个小组来和大家分享。\u003c/p>\u003cul>\u003cli>\u003cp>剪切\u003c/p>\u003c/li>\u003cli>\u003cp>复制\u003c/p>\u003c/li>\u003cli>\u003cp>粘贴\u003c/p>\u003cp>请使用 Ctrl+V 粘贴\u003c/p>\u003c/li>\u003cli>\u003c/li>\u003cli>\u003cp>向上插入 1 行\u003c/p>\u003c/li>\u003cli>\u003cp>向下插入 1 行\u003c/p>\u003c/li>\u003cli>\u003cp>向左插入 1 列\u003c/p>\u003c/li>\u003cli>\u003cp>向右插入 1 列\u003c/p>\u003c/li>\u003cli>\u003c/li>\u003cli>\u003cp>插入超链接\u003c/p>\u003c/li>\u003cli>\u003c/li>\u003cli>\u003cp>合并单元格\u003c/p>\u003c/li>\u003cli>\u003cp>取消合并单元格\u003c/p>\u003c/li>\u003cli>\u003c/li>\u003cli>\u003cp>删除列\u003c/p>\u003c/li>\u003cli>\u003cp>删除行\u003c/p>\u003c/li>\u003cli>\u003cp>删除表格\u003c/p>\u003c/li>\u003c/ul>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>项目\u003c/p>\u003c/td>\u003ctd>\u003cp>内容\u003c/p>\u003c/td>\u003ctd>\u003cp>备注\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>事件内容\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>介绍背景、时间、地点、人物关系、人物的内心想法、点睛评语等\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>人物角色\u003c/p>\u003c/td>\u003ctd>\u003cp>角色A：\u003c/p>\u003cp>角色B：\u003c/p>\u003c/td>\u003ctd>\u003cp>多角色可自行补充\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>对白\u003c/p>\u003c/td>\u003ctd>\u003cp>角色A： \u003c/p>\u003cp>角色B： \u003c/p>\u003cp>角色A： \u003c/p>\u003cp>角色B： \u003c/p>\u003cp>角色A： \u003c/p>\u003cp>角色B： \u003c/p>\u003cp>角色A：&nbsp; \u003c/p>\u003cp>角色B： \u003c/p>\u003cp>角色A： \u003c/p>\u003cp>角色B： \u003c/p>\u003cp>角色A： \u003c/p>\u003cp>角色B： \u003c/p>\u003cp>角色A：&nbsp; \u003c/p>\u003cp>角色B：\u003c/p>\u003c/td>\u003ctd>\u003cp>对话内容要体现以下步骤：\u003c/p>\u003cp>1、回顾\u003c/p>\u003cp>2、分析 \u003c/p>\u003cp>3、反思 \u003c/p>\u003cp>4、提升\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>学员佳音的分享\u003c/p>\u003cul>\u003cli>\u003cp>剪切\u003c/p>\u003c/li>\u003cli>\u003cp>复制\u003c/p>\u003c/li>\u003cli>\u003cp>粘贴\u003c/p>\u003cp>请使用 Ctrl+V 粘贴\u003c/p>\u003c/li>\u003cli>\u003c/li>\u003cli>\u003cp>向上插入 1 行\u003c/p>\u003c/li>\u003cli>\u003cp>向下插入 1 行\u003c/p>\u003c/li>\u003cli>\u003cp>向左插入 1 列\u003c/p>\u003c/li>\u003cli>\u003cp>向右插入 1 列\u003c/p>\u003c/li>\u003cli>\u003c/li>\u003cli>\u003cp>插入超链接\u003c/p>\u003c/li>\u003cli>\u003c/li>\u003cli>\u003cp>合并单元格\u003c/p>\u003c/li>\u003cli>\u003cp>取消合并单元格\u003c/p>\u003c/li>\u003cli>\u003c/li>\u003cli>\u003cp>删除列\u003c/p>\u003c/li>\u003cli>\u003cp>删除行\u003c/p>\u003c/li>\u003cli>\u003cp>删除表格\u003c/p>\u003c/li>\u003c/ul>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>项目\u003c/p>\u003c/td>\u003ctd>\u003cp>内容\u003c/p>\u003c/td>\u003ctd>\u003cp>备注\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>事件内容\u003c/p>\u003c/td>\u003ctd>\u003cp>买到了用不着的东西\u003c/p>\u003c/td>\u003ctd>\u003cp>介绍背景、时间、地点、人物关系、人物的内心想法、点睛评语等\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>人物角色\u003c/p>\u003c/td>\u003ctd>\u003cp>角色A：同事\u003c/p>\u003cp>角色B：佳音\u003c/p>\u003c/td>\u003ctd>\u003cp>多角色可自行补充\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>对白\u003c/p>\u003c/td>\u003ctd>\u003cp>角色A： 今年双十一又买了一堆用不到的东西。\u003c/p>\u003cp>角色B： 为什么呢？怎么会买用不到的东西呢？\u003c/p>\u003cp>角色A：【回顾】先前手里抢了一堆券，后面又是满减，又为了凑单。不知不觉买了很多用不到的东西。\u003c/p>\u003cp>角色B： 那你想买的东西买到了吗？\u003c/p>\u003cp>角色A： 有的买到了，有的没买到。\u003c/p>\u003cp>角色B： 没买到的是什么原因呢？\u003c/p>\u003cp>角色A：&nbsp;【分析】 还不是为了凑单，各种选，等再选其他的东西时候，有的已经没货了。\u003c/p>\u003cp>角色B：那是本来目标定的要买ABC，结果买了ADE，目标从买ABC变成了更便宜地买A？\u003c/p>\u003cp>角色A：是这样的。 \u003c/p>\u003cp>角色B：那最后算下来A买便宜了吗？\u003c/p>\u003cp>角色A： 【反思】也没有啊！这样看买A也不划算，还搭了用不着的DE。\u003c/p>\u003cp>角色B：那有没有办法让自己的目标锁定呢？ \u003c/p>\u003cp>角色A：【反思】其实想想吧，活动内容一开始已经公布了，我只要列好清单，盯住ABC，买回来。反正价格已经比平时便宜了，不能一味地追求更便宜，差不多就可以了。太贪心反而不划算。\u003c/p>\u003cp>角色B：嗯，那双十二你还淘吗？\u003c/p>\u003cp>角色A：淘啊！把没买的BC捞回来。\u003c/p>\u003cp>角色B：那你打算再怎么折腾？\u003c/p>\u003cp>角色A：【提升】先了解活动内容，看双十二是怎么个玩法。然后列好自己要买的东西，锁定目标，不为其他诱惑所困。最后在0点赶紧下手！\u003c/p>\u003c/td>\u003ctd>\u003cp>对话内容要体现以下步骤：\u003c/p>\u003cp>1、回顾\u003c/p>\u003cp>2、分析 \u003c/p>\u003cp>3、反思 \u003c/p>\u003cp>4、提升\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>非常感谢佳音的分享，刚才佳音结合同事的经历复盘了双十一的购物经历。帮同事回顾了当时购买的过程，准备的一堆券；分析了因为凑单，错失自己想买的东西；而后反思发现要锚定自己的购物目标，不能太贪，结果买了一堆没用的东西。最后在接下来的双十二中提升措施是列好购物清单，不为其他货品所动。非常感谢佳音。\u003c/p>\u003cp>【Ending结尾】\u003cbr>\u003c/p>\u003cp>\u003cp>古人说，知其然知其所以然。我们常常在念叨着复盘，但我们真的会复盘吗？今天我们重新认识了复盘，学习了复盘，希望对大家能够真正掌握复盘。\u003c/p>\u003cp>我是拆书家，我是崔俊峰。\u003c/p>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1544679881000,"updated_at":1544679974000,"ria":true},{"id":6746,"topic":"如何养成复盘的习惯","learn_goal":"2-3过级","remark":"大家知道复盘，但怎么真正将复盘形成习惯，本片段将分享养成复盘习惯的四个步骤给大家。","level":"TF2-2","duration":25,"status":29,"type":0,"chaishujia":{"username":"韩晓东","city":"邯郸"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>技能点要求：设定学习目标，学习目标包含学习者可被观察到/测量到的行为或动作，现场学习者设计清晰体现了该学习目标。\u003c/strong>\u003c/p>\u003cp>【开场】不破不能立，不拆不成器！拆书帮把知识拆成你的能力！大家好，我是来自成语之乡邯郸的韩晓东。我是一名注册建造师，喜欢阅读和跑步。希望能和各位小伙伴在拆书帮共同学习进步，成为终身学习的三级拆书家。感谢各位参加今天的拆书练习。\r\n接下来我给大家分个组……（根据现场人数，两人一组或三人一组）。\u003c/p>\u003cp>【目标】在跟随我完成本次RIA现场学习后，教你如何养成复盘的习惯。\r\n &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>\u003cstrong>技能点要求：介绍图书FAB，清晰辨别出F、A、B\u003c/strong>\u003c/p>\u003cp>我今天要拆解的片段来自《复盘+：把经验转化为能力（第2版）》一书。\u003c/p>\u003cp>【F特征】《复盘+》的作者是邱昭良，这是一本系统阐述复盘方法并教我们如何使用复盘的工具性书籍。这本书从上市以来受到市场广泛欢迎，同时，也有很多企业邀请作者进行培训或分享。目前本书在豆瓣上的评分为6.0。&nbsp;\u003c/p>\u003cp>【A优势】本书与其他实用类图书的不同点在于，它把中国围棋复盘的理念运用到企业的日常管理中，把复盘与个人、团队和企业紧密结合。通过复盘，让大家在很短的时间里，从行动中去学习，没有长篇大论，而是与工作紧密相关，让这种学习非常“接地气”。\u003c/p>\u003cp>【B1利益】你是否也在学习与工作的过程中，就某些方面一而再的反复掉进同一个坑里，本书将告诉我们通过复盘可以在经历中总结经验，把经验转化为做事的能力，避免再犯同样的错误，为以后做事节省时间和精力。&nbsp;\u003c/p>\u003cp>【B2利益】人类的很多行为靠的是习惯，如果能够让复盘成为个人和组织的习惯，复盘就会发挥更大的价值，本拆页将教给你如何养成复盘的习惯。\u003c/p>\u003cp>接下来就让我们进入今天的拆书学习，请大家用2分钟时间学习一下原文。\u003c/p>","ratings_count":2,"texts":[{"id":10120,"quote":"\u003cp>\u003cstrong>技能点要求：所选拆页包括HOW的内容，且总内容未超过2页图书内页\u003c/strong>\u003c/p>\u003cp>\u003cstrong>(1)\u003c/strong>\u003cstrong>通过一些做法，创造出一些“暗示”\u003c/strong>\u003c/p>\u003cp>比如，在你的日历或工作安排中事先列上“复盘”的时间；通过手机或邮件订阅有关复盘的动态；在公司例会上，经常进行或提示复盘等。\u003c/p>\u003cp>\u003cstrong>(2)\u003c/strong>\u003cstrong>强化对复盘的“奖赏”\u003c/strong>\u003c/p>\u003cp>比如，上级领导和组织的认可；在公司网站、知识管理系统里建立复盘专栏，定期刊登各单位的复盘成果，并对优秀复盘给予奖励等。\u003c/p>\u003cp>在这里特别想指出的是，要强化“奖赏”，就要“玩真的”，让复盘真正起作用，而且轻松、简单、好玩，千万不要搞得很复杂或成为负担，或者只是“走走形式”“自己骗自己”，更不要让大家觉得会受到批评，会让自己很难堪。如果是这样的话，从复盘中获得的，就不是“奖赏”，而是痛苦了。那样的话，复盘就很难成为人们的习惯。\u003c/p>\u003cp>\u003cstrong>(3)\u003c/strong>\u003cstrong>将“奖赏”与“内心”渴求联系起来\u003c/strong>\u003c/p>\u003cp>长期来看，要将从复盘中获得的“奖赏”与每个人内心深处隐藏着的对学习与成长的“渴求”联系起来，让大家看到:复盘有助于个人学习与成长；复盘可以帮助个人和团队更好地完成工作；复盘简单而有效。\u003c/p>\u003cp>尽管人们本能地害怕或倾向于回避错误，但一方面，无论在东方还是西方文化中，都存在“从失败中学习”的信念，让大家接受并树立这样的观念，有助于消除对失败或错误的“恐惧”；另一方面，用学习与成长产生的“正能量”来抵消这些本能上的“不适”。\u003c/p>\u003cp>\u003cstrong>(4)\u003c/strong>\u003cstrong>充分利用团队的力量\u003c/strong>\u003c/p>\u003cp>如上所述，复盘从本质上是一个团队学习的过程，不仅在复盘过程中要鼓励团队的参与，在组织层面上，也要成立复盘实践小组，定期组织复盘学习、复盘分享会以及交流使用复盘的经验和心得。\u003c/p>\u003cp>此外，公司还可以对各级干部和骨干进行复盘方法论和复盘引导技术的培训，为大家创造共同的理解、共同的经历和共同语言，有助于建立集体信念，让复盘更容易地变成习惯。\u003c/p>","explains":"\u003cp>\u003cstrong>新技能：【I】拆书家讲解引导，给出比原书拆页更加细化的行动步骤，或者将书中的案例进行了意译\u003c/strong>\u003c/p>\u003cp>【what】随着环境日趋多变、不确定、复杂、模糊，无论是个人还是组织，都需要更快更有效地进行创新应变、提升能力。复盘作为一种从经验中学习的结构化方法，满足了快速学习的需求，也是有效进行知识萃取与共享的机制。因此，将复盘习惯化，将会使个人和组织得到更快的成长，这个拆页将教给我们怎样养成复盘的习惯。\u003c/p>\u003cp>【why】为什么养成复盘习惯这么重要？因为复盘可以让自己过去的经验和经历真正变成财富，变成不断提升能力的途径。某一次的复盘，可能解决了某一个问题，也只有将复盘养成了习惯，用无数个复盘反复打磨个人或级织，才能使其迭代成长，真正的实现能力的飞跃。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>\u003cstrong>第一步、提醒复盘。\u003c/strong>建立一个新的习惯总是很难的，因此一开始，我们要设置一个提醒，用来提醒自己记得复盘，比如把“行动后做复盘”作为一条任务列入自己的计划方案中去，并且留下足够的时间。或者明确规定在一周的某一天的某一个时段进行复盘，在一件事情结束后进行复盘，在周例会上进行复盘，在活动场所的醒目位置张贴复盘提醒牌等等。\u003c/p>\u003cp>\u003cstrong>第二步、给于“奖赏”。\u003c/strong>每次完成复盘任务以后，都梳理一下自己因为复盘得到了什么好处，强化自己的认知。比如进行了一次深度的反思，形成了一个规律的文档，或者规避了以后再也不会掉下的“坑”。如果自己领导一个团队，并且想要鼓励团队进行复盘，不妨把复盘行为以及成果纳入绩效考核范围。这样，我们可以真真切切看到或者感受到复盘带来的好处。\u003c/p>\u003cp>\u003cstrong>第三步、集思广益。\u003c/strong>对于项目、大型活动来说，都是团队作业的，所以，复盘就是一个团队集体学习、集体获得收获的过程。我们可以充分调用团队的力量进行复盘，组织大家一起进行反思，总结行动的亮点和不足，提取可重复的经验和规律，并采取组织手段进行推广，带动大家一起养成复盘好习惯。\u003c/p>\u003cp>\u003cstrong>第四步、复盘清单。\u003c/strong>将经验和规律总结成具体的行动步骤和清单，无论是对个人还是组织，人人清楚的清单式复盘更具操作性，清单化的复盘也更容易形成习惯。\u003c/p>\u003cp>通过以上步骤，我们就能从心里感受到复盘对我们带来的改变，并养成复盘的习惯。\u003c/p>\u003cp>【where】复盘不但适用于个人，也适用于多人的团队组织。\u003c/p>\u003cp>举例：上个月，我们单位的行政办公室主任由于家里有特殊情况休假一个月，于是由副主任来责任办公室的全面工作，碰巧的是在上个月来了两拨上级集团的检查，第一拨检查是上月第二周的星期一，办公室的小李将领导的桌牌顺序放置错了，事后的第二天，我到行政办公室想就出现差错的问题给他们提个醒，当我走进他们的办公室时，看到他们正在开会，对昨天的接待工作进行总结和复盘，我还看到他们在墙上挂了一块牌子，上面写着“今天你复盘了吗“？办公室副主任小黄对我说，我们做这个牌子是为了提醒他们自己工作后记的要复盘。（\u003cstrong>第一步、提醒复盘）\u003c/strong>小黄继续说到他们还决定，从这个月开始，行政办公室的每个人复盘数和复盘质量与自己的绩效奖金挂钩，\u003cstrong>（第二步、给于“奖赏”）\u003c/strong>我说这个方法好，我也加入了他们的讨论，小李说昨天的桌牌放错，责任在他，他没有与对方仔细对接所来领导的职务，副主任小黄说自己也有责任，他没有提前到会议室检查一遍。大家集思广益的进行了讨论，小宋就他负责的汇报材料书写如何提高质量进行了总结复盘，小李就他负责的欢迎词和桌牌工作进行了复盘，小赵讲了如何为大家做好会场服务。\u003cstrong>\u003cstrong>\u003cstrong>（第三步、集思广益）\u003c/strong>\u003c/strong>\u003c/strong>最后我提议大家应该将这次讨论的如何做好接待的复盘，形成一个复盘清单，大家讨论的具体接待清单如下：\u003c/p>\u003cp>一是由小宋在24小时间前完成汇报材料的书写，并经单位领导同意。\u003c/p>\u003cp>二是由小李在18小时间前与来人沟通，根据来的领导职务及检查内容确定摆放桌牌顺序，前提前20分钟摆好桌牌，副主任小黄提前10分钟检查确认。\u003c/p>\u003cp>三是小赵提前1小时打好大门口屏幕欢迎词。\u003c/p>\u003cp>四是副主任小黄提前10分钟通知单位领导到大门口迎接来客。\u003c/p>\u003cp>五是小赵负责端茶倒水及会场相关工作。\u003c/p>\u003cp>六是副主任小黄通知单位领导欢送来客及善后工作。\u003c/p>\u003cp>七是副主任小黄带领办公室成员对本次接待工作进行复盘。\u003cstrong>（第四步、复盘清单）\u003c/strong>\u003c/p>\u003cp>由于复盘工作做得好，五天后，另一拔领导来检查时，行政办公室的接待工作就非常完美。\u003c/p>","interaction":"\u003cp>\u003cstrong>【技能点要求1：】给出了一个非常具体、确定场景，学习者可以在此场景中演练、讨论或应用新学技能\u003c/strong>\u003c/p>\u003cp>我们刚刚学习了怎样养成复盘的习惯，那现在请大家一起编排一个演练。我先给大家设定一个演练的场景：我们就以现在筹备邯郸拆书帮为例吧，现在我们处于拆书帮的筹备价段，我观察到我们大部分活动结束后还没有养成复盘的习惯，特别是在活动的组织上，如活动的发布、场地的确定、过级组织、实录提交等等方面。这不利于邯郸拆书帮活动整体水平的提高。我们今天学习了如何养成复盘的习惯后，应用所学的这四个步骤进行排练，根据我们今天来的小伙伴的人数，分为一个组，小组内自行商定谁扮演代舵主，谁扮演代组织长老，谁扮演代教育长老，其它的人统称为团队成员。通过今天的演练，最后形成一个清单式的复盘，使我们分舵在今后的活动后形成复盘的习惯。\u003c/p>\u003cp>\u003cstrong>【技能点要求2：】使用【A3】技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，进行小组讨论、应用知识点并能形成一个解决方案，或者应用知识点进行组内角色扮演\u003c/strong>\u003c/p>\u003cp>以上是我设定的一个场景，下面给大家5分钟时间进行排练。\u003c/p>\u003cp>现在排练结束，演练正式开始。时间为5分钟。\u003c/p>\u003cp>学习者演练记录：\u003c/p>\u003cp>代舵主（刘犇）：我们邯郸筹备拆书帮刚成立，在活动组织上还不规范，这不利于我们活动整体水平的提高，学了今天的拆页后，我们讨论一下，如何使我们邯郸筹备拆书帮在活动组织上形成复盘的习惯。\u003c/p>\u003cp>代组织长老（常乐）：对，我提议做一个提醒牌，写上&quot;复盘&quot;两个字，挂在我们定点活动的墙上，并且在每次活动最后预留20分钟时间用于活动组织的复盘。（\u003cstrong>第一步、提醒复盘）\u003c/strong>\u003c/p>\u003cp>成员一（丽珍）：每次活动复盘后，评选一位复盘之星，表扬复盘工作做的好的成员，如提出好的活动建议，积极主动复盘等，将复盘之星的姓名记录在活动原始记录本的备注里。\u003cstrong>（第二步、给于“奖赏”）\u003c/strong>\u003c/p>\u003cp>代教育长老（敏聪）：好的复盘离不开大家的集思广议，每位成员都有责任建言献策，特别是舵主及几位长老，就分管的工作定时按要求做好，如过级后的小伙伴，我要求三天内将实录和录音传给我，我负责上传等。\u003cstrong>（第三步、集思广益）\u003c/strong>\u003c/p>\u003cp>代舵主（刘犇）：大家说的都非常好，如果我们将活动形成一个复盘清单，那我们在复盘的过程中是不是就不会漏项，而且更容易形成复盘的习惯呢，我总结了大家今天的发言，初形成了以下一个清单，我们在以后的活动中逐渐完善和补充。\u003c/p>\u003cp>一是确定过级活动的时间及地点，如我们的活动时间是每周五晚上6:30-9:30，地点是中煤活动室。\u003c/p>\u003cp>二是升级打怪的不伙伴在周一上午12:00前用微信给师父发送升级打怪“逐字稿”，在升级打怪活动前通过师父的审核。\u003c/p>\u003cp>三是周一下午5:00前，过级的小伙伴用微信向代组织长老发送你升级打怪的说明，主要有拆书主题、拆解图书、拆书简介、拆书家介绍、挑战级别、拆书时长。以方便发布活动通知。\u003c/p>\u003cp>四是拆书活动中的自我介绍、录音、大声墙、点评等要做好。&nbsp;\u003c/p>\u003cp>五是拆书活动后用20分钟对上次活动结束后到本次活动结束前的组织活动进行复盘。\u003c/p>\u003cp>六是升级打怪的小伙伴向代教育长老提交录音和实录，由代教育长老上传。\u003cstrong>（第四步、复盘清单）\u003cbr>\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1544581233000,"updated_at":1546614281000,"ria":true},{"id":6417,"topic":"复盘+把经验转化为能力","learn_goal":"如何使用5Why分析法","remark":"大家好，我是周凯，本次拆TF1-2，今天给大家拆的书是《复盘+把经验转化为能力》，这本书是邱昭良博士的著作，大家知道复盘最早起源于美军作战行动后的反思AAR，再从军方应用转移到企业应用，而国内最早推广复盘是联想创始人的柳传志发起的，因为有效而且好用，最后被大家争先效仿，希望通过本次的拆书分享，能给大家带来收获。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"周凯","city":"武汉"},"club":{"name":"武汉古琴台分舵","city":"武汉"},"prologue":"\u003cp>【分组】\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;为了更好地激活大家分享自己的A1经验和A2应用，我将根据现场人数进行分组，现场人数除我以外有5人，本次观察家涂大侠不参与，其余4人我们2人为一组，待会我将给大家时间进行交流探讨。\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 大家好，我是周凯，本次拆TF1-2，今天给大家拆的书是《复盘+把经验转化为能力》，这本书是邱昭良博士的著作，大家知道复盘最早起源于美军作战行动后的反思AAR，再从军方应用转移到企业应用，而国内最早推广复盘是联想创始人的柳传志发起的，因为有效而且好用，最后被大家争先效仿，希望通过本次的拆书分享，能给大家带来收获。&nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":9720,"quote":null,"explains":"\u003cp>\u003cstrong>【I\u003c/strong>\u003cstrong>拆书家讲解引导】\u003c/strong>\u003c/p>\u003cp>现在我们进入I部分(拆书家讲解引导) 。\u003c/p>\u003cp>这是一篇关于如何使用5Why分析法的案例分享，所谓5why分析法，又称5问法，就是对一个问题连续以5个为什么来提问，最后找到其根本原因。\u003c/p>\u003cp>拆页中向我们分享了3个步骤，第1步提出第1个为什么，第2步依次追问为什么，第3步对问题进行整合。5Why法原则上是5个为什么连续提问，但实际运用中，如果2个或3个为什么就已经能够找到问题的真因，就没必要纠结和死搬硬套了。\u003c/p>\u003cp>我们看到，在拆页案例中，也向我们举例介绍了车间主任看到地上有一摊油，而一旁的顾问运用5Why法提问的全部过程，通过递进式的5Why提问法，透过现象看本质，最终找到问题的真正原因。\u003c/p>\u003cp>这种手法很常见，也非常适用于我们在日常生活及工作中去运用它。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1\u003c/strong>\u003cstrong>激活经验】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计:\u003c/strong>\u003c/p>\u003cp>现在我们进入A1部分(激活经验)。\u003c/p>\u003cp>今天我给大家分享的是关于5Why分析法中的1个知识点，我们通过WhyWhy分析得出的事实，正向推演逻辑合理，循序渐进，反向推演也一样。\u003c/p>\u003cp>接下来我们以小组为单位，我给每个小组发一张针对本次拆书制作的拆书练习表，我在该表中已经列举了5Why法的运用框架。\u003c/p>\u003cp>大家可以看到，上半部分写的是拆页内容。下半部分是我预留给大家做A1部分激活经验用的，大家可以联想自己过往的经历和相关事件，看看有哪些是与5Why分析法类似的，大家将拆书练习表作为参考，回想和激活自己的过往经验，重点是通过WhyWhy分析得出的事实，正向反向推演都逻辑合理，循序渐进。\u003c/p>\u003cp>我给大家5min时间激活经验，然后请1个小组选派1名代表给大家作过往类似经验的分享。\u003c/p>\u003cp>\u003cstrong>学习者案例记录:\u003c/strong>\u003c/p>\u003cp>第二小组学员展开A1激活经验的分享：\u003c/p>\u003cp>我曾经在工作中发生了一件类似的事情，关于一位同事在办公室走道处滑倒的事例：\u003c/p>\u003cp>第1个Why：为什么会滑倒？\u003c/p>\u003cp>回答：因为地面上有一滩水。\u003c/p>\u003cp>第2个Why：为什么地面上有一滩水？\u003c/p>\u003cp>回答：因为柜子上的绿植盆的水流到地面上了。\u003c/p>\u003cp>第3个Why：为什么绿植盆的水会流到地面上？\u003c/p>\u003cp>回答：因为员工和绿植维护人员都在重复浇水。\u003c/p>\u003cp>第4个Why：为什么重复浇水？\u003c/p>\u003cp>回答：因为没有明确规定维护要求和指定人员。\u003c/p>\u003cp>通过4个Why的提问与回答，找到了真正原因，而这4个Why之间，无论正向或反向推演都逻辑合理。这就是我在A1激活经验部分，结合过往经历所想到的一个事例。\u003c/p>\u003cp>\u003cstrong>【A2\u003c/strong>\u003cstrong>催化应用】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计:\u003c/strong>\u003c/p>\u003cp>现在我们进入A2部分(催化应用)。\u003c/p>\u003cp>请大家根据今天拆页的内容，考虑今后如何在工作与生活中合理的运用5Why分析法，尤其是正反向推演的逻辑递进式。\u003c/p>\u003cp>请大家列举一个与自己工作或生活相关的主题，将它先写在纸上，要有明确时限，有可衡量或可观测的预期结果。由于时间关系，我们只请1位伙伴向大家作简要分享。\u003c/p>\u003cp>拆书结束后，希望大家今后多加练习，灵活运用，真正做到为我所用。今天的TF1-2拆书分享到此已全部完成，感谢大家的支持与配合，谢谢大家！\u003c/p>\u003cp>\u003cstrong>学习者案例记录:\u003c/strong>\u003c/p>\u003cp>第一小组学员展开A2催化应用的分享：\u003c/p>\u003cp>下月初（12月5日）部门会议时，针对染厂的负责人不配合工厂评估的问题，利用5Why分析手法，结合管理实际，持续发问调查原因，特别关注提问后回答的事实，正向反向推演是否逻辑合理，最终找到其根本原因解决问题。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1541726734000,"updated_at":1541737244000},{"id":6188,"topic":"关于复盘的那些事儿","learn_goal":"能够区分总结和复盘，并学会有效复盘的四个步骤。","remark":"","level":"TF3-3","duration":60,"status":29,"type":0,"chaishujia":{"username":"华思语","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"【自我介绍】大家好，我是华思语，大家可以叫我华华。我先用三个标签介绍一下我自己，我是一名认证的项目管理专家、一名阅读写作践行者、也是一名二级拆书家。今天我要跟大家分享的是《复盘+：把经验转化为能力（第2版）》这本书中的内容。\r\n【场景法介绍】 \r\n【事件】我有一位同事，他是做产品销售的。有一次，他在客户那里吃了闭门羹之后，拍着自己的脑袋懊悔的说，以前我曾犯过这样的错误，今天为什么又犯了同样的错误呢？\r\n【提问】不知道大家有没有过类似的经验？犯过的错误还会再犯。\r\n【影响】其实我们犯错并不可怕，可怕的是不能从错误中汲取教训，不能吃一堑长一智。若不能及时发现错误和偏差，从错误中学到经验教训并纠正，我们就很可能会掉进同样的坑，多走很多弯路，这不仅会耗费我们的时间和精力，还会阻碍我们的个人成长。\r\n【解决】试想一下，如果我们都能够把自己的每一段工作或生活经历中，面临的每一项任务、每一次挑战都变成学习的机会，促进自己能力的提升，那会是怎样一种状况呢？今天我要跟大家分享的《复盘+》这本书中的关于复盘的内容，就会告诉我们该如何把自己的经验进行提炼和梳理，用于今后类似的场景中，让我们犯过的错误不会再犯。\r\n接下来，我先跟大家分一下组，因为一会儿会进行分组讨论。\r\n请大家用2分钟左右的时间阅读我刚刚发给大家的原文片段中的片段1，看的过程中大家可以留意一下原文中讲了哪两个概念，看完之后可以举手示意一下。","ratings_count":2,"texts":[{"id":9461,"quote":"\u003cp>\u003cstrong>片段一：《复盘+把经验转化为能力》P7\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我们都知道，总结是对一定时期的工作或某个事件的梳理、汇报，每个人依自己的习惯和悟性，对已经发生的事件、行为及结果进行回顾、描述，通常并没有固定的模板和结构，并不必然包括对目标与事实差异原因的分析，以及经验总结等要素。但复盘具有明确的结构与要素，必须遵从特定的步骤进行操作，不仅回顾目标与事实，也要对差异的原因进行分析，得出经验与教训，这样才能算是一次完整的复盘。\u003c/strong>\u003c/p>","explains":"\u003cp>【I】我看小伙伴们都已经看完了，我想先问问大家原文中讲了哪两个概念呢？（总结和复盘）对了，【学习目标】希望我们一起完成这个片段的学习后，【可观察到的动作】大家在进行工作或者生活回顾的时候，都能够从看时间和看导向两个方面进行比较，有效地区分总结和复盘，以后不再错误地把总结当成复盘，而是能够学会通过复盘来提升自己的能力。\u003c/p>\u003cp>【类似概念】所谓总结，就是对一定时期已经发生的事件、行为和结果进行回顾和描述，我想大家都很熟悉，请问大家平时都有做过什么总结呢？（工作总结）对，像工作中的日报、周报、年度总结都属于总结，强调对过去的事情进行回顾。【概念提出】片段中提到的核心概念是复盘，复盘是围棋中的一种学习方法，指的是在下完一盘棋之后，再重新摆一遍，看看哪里下得好，哪里下得不好，对下得好和不好的，都要进行分析和推演。复盘强调的是通过经验学习，从而指导我们未来的行动。\u003c/p>\u003cp>【例子】我想问一下大家一个项目做完了之后，你跟领导汇报项目的完成情况，这是属于复盘还是总结？（是总结）对，这是总结，因为是对过去事情的回顾。那做完一个项目之后，召集项目组成员一起分析项目的成败，形成公司案例库，这是属于复盘还是总结？（是复盘）对，这是复盘，因为形成案例库注重的是指导未来的行动。一次旅程回来，我对旅行过程中花费的所有费用进行了汇总，这是总结还是复盘？（总结）对，这是总结，因为这注重的是得到总费用这个结果。我有一次坐了2站地铁，钱包被偷了，后来回想自己做地铁的整个过程，发现了两个失误点，一是在买票的时候拿出了钱包，二是把背包背在了后面，之后我就决定以后要提前准备好零钱，在公共场合要把包背在前面，这是复盘还是总结？（复盘）对，这是复盘，因为我学习到了经验教训。\u003c/p>\u003cp>【概念步骤how】通过刚刚对概念的讲解和举例，我想大家都对总结和复盘有了更清晰的认识。总结一下，我们可以从看时间和看导向两个方面来区分复盘和总结。\u003c/p>\u003cp>第一是看时间，对总结来说，只会简单的回顾目标、分析过程、得出结论，就像我们说的年度工作总结，整个总结过程都是围绕着过去进行的，所以总结更注重过去。而复盘呢，在头脑中重新过一遍已经发生的事情，过程中会反思为什么这么走，有没有更好的方法？同时深入思考未来要怎么走，从而少走弯路，就像我刚刚举例说我钱包被偷后都会注意在公共场合把包背在前面，所以复盘的过程更关注未来。\u003c/p>\u003cp>第二是看导向，总结更加重视目标有没有达成，任务有没有完成，就像销售的年度业绩汇报，在总结的过程中可能会有奖励或者惩罚，比如对销售业绩好的同事进行表彰，所以总结是以结果为导向的。而复盘在还原整个事情的过程中，是秉承中立态度的，不批评不表扬，更关注从中得到经验教训，从而为未来所用，所以复盘是以学习为导向的。\u003c/p>\u003cp>【预防异议】可能有些小伙伴会问我们能不能对别人的事情进行复盘呢？复盘的本质其实是每个人从自己的亲身实践中进行总结学习，所以我们不能对他人的事件进行复盘，对他人的事件进行回顾分析并从中学习，这叫做“案例研究”。\u003c/p>\u003cp>也可能有的小伙伴会说复盘多浪费时间，还不如继续做事呢。如果复盘仅仅是吐槽、后悔，没有对原因进行深入分析，也不会落实到之后的行动，那么复盘就是浪费时间。复盘最重要的是要有行动计划。想想未来我们遇到同类的事情，不会再犯同样的错误了，该节省多少我们为错误买单的时间！\u003c/p>\u003cp>【适用边界】其实总结很适合在一些严肃的汇报场合使用，简单明了地回顾过去做了什么事情，让他人知道你过去的成果。而复盘适合在一些重要的事情发生后对事情进行还原，让自己能从经验中学习，从错误中改进，从而得到成长。\u003c/p>","interaction":"\u003cp>【A2】我们拆书帮有一个理念就是“教是最好的学”，接下来请大家规划在未来的一周内可能会发生的一个小故事。比如你跟朋友分享复盘是什么，跟项目组的同事讲解复盘的特点，也可以和老板建议在公司践行复盘……，让身边的小伙伴也懂得复盘的概念，让他们复盘的时候也能够绕过总结的坑。大家能想到什么场景呢？\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>邱姐：上周公司完成了一个接待任务，想建议同事们一起复盘一下。\u003c/p>\u003cp>那现在就请大家根据自己想到的场景，编一个小故事，故事中要包含人物、情节和对话，并在对话中解释清楚复盘的特点。大家可以在片段一下面写下你的故事，5分钟后我会请小伙伴来分享一下你的故事，在写的过程中有什么问题可以随时交流。\u003c/p>\u003cp>有哪位小伙伴愿意分享一下吗？\u003c/p>\u003cp>【学习者分享】邱姐：\u003c/p>\u003cp>\u003cstrong>故事背景（时间、地点）：\u003c/strong>明天在公司办公室\u003c/p>\u003cp>\u003cstrong>人物：\u003c/strong>我们办公室的所有同事\u003c/p>\u003cp>\u003cstrong>故事内容（事件经过）：\u003c/strong>我们办公室上周准备了一个非常重大的接待，来的领导的级别也比较高，由于任务非常临时，大家在接待的过程中进行的准备有点手忙脚乱，虽然完成了任务，但是我觉得并不理想，就想明天组织同事们一起在公司进行一次复盘。\u003c/p>\u003cp>\u003cstrong>对话设计：\u003c/strong>\u003c/p>\u003cp>我：我们今天对上周准备的接待任务进行一下复盘吧。\u003c/p>\u003cp>同事：（有些小伙伴很茫然）是不是就是对这件事情进行总结？\u003c/p>\u003cp>我：要总结，但不仅仅是总结，我们要回顾一下接待的整个过程，同时对过程中的漏洞和状况进行分析，下次遇到类似的情况我们该如何改进。\u003c/p>\u003cp>同事：这就是复盘啊？不仅仅是总结，同时还要对过程中的状况进行分析，而且应用到未来的改善提高，是这个意思吗？\u003c/p>\u003cp>我：是的。\u003c/p>\u003cp>\u003cstrong>故事的结果：\u003c/strong>大家知道了复盘的概念，开始共同对问题进行探讨，分析遇到类似的情况该如何处理，最后给出了备选方案，供下次接待时参考使用。\u003c/p>\u003cp>【拆书家反馈】非常好，谢谢邱姐的分享。刚刚在分享的过程中邱姐完全讲清楚了复盘的概念，而且还区分了复盘和总结，这一点做得特别好，整个故事让人感觉非常的生动形象，再次谢谢邱姐的分享。\u003c/p>\u003cp>【两个片段的关系】刚刚我们一起区分了复盘和总结，现在我们来一起回顾一下：注重过去的是复盘还是总结？（总结）那注重未来的呢？（复盘）以结果为导向的是复盘还是总结？（总结）以学习为导向的呢？（复盘），我们知道了复盘能够帮助我们把经验化为能力，那么接下来我们一起来学习如何有效地进行复盘吧。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":9462,"quote":"\u003cp>\u003cstrong>片段二：《复盘+：把经验转化为能力（第2版）》P22-P23\u003c/strong>\u003c/p>\u003cp>\u003cstrong>联想认为，复盘可以用来考察一个人的学习能力，也是选拔干部的重要参考标准。正如联想集团创始人柳传志先生所说“复盘是联想认为最重要的一件事情。联想经常说，对人，用谁不用谁，就看他的学习能力怎么样。对于学习，我自己总结了一下，无非是跟书本学、跟自己学，还有一个就是跟别人做的事情学。最多、最深刻的还是跟自己学，跟自己学无非就是复盘’。一件事情做完了以后，做成功了或者没做成功，尤其是没做成功的，坐下来把当时的这个事情，我们预先怎么定的、中间出了什么问题、为什么做不到，理一遍，理一遍以后，下次再做的时候，自然这次的经验教训他就吸收了。”\u003c/strong>\u003c/p>","explains":"\u003cp>【学习目标】希望通过对第二个片段的学习，【可观察到的动作】大家都能够学会有效复盘的4步骤，能够通过回顾目标、评估结果、分析原因、总结经验四个步骤对你认为重要的事情进行复盘，用学到的经验教训来指导自己未来的行动，从而让自己不断得到成长。\u003c/p>\u003cp>【A1自测】\u003c/p>\u003cp>阅读片段二前，请大家先做一个简单的测试，看看现在的你是否有复盘的意识。这里一共有6道题目，请大家仔细阅读下面表格中的每句话，按照1~6的标准根据自己的实际情况给自己打分，1代表完全不符合，6代表完全符合。打完分后请大家汇总一下得分。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>【自测量表】\u003c/p>\u003cp>请你先做一个简单的测试，看看现在的你是否有复盘的意识。\u003c/p>\u003cp>以下共有6道题目，请按照1~6的标准根据自己的实际情况给自己打分。（1~6分，1分表示非常不符合，6分表示非常符合）\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>1.做完一件事后，我会对当初的目标进行回顾。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2.事情完成后，我会思考哪些地方做得好、哪些地方做得不好。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3.犯错误后，我会思考自己为什么会犯错。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4.预期的目标没有完成，我会分析没有完成的原因。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5.一件事情没有达到预期，我会从中总结经验教训。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>6.我从不犯同样的错误。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>总分\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>【自测量表-量表解释】我看小伙伴们都做完了，我们先一起来看看大家的答题情况吧。请问有没有总分在30分以上的小伙伴？那有没有总分在12分以下的小伙伴呢？如果你的总分在30分-36分，说明你平时就有复盘的意识，可以看看今天的学习能不能给你带来新的启发；如果你的总分在12分-30分之间，说明你有部分复盘意识，但是并不熟练，希望今天学习的有效复盘的步骤能够帮助你更好地从自己的经验中进行学习; 如果你的总分在6分-12分之间，相对来说，你的复盘意识相对较弱，相信我们今天学习的复盘方法一定会对你有所帮助。\u003c/p>\u003cp>接下来， 就请大家花2分钟左右的时间阅读我刚刚发给大家的原文片段二，看完之后可以举手示意一下。\u003c/p>\u003cp>I【互动】我看大部分小伙伴都已经看完了。大家都很清楚，这段话是在讲什么的重要性？（复盘）前面我们已经讲了复盘的概念，而在这个片段中，主要讲了我们为什么要进行复盘，就是跟自己学的情况更多，同时也更深刻。\u003c/p>\u003cp>关于跟自己学的情况更多，培训界曾把成人学习分成在岗的工作实践、与他人交流和正式的教育培训三种，请大家猜猜哪种学习最多？（在岗的工作实践）对了，这部分占到了70%，而与他人交流和正式的教育培训分别只占到了20%和10%，而从在岗的工作实践中学习无非就是复盘。\u003c/p>\u003cp>那为什么跟自己学会更深刻呢？（是因为自己亲身经历的事情会更有感触）。通过把经验或教训总结出来，不仅有助于自我能力的发展，而且还可以通过与团队成员进行共享，把个人的经验变成整个团队共同的智慧。所以复盘不仅适用于个人、也适用于整个团队。\u003c/p>\u003cp>那么我们到底该如何进行复盘呢？接下来我要跟大家介绍的就是有效复盘的四个步骤：“回评分总”，就是回顾目标、评估结果、分析原因、总结经验。\u003c/p>\u003cp>第一步“回顾目标”，这是复盘的开始，也就是问最开始的目标是什么？回顾目标能够让参与复盘的人心中有数，知道要讨论什么。有一个简单有效的方法是把目标清晰明确地写出来，比如写在白板上，以防止复盘的过程中偏离目标。\u003c/p>\u003cp>第二步“评估结果”，明确了目标之后，就要还原事实，回顾实际发生了什么？与目标相比哪些地方做得好哪些做得不好？找到实际结果与期望目标之间的差距或者差异。\u003c/p>\u003cp>第三步“分析原因”，这是复盘的核心环节，找出结果和目标之间存在差异的根本原因。这时可以问为什么没有达成预期的目标？若是团队参与，那每个人分析的角度也会不一样，分析得也会更加透彻。\u003c/p>\u003cp>第四步“总结经验”，这是复盘最重要的一步，核心目的是从行动中学到经验教训，并将其付诸后续的改进，这时候可以问我们从过程中学到了什么新的东西？接下来我们该做些什么？要知道想让复盘真正起作用就必须落实到具体的行动计划，并执行到位。\u003c/p>\u003cp>举个例子：这个月初的时候，我负责的一个安全产品上线之后，就组织项目组的小伙伴一起进行了一次复盘。首先我们回顾了目标，目标是产品在9月1日前上线，并交付用户使用，这在项目开始前我就已经发邮件同步过，所以大家对目标是有共识的。接下来，我们评估了结果，对从项目开始到结束的整个过程进行了回顾，发现我们做得不好的第一点是很多页面没有特别设计初始页，第二点是很多小问题没有进行全面测试，做得好的点是在规定的时间产品完成了上线，基本业务流程能够走通。第三步，分析原因，为什么会出现上面的问题呢？通过分析我们得出第一个原因是产品交互设计得不够细致，没有考虑全各种可能性，第二个原因是测试没有完整的测试用例，在时间紧的情况下只顾及了大的业务流程。第四步，总结经验，我们觉得在以后做所有的项目时，在产品交互方面，不仅要考虑常规状态，还要考虑初始状态；在测试开始前，要准备好完整的测试用例，研发完成后通过邮件发送测试用例让公司同事一起来参与测试，提高产品的稳定性。我们把这两项加入到了项目工作规范中。\u003c/p>","interaction":"\u003cp>【A3】微行动学习\u003c/p>\u003cp>好了，我们再来一起回顾一下复盘的四个步骤，分别是？（回顾目标、评估结果、分析原因、总结经验）我想问问大家：在这四个步骤中，大家有没有哪个知识点不太理解、或者觉得操作起来有难度的？\u003c/p>\u003cp>【伙伴提问】\u003c/p>\u003cp>舒畅：分析原因有难度\u003c/p>\u003cp>木子：回顾目标有难度\u003c/p>\u003cp>【提问式反馈与回应】好的，我看小伙伴们有不同的答案，但是我们今天的时间有限，我们对这四个步骤投一下票，我们就对票数最高的那个步骤进行分析好不好？\u003c/p>\u003cp>【伙伴确认】好的。\u003c/p>\u003cp>【提问式反馈与回应】第一个回顾目标，大家觉得有困难的请举一下手，一共有2票；大家觉得评估结果有困难的请举手，1票；大家觉得分析原因有困难的请举手，一共有4票；大家觉得总结经验有困难的请举手，没有。\u003c/p>\u003cp>【伙伴确认】原因出来了，那结果也就出来了啊。\u003c/p>\u003cp>【提问式反馈与回应】是的，从刚刚大家的投票结果来看，觉得分析原因有困难的小伙伴会多一些，那我们就一起来看看为什么大家会觉得分析原因有问题？难度在哪里呢？大家都可以说一下。\u003c/p>\u003cp>【伙伴确认】\u003c/p>\u003cp>康康：可能会不客观，看不到本质。\u003c/p>\u003cp>丹燕：还有一个原因是可能会被人带偏了。\u003c/p>\u003cp>舒畅：还有就是可能我的是对的，但是由于某些权威不敢认为这是真正的原因。\u003c/p>\u003cp>邱姐：自己能力受限，看不到问题的本质。\u003c/p>\u003cp>丹燕：原因太多了，抓不到主要原因。\u003c/p>\u003cp>豆子：还有可能是原因总是它、老是它、一直是它。\u003c/p>\u003cp>【提问式反馈与回应】刚刚大家讲了几个原因，这里面不客观、被人带偏、能力受限我们把它们归为一类，属于需要提高能力层面，大家觉得可以吗？\u003c/p>\u003cp>【伙伴确认】可以。\u003c/p>\u003cp>【提问式反馈与回应】抓不住主要原因属于一个类别，屈于权威也属于一个类别，还有总是这个原因的话很可能是第四步总结经验时，落实到后面的行动计划上有问题，我们聚焦于分析原因，暂时不讨论这个问题可以吗？\u003c/p>\u003cp>【伙伴确认】可以。\u003c/p>\u003cp>【提问式反馈与回应】好的。由于我们现在只有10多分钟的时间，我们只能解决一个问题，大家觉得需要提高能力、抓不住主要原因、屈于权威这三个问题中，哪个比较好在现场解决？\u003c/p>\u003cp>【伙伴确认】抓不住主要原因吧。\u003c/p>\u003cp>豆子：屈于权威可能要调认知。\u003c/p>\u003cp>舒畅：调认知也是一种方法，但是好难调啊。能力也不是短时间能够提高的。\u003c/p>\u003cp>【提问式反馈与回应】好的。屈于权威我们10多分钟解决不了，能力问题也不是短时间内能够提高的，那我们就一起来解决“分析原因”中的这个小问题“抓不住主要原因”好不好？\u003c/p>\u003cp>【伙伴确认】可以。\u003c/p>\u003cp>【引导分组讨论问题本质】关于抓不住主要原因，大家觉得这个问题的本质是什么？就是我们为什么会抓不住主要原因呢？\u003c/p>\u003cp>【伙伴确认】\u003c/p>\u003cp>兰兰：不是抓不到，是不想承认，无法接受失败的自己。\u003c/p>\u003cp>木子：找不到突破口，没有经验在前面，不能从关键事项进行分析。\u003c/p>\u003cp>【明确问题本质】从大家的分享来看，抓不住主要原因的本质是不知道怎么找整个事情的关键点，找到这个关键点，主要原因也找到了，大家认同吗？\u003c/p>\u003cp>【伙伴确认】认同。\u003c/p>\u003cp>【引导分组讨论解决方案】那么接下来，请大家在小组内进行分组讨论，在进行复盘的时候，我们该如何找到复盘的这件事的关键点？给大家5分钟的时间，大家可以把小组讨论的结果写在白纸上。\u003c/p>\u003cp>（小组讨论）\u003c/p>\u003cp>时间差不多了，我们每个小组都各自分享一下自己小组的解决方案好不好？从这边的第一组开始。\u003c/p>\u003cp>【伙伴分享】\u003c/p>\u003cp>第一组：\u003c/p>\u003cp>康康：我们是两条思路走，一个是从流程化方面去分析，从主观原因和客观原因出发去找到关键点。第二个是操作者，也就是执行的人层面，去找到那个关键的人。\u003c/p>\u003cp>第二组：\u003c/p>\u003cp>丹燕：我们这组有两点，第一点是如果我们找到了很多原因，可能所有的原因都能达到目标，我们认为最短最快最省力的原因，这就是最关键的原因。这个可以通过数值进行评定，若没有办法用数值，我们可以从他人的经验、或者团队的经验方面来入手。我们第二点也是细分项目，找细分项目的负责人。\u003c/p>\u003cp>第三组：\u003c/p>\u003cp>兰兰：我们是从事件这个方向进行梳理的。首先我们会把影响目标达成的所有的关键事项全部罗列出来，接下来我们就会清理这些影响目标达成的事项都有没有完成，完成的放在一边，然后找出没有完成的事件，接着对这些事件进行分析，给出相应的权重，通过权重分析来找出这个目标没有达成的关键点是在哪里。\u003c/p>\u003cp>【拆书家反馈】谢谢大家的分享。大家给出的解决方案都很赞，我把刚刚大家讲的再归纳一下，刚刚提到把所有的关键事件都列出来，也就是对目标进行分解，界定清楚目标后，我们再界定关键的流程和关键的人物，从中挑出那些没有完成的，再针对这个没有完成的环节进行权重分析。\u003c/p>\u003cp>所以我理解的我们在目标清晰的基础上，第一步是确定清晰的流程和关键的人物，第二步是在这个基础上进行权重的分析，综合权重高的就是关键点，大家觉得这样可以吗？\u003c/p>\u003cp>【伙伴确认】可以。很清晰。这样很明确。\u003c/p>\u003cp>【拆书家反馈】好的。我们刚刚就一起解决了分析原因中的抓不住主要原因时我们该怎么办这个问题，那就是去找关键点，接着我们也一起给出了如何找关键点的解决方案。因为今天的时间有限，我们对这个问题的讨论就到这里，一会我分享完后，若还有时间大家还可以一起讨论别的难点。\u003c/p>\u003cp>【A2】刚刚我们一起学习了有效复盘的4个步骤，下面我要给小伙伴们布置一个家庭作业了。\u003c/p>\u003cp>【特定任务】在接下来的一周内，请大家选择一件你自己做过的、你觉得重要的一件事情进行复盘。比如你制定的减肥目标没有完成，工作中的项目刚刚结束，或者是你和家人因为某件事情吵架了……大家有想到合适的场景吗？\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>丹燕：我上次拆书没有通过，我想进行一次系统的复盘。\u003c/p>\u003cp>兰兰：我相对上个月的工作招商任务完成情况进行一次复盘。\u003c/p>\u003cp>谢谢小伙伴的分享。请大家回去后根据自己选择的经历过的这件事情，应用我们今天学习的回顾目标、评估结果、分析原因和总结经验四个步骤进行复盘。复盘之后，欢迎本周分享到我们的爱好者群里，提交作业的小伙伴我会给她发红包哦。\u003c/p>\u003cp>【强有力的总结】\u003c/p>\u003cp>在今天将近一个小时的时间里，我们区分了复盘和总结，知道了总结更注重过去，是以结果为导向的，而复盘更关注未来，是以学习为导向的，因此复盘更能够让我们真正地“吃一堑长一智”。\u003c/p>\u003cp>接下来我们学习了有效复盘的四个步骤“回评分总”，大家还记得吗？就是回顾目标、评估结果、分析原因和总结经验，其中最重要的是从经验中学习，指导下一次的行动。所以，复盘绝对不是一次性偶尔为之的事件，而是要把复盘培养成习惯，不断地迭代优化自己。曾子说的“吾日三省吾身”也是这个道理，期待我们一起通过复盘成为更好的自己。\u003c/p>\u003cp>我今天的分享就到这里，谢谢大家。\u003c/p>\u003cp>【学习者案例分享】\u003c/p>\u003cp>丹燕：我对上次拆书没有通过进行了一次复盘。\u003c/p>\u003cp>第一步回顾目标，我的目标是1-2顺利过级；\u003c/p>\u003cp>第二步评估结果，同一个片段拆解了3次，3次都没有通过，第一次是超时，第二次是A2没有完成且超时，第三次是A2指向不清且超时；\u003c/p>\u003cp>第三步分析原因，主要是以下4个原因导致我没有过级：\u003c/p>\u003cp>01 控场能力有限导致超时\u003c/p>\u003cp>02 I的讲解偏长导致超时\u003c/p>\u003cp>03 A2没有清晰的步骤造成学习者不理解\u003c/p>\u003cp>第四步是总结经验，通过分析原因，在之后的拆书过程中我会在以下几个方面进行改进：\u003c/p>\u003cp>01 时刻注意自己的目标，把控好每一个部分的时间，学习者分享超时后要有礼貌地打断，引导学习者等拆书完后再进行分享。\u003c/p>\u003cp>02 尽量选择步骤清晰、好落地的片段，举例子的时候要接地气，用大家觉得通俗易懂的案例讲解，这样I会更容易在短时间内讲清楚。\u003c/p>\u003cp>03 A2强调的是未来的应用，规划未来应用的时候与步骤要一一对应，方便学习者进行理解，同时也能对学习步骤再次进行回顾。\u003c/p>\u003cp>【拆书家反馈】谢谢丹燕的分享。在分享中，丹燕用到了进行有效复盘的四个步骤，分析出了自己没有顺利过级的原因，并总结出了经验，制定了非常切实可行的行动步骤，思路非常清晰，相信通过改进，丹燕在以后的拆书路上一定会越走越顺利。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}}],"created_at":1538960927000,"updated_at":1538960927000,"ria":true},{"id":4858,"topic":"学习还原事实，锻炼批判性思考的的能力。","learn_goal":"应用还原事实的方法，能立刻对过往的经验做出反思和应用的修正","remark":"","level":"TF2-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"佳山","city":"厦门"},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;【学习主题】学习还原事实，锻炼批判性思考的的能力。\r\n【学习目标】学习者在完成本次拆书学习之后，在遇到需要进行重大判断和回顾总结时，能采用还原事实的三个步骤进行反思，不急于做出判断、不盲从。\r\n &nbsp; &nbsp; &nbsp;Hello，大家好！\r\n &nbsp; &nbsp; &nbsp;我是佳山，这是我的微信昵称。\r\n &nbsp; &nbsp; &nbsp;今天我们的学习内容会涉及到讨论，所以我们先分下组。我们两两分为一组，最右手边的这三位伙伴分为一组。\r\n【开场】 &nbsp; &nbsp; &nbsp;有一本书叫做《你以为你以为的就是你以为的吗》，是一本检测思维清晰度逻辑的书。这本书的背景是说大部分的人类总是相信自己所以为的那个样子，所以这本书的书名是以反问的形式来吸引读者眼球的。\r\n &nbsp; &nbsp; &nbsp; &nbsp;人类之所以会相信自己以为的那个样子，主要是源于主客观两个因素：主观是选择性相信，即我只相信我愿意相信的那个“事实”；客观是别人想让你相信的那个“事实”。这二者的共通点只有一个——事实。那什么是事实呢？\u003c/p>","ratings_count":1,"texts":[{"id":7917,"quote":"\u003cp>【F】有一本书叫做《你以为你以为的就是你以为的吗》，是一本检测思维清晰度逻辑的书。这本书的背景是说大部分的人类总是相信自己所以为的那个样子，所以这本书的书名是以反问的形式来吸引读者眼球的。\u003c/p>\u003cp>人类之所以会相信自己以为的那个样子，主要是源于主客观两个因素：主观是选择性相信，即我只相信我愿意相信的那个“事实”；客观是别人想让你相信的那个“事实”。这二者的共通点只有一个——事实。那什么是事实呢？\u003c/p>\u003cp>【A】今天我想和大家分享的拆页并不来自于《你以为...》这本书，而是由机械工业出版社出版，邱昭良博士著述的《复盘+：把经验转化为能力》。\u003c/p>\u003cp>作者邱昭良，是管理学博士，在组织发展领域，也就是现在人力资源领域很火的OD，淫浸多年。并在联想集团的多个部门工作过，并为数百家企事业单位提供过组织学习和知识管理等方面的咨询和培训工作。有着深厚的理论功底和丰富的企业运作与管理实务经验。\u003c/p>\u003cp>【B】这本书通过联想、万达、美军、英国石油等公司的实际案例，介绍了引导复盘的工作指引与常用方法、工具与模板，是应用复盘的专业、深入而全面的操作指南，可供个人、管理者与企业家对过去的成败进行结构总结，快速学习与成长，将个人的经验转化为能力，应对复杂多变的商业环境挑战。\u003c/p>","explains":"\u003cp>片段中描述了评估结果重要的一步。\u003c/p>\u003cp>【what】还原事实。那什么是还原事实？顾名思义，就是回顾之前发生了什么？\u003c/p>\u003cp>这个定义很简单，以致简单到我们经常忽略了还原事实，把我们看到的、或脑子里想起来的过去简单地当做了事实。简单讲，就是“我以为的就是我以为的。”但这么做其实是有着很大的危害性的。\u003c/p>\u003cp>【how】那么该如何还原事实呢？书中为我们总结了三个步骤：\u003c/p>\u003cp>1、实际上发生了什么事——这是我们在还原事实的过程中的首要反映，也是我们习惯于认为的“事实”。\u003c/p>\u003cp>但在还原事实的过程中，最关键也最容易被忽略的是下面两步：\u003c/p>\u003cp>2、是在什么情况下发生的——任何事情的产生过程都是有他的背景和前提条件的，我们可以称之为“适用边界”，离开这个环境，可能相同的事情经过，但结果会截然不同，即便是相同的经过和结果，给人们带来的认知也会不同。\u003c/p>\u003cp>3、是怎么发生的——细节决定成败。在还原事实的过程中，每个场景、画面，他是怎么发生的？是哪些环节、细节催生了这个结果的产生。这对于还原事实本身是很重要的。\u003c/p>\u003cp>【不这样做的坏处】接下来，我们通过一个例子来看下如果我们不这样“繁琐”地还原事实的话，会发生什么。我们一起来看下这幅图：\u003c/p>\u003cp>当我第一次看到新闻里的这张图时，配上新闻有图有真相的宣传报道，着实让我相信了美军在中东地区的残暴。但没多久，我在网上又看到了下面这张揭秘照时，我整个人是惊呆的，我觉得，我的智商被侮辱了。一图怎么可以两吃呢？这边来一刀，你就是残暴的；这边来一刀，你就是仁义的。截屏要有用，那还要真相干嘛呢？\u003c/p>\u003cp>宣传，是为了让你知道或相信他想让你知道或相信的，有图也不一定就会有真相，你以为的，也不一定就真是你以为的。所以我们一定要有质疑和批判的精神去思考。\u003c/p>\u003cp>“出离愤怒”之后，我们冷静地想想，为什么我们这么容易被别人的“暗示”带走？如果下次回到再看到类似的新闻和图的时候，我不急着下结论，先了解发生了什么事？这个图是在什么背景下拍摄的？这些新闻和图背后的事情是怎么发生的？是抓拍还是摆拍？拍摄的时候周边发生着什么？有哪些细节导致发生了这个结果。综合所有的信息之后，我再来下结论，这样避免因为信息了解不充分，而匆忙的下结论。\u003c/p>\u003cp>【适用边界】还原事实很重要，是基于事实对我们的判断、认知很重要。当事情紧急，而结果的好坏又无伤大雅的时候，存下这份还原事实的心就好，就没有必要去按图索骥地还原事实了。\u003c/p>","interaction":"\u003cp>【显像提问】以上是和大家分享的按步骤还原事实的重要性。接下来请大家回想下，在你的生活中有无这样的经历或体验：\u003c/p>\u003cp>在那件事情发生时，你看到的情景令你感到十分地气愤、义愤填膺，想发脾气.....一场狂风暴雨之后，当你知道了事情的始末原委，又会感到十分地尴尬。\u003c/p>\u003cp>有没有这样的经历？可以是和同事间，或是和家人间的。请大家在小组内用一分钟的时间讨论分享下。\u003c/p>\u003cp>那么，有哪位伙伴愿意和我们分享自己的经历呢？\u003c/p>\u003cp>小红：以前和我的一个工作伙伴，头天晚上因为某件事我们之间有了分歧，彼此存在心结。第二天早晨他6点钟上班要刷门禁，门禁系统是归我管理的，但恰巧那天门禁系统坏了。因为头天有心结，第二天遇到这样的事，她就很生气，（可能认为是我故意搞鬼），于是和我大吵了一架。那我也很生气，也不想和他解释，也就吵了起来。后来她知道是门禁系统坏了的原因后，就很尴尬，和我道歉。\u003c/p>\u003cp>我：当时是她误会了你，对吗？\u003c/p>\u003cp>小红：对。\u003c/p>\u003cp>【反思加工】我：如果回到当时，你用这三步骤的话，你会怎么做？\u003c/p>\u003cp>小红：我会站在她的角度去考虑，想下当时发生了什么？是在什么情况下发生的？用这个方法来反问下。\u003c/p>\u003cp>我：帮助她来理解下，这个门禁是为什么锁的？是什么原因锁的。\u003c/p>\u003cp>小红：是。\u003c/p>\u003cp>我：好的非常感谢。\u003c/p>\u003cp>好，这就是我们今天一起来学习的还原事实的三个步骤：\u003c/p>\u003cp>1、实际上发生了什么事\u003c/p>\u003cp>2、是在什么情况下发生的\u003c/p>\u003cp>3、是怎么发生的\u003c/p>\u003cp>通过学习，你是否掌握这三个步骤呢？是否开始不盲从，会批判性地思考了呢？\u003c/p>\u003cp>以上就是我今天和大家分享的复盘的定义。希望能对大家有所帮助。\u003c/p>\u003cp>我是拆书家，我是崔俊峰。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1521699931000,"updated_at":1526448688000,"ria":true},{"id":4490,"topic":"知识的融合，能力的迭代","learn_goal":"通过学习复盘和PDCA环的融合，在工作中掌握复盘","remark":"","level":"TF1-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"佳山","city":"厦门"},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"我是佳山，这是我的微信昵称。佳山这个词是我根据自己的姓氏拆解的，没想到和台湾的一个很有名的基地撞名了。于是就自我感觉这个名字也小有点名气的样子了。\r\n大家都能体会到，我们所处的这个时代是一个快节奏的时代。快到什么程度呢？快到我们可以用一个音来形容自己对这个时代的感受，那就是忙、盲、茫。这并不是重要的事情说三遍。第一个忙，忙碌的忙，是我们当下的普遍状态；第二个盲，盲目的盲，是我们接收到项目、任务后开始进入到工作的状态；第三个茫，迷茫的茫，是我们对自己的前景和方向的一种焦虑感受。因此，在我们厌倦了当下的工作想换个新工作时，总会面对这样的疑惑，我是一个有着十年经验的人？还是一个经验用了十年的人？\r\n 怎样解除这样的疑惑呢？这就是今天我要和大家来学习的这本书。\r\n 由机械工业出版社出版，邱昭良博士著述的《复盘+：把经验转化为能力》。\r\n 这本书的作者邱昭良，是管理学博士，在组织发展领域，也就是现在人力资源领域很火的OD，淫浸多年。并在联想集团的多个部门工作过，并为数百家企事业单位提供过组织学习和知识管理等方面的咨询和培训工作。有着深厚的理论功底和丰富的企业","ratings_count":1,"texts":[{"id":7503,"quote":null,"explains":"\u003cp>相信大家对计划、执行、检查、调整的PDCA闭环管理已经相当的熟稔了。那当复盘融入其中时，我们发现，原来PDCA环还可以这样滚动：\u003c/p>\u003cp>领导布置了一项工作后，我们会根据自己的认知水平和能力制定完成工作的行动计划，成为指导自己工作的路径图。但市场总是多变的，在按图索骥的过程中，难免会出现现实与理想的偏离，即差距，这就需要我们对自己的路径图进行检查、调整。怎么调整？这时，就可以使用复盘这个工具了。\u003c/p>\u003cp>首先，我们要明确我们的预期目标是什么，即领导布置的工作要求，这是当初我们制定自己行动计划的初衷。\u003c/p>\u003cp>其次，还原我们的执行过程，评估执行的结果与预期目标的差距。这里面最重要的“还原过程”，这是一种对已经发生的现象的不带评论的回顾。\u003c/p>\u003cp>第三，对上一步的差距成因进行深入分析。只有找到根本原因，才能为下一步的纠偏措施提供指引，是采取既定目标和规则，改善行动步骤的“单环学习”方法，还是优化目标和规则的“双环学习”方法。\u003c/p>\u003cp>最后，反思在整个过程中我们获得了那些经验和教训，在未来类似的工作中如何能前置性地制定相应的行动计划来规避那些可能存在的坑。\u003c/p>\u003cp>这里，我举一个自己的例子。刚调到市场口工作的时候，一次领导让我对某一特性的用户群体进行消费分析，好制定相应的营销案。那首先我就要进行取数。在取数前，按照领导的期望，我要先定一个清单，这个清单包括要取哪些维度、要规避哪些维度。清单列好后，进行了操作。等结果出来我发现，取出来的用户规模和我想象的要差很多。于是我就开始从头梳理，领导需要的用户群体是怎样的一个用户群体？在我做计划清单时，我列了哪些维度。。。。。。最后发现，我增加了多余的两个规避维度，进而缩减了用户规模，于是我调整了自己的操作步骤，减掉了两个维度。达到了目标。\u003c/p>\u003cp>这就是一个简单的复盘过程。\u003c/p>","interaction":"\u003cp>好，分享了我的经验后，现在我们一起来听听大家的。我们按之前分好的小组在小组内讨论。在你的工作和生活中，比如领导交办的工作，或与家人的一次旅行，在整个过程中，你是否有进行PDCA的闭环管理，如果有，那在执行过程中你是怎么修正自己的计划的，如果没有，又是怎么完成任务的。\u003c/p>\u003cp>下面我们请一位伙伴来和我们一起分享一下他的经验：\u003c/p>\u003cp>小红：像PDCA是非常好的应用，但在工作中很少应用到，或最多用到其中的几个。如果我们在工作中能结合复盘的这四个不走，比如在内训师的课程设计中，通过复盘的四个步骤和PDCA很好地结合起来，相信能给学员带来更好的学习效果。\u003c/p>\u003cp>很感谢刚才小伙伴的分享。那接下来就到了布置作业的时候了。\u003c/p>\u003cp>现在已经是2018年初了，相信大家在过去的2017年底都有被要求写工作总结和来年工作计划的要求。但我们很少对自己的生活进行一个总结。那通过今天的学习，动笔写下你对自己2017年、或四季度整体工作或12月的某项工作的复盘，也可以对生活中的某件事情进行复盘。要求，你的行动计划要有明确的目标、有时间限制、且结果是可以被衡量或观察到的。\u003c/p>\u003cp>小林：回去后对今天的学习内容进行复盘：\u003c/p>\u003cp>1、今天来学习的目的和预期目标是什么？\u003c/p>\u003cp>2、通过一下午的学习，我是否达到了我的预期目标？差距是什么？\u003c/p>\u003cp>3、为什么没达到？是事前我获取的信息不完全，目标设定太高？还是中间觉得没意思，溜出去了几次？\u003c/p>\u003cp>4、以后参加活动要先全面了解相关信息，充分利用好自己的双休日。\u003c/p>\u003cp>小明：对2017年组内运营的8个项目进行复盘：\u003c/p>\u003cp>1、这些项目的预期目标是什么？\u003c/p>\u003cp>2、我们都做了些什么工作，达到的结果和预期目标的差距是什么？\u003c/p>\u003cp>3、产生这个差距的原因有哪些？\u003c/p>\u003cp>4、2018年要运营的项目中，我们可以从上面的分析中获得怎样的经验，避免在同一个地方摔倒两次。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1515997774000,"updated_at":1515997802000},{"id":4425,"topic":"了解什么是复盘","learn_goal":"通过学习复盘的概念，当下形成对复盘的正向认识。","remark":"","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"佳山","city":"厦门"},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"Hello，大家好！\r\n 我是佳山，这是我的微信昵称，而他又取自我的姓名——崔俊峰，山佳崔，俊美的山峰，故而佳山。\r\n 我的经历大家可以从我的微信签名看到，曾经懂业务的的HR，现在践躬行的marketing，永远爱阅读的玫楠纸。这就是我的三个标签。\r\n 接下来，我为大家介绍一下拆书和拆书帮。\r\n 和拆书帮结缘，是因为我爱阅读。但我阅读的目的是很功利和贪婪的，我觉得阅读一是为了掌握知识，二是为了掌握方法。当你自己在一个月黑风高的夜晚，独自倚窗捧卷是可以做到第一点的，第二点就需要借助一定的工具和外力了。\r\n 【拆书】拆书，就是我找到的好方法了。古语云，“书非借，不能读也。”我觉得，“书非解，不能懂也。”这里的解，就是指拆解。拆书，就是要你把你吃进去的知识，通过自己的理解、消化再加工吐出来，让这些知识真正成为自己的知识和技能。这个生产加工的过程就是拆书。拆书的过程可以是自己单打独斗地学习，也可以由一个拆书家组织一群人一起学习——其效果不亚于一场正式的企业培训。那生产拆书家的地方，就是拆书帮了。","ratings_count":2,"texts":[{"id":7434,"quote":"\u003cp>#接开场#\u003c/p>\u003cp>【拆书帮】如果说我们想掌握的知识和技能是老鼠的话，那拆书帮就是一群养猫人，一群志同道合、热心公益，以非盈利为目的的共同研究如何能养出抓住老鼠的好的养猫人。\u003c/p>\u003cp>下面，请大家和我一起来领略下拆书的魅力。\u003c/p>\u003cp>发给大家的片段是选自机械工业出版社出版，邱昭良著述的《复盘+：把经验转化为能力》一书。请大家用3~5分钟阅读一下拆页的内容。\u003c/p>","explains":"\u003cp>很多人刚接触复盘的时候，都会下意识地觉得，这不就是总结嘛！包括我在内。不知道大家有多久没有进行自我总结了。我是很久了。\u003c/p>\u003cp>但这个片段告诉了我们复盘与一般意义的总结之间的不同。复盘不等于总结。\u003c/p>\u003cp>总结的话，可能我们会说，这次这个事情我是怎么怎么做的，（好点的总结可能还会包括），有什么可取之处，和不足之处，下次我会如何如何地再去做。回头想想，每次总结其实我们都是漫无目的的回顾，没有既定的套路。\u003c/p>\u003cp>而复盘，却是以团队为单位、学习为导向的结构化总结方法。\u003c/p>\u003cp>不论是我们的工作团队还是家庭，只要他是一个成长型的组织，成员间观点的相互碰撞和促进，对我们个人而言就会起到他山之石可以攻玉的效果。在工作或生活中，对某一特定的事件，按照固定的步骤进行操作：\u003c/p>\u003cp>1、回顾事实；\u003c/p>\u003cp>2、分析差异；\u003c/p>\u003cp>3、反思自我；\u003c/p>\u003cp>4、获取经验。\u003c/p>\u003cp>找到未来可改进的地方，不断提升自己和整个团队的效能。\u003c/p>","interaction":"\u003cp>这里我举个自己的例子。\u003c/p>\u003cp>我们公司每年9~10月在高校开学时，都要对新老生开展一次大型户外营销活动——高校迎新。2015年的时候，我还在人力资源部工作，那年因为迎新的压力，公司领导要求，除了生产单位外，其他职能部门也要派人去现场进行营销支援，我们叫做综援。\u003c/p>\u003cp>那年营销综援后，我天马行空地从未来的人力资源市场与危机，商业、工业化、效率和未来，事前的培训，人物角色技能的设定，个人技能的提升，生活和工作的关系六个方面进行了总结、当然，那时我恬不知耻地称之为复盘。\u003c/p>\u003cp>相信大家对我刚才介绍这六个方面都觉得很发散，有点前后不搭。所以，通过学习了解复盘的定义，我们会发现，什么是复盘，复盘能够给我们带来什么。\u003c/p>\u003cp>接着上面的案例，掌握了复盘的定义后，在本月30日，按照公司的布置，我们团队要对去年四季度营销活动进行复盘总结，我就会按照复盘的定义和方法，做一次真正的复盘：\u003c/p>\u003cp>1.拉上我的团队，大家坐在一起，本着学习提升而非批评指正的态度，进行复盘总结；\u003c/p>\u003cp>2.回顾整个活动的事前策划、事中执行、事后效果。\u003c/p>\u003cp>3.分析每个环节的实际效果和我们预想之间的差距原因是什么。\u003c/p>\u003cp>4.反思整个活动，我们从中学习到了什么经验，下次可以改进的地方是什么。\u003c/p>\u003cp>5.团队中每个成员就自己负责的项目或环节重复上述的三个步骤。\u003c/p>\u003cp>6.向公司领导介绍分享我们复盘的结果。\u003c/p>\u003cp>以上就是我今天和大家分享的复盘的定义。希望能对大家有所帮助。\u003c/p>\u003cp>我是拆书家，我是崔俊峰。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":7590,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1515407086000,"updated_at":1516793401000,"ria":true},{"id":4275,"topic":"《复盘：把经验转化成能力》邱昭良","learn_goal":"让大家学习什么是复盘，怎样复盘，复盘后让我们的经验变成价值。","remark":"宣传介绍：\r\n复盘！你知道什么是复盘，复盘和总结的区别是什么呢？怎样实现最复盘呢？请大家跟随我一起学习如何复盘，从此大家在2018年以后再也不会在错误的坑里重复摔跤。","level":"TF2-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"齐艳","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"我是喜鹊！做书法老师，今天进行的2-2的分享。谢谢\r\n【学习目标】\r\n请大家跟随我完成本次RIA现场学习后，掌握高效学习的法宝“复盘”这个技能。让我们把有限的精力放在新知上，不如把人生的每一次经验转化为价值，那怎样把经验转化为价值呢？现在请我一起学习复盘四步骤吧。\r\n 【图书介绍】\r\n时间：1分钟30秒\r\n【F】 大家好今天我带来的拆页来自于《复盘+：把经验转化为能力》这本书。\r\n 本书的作者是邱昭良博士，他是管理学博士，在联想集团，东方道尔集团做过高级管理人员。\r\n【A】 和同类型书相比，它是唯一经过联想董事长柳传志审读并指导修改的图书，卡拉卡有限公司创始人孙陶然以自己亲身经历为证，倾情作序的。\r\n【B】 \r\n【B1】我选择此书理由：本书是 “复盘”实务的操作指南，从复盘日常的工作指导和常用方法，到工具和模型都能直接帮助我们快速实操复盘这个工具。\r\n【B2】来我们拆书帮的小伙伴都是爱学习的，可是为什么总是相同坑里不停的摔跤呢？为什么总结一次又一次没有改变呢？ 因为大家没复盘掌握复盘这个方法，让今天我们学习什么是复盘，怎样复盘，从而掌握提升自己能力的制胜法","ratings_count":0,"texts":[{"id":7261,"quote":"\u003cp>请大家阅读拆页，时间是1分钟，看完的小伙伴请示意下我\u003c/p>\u003cp>“复盘”原是围棋术语，本意是对弈者下完一盘棋之后，重新在棋盘上把对弈过程摆一遍，看看哪些地方下得好，哪些地方下得不好，哪些地方可以有不同甚至是更好的下法等。\u003c/p>\u003cp>正如联想集团创始人柳传志先生所说：所谓复盘，就是一件事情做完了以后，做成功了，或者没做成功，尤其是没做成功的，坐下来把当时的这个事情，我们预先怎么定的、中间出了什么问题、为什么做不到，把这个过程要理一遍，理一遍之后，下次再做的时候，自然这次的经验教训就吸收了。\u003c/p>\u003cp>基于复盘的机理和长期的实践，联想集团于2011年提出了复盘的操作步骤，包括四个阶段：回顾目标、评估结果、分析原因、总结经验。\u003c/p>\u003cp>对应的四个阶段的问题：\u003c/p>\u003cp>第一阶段回顾目标：预期目标是什么？\u003c/p>\u003cp>第二阶段评估结果：实际发生了什么？\u003c/p>\u003cp>第三阶段分析原因：差异原因是什么？\u003c/p>\u003cp>第四阶段总结经验：从中学习到什么？如何改进？\u003c/p>","explains":"\u003cp>&nbsp; 【学习目标】\u003c/p>\u003cp>请大家跟随我完成本次RIA现场学习后，掌握高效学习的法宝“复盘”这个技能。让我们把有限的精力放在新知上，不如把人生的每一次经验转化为价值，那怎样把经验转化为价值呢？现在请我一起学习复盘四步骤吧。\u003c/p>\u003cp>【what】\u003c/p>\u003cp>中国独创的对弈游戏围棋里有一个术语—-复盘， \u003c/p>\u003cp>复盘就是指是下完一盘棋之后，重新在棋盘上把对弈过程摆一遍，看看哪些地方下得好，哪些地方下得不好，哪些地方可以有不同甚至是更好的方法。\u003c/p>\u003cp>我们从以下2点来理解复盘。\u003cbr> 1、复盘是结构化的学习方法\u003c/p>\u003cp>2、复盘是以学习为导向\u003c/p>\u003cp>你会说这就是不总结吗？而总结就是写成绩，经验，存在问题，未来计划，并且没有固定的模式.而复盘呢？只是还原事件本来面貌，以学习经验为目标，必须遵从特定步骤的方法。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>那什么事情要复盘呢？什么时间复盘呢？复盘事件大到你的人生目标，职业规划，小到你今天到百读书社参加活动的路线安排，不论周期长短，目标大小，都需要我们随时随地复盘。但是我们复盘的“内容”，某件事或某一系列事情必须有一个起点和终点，并且还有具体目标，这样才更好的帮助我们把经验转换成能力。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>复盘四步骤是：\u003c/p>\u003cp>（1）回顾目标：想想你当初的行动计划目标是什么，有分解目标吗？\u003c/p>\u003cp>（2）评估结果：客观还原整个事件，亮点是什么？不足是什么？\u003c/p>\u003cp>（3）分析原因：亮点，不足出现因素？\u003c/p>\u003cp>（4）学习改进：学习到什么经验，掌握什么规律，改进什么，具体行动时间，方式，内容。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>【不这么做的坏处】\u003c/p>\u003cp>我们大家一般会怎么做呢？不复盘，只是简单总结，但是发现不论总结多少次存在问题依旧没有解决。\u003c/p>\u003cp>比如拿我举一个例子\u003c/p>\u003cp>我的厨艺很臭，最近迷恋上拉麻辣香锅，上周我目标是为我和我老公做一份色香味俱全的麻辣香锅，可最后我自己都不想吃。\u003c/p>\u003cp>我总结，只是归结于我没有这方面天赋。\u003c/p>\u003cp>现在用复盘的4步骤来提升我的麻辣香锅这道菜的制作水平。\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 回顾目标\u003c/p>\u003cp>预计目标做好看好吃营养丰富的麻辣香锅，这个目标太模糊，什么是好吃的呢？\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 评估结果\u003c/p>\u003cp>还原整个采买，准备，烹饪，装盘整个过程。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 亮点：菜品丰富，色彩动人，营养全面。\u003c/p>\u003cp>不足：口味的太辣，太麻，完全不符合家里2个人的口味。\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 差异原因\u003c/p>\u003cp>亮点：菜品准备用列清单方式购买\u003c/p>\u003cp>不足：烹饪程序混乱 ，调料准备不全 \u003c/p>\u003cp>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 改进学习：\u003c/p>\u003cp>学习：列清单采购菜品和调料\u003c/p>\u003cp>改进：熟悉烹饪程序\u003c/p>\u003cp>&nbsp;通过复盘，我终于明白自己多年是为做饭而做饭，完全没有目标，应该根据我们家2个人口味习惯制定一个标准，从现在开始好好考虑整个家庭菜谱。这就是 \u003c/p>\u003cp>复盘给我带来的价值，姐也是可以做好饭的。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>&nbsp;当然也许你认为什么事情都不值复盘，因为人算不如天算，一切都是命。也许你对某项活动只是消遣，比如我看一些解压的书籍，不就是放松吗？干嘛费劲去复盘。复盘是工具，是方法，可以让我们的经验成为价值，就如同我的“麻辣香锅”复盘，给我带来价值。\u003c/p>\u003cp>因此如果在坐这里的小伙伴们内心里想遇到更美好的自己，那请刻意的复盘，这是学习提升自己是必要的法宝。\u003c/p>\u003cp>以上呢我对这个片段的分享\u003c/p>","interaction":"\u003cp>【A2分步催化】\u003c/p>\u003cp>设想下，下周周六，你和你的好友很久没有见面，相约在茶馆一起喝茶，聊天，在沟通过程中大家都很感慨，时间真快，有到2017年岁末，是不是应该对最近发生的重大事件，或者重大项目，或者学习内容，或者年初计划做一个复盘呢？你最想复盘的内容是什么呢，同时回想下，你确定复盘内容目标是什么？\u003c/p>\u003cp>我们就讨论到这里，请一位小伙伴分享接下要应用的场景。\u003c/p>\u003cp>【A2分步催化2】\u003c/p>\u003cp>当你正想和小伙伴分享的时候，突然想到今天学习的复盘4步骤，那么请你们按我发给你们的复盘4步骤提问清单和已确定的复盘内容， 22分组进行分享，即一个人按清单提问，一个按自己确定的复盘内容客观的回答。时间是5分。\u003c/p>\u003cp>我看大家分享的很热烈，现在请一个小伙伴分享下自己用复盘四步骤来复盘自己确定的内容。\u003c/p>\u003cp>大家都分享完了，非常谢谢大家。希望从今天开始，刻意对自己在意的事情复盘，用复盘方式提升自己，让经验产生价值。\u003c/p>\u003cp>小伙伴分享：\u003c/p>\u003cp>复盘内容：2017年理财计划。\u003c/p>\u003cp>1、&nbsp; 回顾目标：2017年理财目标投入资金30% 收益。投资项目，美股，P2P，比特币。\u003c/p>\u003cp>2、&nbsp; 评估结果：收益没有达到30%\u003c/p>\u003cp>亮点：把资金全部投入到项目。\u003c/p>\u003cp>不足：美股，比特币没有时间看，大部分也看不懂。\u003c/p>\u003cp>3、&nbsp; 分析原因：&nbsp;\u003c/p>\u003cp>亮点：行动力，执行力强\u003c/p>\u003cp>不足：英语基础，金融专业知识欠缺。\u003c/p>\u003cp>4、改进学习\u003c/p>\u003cp>&nbsp;&nbsp; 学习：行动力\u003c/p>\u003cp>&nbsp;&nbsp; 改进：1、学习英文和金融专业知识\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 途径：阅读书籍\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 时间安排：每天30分钟\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 2、每天安排最少1小时看盘时间，知道走势\u003c/p>\u003cp>&nbsp;附：提问清单：\u003c/p>\u003cp>1、回顾目标\u003c/p>\u003cp>&nbsp;&nbsp; 目标是什么？\u003c/p>\u003cp>&nbsp;&nbsp; 分解目标是什么？\u003c/p>\u003cp>2、评估结果：（进行事实求事的描叙）\u003c/p>\u003cp>实际发生是什么？的\u003c/p>\u003cp>是什么情况下发生的？\u003c/p>\u003cp>是怎么发生的？\u003c/p>\u003cp>3、分析原因\u003c/p>\u003cp>做得好的成功因素是什么？&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003c/p>\u003cp>做得失败的因素是什么？\u003c/p>\u003cp>4、学习改进：\u003c/p>\u003cp>学习到什么新东西？\u003c/p>\u003cp>有哪些经验或规律可以掌握？\u003c/p>\u003cp>以后如何改进？具体时间、地点？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1513688906000,"updated_at":1513688906000,"ria":true},{"id":3946,"topic":"如何从过去的事中获得提升自己的能力","learn_goal":"学习者能够使用复盘，在生活和工作中避免同样的错误再次出现","remark":"有多少事，让你悔不当初？\r\n有多少事，让你重复犯错？\r\n有多少事，让你徒劳无功？\r\n现在只需要一件事，就可以让这些让你烦恼的事灰飞烟灭，让我们一起来看看到底是什么？","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"李佳","city":"宁波"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"各位小伙伴，大家好！我是六子，今天给大家带来的拆解内容是通过复盘，让自己从过去经历的事情中获得提升自己的能力，内容选自《复盘+把经验转化为能力》这本书。","ratings_count":0,"texts":[{"id":6889,"quote":"\u003cp>“复盘”原是围棋术语，本意是对弈者下完一盘棋之后，重新在棋盘上把对弈过程摆一遍，看看哪些地方下得好，哪些下得不好，哪些地方可以有不同甚至是更好的下法等。\u003c/p>\u003cp>这个把对弈过程还原并且进行研讨、分析的过程，就是复盘。通过复盘，棋手们可以看到全局以及整个对弈过程，了解棋局的演变，总结出适合自己和不同对手的套路，或找到更好的下法，从而实现自己棋力的提升。\u003c/p>","explains":"\u003cp>\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够使用复盘的方法，解决日常工作和生活中重复犯相同的错的问题。\u003c/p>\u003cp>\u003cstrong>图书介绍：\u003c/strong>\u003c/p>\u003cp>事件场景：&nbsp;\u003c/p>\u003cp>现场的小伙伴有没有这样一种经历？今天听了一节微课，讲的是日常沟通方面的方法和套路，觉得很是受用，却发现自己不能运用到生活中，或者不能够和别人分享自己在微课上学到了什么。不管听再多的课，依然止步不前，坚守自己原来的阵地！\u003c/p>\u003cp>提问:\u003c/p>\u003cp>你是不是怀疑过自己的能力？除了贬低自己的能力之外，还有没有办法让你去应用你所学到的东西？\u003c/p>\u003cp>影响:\u003c/p>\u003cp>投入了却没有多少回报，没有进步，本身就让我们很是焦虑，浪费自己的精力和时间，再质疑自己的能力的话，只会徒增烦恼，给自己增加更多的负能量。\u003c/p>\u003cp>解决：\u003c/p>\u003cp>《复盘+》是一本系统阐述复盘方法并教我们如何使用复盘的工具性书籍，通过复盘可以在经历中总结经验，把经验转化为做事的能力，避免没有进步的焦虑，为以后做事节省时间和精力。不是自己能力有问题，只是方法有问题。今天我们学习的主题就选自这本书，让我们看看什么是复盘，如何通过复盘让自己避免重复性且没有进步的行为的发生。\u003c/p>\u003cp>\u003cstrong>I拆书家讲解：\u003c/strong>\u003cbr>\u003c/p>\u003cp>在这个拆页中我们知道了复盘的来源是围棋，俗话说，当局者迷，旁观者清，复盘可以让我们从局外去看我们当时在局内看不清的东西。\u003c/p>\u003cp>在这之前，我一直以为事后反思一下，当初要是那么做就好了，当初要是不做就好了，这种悔不当初就是复盘。\u003c/p>\u003cp>举个例子：\u003c/p>\u003cp>现在有一款手机游戏，非常的火，如果你没玩过，我相信你身边一定有人在玩。这个游戏就是王者荣耀，又称王者农药，因为毒害了很多人。我也是这个游戏的玩家，而且属于有点着迷的那种，我经常会玩到晚上很晚，以致于第二天爬起来的时候太困难，这个时候我就会去反思，要是昨天晚上不玩手机，现在就不会这么痛苦了。\u003c/p>\u003cp>还有就是这种团战游戏，如果跟朋友一起玩的话，不管输赢大家都会在游戏结束后讨论一下刚才的对战如何如何，输在了什么地方，赢在什么地方，一般这种讨论性总结都是在互相埋怨队友或者互相炫耀自己的水平。你太菜，或者多亏有我带你们飞。\u003c/p>\u003cp>\u003cstrong>概念对比：\u003c/strong>\u003c/p>\u003cp>而事实上，反思一般是从过去的经历中发现原因，总结是对事情过程的梳理，对已经发生的行为和结果进行描述分析，相对来说关注一些关键点和里程碑。\u003c/p>\u003cp>复盘是在头脑中对做过的事情重新过一遍，像过电影一样，不止包括反思，总结，还包括一些没有做的一些可能的行为的推测。就像拆页里面所说的，哪些地方可以有不同甚至是更好的下法等，发现更好的方法。\u003c/p>\u003cp>再说一下打游戏，职业选手都是有教练的，他们的教练会不断回看自己选手比赛的视频，留意各种细节，然后去制定战术，这就是一个复盘的过程，而我们普通的玩家呢，开心就好！\u003c/p>\u003cp>\u003cstrong>HOW：\u003c/strong>\u003c/p>\u003cp>&nbsp;我们可以从拆页当中根据复盘的概念，归纳出复盘的步骤：&nbsp;\u003c/p>\u003cp>1、梳理过程：我是如何经历这件事的？\u003c/p>\u003cp>2、回顾目标：我原来是想达到什么样的效果？\u003c/p>\u003cp>3、对比结果：现在发生了什么，与我预期的有什么不同？\u003c/p>\u003cp>4、分析原因：为什么会有不同？哪里没有做好？\u003c/p>\u003cp>5、提出假设：还有没有别的更好的方式？\u003c/p>\u003cp>6、总结规律：再遇到类似的事情会采取什么样的行动？\u003c/p>\u003cp>\u003cstrong>&nbsp;举例讲解：\u003c/strong>\u003c/p>\u003cp>比如，我昨天听了一节微课：\u003c/p>\u003cp>下班后，吃完饭就打开了电脑，登陆微信听起了原来拉下的微课，这节课叫《如何得出自己的独特观点》，在听课的过程中，时不时会收到微信消息，这个时候我就会去浏览这些消息，电脑右下角还弹出来了电脑垃圾过多，需要清理的指令，于是乎又清理了一下电脑，这个时候，微课断断续续的听完了，总觉得少了点什么。\u003c/p>\u003cp>我听课的目标是想GET这个培养自己独特观点的技能，以及把这个微课的内容写成一篇文章分享一下。\u003c/p>\u003cp>结果是我不止没有get完全这个技能，文章也被扼杀。\u003c/p>\u003cp>原因在于我没有专心的放在听课上，被太多的信息给干扰，对于文章也是想要写的完美一些，于是迟迟没有动笔。\u003c/p>\u003cp>假如我听课的时候关闭消息提示，边听边用笔记录，是不是更能提升自己的专注力，或者说在听课之前告诉一位小伙伴，说好听完课之后的固定时间，给她做个分享。这样会不会让自己更有动力用心去听？\u003c/p>\u003cp>以后听课我首先得提升自己的注意力，要集中于课程的听讲，时刻提醒自己有输入就有输出，听完课立马做分享，这样就不会导致听完课没有任何收获了。\u003c/p>\u003cp>\u003cstrong>适用边界\u003c/strong>：\u003c/p>\u003cp>所有的事都可以复盘吗？可以这么说，大事小事都可以复盘，但最好是就近原则，这个近根据人的记性不同，时间长短也不同，也就是最近发生的对你有影响的事情，最好是事情发生后就直接复盘，这样才能更加翔实的梳理事情发生的细节，复盘的结果才会收益更大。\u003c/p>\u003cp>因为我们生活中没有录影机，自己的记性也不会记下很久的事情的一些细节，时间过的太久，事情发生的细节的时候往往就会忽略很多，这也就成了我们所说的总结，因为前面有说过，总结是对过去的关键点和里程碑进行梳理分析。\u003c/p>\u003cp>还有就是自己亲身经历的事情，别人发生的事情那是别人的复盘，对你来说是案例研究。你不能够详细的体会当中的细节。当然了，你可以通过别人的事情帮助别人复盘。\u003c/p>","interaction":"\u003cp>\u003cstrong>A2催化学习者应用：\u003c/strong>\u003c/p>\u003cp>在我们学到了复盘的理论知识之后呢，看看今天这个复盘概念能不能解决一个你生活中实际遇到的一个问题。接下来请大家编写一个剧本，这个剧本的场景最好是可以在将来可能遇到的，还需要包括背景、人物、对话等，其中对话过程中能够要求包含“复盘”概念的应用，摘要写在纸上，五分钟后我们请人站起来讲讲他的剧本。\u003c/p>\u003cp>&nbsp;\u003cstrong>案例\u003c/strong>：\u003c/p>\u003cp>\u003cstrong>背景\u003c/strong>：在一次拆书活动结束后，A和身边坐着的B相谈甚欢，于是约起了饭局，在饭局上讨论今天参加活动的收获。\u003c/p>\u003cp>\u003cstrong>人物\u003c/strong>：今天参加活动的两名小伙伴A和B\u003c/p>\u003cp>\u003cstrong>内容\u003c/strong>：\u003c/p>\u003cp>两人点完菜之后，在上菜之前开始聊天。\u003c/p>\u003cp>A：你怎么知道的这个活动呀？ \u003c/p>\u003cp>B：我是在拆书帮群里看到宣传文案报名的。因为这期内容感觉应该会对我有点收获，所以就报名来了。\u003c/p>\u003cp>A：那你今天有什么收获呀，说说看？（\u003cstrong>梳理过程\u003c/strong>）\u003c/p>\u003cp>B：从刚开始的自我介绍，就认识了几个小伙伴，接着就是通过拆书家带拆内容，我们针对自己的情况做了分享，学到了……\u003c/p>\u003cp>A：今天来之前你想在活动中得到什么？（\u003cstrong>回顾目标\u003c/strong>）\u003c/p>\u003cp>B：想认识几个爱学习的伙伴，可以一起互相监督学习，还有学习下今天分享主题，把这个应用到生活中去。\u003c/p>\u003cp>A：实际的收获跟你预期的收获一样吗？（\u003cstrong>对比结果\u003c/strong>）\u003c/p>\u003cp>B：对于今天的主题是没啥问题，重要的是没有和认识的小伙伴建立联系\u003c/p>\u003cp>A：为什么不去呢？（\u003cstrong>分析原因\u003c/strong>）\u003c/p>\u003cp>B：这次活动参与不够积极，该表现的时候没有积极上场表现，让别人看不到闪光点吧\u003c/p>\u003cp>A：怎么才能让别人看到闪光点呢？（\u003cstrong>提出假设\u003c/strong>）\u003c/p>\u003cp>B：在开始的自我介绍时，如果能把我的特长或者能给大家带来的好处什么的说一下，或者在互动环节多发言，这样应该可以吸引到别人的注意力了吧\u003c/p>\u003cp>A：其实这也是一种收获呀 （\u003cstrong>总结规律\u003c/strong>）\u003c/p>\u003cp>B: 嗯，提前把自己的闪光点先总结一下，自己的优势在哪，这样别人知道认识我可以有什么收获了。这样更容易和别人建立联系。\u003c/p>\u003cp>\u003cstrong>学习者分享\u003c/strong>：\u003c/p>\u003cp>背景：最近我一直坚持跑步，未曾想到膝盖越跑越痛，刚才小组讨论的时候，各位小伙伴在帮我寻找到的膝盖疼痛的原因，然后套用今天的复盘公式来编写的剧本。假设场景是我去医院请医生帮我检查膝盖。\u003c/p>\u003cp>人物：我和医生\u003c/p>\u003cp>内容：\u003c/p>\u003cp>我坐在医生对面，医生对着我伸出右手在我的左膝盖轻揉了几下，大概心中有了底。\u003c/p>\u003cp>医生：你是什么时候开始痛的？\u003c/p>\u003cp>我：大概有一个礼拜左右了。\u003c/p>\u003cp>医生：最近有没有做什么剧烈运动，或者有没有让膝盖遭到撞击什么样的伤害？\u003cstrong>（梳理过程）\u003c/strong>\u003c/p>\u003cp>我：碰撞性的伤害倒是没有，不过我最近一直在坚持跑步，每天都会在早晨六点钟起床之后去跑个5km左右，坚持了一个月左右，刚开始的时候是没什么感觉，后面跑了几天之后，膝盖在跑步的时候隐约会出现疼痛，当时也没在意，以为跑步过程中遇到点困难是正常的，咬牙坚持一下就会过去的，没想到越来越严重了。\u003c/p>\u003cp>医生：你这种属于对身体的不负责任，痛了还去跑，不知道跑步姿势不正确，对膝盖损伤很严重吗？你为什么要跑步？\u003cstrong>（回顾目标）\u003c/strong>\u003c/p>\u003cp>我：我看目前很多人都在跑，也觉得跑步对身体健康确实有帮助，想通过跑步让自己有个健康的身体，还可以帮助自己控制体重。\u003c/p>\u003cp>医生：那你觉得你今天来医院看病，是跑步帮了你还是害了你？\u003cstrong>（对比结果）\u003c/strong>\u003c/p>\u003cp>我：之前只是觉得跑步这么简单，大家都会，没想到会出这种事情。\u003c/p>\u003cp>医生：你这种就属于盲目冲动，在做运动之前不去考虑身体状况，也不考虑自己有没有掌握标准运动方式，跑步就一定要经历痛苦才叫有毅力？\u003cstrong>（分析原因）\u003c/strong>\u003c/p>\u003cp>我：确实有点盲目，没有掌握正确的姿势就开始，虽然出于好心，但方法没用对，努力也白费了，还害自己进医院。\u003c/p>\u003cp>医生：跑步也不是让身体健康的唯一方法吧？如果为了让自己健康而去经历痛苦，这个不就是本末倒置了么？运动其实是件非常愉快的事，为了让身体健康的运动也是非常轻松的事。\u003cstrong>（提出假设）\u003c/strong>\u003c/p>\u003cp>我：对，我不该只是看到大家都在跑，自己也盲目去跟风，我还可以跟朋友一起去游泳，这样不至于让膝盖承受那么大压力。\u003c/p>\u003cp>医生：照你目前这个情况，先修养一段时间再说吧，先给你开几幅药，拿些膏药敷一下，好点了再说运动的事吧。\u003c/p>\u003cp>我：好的，谢谢医生。原本是想让身体健康的，结果却因为自己的盲目害的膝盖都受伤了，不止是运动，在任何方面太盲目的跟风都是不可取的，一定要根据自身情况做相应的准备，比如研究一下方法，才能够不让好心办坏事。\u003cstrong>（总结规律）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>结语：\u003c/strong>\u003c/p>\u003cp>非常精彩的剧本分享，通过对跑步的复盘，意识到跑步真正的目的，跑步是为了健康而不是靠毅力坚持，也总结出了盲目跟风是不可取行为的规律，感谢分享，请大家鼓个掌吧！我今天的领拆到此结束，希望能够为大家在今后的生活中带来一点改变，谢谢大家的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1509511537000,"updated_at":1509803525000,"ria":true},{"id":3906,"topic":"使用五个“为什么”找到解决问题的方案","learn_goal":"学会通过追问“五个为什么”找到问题的根本原因","remark":"拆书家英爱1-2定级","level":"TF1-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"英爱","city":"合肥"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"在座的小伙伴大家好，我是英爱。平时喜欢看书、看电影、结交一些志同道合的朋友。加入拆书帮是希望能够认识更多优秀的小伙伴，大家一起抱团学习，让自己也慢慢成长为一个优秀的人。\r\n 今天现场一共来了8 位小伙伴，为了便于后面环节的互动，我们先分下组。shooshoo和新来的两位小伙伴一组，洪舵和雅韵姐一组，河老师和这两位小伙伴一组。\r\n【图书介绍】 今天我拆解的片段来自《复盘+把经验转化为能力》这本书，【F】作者是邱昭良博士。邱昭良先生硕士和博士两段研究经历的专业方向均为学习型组织，曾任联想集团高级经理、联想投资公司咨询经理、东方道迩集团首席运营官。【A】本书详细阐述了联想、万达、美国军队、英国石油公司复盘的实务做法，分享了作者多年的实践经验以及“内功心法”，介绍了引导复盘的工作指引与常用方法、工具与模板，是应用复盘的专业、深入而全面的操作指南。作者本人有着非常丰富的一线经营与管理实务经验，因此本书的实操性非常强。【B】学习者通过本书的学习，可以学会如何通过对过去的思维和行为进行回顾，反思和探究，从而达到能力的提升。","ratings_count":0,"texts":[{"id":6847,"quote":"\u003cp>\u003cstrong>《复盘+把经验转化为能力》\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp; 如何使用“五个为什么”\u003c/strong>\u003c/p>\u003cp>这一方法的使用非常简单，以至于只需要以下三个步骤。\u003c/p>\u003cp>\u003cstrong>第一步，提出第一个为什么\u003c/strong>\u003c/p>\u003cp>挑选出一个问题症状作为开端，然后问小组成员第一个为什么：“为什么这件事情正在发生？”\u003c/p>\u003cp>可能对这个问题有三四个答案。把这些答案全部粘贴在墙上，在这些答案周围留有足够的空间。\u003c/p>\u003cp>\u003cstrong>第二步，依次追问“为什么”\u003c/strong>\u003c/p>\u003cp>重复墙上的每个答案，依次追问“为什么”。把每个答案和“答案的答案”粘贴到它的“母问题”附近。\u003c/p>\u003cp>\u003cstrong>第三步，对问题进行整合\u003c/strong>\u003c/p>\u003cp>当所有问题回答完毕之后，一些问题可能开始整合，并追溯到十几个不同的症状，发掘两三个系统性的根源。\u003c/p>\u003cp>例如，里克.罗斯《第五项修炼.实践篇》中提到了一个有趣的案例。\u003c/p>\u003cp>一位车间主任看到车间地板上有一摊油。他马上习惯性地抓住离他最近的一个工人，让他把油擦掉。\u003c/p>\u003cp>此时，一个善于使用“五个为什么”的顾问提出了第一个“为什么”：“为什么地板上会有一滩油？”\u003c/p>\u003cp>旁边的工人回答到：“奥，葛本机漏油了。”\u003c/p>\u003cp>“那你还不赶紧去吧葛本机修好？”车间主任吼道。可那个顾问却继续追问：“为什么葛本机会漏油？”\u003c/p>\u003cp>“因为塞子有毛病。”工人答道。\u003c/p>\u003cp>“为什么塞子有毛病？”那个顾问继续追问，提出了第三个“为什么”。\u003c/p>\u003cp>“我也不清楚，反正这批塞子都不经用，很差”。工人无奈地说。\u003c/p>\u003cp>“那么，你需要搞清楚，为什么你们会买这么差的塞子。”顾问对车间主任说。\u003c/p>\u003cp>……\u003c/p>\u003cp>通过不停的追问“为什么”，可以找到导致问题出现的深层次原因，避免就事论事，只是消除了问题的“症状”，而未从根本上解决问题。\u003c/p>","explains":"\u003cp>这个片段带给大家的是学会运用“五个为什么”来解决问题，这“五个为什么”是逐层递进的关系，通过逐步的追问客户找到问题的根源，为什么重点介绍这个方法呢？因为我们的思维惯性是我们做不到逐步追问。\u003c/p>\u003cp>大家想想，平时出现问题的时候，我们的本能反应是怎样呢？是不是希望问题可以立马解决！最好是一次性给搞定，越快越好。于是，当问题来的时候，并没有给自己足够的时间去思考，去多问几个为什么，更找不到问题的关键所在。这就导致，我们很多时候仅仅只是了解到一些基本信息后，就草草处理，而问题的根源还未被发掘，治标不治本的状态屡见不鲜。\u003c/p>\u003cp>这让我想起了，之前有段时间有位客户老是反映我们公司送货速度太慢，从表面上看，每个环节的同事都在规定时限完成了工作，因此找不出原因。后来运用五个为什么来排查，就很快找到了答案。第一个问题“送货慢”， 为什么送货慢呢？答案是物流周一才送货；第二个问题“为什么物流周一才送货”，答案是物流周五才收到订单，周末送货担心客户不收货。第三个问题“为什么物流周五才收到工厂送货单”，答案是“工厂周五才开出送货单”，第四个问题“为什么工厂周五才给物流送货单”，答案是客户周四下午才汇的货款。这样几个问题追问下来，很快就找到问题根源了。\u003c/p>\u003cp>&nbsp;其实想要找到问题的根本所在，针对性的去解决，是有章可循的，结合原文我给大家三个详细的步骤。\u003c/p>\u003cp>1、症状切入，穷尽答案。以一个问题“症状”，并把所有可能性的答案写出来，粘贴在问题的后面，每个答案的周围留有足够的空白。\u003c/p>\u003cp>2、二级追问，细化答案：依次对所有可能性的答案进行提问，并把每个答案粘贴在“母问题” 附近。\u003c/p>\u003cp>3、整合问题，追根溯源：当所有的问题回答完毕之后，对其中的一些问题进行整合，并追溯到不同的症状，从中发掘两到三个根源性的问题，统筹解决。\u003c/p>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>【A1】当我们遇到问题的时候，都希望能够尽快妥善的解决掉，但实际过程中并不那么容易。那么现在请大家回忆一下，最近有没有什么让你比较头痛，总也没有办法的解决的问题；或者说有什么问题总是反反复复出现，无法彻底解决掉的？请大家在一张便签上写出来，并在小组内分享交流一下，一会我请一个小伙伴分享一下自己的经历。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 好了，我们看下哪位小伙伴可以来分享下下自己的案例。\u003c/p>\u003cp>学习者分享案例：\u003c/p>\u003cp>\u003cstrong>学习者A：\u003c/strong>最近发现自己五岁的的儿子，在外面逛的时候老是要一些小玩具，如果不给他买的话，就哭闹或者耍无赖。经过观察发现是儿子跟爷爷出去玩的时候，爷爷总会无原则的满足他，让儿子养成了乱要东西的坏习惯。虽然多次教训，但是基本没有什么用。而当自己去跟父亲就这件事情进行沟通的时候，双方总是不欢而散，老爷子压根不听自己的话。\u003c/p>\u003cp>&nbsp;&nbsp; 【拆书家点评】那么通过小伙伴A刚刚给大家分享的这案例，可以尝试运用五个“为什么”来解决。当对孙子的教育没有效果时，就要尝试与爷爷进行沟通。当与爷爷也无法沟通的时候，就需要考虑更深层的问题，是否爷爷因为对儿子不满，所以在对待孙子教育问题上，不想听父亲的，执意要溺爱孙子。如果是这样，就需要从根本着手，切实有效的改善自己与父亲之间的关系，才可以彻底解决这个问题。\u003cbr>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>&nbsp;【A2】今天各位来到现场，学习了片段介绍的方法，我想大家多少都会有些启发。那么现在请大家再次拿出手中的笔和便签纸，写下近期需要解决的问题，尝试运用今天片段中提到的方法和步骤。在这里，需要请大家注意两点：\u003c/p>\u003cp>&nbsp;&nbsp; 首先，是最近希望解决的一个具体问题。\u003c/p>\u003cp>&nbsp;&nbsp; 其次，要有明确的时间，我们拆书学习的目的就是即学即用。\u003c/p>\u003cp>&nbsp;&nbsp; 下面再请一位小伙伴来给大家分享下近期的行动计划。\u003c/p>\u003cp>&nbsp; 学习者分享近期计划：\u003c/p>\u003cp>&nbsp;&nbsp;\u003cstrong>学习者B：\u003c/strong>近期发现课堂上个别有学生打瞌睡的现象，打算下周用“五个为什么”来找出答案并解决。\u003c/p>\u003cp>第一个“为什么”，为什么上课打瞌睡？是学生的问题还是我自己的问题。\u003c/p>\u003cp>第二个“为什么”，是学生上课前一天晚上没有休息好吗？还当天是身体不舒服。\u003c/p>\u003cp>第三个“为什么”，是我的课讲得很枯燥吗？ 需要改进我的讲课方式吗？\u003c/p>\u003cp>然后根据得到的答案，再进一步追问，直到真实的情况，再给出有针对性的解决方案。 \u003c/p>\u003cp>感谢小伙伴B的分享，他所制定的的这个计划，基本上运用了五个“为什么”的方法步骤，问题设计非常很贴切，相信他很快就能找出答案并解决了。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>【总结】今天我的分享就到这里。希望今天所学习的方法可以帮助到大家拓展思路，下次再遇到什么问题的时候，能够溯本逐源，找到问题关键之所在。\u003c/p>\u003cp>最后希望在拆书帮这个大家庭里，我们一起努力，成就更好的自己。谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1508833432000,"updated_at":1508836036000,"ria":true},{"id":3435,"topic":"五个“为什么”问题解决法","learn_goal":"能够学会通过不断的提出问题，达到溯本求源解决问题的目的。","remark":"拆书家英爱1-2定级","level":"TF1-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"英爱","city":"合肥"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"在座的小伙伴，大家好，我是英爱。我的本职工作是药品销售，平时喜欢看书、看电影、结交一些志同道合的朋友。\r\n 加入拆书帮是希望能够认识更多优秀的小伙伴，大家一起抱团学习，让自己也慢慢成长为一个优秀的人。\r\n 今天现场一共来7位小伙伴，为了便于后面环节的互动，我们先分下组，我们分3组。树袋熊贝贝、河老师、橙子姐一组；阿波罗老师，观察员一组；秀秀和新来的这位小伙伴一组。\r\n 今天所拆解的片段来自《复盘+把经验转化为能力》这本书，它的作者是邱昭良博士。邱昭良先生硕士和博士两段研究经历的专业方向均为学习型组织。他本人曾任联想集团高级经理、联想投资公司咨询经理、东方道迩集团首席运营官，有着非常丰富的一线经营与管理实务经验。\r\n本书详细阐述了联想、万达、美国军队、英国石油公司复盘的实务做法，分享了作者多年的实践经验以及“内功心法”，介绍了引导复盘的工作指引与常用方法、工具与模板，是应用复盘的专业、深入而全面的操作指南。\r\n 这本书告诉读者如何通过对过去的思维和行为进行回顾，反思和探究，实现能力的提升。","ratings_count":0,"texts":[{"id":6299,"quote":"\u003cp>\u003cstrong>如何使用“五个为什么”\u003c/strong>\u003c/p>\u003cp>这一方法的使用非常简单，以至于只需要以下三个步骤。\u003c/p>\u003cp>\u003cstrong>第一步，提出第一个为什么\u003c/strong>\u003c/p>\u003cp>挑选出一个问题症状作为开端，然后问小组成员第一个为什么：“为什么这件事情正在发生？”\u003c/p>\u003cp>可能对这个问题有三四个答案。把这些答案全部粘贴在墙上，在这些答案周围留有足够的空间。\u003c/p>\u003cp>\u003cstrong>第二步，依次追问“为什么”\u003c/strong>\u003c/p>\u003cp>重复墙上的每个答案，依次追问“为什么”。把每个答案和“答案的答案”粘贴到它的“母问题”附近。\u003c/p>\u003cp>\u003cstrong>第三步，对问题进行整合\u003c/strong>\u003c/p>\u003cp>当所有问题回答完毕之后，一些问题可能开始整合，并追溯到十几个不同的症状，发掘两三个系统性的根源。\u003c/p>\u003cp>例如，里克.罗斯《第五项修炼.实践篇》中提到了一个有趣的案例。\u003c/p>\u003cp>一位车间主任看到车间地板上有一摊油。他马上习惯性地抓住离他最近的一个工人，让他把油擦掉。\u003c/p>\u003cp>此时，一个善于使用“五个为什么”的顾问提出了第一个“为什么”：“为什么地板上会有一滩油？”\u003c/p>\u003cp>旁边的工人回答到：“奥，葛本机漏油了。”\u003c/p>\u003cp>“那你还不赶紧去吧葛本机修好？”车间主任吼道。可那个顾问却继续追问：“为什么葛本机会漏油？”\u003c/p>\u003cp>“因为塞子有毛病。”工人答道。\u003c/p>\u003cp>“为什么塞子有毛病？”那个顾问继续追问，提出了第三个“为什么”。\u003c/p>\u003cp>“我也不清楚，反正这批塞子都不经用，很差”。工人无奈地说。\u003c/p>\u003cp>“那么，你需要搞清楚，为什么你们会买这么差的塞子。”顾问对车间主任说。\u003c/p>\u003cp>……\u003c/p>\u003cp>通过不停的追问“为什么”，可以找到导致问题出现的深层次原因，避免就事论事，只是消除了问题的“症状”，而未从根本上解决问题。\u003c/p>","explains":"\u003cp>在座的各位小伙伴在读完这个片段后，是不是觉得照着这个套路去解决问题，那也太简单了吧。其实把复杂的问题简单化解决可是个大学问呢。\u003c/p>\u003cp>&nbsp;但为什么这么简单的套路，平时我们想不到呢？\u003c/p>\u003cp>&nbsp;问题在于习惯性思维，大家想想平时出现问题的时候，我们的本能反应是怎样呢？我们是不是本能的希望问题可以立马解决！最好是一次性给搞定，越快越好。于是，问题来的时候，没有给自己足够的时间去思考，去溯本求源，去找问题的关键所在。这就导致，我们很多时候仅仅是了解一些基本信息后，就草草的处理掉一些表面问题。而问题的根源还未被发掘，治标不治本的状态屡见不鲜。\u003c/p>\u003cp>试想一下，如果我们能够多点耐心，多追问几个问题，并且认真思考每个答案之间的内在联系。看问题会不会简单些呢？\u003c/p>\u003cp>其实想要找到问题的根本所在，针对性的去解决。其实是有章可循的，结合原文我给大家三个详细的步骤。\u003c/p>\u003cp>1、症状切入，穷尽答案。以一个问题“症状”，并把所有可能性的答案写出来，粘贴在问题的后面，每个答案的周围留有足够的空白。\u003c/p>\u003cp>2、二级追问，细化答案：依次对所有可能性的答案进行提问，并把每个答案粘贴在“母问题” 附近。\u003c/p>\u003cp>3、整合问题，追根溯源：当所有的问题回答完毕之后，对其中的一些问题进行整合，并追溯到不同的症状，从中发掘两到三个根源性的问题，统筹解决。\u003c/p>","interaction":"\u003cp>A1：\u003c/p>\u003cp>在工作和生活中，我们一定会遇到这样那样的问题要去解决，我们希望问题可以尽快妥善的解决。但是也一定存在不尽如意的地方。举个例子，最近女儿总是跟我说不愿意去补习班上课，我问她是什么原因她说不喜欢那里的环境。开始问她为什么她也不愿意说，后来细心开导后才知道，原来他们补习班有低年级的同学，那些孩子作业相对较少，一写完作业，就在教室里面说话打闹，影响女儿学习。女儿跟老师反映过一两次，老师不是很上心，也没有认真对待这件事。所以女儿不想去那里学习。\u003c/p>\u003cp>那么现在请大家回忆一下，最近有没有什么让你比较头痛，总也没有办法的解决的问题；或者说有什么问题总是反反复复出现，无法彻底解决掉的？请大家在一张便签上写出来，并在小组内分享交流一下，一会我请一个小伙伴分享一下自己的经历。\u003c/p>\u003cp>好了，我们看下哪位小伙伴可以来分享下下自己的案例。\u003c/p>\u003cp>有请这位小伙伴，大家掌声鼓励下。\u003c/p>\u003cp>橙子姐：有一个业务单元的人员离职率较高，经过初步的了解，跟这个部门的主管的行事作风关系比较大。虽然也多次跟这位主管沟通，但是他部门的人员流失率还是没有降低。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;感谢橙子姐的分享，从她分享中我们大概能够了解到，虽然大家都知道问题是出在了这名主管身上，但是并没有搞清楚这名主管为什么会有这样的行事作风，以及为什么他不愿意去改变自己的工作习惯来避免人员的流失。所以说，要想解决这个人员流失的问题，还需要管理者在这名主管身上多探究一下了。\u003cbr>\u003c/p>\u003cp>\u003cbr>&nbsp;&nbsp; A2:\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;今天各位来到现场，学习了片段所介绍的方法，我想大家多少都会有些启发。那么现在请大家再次拿出手中的笔和便签纸，写下近期需要解决的问题，尝试运用今天片段中提到的方法和步骤。在这里，需要请大家注意两点：\u003c/p>\u003cp>&nbsp;&nbsp; 首先，是最近希望解决的一个具体问题。\u003c/p>\u003cp>&nbsp;&nbsp; 其次，要有明确的时间，我们拆书学习的目的就是即学即用。\u003c/p>\u003cp>&nbsp;&nbsp; 下面再请一位小伙伴来分享下近期的行动计划，好的，我们请河老师来给大家分享下。\u003c/p>\u003cp>&nbsp;&nbsp; 河老师：近期在规划写一本关于构建知识体系的书，为了这本书能够在年底顺利出版。决定利用今天片段所学习到的技能，对写书过程中将会遇到的问题进行梳理。\u003c/p>\u003cp>&nbsp;&nbsp; 首先，确定图书主题：我为什么写这本书？是为了解决成长者的知识焦虑。\u003c/p>\u003cp>&nbsp;&nbsp; 其次，分解问题：逐一分析产生知识焦虑的症结所在，形成图书纲领。\u003c/p>\u003cp>&nbsp;&nbsp; 再次，整合成书：把各个症结进行深入分析，给出解决方案，最后成书。\u003c/p>\u003cp>&nbsp; 结束语：\u003c/p>\u003cp>今天我的分享就到这里。希望今天所学习的方法可以帮助到大家拓展思路，下次再遇到什么问题的时候，能够溯本逐源，找到问题关键之所在。\u003c/p>\u003cp>最后希望在拆书帮这个大家庭里，我们一起努力，成就更好的自己。\u003c/p>\u003cp>谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1502870593000,"updated_at":1502871285000,"ria":true},{"id":2904,"topic":"后悔药的正确服用方法","learn_goal":"通过本次分享向大家介绍复盘及其基本技法","remark":"世界上最后悔的事，是原本可以做到的事情，结果却没有做到；\r\n世界上更后悔的事情，是上次就可以做到的事情，再次发生了，还是没有做到！\r\n比如第三次减肥计划的破产，第六次关掉早起的闹铃，\r\n我们没有后悔药可以让过去的事情发生改变，\r\n但我们有后悔药可以让未来不再为这样的事再次后悔，\r\n这个后悔药的药方，\r\n就是复盘。","level":"TF1-1","duration":15,"status":29,"type":0,"chaishujia":{"username":"金宇龙","city":"宁波"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，接下来由我为大家拆书，我叫金宇龙，大家也可以叫我金龙鱼，大家可能都知道这个著名的食用油品牌，因为姓名谐音关系，所以我就借这个名字做艺名正好揩油，也希望今天可以加油。\r\n【介绍拆书帮】很多人都感慨“读过很多书,听过很多道理,依旧过不好这一生”，包括我自己。但我知道，我是活该，很多书很多道理都是看看就过去了，左眼进右眼出，这样就能过好一生，这个世界就是极乐世界了。\r\n我们拆书帮立足于武林的看家本领就是“拆书学习法”，正好可以解决这一问题。这一方法的关键就是，把书中的某个具体知识，放到自己的过去和未来中，进行反思和应用。想想是否曾经有一段经历可以用到书中的知识，当初没有书中的知识，自己是怎么做的，如果当时应用了书中的知识，结局又会如何；未来遇到能应用书中知识的地方，你会如何使用，这样反思和演练之后，对书中的知识就会理解更深入掌握更透彻，更有机会改变人生。\r\n拆书帮就是一群以拆书法为学习方法的学习促进者搭建起来的社群，大家在这里互相促进，一起精进，在自我学习成长的同时影响更多的人。","ratings_count":1,"texts":[{"id":5687,"quote":"\u003cp>许多人都有写工作总结的习惯。那么，这是不是复盘呢？\u003cbr>\u003c/p>\u003cp>我的看法是：虽然复盘也是一种形式的总结，但严格讲起来，工作总结并不必然等同于复盘。在我看来，复盘与总结的区别有以下三点。\u003c/p>\u003cp>1.复盘是结构化的总结方法\u003c/p>\u003cp>我们都知道，总结是对一定时期的工作或某个事件的梳理、汇报，每个人依自己的习惯和悟性，对已经发生的事件、行为及结果进行回顾、描述，通常并没有固定的模板和结构，并不必然包括对目标与事实差异原因的分析，以及经验总结等要素。但复盘具有明确的结构与要素，必须遵从特定的步骤进行操作，不仅回顾目标与事实，也要对差异的原因进行分析，得出经验与教训，这样才能算是一次完整的复盘。\u003c/p>","explains":"\u003cp>复盘是什么？\u003c/p>\u003cp>片段里说，复盘是结构化的总结方式，两个关键词，总结，就是对已经发生的某件事进行结算回顾；结构化，这种总结方式是有结构的条理清晰的。所以复盘是发生在事后的，有一定结构和条理的回顾、结算。\u003c/p>\u003cp>复盘怎么做？片段里也给了我们一个流程，就是\u003c/p>\u003cp>1·回顾目标与事实，这个事实就是事情的客观结果；\u003c/p>\u003cp>2·寻找目标与事实之间的差异产生的原因，这一差异，可以是做的不好没达到目标，也可以是做的很好超出预期，但其中总有一些原因；\u003c/p>\u003cp>3·得出经验教训，这次导致低于目标的因素，以后如何去避免、克服甚至转化为利好因素，这次成就超出目标的因素，以后如何使他常态化，如何保持、发扬下去。\u003c/p>\u003cp>这样就不会在同一件事情上栽倒两次，也不会后悔第二次。\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>不知道大家反思、总结的时候是怎样的。我做菜的时候，经常会意识到，咦，这次好咸，下次盐少放点。到下一次做同样的菜，还是炒咸了，然后就后悔，责怪自己不长记性。\u003c/p>\u003cp>其实这锅不该记性背，首先我并没有明确设定一个目标就是这盘菜我要炒的淡一些，所以放盐的时候没有刻意去控制；然后上次说“下次盐少放点”，少放点是放多少？所以这样的反思总结没有什么实质作用，如果我复个盘，目标：我想炒淡一点，结果：太咸，原因：因为盐放多了，教训：这次放了一满勺，下次放三分之二勺。这样就更容易记住，我的厨艺也才能越来越好，而不是像现在这样自己都要皱着眉头吃。\u003c/p>\u003cp>A2\u003c/p>\u003cp>复盘最佳的时间是什么？就是事情刚刚发生，这个盘还是热乎的，很多细节的记忆都清晰，这再给他复一遍，效果是最好的。所以今天拆书完成之后，也就是今晚，就要对这次拆书进行一个复盘。\u003c/p>\u003cp>首先就是需要回顾我的目标，我今天的目标并没有非常高，我不是一个特别擅长当众讲话的人，所以这一次能够流畅自然地完成分享，没有紧张到尿裤子或者结结巴巴，就可以了。当然仅仅是这一次，以后还会不断提高目标和挑战。\u003c/p>\u003cp>那么结果，回去我会听一下录音，再结合自我感觉和大家的一些肢体语言和表情的反馈，尽量客观地评估我的拆书效果。如果讲话流畅没有硬伤，并且有幸得到大家的认可或者掌声，那就是超出预期了。如果自己讲的吞吞吐吐语无伦次，大家纷纷摇头，那么就是没有达成目标。\u003c/p>\u003cp>寻找差异的原因，如果这次的目标实现的还是比较不错的，那是为什么呢？首先当然是这里的朋友们都是宽容阳光的，能够给于我支持的眼神，帮里的长老众兄弟们也提供了很多帮助，然后我自己准备的也比较充分有把握；如果没有达成目标，是否是因为自己的准备不足，所选书目不是大家感兴趣的，或者是发生一些意外打乱了节奏。\u003c/p>\u003cp>最后一步是经验教训，首先自我准备一定要充分，包括对书的理解、举的例子等等，一定要对得起自己和观众的时间；然后就是分享书这种事情，就是要寻找咱们这样的灵魂有香气的观众和这样清静典雅的场所，才能有这样的气场和氛围，也让拆书分享更有成就感。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1497274057000,"updated_at":1522154553000,"ria":true}]};